__CR('t:sysd',[{"t":"세션·인증 시스템 설계","l":[{"t":"세션 저장소와 인증 전략","q":[{"t":"choice","k":"sd2-session-store","cat":"design","q":"하루 1억 요청 규모의 로그인 세션 시스템을 설계한다. 여러 API 서버가 무상태로 확장되어야 하고 세션 무효화(강제 로그아웃)도 즉시 가능해야 한다. 세션 저장소로 가장 적절한 것은?","o":["각 API 서버의 로컬 메모리에 세션 저장, 스티키 세션으로 고정","Redis 등 중앙 인메모리 저장소에 세션 저장, TTL과 즉시 삭제 지원","관계형 DB의 sessions 테이블에 매 요청마다 조회/갱신","세션 자체를 클라이언트 쿠키에 평문으로 저장"],"a":1,"ex":"무상태 확장과 즉시 무효화를 동시에 만족하려면 중앙 인메모리 저장소(Redis)가 적절하다. 로컬 메모리는 서버 확장/장애 시 세션이 흩어지고, RDB는 매 요청 조회 비용이 크다.\n💡 개념: 세션은 읽기가 압도적으로 많고 TTL 만료가 핵심이라 인메모리 KV가 접근 지연과 만료 처리에 유리하다.\n🛠 실무: Redis를 세션 저장소로 쓸 때 AOF/RDB 지속성과 복제 구성을 두어 단일 장애점이 되지 않게 한다."},{"t":"choice","k":"sd2-jwt-vs-server","cat":"design","q":"모바일·웹·서드파티가 함께 쓰는 인증을 설계한다. 팀은 '무상태 확장'을 이유로 JWT를 서버 세션 없이 도입하려 한다. 이때 반드시 감수해야 하는 트레이드오프는?","o":["JWT는 서명 검증 비용이 커서 QPS가 급감한다","발급된 JWT는 만료 전 즉시 무효화가 어려워 강제 로그아웃/탈취 대응이 까다롭다","JWT는 페이로드 암호화가 불가능해 항상 평문이 노출된다","JWT는 여러 서버에서 검증할 수 없어 스티키 세션이 필수다"],"a":1,"ex":"JWT는 자가 검증형이라 무상태 확장에 유리하지만, 서버가 상태를 갖지 않기에 만료 전 즉시 폐기가 구조적으로 어렵다.\n💡 개념: 무효화를 위해 블랙리스트/짧은 만료+리프레시 토큰 회전 같은 상태를 다시 도입해야 하는 역설이 생긴다.\n🛠 실무: 액세스 토큰은 5~15분으로 짧게, 리프레시 토큰은 서버 저장·회전(rotation)해서 탈취 시 폐기 가능하게 설계한다."},{"t":"input","k":"sd2-sticky-term","cat":"design","q":"로드밸런서가 특정 사용자의 요청을 항상 같은 백엔드 서버로 보내 로컬 세션을 유지하게 하는 방식을 무엇이라 부르는가? (영문 용어)","a":["sticky session","session affinity","sticky sessions","sticky"],"ex":"같은 클라이언트를 같은 서버로 고정하는 방식을 sticky session(session affinity)이라 한다.\n💡 개념: 로컬 세션을 살릴 수 있지만 특정 서버로 부하가 몰리고 서버 장애 시 그 서버의 세션이 통째로 사라진다.\n🛠 실무: 무상태 아키텍처를 원하면 스티키 대신 세션을 외부 저장소로 빼는 편이 확장·장애 대응에 유리하다."},{"t":"choice","k":"sd2-ttl-choice","cat":"perf","q":"세션 TTL을 정한다. 활성 사용자 500만, 평균 세션 크기 1KB, 세션은 갱신 없이 절대 만료 30일로 잡았다. 운영 중 발견된 문제는?","o":["저장량이 약 5GB로 과도해 Redis가 즉시 OOM 된다","TTL이 너무 길어 오래 방치된 세션이 쌓이고 탈취 토큰의 유효기간도 길어진다","TTL이 짧아 사용자가 매 요청마다 재로그인한다","절대 만료는 슬라이딩 만료보다 항상 안전하다"],"a":1,"ex":"500만×1KB는 약 5GB로 용량 자체는 감당 가능하나, 30일 절대 만료는 유휴 세션 누적과 탈취 시 노출 기간 확대라는 보안 문제를 낳는다.\n💡 개념: 슬라이딩 만료(마지막 활동 기준 갱신)와 절대 만료 상한을 함께 두어 유휴 세션을 자연 정리한다.\n🛠 실무: 예: idle 30분 + absolute 12시간처럼 이중 만료를 걸고, 민감 작업은 재인증을 요구한다."},{"t":"choice","k":"sd2-logout-storm","cat":"ops","q":"세션 저장소 Redis가 30초간 장애를 겪고 복구됐다. 그동안 검증 실패한 모든 세션이 401을 받아 클라이언트가 일제히 재로그인·재발급을 시도하며 인증 서버가 폭주했다. 근본 완화책은?","o":["인증 서버 인스턴스를 무한정 오토스케일해 요청을 모두 받는다","세션 검증 실패 시 지수 백오프+지터로 재시도를 분산하고, 짧은 로컬 캐시·서킷브레이커로 폭주를 흡수한다","장애 시 모든 요청을 무조건 통과(fail-open)시켜 인증을 건너뛴다","TTL을 무한대로 설정해 세션이 절대 만료되지 않게 한다"],"a":1,"ex":"동시 재로그인 폭풍(thundering herd)은 재시도 분산과 백프레셔로 흡수해야 한다. fail-open은 보안 붕괴, 무한 스케일은 비용·전파 위험이 크다.\n💡 개념: 상관관계 있는 대량 재시도는 지터 없는 백오프에서 동기화되어 재폭주하므로 지터가 핵심이다.\n🛠 실무: 리프레시 토큰 검증에 서킷브레이커를 두고, 클라이언트 SDK에 지터 백오프를 기본 탑재한다."},{"t":"input","k":"sd2-session-qps","cat":"perf","q":"하루 4.32억 건의 세션 검증 요청이 균등하게 발생한다고 가정할 때 평균 QPS는 얼마인가? (정수, 숫자만)","a":["5000","5,000"],"ex":"432,000,000 / 86,400 = 5,000 QPS.\n💡 개념: 일일 요청을 86,400초로 나누면 평균 QPS가 나오고, 피크는 여기에 배수를 곱해 추정한다.\n🛠 실무: 평균 5,000 QPS라도 피크가 3~5배면 15,000~25,000 QPS를 감당하도록 저장소·연결풀을 산정한다."},{"t":"choice","k":"sd2-refresh-rotation","cat":"security","q":"리프레시 토큰 회전(rotation)을 도입했다. 회전이 탈취 대응에 주는 핵심 이점은?","o":["토큰 크기가 작아져 네트워크 대역폭을 절약한다","이전 리프레시 토큰이 재사용되면 탈취를 탐지해 해당 토큰 패밀리 전체를 무효화할 수 있다","액세스 토큰 서명 검증이 필요 없어진다","세션을 서버에 저장하지 않아도 되게 만든다"],"a":1,"ex":"회전은 매 갱신마다 새 리프레시 토큰을 발급하고 옛 토큰을 폐기하므로, 폐기된 옛 토큰이 다시 쓰이면 탈취 신호로 보고 패밀리 전체를 끊는다.\n💡 개념: 정상 클라이언트는 항상 최신 토큰만 쓰기에 옛 토큰 재사용은 곧 복제·탈취를 의미한다.\n🛠 실무: 토큰에 family_id를 부여해 재사용 감지 시 그 family의 모든 토큰을 한 번에 무효화한다."}],"th":{"sum":"대규모 인증은 **무상태 확장**과 **즉시 무효화** 사이의 트레이드오프다. 세션은 무효화가 쉽고, JWT는 확장이 쉽지만 즉시 폐기가 어렵다.","body":[{"h":"세션 vs JWT","t":"서버 세션(Redis)은 강제 로그아웃을 저장소에서 키를 지우는 것으로 즉시 처리하지만, 검증마다 저장소 조회가 필요하다. JWT는 서명만으로 무상태 검증이 되어 확장에 유리하나, 만료 전 폐기가 원천적으로 어렵다(블랙리스트를 두면 다시 상태가 생김)."},{"h":"TTL·회전·장애 대비","t":"절대 만료만 길게 잡으면 저장소가 무한정 커지므로 슬라이딩 TTL이나 짧은 access + 긴 refresh 조합을 쓴다. 세션 저장소 장애 후 일제 재로그인은 인증 서버에 thundering herd를 일으키므로 지터·백오프가 필요하다. 리프레시 토큰 회전은 한 번 쓴 토큰을 폐기해, 탈취된 옛 토큰 재사용을 탐지·차단한다."}],"code":{"c":"access_token:  TTL 15분 (무상태 검증)\nrefresh_token: TTL 14일 + 회전(rotation)\n세션 검증 QPS = 4.32억 / 86,400 = 5,000","cap":"짧은 access + 회전 refresh로 확장과 폐기를 절충"},"key":["JWT = 무상태 확장 O, 즉시 무효화 X (트레이드오프)","sticky routing = session affinity(스티키 세션)","refresh 회전: 재사용 탐지로 탈취 대응","저장소 장애 후 재로그인 폭주엔 지터·백오프"]}}]},{"t":"피드·타임라인 설계","l":[{"t":"팬아웃과 핫키 문제","q":[{"t":"choice","k":"sd2-fanout-model","cat":"design","q":"소셜 앱의 홈 타임라인을 설계한다. 대부분 사용자는 팔로워 수백 명이고 읽기가 쓰기보다 훨씬 잦다. 타임라인 조회 지연을 최소화하려는 1차 전략으로 적절한 것은?","o":["fanout-on-read: 조회 시점에 팔로우한 모두의 최신 글을 실시간 병합","fanout-on-write: 글 작성 시 팔로워들의 타임라인 캐시에 미리 밀어넣기","매 조회마다 전체 게시물 테이블을 풀스캔","타임라인을 아예 캐시하지 않고 항상 원본 DB에서 계산"],"a":1,"ex":"읽기가 많고 팔로워 규모가 보통이면 쓰기 시점에 미리 밀어넣는 fanout-on-write가 조회 지연을 낮춘다.\n💡 개념: 읽기/쓰기 비율과 팬아웃 규모가 전략을 가른다. 읽기 폭증엔 write 팬아웃이 유리하다.\n🛠 실무: 각 사용자 타임라인을 Redis 리스트로 유지하고 일정 길이로 트리밍해 메모리를 관리한다."},{"t":"choice","k":"sd2-celeb-problem","cat":"design","q":"fanout-on-write를 도입했는데 팔로워 5,000만 명인 셀럽이 글을 올리자 5,000만 개의 타임라인 쓰기가 폭발했다(셀럽 문제). 실무적으로 가장 널리 쓰는 해법은?","o":["셀럽 계정의 게시를 하루 1회로 제한한다","셀럽 등 대형 계정은 fanout-on-write에서 제외하고 조회 시점에 pull(read 팬아웃)로 병합하는 하이브리드","모든 사용자를 fanout-on-read로 전환한다","셀럽 게시물만 별도 DB에 복제해 팬아웃을 2배로 늘린다"],"a":1,"ex":"일반 계정은 write 팬아웃, 대형 계정은 read 팬아웃으로 처리하는 하이브리드가 표준 해법이다.\n💡 개념: 팬아웃 비용은 팔로워 수에 비례하므로 상위 소수 계정만 pull로 돌려도 쓰기 폭발을 크게 줄인다.\n🛠 실무: 팔로워 임계치(예: 100만)를 기준으로 계정을 분류하고, 조회 시 push 타임라인과 셀럽 pull 결과를 병합한다."},{"t":"input","k":"sd2-hotkey-term","cat":"perf","q":"특정 인기 게시물/셀럽 키에 읽기 요청이 극단적으로 몰려 그 키가 있는 캐시 샤드만 과부하되는 현상을 무엇이라 하는가? (영문 용어)","a":["hot key","hotkey","hot key problem","hotspot"],"ex":"부하가 특정 키에 집중되는 현상을 hot key 문제라 한다.\n💡 개념: 균등 샤딩을 해도 접근 분포가 편향되면 특정 샤드가 병목이 된다.\n🛠 실무: 핫키는 로컬 캐시로 앞단에서 흡수하거나, 키를 여러 복제본으로 분산(key replication)해 읽기를 나눈다."},{"t":"choice","k":"sd2-timeline-cache","cat":"perf","q":"타임라인 캐시가 만료되어 인기 사용자에 대한 요청 수천 개가 동시에 원본 DB로 몰려 DB가 출렁였다. 재계산 폭주를 막는 방법은?","o":["TTL을 없애 캐시가 절대 만료되지 않게 한다","캐시 재계산에 단일 잠금(mutex)이나 single-flight를 걸어 한 요청만 계산하고 나머지는 결과를 기다린다","요청이 몰릴 때마다 DB 인스턴스를 즉시 추가한다","타임라인 조회를 큐에 넣어 1초에 한 건만 처리한다"],"a":1,"ex":"동일 키 재계산을 하나로 합치는 single-flight/뮤텍스가 cache stampede를 막는다.\n💡 개념: 만료 순간 다수가 동시에 miss하면 원본이 폭주하므로, 재계산을 직렬화하거나 조기 만료로 분산한다.\n🛠 실무: 만료 임박 시 확률적 조기 갱신(probabilistic early recompute)을 더하면 동시 만료 자체를 줄일 수 있다."},{"t":"choice","k":"sd2-timeline-storage","cat":"perf","q":"사용자 2억, 각 타임라인에 최근 게시물 ID 800개를 저장하고 ID당 16바이트라면 타임라인 인덱스의 대략적 저장량은?","o":["약 2.5GB","약 25GB","약 2.5TB","약 25TB"],"a":2,"ex":"2억 × 800 × 16B = 2×10^8 × 12,800B ≈ 2.56×10^12B ≈ 약 2.5TB.\n💡 개념: 사용자수 × 항목수 × 항목크기로 대략 저장량을 잡고, 자릿수만 맞아도 용량 계획엔 충분하다.\n🛠 실무: 타임라인은 길이를 제한(트리밍)하고 오래된 항목은 원본 조회로 대체해 인메모리 비용을 억제한다."},{"t":"choice","k":"sd2-feed-consistency","cat":"design","q":"타임라인은 강한 일관성보다 지연·가용성이 중요하다는 판단으로 설계한다. 이 선택에 가장 부합하는 것은?","o":["모든 팬아웃을 동기 트랜잭션으로 처리해 즉시 일관성을 보장한다","팬아웃을 비동기 큐로 처리해 약간의 전파 지연을 허용하되 쓰기 응답을 빠르게 반환한다","게시 성공은 모든 팔로워 타임라인 반영이 끝나야만 응답한다","타임라인은 항상 원본 DB에서 실시간 조인으로 계산한다"],"a":1,"ex":"피드는 최종 일관성이 허용되는 대표 사례로, 팬아웃을 비동기화하면 쓰기 지연을 낮추고 가용성을 높인다.\n💡 개념: 일부 팔로워에게 몇 초 늦게 보이는 것은 대개 허용 가능한 트레이드오프다.\n🛠 실무: 게시 이벤트를 큐에 넣고 워커가 팬아웃을 소비하며, 실패 항목은 재시도/DLQ로 보정한다."},{"t":"input","k":"sd2-fanout-write-qps","cat":"perf","q":"초당 500건의 게시가 발생하고 평균 팔로워가 200명일 때, fanout-on-write로 발생하는 초당 타임라인 쓰기 건수는? (정수, 숫자만)","a":["100000","100,000"],"ex":"500 × 200 = 100,000 writes/s.\n💡 개념: write 팬아웃 부하 = 게시 QPS × 평균 팔로워 수. 팔로워가 많을수록 쓰기 증폭이 크다.\n🛠 실무: 쓰기 증폭이 크면 배치 쓰기·파이프라이닝으로 왕복을 줄이고, 대형 계정은 pull로 분리한다."}],"th":{"sum":"타임라인은 **팬아웃 전략**의 선택 문제다. fanout-on-write는 읽기가 빠르지만 셀럽에서 폭발하고, **핫키**와 stampede 방어가 핵심이다.","body":[{"h":"팬아웃-온-라이트 vs 리드","t":"읽기가 잦으므로 게시 시점에 팔로워 피드에 미리 뿌리는 fanout-on-write가 조회 지연을 최소화한다. 그러나 팔로워 5,000만 셀럽은 쓰기가 폭발한다(셀럽 문제). 실무 해법은 하이브리드: 일반 사용자는 write 팬아웃, 셀럽은 read 시점에 병합(pull)한다."},{"h":"핫키와 stampede","t":"특정 인기 키에 읽기가 몰려 한 샤드만 과부하되는 것이 hot key다. 로컬 캐시 복제·키 분할로 완화한다. 캐시 만료 순간 다수 요청이 원본 DB로 몰리는 cache stampede는 뮤텍스(single-flight)·논리적 TTL·조기 재계산으로 막는다. 타임라인은 강일관성보다 지연·가용성이 중요해 최종 일관성을 택한다."}],"code":{"c":"일반 사용자: fanout-on-write (미리 배포)\n셀럽:       fanout-on-read (조회 시 병합)\n초당 타임라인 쓰기 = 500 게시 × 200 팔로워 = 100,000","cap":"하이브리드 팬아웃으로 셀럽 폭발을 회피"},"key":["읽기 우선이면 fanout-on-write, 셀럽은 read로 하이브리드","hot key = 인기 키에 읽기 집중, 샤드 편중","cache stampede는 single-flight/뮤텍스로 방어","타임라인은 최종 일관성 + 가용성 선택"]}}]},{"t":"캐시 전략","l":[{"t":"캐시 패턴과 장애 대응","q":[{"t":"choice","k":"sd2-cache-aside","cat":"design","q":"읽기 위주 상품 상세 페이지에 캐시를 붙인다. 애플리케이션이 캐시를 먼저 조회하고 miss면 DB에서 읽어 캐시에 채우는 패턴의 이름과 특징으로 옳은 것은?","o":["write-through: 쓰기 시 캐시와 DB를 함께 갱신해 항상 최신 유지","cache-aside(lazy loading): 실제 요청된 데이터만 캐시에 적재, 초기 miss 존재","write-back: 캐시에만 쓰고 나중에 DB로 비동기 반영","read-through 전용: 캐시 계층이 DB 조회를 대신 수행하며 앱은 관여 안 함"],"a":1,"ex":"앱이 miss 시 DB에서 읽어 캐시를 채우는 것은 cache-aside(lazy loading)다.\n💡 개념: 요청된 데이터만 캐시에 오르므로 메모리 효율이 좋지만 첫 접근은 반드시 miss가 난다.\n🛠 실무: DB 갱신 시 캐시 무효화(삭제)를 함께 처리하지 않으면 stale 데이터가 남는다."},{"t":"choice","k":"sd2-write-back-risk","cat":"ops","q":"쓰기 지연을 극단적으로 낮추려 write-back(write-behind) 캐시를 도입했다. 반드시 감수해야 하는 위험은?","o":["읽기 지연이 write-through보다 항상 높다","캐시에만 있고 DB에 미반영된 데이터가 캐시 장애 시 유실될 수 있다","DB 부하가 write-through보다 항상 커진다","캐시 hit율이 구조적으로 0에 수렴한다"],"a":1,"ex":"write-back은 캐시에 먼저 쓰고 DB 반영을 지연하므로, 미반영 상태에서 캐시가 죽으면 데이터가 유실된다.\n💡 개념: 쓰기 지연↓·처리량↑ 대신 내구성 위험을 얻는 트레이드오프다.\n🛠 실무: 미반영 쓰기를 복제/영속 로그로 보호하고, 금전 등 유실 불가 데이터엔 쓰지 않는다."},{"t":"input","k":"sd2-stampede-term","cat":"perf","q":"많은 키가 동시에 만료되거나 인기 키가 만료되는 순간 다수 요청이 한꺼번에 원본 DB로 몰려 부하가 폭증하는 현상을 통칭하는 용어는? (영문, 한 가지)","a":["cache stampede","thundering herd","stampede","cache stampede problem"],"ex":"만료 순간 동시 miss로 원본이 폭주하는 현상을 cache stampede(또는 thundering herd)라 한다.\n💡 개념: 개별 키 만료가 시간적으로 몰리면 순간 부하가 집중된다.\n🛠 실무: TTL에 지터를 더해 만료를 흩고, single-flight로 재계산을 하나로 합친다."},{"t":"choice","k":"sd2-cache-penetration","cat":"ops","q":"존재하지 않는 상품 ID로 대량 조회가 들어와 매번 캐시 miss 후 DB까지 도달해 DB가 시달린다(cache penetration). 방어책으로 가장 적절한 것은?","o":["존재하지 않는 키에 대해서는 캐시를 절대 사용하지 않는다","'없음' 결과를 짧은 TTL로 캐시하거나 블룸 필터로 존재하지 않는 키를 앞단에서 차단","모든 조회를 큐에 직렬화해 DB를 보호한다","DB 커넥션 풀을 무한대로 늘린다"],"a":1,"ex":"없는 키의 조회 폭주는 음수 캐싱(negative caching)과 블룸 필터로 막는다.\n💡 개념: miss가 항상 DB로 새어나가는 구조를 끊는 것이 핵심이다.\n🛠 실무: 음수 캐시 TTL은 짧게 두어 뒤늦게 생성된 데이터가 오래 가려지지 않게 한다."},{"t":"choice","k":"sd2-invalidation-order","cat":"design","q":"DB 갱신과 캐시 무효화를 함께 수행할 때 흔히 권장되는 순서·방식은?","o":["먼저 캐시를 갱신하고 나서 DB를 쓴다","DB를 먼저 쓰고 캐시는 갱신이 아니라 '삭제(무효화)'해 다음 조회에서 최신을 적재","DB와 캐시를 순서 없이 병렬로 쓴다","캐시는 절대 건드리지 않고 TTL 만료만 기다린다"],"a":1,"ex":"DB 먼저 쓰고 캐시는 삭제하는 방식이 동시성 하에서 stale 위험이 낮다. 갱신 대신 삭제는 경쟁 쓰기의 덮어쓰기 문제를 줄인다.\n💡 개념: 두 저장소를 원자적으로 못 바꾸므로, 무효화 순서와 재적재 시점이 일관성을 좌우한다.\n🛠 실무: 미묘한 경쟁을 없애려면 변경 로그(CDC)로 캐시를 무효화하는 방식도 검토한다."},{"t":"input","k":"sd2-hit-ratio","cat":"perf","q":"캐시 hit율이 90%, hit 지연 2ms, miss 지연 50ms일 때 평균 조회 지연은 몇 ms인가? (숫자만)","a":["6.8","6.8ms"],"ex":"0.9×2 + 0.1×50 = 1.8 + 5 = 6.8ms.\n💡 개념: 평균 지연 = hit율×hit지연 + miss율×miss지연. miss 비용이 크면 hit율 개선 효과가 크다.\n🛠 실무: hit율을 90%→95%로 올리면 miss가 절반이 되어 평균 지연이 크게 낮아진다. hit율 모니터링이 핵심 지표다."},{"t":"choice","k":"sd2-ttl-jitter","cat":"perf","q":"인기 데이터 1만 개를 배치로 한 번에 적재하며 모두 TTL 600초를 동일하게 걸었다. 600초 뒤 예상되는 문제와 해법은?","o":["문제 없음, TTL이 같으면 부하가 오히려 분산된다","1만 키가 동시에 만료되어 순간 폭주하므로 TTL에 무작위 지터를 더해 만료 시점을 분산한다","TTL을 아예 걸지 않으면 해결된다","적재 순서를 역순으로 바꾸면 해결된다"],"a":1,"ex":"동일 TTL 일괄 적재는 동시 만료로 stampede를 유발하므로, TTL에 지터(예: 600±60초)를 준다.\n💡 개념: 만료 시점의 분포를 넓히는 것이 순간 부하를 낮추는 핵심이다.\n🛠 실무: 적재 시 base TTL + rand(0, jitter)로 흩고, 재계산엔 single-flight를 병행한다."}],"th":{"sum":"**캐시 전략**은 패턴(cache-aside/write-through/write-back)과 장애(stampede·penetration) 대응의 조합이다. 무효화 순서와 TTL 지터가 실무 포인트다.","body":[{"h":"쓰기 패턴과 위험","t":"cache-aside는 miss 시 DB에서 읽어 채우는 지연 로딩으로 구현이 단순하다. write-back(write-behind)은 캐시에 먼저 쓰고 나중에 DB 반영해 쓰기 지연이 낮지만, 캐시 소실 시 미반영 데이터가 유실될 위험을 감수해야 한다. DB 갱신과 캐시 무효화는 보통 DB 먼저 쓰고 캐시를 삭제(invalidate)하는 순서를 권장한다."},{"h":"stampede·penetration","t":"인기 키·다수 키 동시 만료로 요청이 원본에 몰리는 현상을 cache stampede라 하며, 뮤텍스·조기 재계산으로 막는다. 존재하지 않는 ID 조회가 매번 DB까지 가는 cache penetration은 블룸 필터나 널 값 캐싱으로 방어한다. 1만 키에 동일 TTL 600초를 걸면 동시 만료로 stampede가 나므로 TTL에 지터를 준다."}],"code":{"c":"평균 지연 = 0.9×2ms + 0.1×50ms = 6.8ms\n\n무효화 순서: DB update → cache delete\n동일 TTL 대량 적재 → TTL + rand(지터)로 분산","cap":"hit율·지연 계산과 TTL 지터"},"key":["write-back = 낮은 쓰기 지연, 데이터 유실 위험","무효화는 DB 쓰기 후 캐시 삭제","penetration은 블룸 필터/널 캐싱으로 방어","동일 TTL 대량 적재는 지터로 동시 만료 방지"]}}]},{"t":"데이터 파티셔닝·샤딩","l":[{"t":"샤딩 전략과 리샤딩","q":[{"t":"choice","k":"sd2-hash-vs-range","cat":"design","q":"쓰기가 user_id 기준으로 고르게 퍼져야 하고 특정 사용자 데이터에 대한 포인트 조회가 대부분이다. 샤딩 키 전략으로 가장 적절한 것은?","o":["생성 시각 기준 레인지 샤딩","user_id 해시 기반 샤딩","국가명 알파벳 순 레인지 샤딩","자동증가 정수 PK 순차 레인지 샤딩"],"a":1,"ex":"포인트 조회 중심에 균등 분산이 필요하면 해시 샤딩이 적합하다. 시각/순차 키 레인지 샤딩은 최신 샤드에 쓰기가 몰린다.\n💡 개념: 해시는 분산에 강하지만 범위 스캔에 약하고, 레인지는 범위 스캔에 강하지만 핫스팟 위험이 있다.\n🛠 실무: 범위 질의가 거의 없다면 해시가 낫고, 시계열 범위 스캔이 잦으면 레인지+핫샤드 대비책을 함께 설계한다."},{"t":"choice","k":"sd2-range-hotspot","cat":"perf","q":"타임스탬프를 샤드 키로 쓰는 레인지 샤딩에서 '최근 데이터'에만 트래픽이 집중돼 마지막 샤드가 과부하다. 핫 파티션을 완화하는 방법은?","o":["샤드 수를 절반으로 줄인다","키 앞에 해시 프리픽스/버킷을 붙여(salting) 최근 쓰기를 여러 샤드로 분산","타임스탬프 정밀도를 밀리초로 높인다","마지막 샤드에만 SSD를 쓰고 나머지는 HDD로 둔다"],"a":1,"ex":"순차 키의 말단 핫스팟은 키에 해시 버킷을 접두(salting)해 여러 샤드로 흩는다.\n💡 개념: 시간 순 키는 항상 '지금' 샤드에 쓰기가 몰리는 구조적 핫스팟을 갖는다.\n🛠 실무: bucket = hash(id) % N을 접두로 붙이면 쓰기가 분산되지만 범위 스캔은 N개 샤드를 팬아웃해야 함을 감안한다."},{"t":"input","k":"sd2-consistent-hash","cat":"design","q":"노드를 추가/제거할 때 재배치되는 키의 비율을 최소화하기 위해 널리 쓰는 해싱 기법의 이름은? (영문 용어)","a":["consistent hashing","consistent hash","consistenthashing"],"ex":"노드 변경 시 이동 키를 최소화하는 기법이 consistent hashing이다.\n💡 개념: 일반 모듈로 해싱은 노드 수가 바뀌면 거의 모든 키가 재배치되지만, 컨시스턴트 해싱은 인접 구간만 이동한다.\n🛠 실무: 노드별 부하 편차를 줄이려면 가상 노드(virtual node)를 여러 개 배치한다."},{"t":"choice","k":"sd2-modulo-resharding","cat":"ops","q":"shard = id % N (N=4)로 샤딩했는데 N을 5로 늘렸더니 거의 모든 키의 소속 샤드가 바뀌어 대규모 데이터 이동이 발생했다. 근본 원인과 대안은?","o":["해시 함수가 약해서다. 더 강한 해시로 바꾸면 이동이 사라진다","모듈로 샤딩은 N 변경 시 대부분 키가 재매핑된다. 컨시스턴트 해싱이나 논리 샤드 고정 방식으로 이동을 최소화한다","N을 소수로만 고르면 이동이 없어진다","id를 문자열로 바꾸면 재배치가 사라진다"],"a":1,"ex":"id % N은 N이 바뀌면 잉여류가 통째로 달라져 대부분 키가 이동한다. 컨시스턴트 해싱이나 다수의 논리 샤드를 물리 노드에 매핑하는 방식이 리샤딩 부담을 줄인다.\n💡 개념: 이동량을 결정하는 것은 해시 강도가 아니라 매핑 함수의 안정성이다.\n🛠 실무: 처음부터 논리 샤드를 넉넉히(예: 1024개) 만들고 물리 노드에 나눠 붙이면 노드 증설 시 논리 샤드 단위로만 옮기면 된다."},{"t":"choice","k":"sd2-vnode","cat":"design","q":"컨시스턴트 해싱에서 물리 노드 3대만 링에 배치했더니 노드별 담당 구간 크기가 크게 달라 부하가 불균등했다. 표준 해법은?","o":["노드를 반드시 2의 거듭제곱 개수로 맞춘다","각 물리 노드를 다수의 가상 노드로 링에 분산 배치해 담당 구간을 고르게 만든다","해시 함수를 SHA-512로 바꾼다","링을 사용하지 않고 모듈로 방식으로 회귀한다"],"a":1,"ex":"소수 노드일 때 구간 편차는 가상 노드(virtual node)로 완화한다.\n💡 개념: 물리 노드당 가상 노드를 많이 둘수록 담당 구간이 통계적으로 균등해진다.\n🛠 실무: 노드 성능이 다르면 강한 노드에 가상 노드를 더 많이 배정해 가중치를 준다."},{"t":"choice","k":"sd2-cross-shard-join","cat":"design","q":"주문 데이터를 user_id로 샤딩했는데, 특정 상품을 산 모든 사용자를 찾는 질의가 자주 필요해졌다. 이 질의의 성능 특성은?","o":["단일 샤드 조회로 끝나 가장 빠르다","샤드 키가 아니므로 모든 샤드를 스캐터-개더해야 해 비용이 크다. 필요하면 product_id 기준 보조 인덱스/역인덱스를 별도 구성","샤딩과 무관하게 항상 상수 시간이다","user_id 해시만 바꾸면 단일 샤드로 해결된다"],"a":1,"ex":"샤드 키가 아닌 속성으로의 질의는 전 샤드 팬아웃(scatter-gather)이 필요하다. 자주 쓰이면 다른 키로 정렬된 보조 저장소를 둔다.\n💡 개념: 샤딩은 접근 패턴을 하나의 키에 최적화하므로, 다른 축의 질의는 별도 인덱스가 필요하다.\n🛠 실무: product_id → user_id 역인덱스를 검색엔진/별도 테이블로 유지해 팬아웃을 피한다."},{"t":"input","k":"sd2-shard-count","cat":"perf","q":"총 12TB 데이터를 샤드당 최대 500GB로 담고 싶다. 최소 몇 개의 샤드가 필요한가? (정수, 숫자만)","a":["24"],"ex":"12,000GB / 500GB = 24 샤드.\n💡 개념: 필요한 샤드 수 = 총량 / 샤드당 용량. 여유율을 감안해 올림한다.\n🛠 실무: 향후 성장과 리밸런싱 여유를 위해 실제로는 논리 샤드를 더 넉넉히 잡고 물리 노드에 매핑한다."}],"th":{"sum":"**샤딩**은 샤드 키 선택과 리샤딩이 핵심이다. 모듈로는 재배치가 크고, **컨시스턴트 해싱 + 가상 노드**가 표준이다.","body":[{"h":"샤드 키와 핫 파티션","t":"포인트 조회가 대부분이고 쓰기를 고르게 퍼뜨리려면 user_id 해시 샤딩이 적합하다. 타임스탬프 레인지 샤딩은 최신 데이터에 트래픽이 몰려 마지막 샤드가 과부하되므로, 키 앞에 해시 접두사를 붙이는 등으로 분산한다. 교차 질의(특정 상품 구매자 전체)는 모든 샤드를 훑는 scatter-gather라 느리다."},{"h":"컨시스턴트 해싱","t":"`id % N`은 N 변경 시 거의 모든 키의 소속이 바뀌어 대규모 이동이 발생한다. 컨시스턴트 해싱은 노드 추가/제거 시 재배치 키를 최소화한다. 다만 물리 노드가 적으면 담당 구간이 불균등해지므로, 각 노드를 링 위 여러 지점에 두는 가상 노드(virtual node)로 부하를 고르게 만든다."}],"code":{"c":"shard = id % 4  → % 5 로 변경 시 거의 전부 이동\n대안: consistent hashing + virtual nodes\n\n필요 샤드 수 = ceil(12TB / 500GB) = 24개","cap":"모듈로 리샤딩 문제와 가상 노드 해법"},"key":["포인트 조회엔 user_id 해시 샤딩","레인지 샤딩은 최신 편중, 접두사 분산","id%N은 리샤딩 취약, consistent hashing 표준","노드 불균등은 virtual node로 해결"]}}]},{"t":"Rate Limiting·트래픽 제어","l":[{"t":"레이트 리밋과 백프레셔","q":[{"t":"choice","k":"sd2-token-vs-leaky","cat":"design","q":"API는 평소 완만하지만 사용자별로 짧은 순간의 버스트는 허용하고 싶다. 다만 장기 평균 속도는 제한해야 한다. 적절한 알고리즘은?","o":["leaky bucket: 유출 속도를 고정해 버스트를 평탄화(허용 안 함)","token bucket: 버킷에 토큰이 쌓여 있으면 순간 버스트를 허용하되 리필 속도로 평균을 제한","고정 윈도 카운터만 사용해 초당 정확히 N개로 자른다","요청을 무제한 허용하고 사후에 차단한다"],"a":1,"ex":"버스트 허용+평균 제한은 token bucket이 적합하다. leaky bucket은 유출을 고정해 버스트를 평탄화한다.\n💡 개념: token bucket은 쌓인 토큰만큼 순간 초과를 허용하고, leaky bucket은 출력 속도를 일정하게 유지한다.\n🛠 실무: 버킷 용량으로 최대 버스트 크기를, 리필률로 지속 평균 속도를 각각 튜닝한다."},{"t":"choice","k":"sd2-fixed-window-burst","cat":"perf","q":"'분당 100회' 제한을 고정 윈도 카운터로 구현했다. 사용자가 12:00:59에 100회, 12:01:00에 100회를 보내 2초 만에 200회가 통과했다. 이 경계 버스트를 완화하는 방식은?","o":["윈도를 분 단위에서 시간 단위로 늘린다","슬라이딩 윈도(로그 또는 가중 카운터)로 최근 60초를 연속적으로 평가한다","제한을 분당 50회로 절반으로 줄인다","카운터를 클라이언트 측에서 관리한다"],"a":1,"ex":"고정 윈도의 경계 버스트는 슬라이딩 윈도로 완화한다. 최근 60초를 연속 평가하면 경계에서의 2배 통과를 막는다.\n💡 개념: 고정 윈도는 리셋 경계에서 이론상 2배까지 통과할 수 있는 구조적 약점이 있다.\n🛠 실무: 슬라이딩 윈도 로그는 정확하지만 메모리가 크고, 슬라이딩 카운터(가중 근사)가 비용과 정확도의 절충안이다."},{"t":"choice","k":"sd2-distributed-counter","cat":"ops","q":"여러 API 게이트웨이 인스턴스가 각자 로컬 카운터로 레이트 리밋을 적용했더니 전체 허용량이 인스턴스 수만큼 뻥튀기됐다. 분산 환경의 정확한 제한 방법은?","o":["각 인스턴스 로컬 제한을 그대로 두고 인스턴스 수를 고정한다","Redis 등 중앙 카운터에 원자적 증가(INCR/Lua)로 집계해 전역 한도를 강제","제한을 인스턴스 수로 나눠 각자 적용하면 항상 정확하다","레이트 리밋을 클라이언트에게 위임한다"],"a":1,"ex":"전역 한도는 중앙 저장소의 원자적 카운터로 집계해야 정확하다. 로컬 분할은 트래픽 편중 시 부정확하다.\n💡 개념: 각 노드가 독립 카운트하면 합이 한도를 초과하고, 균등 분할은 편향 트래픽에서 과소/과대 제한을 낳는다.\n🛠 실무: 중앙 조회 지연을 줄이려 로컬 토큰을 소량 프리페치(배치 대여)하고 부족분만 중앙과 정산하는 방식을 쓴다."},{"t":"input","k":"sd2-429-code","cat":"security","q":"클라이언트가 레이트 리밋을 초과했을 때 서버가 반환하는 표준 HTTP 상태 코드는? (숫자만)","a":["429"],"ex":"레이트 리밋 초과는 429 Too Many Requests다.\n💡 개념: 429는 클라이언트에게 '요청이 너무 잦으니 잠시 뒤 재시도'를 알리는 표준 신호다.\n🛠 실무: 429와 함께 Retry-After 헤더를 주어 클라이언트가 언제 재시도할지 알 수 있게 한다."},{"t":"choice","k":"sd2-backpressure","cat":"ops","q":"다운스트림 결제 서비스가 느려지자 게이트웨이의 대기 큐가 무한정 쌓여 메모리가 터지고 지연이 눈덩이처럼 커졌다. 올바른 백프레셔 설계는?","o":["큐 크기를 무제한으로 두어 모든 요청을 받는다","큐에 상한을 두고 초과분은 429/즉시 거절하며, 서킷브레이커로 다운스트림을 보호","타임아웃을 없애 요청이 끝까지 기다리게 한다","재시도를 즉시·무한 반복해 성공할 때까지 보낸다"],"a":1,"ex":"백프레셔는 유한 큐+조기 거절+서킷브레이커로 구현한다. 무한 큐와 무한 재시도는 장애를 증폭한다.\n💡 개념: 부하가 처리 능력을 넘으면 빠르게 거절(load shedding)하는 것이 전체 지연 붕괴를 막는다.\n🛠 실무: 큐 대기 시간이 SLA를 넘길 요청은 미리 버리고(deadline), 재시도엔 지터 백오프와 서킷브레이커를 결합한다."},{"t":"choice","k":"sd2-ratelimit-key","cat":"security","q":"무료 API 남용을 막으려 레이트 리밋을 건다. 인증 전 공개 엔드포인트에서 IP 단위로만 제한할 때의 한계는?","o":["IP 제한은 항상 완벽하며 한계가 없다","NAT/프록시 뒤 다수 사용자가 한 IP를 공유하면 정상 사용자가 함께 막히고, 공격자는 IP를 돌려 우회할 수 있다","IP 제한은 인증된 사용자에게만 적용된다","IP 제한은 CPU를 과도하게 소모해 쓸 수 없다"],"a":1,"ex":"IP 단위 제한은 공유 IP에서 무고한 사용자를 막고, IP 로테이션엔 취약하다.\n💡 개념: 식별 단위(IP/API 키/사용자/디바이스)마다 오탐·우회 특성이 다르다.\n🛠 실무: 가능한 곳은 API 키·사용자 단위로 제한하고, 공개 엔드포인트는 IP+행동 기반 탐지를 병행한다."},{"t":"input","k":"sd2-token-refill","cat":"perf","q":"토큰 버킷 용량 20, 리필 속도 초당 5개다. 버킷이 가득 찬 상태에서 순간에 최대 몇 개의 요청을 즉시 통과시킬 수 있는가? (정수, 숫자만)","a":["20"],"ex":"버킷 용량이 20이므로 가득 찼을 때 순간 버스트 최대치는 20이다.\n💡 개념: 버킷 용량이 최대 버스트 크기를, 리필 속도가 지속 평균 속도를 결정한다.\n🛠 실무: 순간 버스트를 줄이려면 용량을, 장기 처리량을 조절하려면 리필률을 조정한다."}],"th":{"sum":"**레이트 리밋**은 버스트 허용과 평균 제한을 동시에 다루고, 분산 환경에선 카운터를 공유해야 정확하다. **백프레셔**로 과부하 전파를 막는다.","body":[{"h":"알고리즘 선택","t":"토큰 버킷은 버킷 용량만큼의 순간 버스트를 허용하면서 리필 속도로 장기 평균을 제한한다. 고정 윈도 카운터는 경계에서 두 배 통과가 가능한 결함이 있어(12:00:59 + 12:01:00), 슬라이딩 윈도로 보완한다. 초과 시 표준 응답은 429 Too Many Requests."},{"h":"분산 카운터와 백프레셔","t":"게이트웨이마다 로컬 카운터를 두면 전체 허용량이 인스턴스 수만큼 뻥튀기되므로, Redis 같은 공유 저장소에 카운터를 둔다. 다운스트림이 느려질 때 큐를 무한정 쌓으면 메모리·지연이 폭발하므로, 큐 상한 + 초과 시 즉시 거부(load shedding)로 백프레셔를 건다."}],"code":{"c":"토큰 버킷: capacity=20, refill=5/s\n가득 찬 상태 순간 버스트 = 20건 즉시 통과\n초과 응답: HTTP 429 Too Many Requests","cap":"버킷 용량이 곧 최대 순간 버스트"},"key":["토큰 버킷 = 버스트 허용 + 평균 제한","고정 윈도는 경계 2배 통과, 슬라이딩으로 보완","분산 리밋은 공유 카운터(Redis)로 정확히","백프레셔 = 큐 상한 + 초과 거부(load shedding), 429"]}}]},{"t":"메시지 큐·비동기 처리","l":[{"t":"전달 보장과 멱등성","q":[{"t":"choice","k":"sd2-at-least-once","cat":"design","q":"결제 이벤트를 큐로 처리한다. 대부분의 큐는 at-least-once를 보장하므로 같은 메시지가 재전달될 수 있다. 중복 결제를 막는 올바른 방법은?","o":["큐를 exactly-once로 설정하면 애플리케이션은 아무 처리도 필요 없다","컨슈머를 멱등(idempotent)하게 설계해 같은 이벤트가 여러 번 와도 결과가 한 번과 동일하게","재전달을 막기 위해 ACK를 아예 보내지 않는다","메시지를 받자마자 삭제하고 처리한다"],"a":1,"ex":"at-least-once 환경에서 중복은 컨슈머 멱등성으로 흡수한다. exactly-once는 대개 근사이며 앱의 멱등성이 실질 방어선이다.\n💡 개념: 재전달은 정상 동작의 일부이므로 '두 번 와도 안전한' 처리 설계가 핵심이다.\n🛠 실무: 이벤트마다 고유 ID를 두고 처리 완료 ID를 저장(dedup table)해 재처리 시 건너뛴다."},{"t":"input","k":"sd2-idempotency-key","cat":"design","q":"동일 요청이 여러 번 처리돼도 부작용이 한 번만 일어나게 하기 위해, 클라이언트가 요청에 실어 보내 서버가 중복을 식별하는 데 쓰는 키를 무엇이라 하는가? (영문 용어)","a":["idempotency key","idempotency-key","idempotencykey"],"ex":"중복 부작용을 막기 위한 식별자를 idempotency key라 한다.\n💡 개념: 서버는 이 키로 이미 처리한 요청을 인식해 재실행 대신 이전 결과를 반환한다.\n🛠 실무: 결제/주문 생성 API에 idempotency key를 받아 일정 기간 저장하고, 재시도 시 동일 응답을 준다."},{"t":"choice","k":"sd2-dlq","cat":"ops","q":"특정 메시지가 컨슈머에서 계속 예외를 던져 무한 재시도되며 파티션 처리를 막고 있다(poison message). 표준 대응은?","o":["그 메시지를 성공할 때까지 무한 재시도한다","최대 재시도 횟수 초과 시 DLQ(dead-letter queue)로 격리하고 나머지 처리를 계속 진행","컨슈머를 재시작하면 자동으로 해결된다","파티션 전체를 삭제한다"],"a":1,"ex":"반복 실패 메시지는 DLQ로 격리해 정상 처리 흐름을 막지 않게 한다.\n💡 개념: 독성 메시지를 무한 재시도하면 헤드-오브-라인 블로킹으로 전체가 멈춘다.\n🛠 실무: DLQ 항목엔 실패 원인·재시도 이력을 남기고, 별도 프로세스로 원인 분석·재처리한다."},{"t":"choice","k":"sd2-ordering","cat":"design","q":"한 사용자의 이벤트는 반드시 발생 순서대로 처리돼야 하지만 전체 시스템 처리량도 높여야 한다. Kafka 같은 파티션 큐에서의 적절한 설계는?","o":["파티션을 1개만 두어 전역 순서를 보장한다","user_id를 파티션 키로 삼아 같은 사용자는 같은 파티션(순서 보장), 서로 다른 사용자는 병렬 처리","순서는 포기하고 타임스탬프로 사후 정렬만 한다","모든 이벤트를 랜덤 파티션에 보낸다"],"a":1,"ex":"파티션 큐는 파티션 내에서만 순서를 보장하므로, 순서가 필요한 단위(user_id)를 파티션 키로 삼는다.\n💡 개념: 순서 보장 범위를 키로 좁히면 서로 다른 키는 병렬화해 처리량을 유지할 수 있다.\n🛠 실무: 파티션 키 선택이 곧 순서 보장 단위이자 병렬성 상한이므로 도메인 키를 신중히 고른다."},{"t":"choice","k":"sd2-mq-backpressure","cat":"ops","q":"프로듀서가 컨슈머 처리 속도보다 훨씬 빠르게 메시지를 쌓아 큐 적체(consumer lag)가 계속 커진다. 지속 가능한 대응은?","o":["큐 용량이 무한하니 신경 쓰지 않아도 된다","컨슈머를 수평 확장(파티션·컨슈머 그룹 증설)하고, 필요 시 프로듀서에 백프레셔를 전달","메시지 TTL을 무한으로 두어 모두 보관한다","컨슈머 배치 크기를 1로 줄여 처리량을 낮춘다"],"a":1,"ex":"지속적 lag 증가는 컨슈머 처리량 부족이므로 컨슈머·파티션을 늘리고, 그래도 부족하면 프로듀서 유입을 조절한다.\n💡 개념: 큐는 일시적 버스트를 흡수하는 완충일 뿐, 평균 유입&gt;처리면 적체는 무한히 커진다.\n🛠 실무: consumer lag을 핵심 지표로 알림을 걸고, 파티션 수를 병렬성 상한으로 미리 넉넉히 잡는다."},{"t":"choice","k":"sd2-outbox","cat":"design","q":"DB에 주문을 저장하고 곧바로 큐에 이벤트를 발행하는데, 커밋은 됐지만 발행 직전 프로세스가 죽어 이벤트가 유실됐다. 이 이중 쓰기 문제의 정석 해법은?","o":["발행을 먼저 하고 나서 DB에 커밋한다","transactional outbox: 같은 DB 트랜잭션에 이벤트를 outbox 테이블로 저장하고, 별도 릴레이가 이를 읽어 큐로 발행","DB와 큐 발행을 두 개의 독립 트랜잭션으로 나눈다","이벤트 유실은 불가피하므로 무시한다"],"a":1,"ex":"DB 커밋과 메시지 발행의 원자성 결여(이중 쓰기)는 transactional outbox 패턴으로 해결한다.\n💡 개념: 이벤트를 업무 데이터와 같은 트랜잭션으로 저장하면 커밋된 이벤트는 반드시 발행 대상이 된다.\n🛠 실무: CDC나 폴링 릴레이가 outbox를 읽어 발행하고, at-least-once이므로 컨슈머는 멱등하게 둔다."},{"t":"input","k":"sd2-lag-drain","cat":"perf","q":"큐에 60만 건이 적체됐고 컨슈머 전체 처리량이 초당 1,000건이다. 신규 유입이 없다고 가정할 때 적체를 모두 소진하는 데 걸리는 시간은 몇 초인가? (정수, 숫자만)","a":["600"],"ex":"600,000 / 1,000 = 600초.\n💡 개념: 소진 시간 = 적체량 / 순처리량(처리 - 유입). 유입이 있으면 순처리량으로 나눠야 한다.\n🛠 실무: 유입이 계속되면 (처리량-유입량)이 양수여야 적체가 줄고, 0 이하이면 확장 없이는 영원히 못 따라잡는다."}],"th":{"sum":"메시지 큐는 보통 **at-least-once**라 재전달이 생긴다. **멱등성**·멱등키·DLQ·아웃박스가 안전한 비동기 처리의 축이다.","body":[{"h":"멱등성과 순서","t":"at-least-once에서 같은 메시지가 재전달되므로, 소비자를 멱등하게 만들어야 중복 결제를 막는다. 클라이언트가 실어 보내 서버가 중복을 식별하는 값이 멱등키(idempotency key)다. Kafka에서 한 사용자 이벤트의 순서 보장은 그 사용자 키로 파티셔닝해 같은 파티션에 넣되, 파티션 수로 전체 처리량을 높인다."},{"h":"poison·lag·이중 쓰기","t":"특정 메시지가 계속 예외로 무한 재시도되면(poison message) 재시도 한도 후 DLQ(데드레터 큐)로 격리한다. 컨슈머 lag이 계속 커지면 컨슈머 스케일아웃·파티션 증설로 대응한다. DB 커밋 후 발행 전 프로세스가 죽어 이벤트가 유실되는 이중 쓰기 문제는 트랜잭셔널 아웃박스 패턴으로 해결한다."}],"code":{"c":"소진 시간 = 60만 / 1,000 = 600초\n\n순서 보장: partition_key = user_id (같은 파티션)\n무한 실패: 재시도 N회 → DLQ 격리\n이중 쓰기: DB tx 안에 outbox 저장 → 릴레이가 발행","cap":"적체 소진 계산과 큐 신뢰성 패턴"},"key":["at-least-once → 소비자 멱등성 필수","멱등키로 중복 요청 식별","poison message는 DLQ로 격리","이중 쓰기는 transactional outbox로 해결"]}}]},{"t":"로드밸런싱·CDN·가용성","l":[{"t":"부하 분산과 고가용성","q":[{"t":"choice","k":"sd2-l4-vs-l7","cat":"design","q":"URL 경로별로 다른 백엔드로 라우팅하고 헤더 기반 A/B 라우팅과 TLS 종료도 필요하다. 적절한 로드밸런서 계층은?","o":["L4(전송 계층): IP/포트 기준으로만 분산, 애플리케이션 내용은 모름","L7(애플리케이션 계층): HTTP 경로·헤더·쿠키 기반 라우팅과 TLS 종료 가능","DNS 라운드로빈만으로 경로 기반 라우팅이 가능하다","L2 스위칭으로 헤더 라우팅을 처리한다"],"a":1,"ex":"경로·헤더 기반 라우팅과 TLS 종료는 L7 로드밸런서의 영역이다. L4는 콘텐츠를 보지 않아 이런 라우팅이 불가능하다.\n💡 개념: L4는 빠르고 단순하며, L7은 콘텐츠 인지 라우팅·기능이 풍부한 대신 처리 비용이 있다.\n🛠 실무: 대량 TCP 스루풋엔 L4, 마이크로서비스 라우팅·인증·A/B엔 L7을 조합해 쓴다."},{"t":"choice","k":"sd2-health-check","cat":"ops","q":"헬스체크를 '/'가 200을 반환하는지로만 확인했더니, 백엔드는 살아 있지만 DB 연결이 끊긴 상태에서도 트래픽을 계속 받아 오류가 났다. 개선책은?","o":["헬스체크 주기를 1시간으로 늘린다","핵심 의존성(DB 등) 상태까지 확인하는 심층(readiness) 헬스체크를 두어 준비 안 된 노드를 풀에서 제외","헬스체크를 아예 없앤다","'/'가 아니라 정적 파일 존재만 확인한다"],"a":1,"ex":"얕은 헬스체크는 의존성 장애를 놓치므로, 준비 상태(readiness)를 반영하는 심층 체크가 필요하다.\n💡 개념: liveness(프로세스 살았나)와 readiness(트래픽 받을 준비됐나)를 구분해야 한다.\n🛠 실무: readiness는 DB·캐시 연결을 점검하되, 과도한 연쇄 체크로 한 의존성 장애가 전체 노드 배제를 부르지 않게 균형을 잡는다."},{"t":"input","k":"sd2-spof","cat":"ops","q":"장애 시 시스템 전체가 멈추게 만드는 '단일 장애점'을 뜻하는 영문 약어는?","a":["spof","single point of failure"],"ex":"단일 장애점은 SPOF(Single Point Of Failure)다.\n💡 개념: 이중화되지 않은 컴포넌트는 그 하나가 죽으면 전체 가용성을 무너뜨린다.\n🛠 실무: 로드밸런서·DB·게이트웨이 등 경로상의 모든 단일 지점을 이중화하거나 페일오버 대상을 둔다."},{"t":"choice","k":"sd2-cdn-cache","cat":"perf","q":"전 세계 사용자에게 이미지·JS 등 정적 자산을 빠르게 제공해야 한다. CDN을 도입할 때 원본(origin) 부하를 낮추는 핵심 원리는?","o":["CDN은 요청마다 항상 원본에서 다시 받아온다","엣지 노드가 자산을 캐시해 사용자 근처에서 응답하고, 캐시 만료 전까지 원본 요청을 크게 줄인다","CDN은 동적 API 응답만 캐시하고 정적 파일은 캐시하지 않는다","CDN은 지연을 늘리는 대신 대역폭만 절약한다"],"a":1,"ex":"CDN은 엣지 캐시로 사용자 근처에서 응답해 지연과 원본 부하를 동시에 줄인다.\n💡 개념: 캐시 hit는 원본에 도달하지 않으므로 origin 트래픽이 hit율만큼 감소한다.\n🛠 실무: Cache-Control/ETag로 TTL과 재검증을 제어하고, 배포 시 파일명 해시(버전) 무효화로 stale 자산을 피한다."},{"t":"choice","k":"sd2-multi-az","cat":"ops","q":"단일 가용 영역(AZ)에만 배포한 서비스가 그 AZ 정전으로 완전히 멈췄다. 가용성을 높이는 설계는?","o":["같은 AZ에 인스턴스를 2배로 늘린다","여러 AZ에 걸쳐 배포하고 AZ 간 로드밸런싱·데이터 복제로 한 AZ 장애를 견디게 한다","인스턴스 사양을 더 큰 것으로 교체한다","재해 복구는 백업 복원만으로 충분하다"],"a":1,"ex":"AZ 단위 장애를 견디려면 multi-AZ 배포와 AZ 간 복제가 필요하다. 같은 AZ 증설은 그 AZ 장애를 못 막는다.\n💡 개념: 장애 격리 경계(AZ/리전)를 넘어 분산해야 그 경계의 장애를 흡수할 수 있다.\n🛠 실무: 상태 저장소는 AZ 간 동기/준동기 복제로 두고, 페일오버 시 데이터 손실 목표(RPO)와 복구 시간(RTO)을 명시한다."},{"t":"choice","k":"sd2-failover","cat":"ops","q":"액티브-스탠바이 DB에서 마스터 장애 시 스탠바이로 자동 승격(failover)한다. 이때 흔히 발생하는 위험과 대비책은?","o":["페일오버는 위험이 전혀 없어 별도 대비가 불필요하다","네트워크 분단으로 양쪽이 서로 마스터가 되는 split-brain 위험이 있어, 쿼럼/펜싱으로 단일 마스터를 강제","스탠바이는 승격 즉시 항상 최신 데이터를 갖는다","failover 후에는 롤백이 불가능하므로 하지 않는 게 낫다"],"a":1,"ex":"자동 페일오버의 대표 위험은 split-brain(양쪽 마스터)이며, 쿼럼 합의와 펜싱으로 단일 마스터를 강제해 방지한다.\n💡 개념: 분단 시 '아직 살아 있는데 죽었다고 판단'하면 이중 마스터로 데이터가 갈라진다.\n🛠 실무: 홀수 노드 쿼럼, 리스(lease)/펜싱 토큰으로 옛 마스터의 쓰기를 차단하고, 준동기 복제로 승격 시 손실을 줄인다."},{"t":"input","k":"sd2-nines","cat":"perf","q":"가용성 목표가 99.9%(three nines)일 때, 30일(=43,200분) 기준 허용되는 월간 다운타임은 대략 몇 분인가? (정수, 숫자만)","a":["43","43.2"],"ex":"43,200분 × 0.001 = 43.2분 ≈ 약 43분.\n💡 개념: 허용 다운타임 = 총 시간 × (1 - 가용성). 나인이 하나 늘 때마다 허용 다운타임은 1/10로 줄어든다.\n🛠 실무: 99.99%면 월 약 4.3분으로 급격히 빡빡해지므로, 목표 나인에 맞춰 이중화·자동 페일오버 수준을 정한다."}],"th":{"sum":"가용성 설계는 **SPOF 제거**, 다중 AZ, 제대로 된 헬스체크가 핵심이다. **CDN**은 엣지 캐싱으로 오리진 부하와 지연을 함께 낮춘다.","body":[{"h":"로드밸런싱과 헬스체크","t":"URL 경로·헤더 기반 라우팅과 TLS 종료는 L7(애플리케이션 계층) 로드밸런서가 담당한다. 헬스체크를 `/`의 200만 보면 DB 끊긴 인스턴스도 트래픽을 받으므로, 의존성까지 확인하는 딥 헬스체크(예: /healthz가 DB 연결 확인)를 써야 한다."},{"h":"다중화와 CDN","t":"단일 AZ 배포는 그 AZ 정전에 전멸하므로 여러 AZ에 분산한다. DB 액티브-스탠바이 failover 시 split-brain·데이터 유실 위험이 있어 펜싱·정족수 기반 승격으로 대비한다. CDN은 정적 자산을 엣지에 캐싱해 오리진 요청 자체를 줄이는 것이 핵심 원리다."}],"code":{"c":"가용성 99.9% → 월 다운타임\n= 43,200분 × (1 - 0.999)\n= 43,200 × 0.001 ≈ 43분","cap":"three nines는 월 약 43분의 다운타임 허용"},"key":["L7 LB = 경로/헤더 라우팅 + TLS 종료","헬스체크는 의존성까지 보는 딥 체크로","SPOF 제거 + 다중 AZ로 가용성 확보","CDN 핵심 = 엣지 캐싱으로 오리진 부하 절감"]}}]},{"t":"용량 추정과 기본 빌딩블록","l":[{"t":"용량 추정 (QPS·저장량)","q":[{"t":"choice","k":"dau-qps","cat":"design","q":"DAU 1억, 사용자당 하루 평균 20건 쓰기 요청인 서비스의 평균 쓰기 QPS는 대략 얼마인가? (하루 86,400초)","o":["약 230 QPS","약 2,300 QPS","약 23,000 QPS","약 230,000 QPS"],"a":2,"ex":"1억×20 = 20억 요청/일, 20억/86,400 ≈ 23,000 QPS.\n💡 개념: QPS = 일일 요청수 / 86,400. 총 요청 = DAU × 사용자당 요청수.\n🛠 실무: 계산 결과는 평균값이며, 실제 설계는 피크 대비를 위해 평균의 2~10배를 안전 마진으로 잡는다."},{"t":"choice","k":"peak-qps","cat":"design","q":"평균 QPS가 5,000인 서비스에서 피크 시간대 트래픽이 평균의 4배로 몰린다. 용량 설계 시 기준으로 삼아야 할 QPS는?","o":["평균 그대로 5,000","피크 20,000","최소값 1,250","평균과 피크의 산술평균 12,500"],"a":1,"ex":"용량 산정은 피크 기준으로 해야 장애를 막는다. 5,000×4 = 20,000 QPS.\n💡 개념: 평균이 아닌 피크(peak) QPS로 서버 수와 커넥션 풀을 계산한다.\n🛠 실무: 피크 대비 여유(headroom)를 추가로 20~30% 확보하고, 오토스케일링으로 평시 비용을 절감한다."},{"t":"input","k":"storage-daily","cat":"design","q":"하루 100만 개의 게시물이 생성되고 게시물당 평균 1KB를 저장한다. 복제나 인덱스를 무시할 때 하루에 늘어나는 순수 데이터 저장량은 몇 GB인가? (숫자만, 1GB=10^6 KB로 근사)","a":["1","1GB","약 1"],"ex":"100만 × 1KB = 100만 KB = 1GB.\n💡 개념: 일일 저장량 = 일일 항목수 × 항목당 크기. 장기 저장량은 여기에 일수를 곱한다.\n🛠 실무: 실제로는 복제 계수(예: 3배)와 인덱스, 메타데이터를 곱해야 하므로 실제 사용량은 추정치의 수 배가 된다."},{"t":"choice","k":"read-write-ratio","cat":"design","q":"뉴스피드처럼 읽기가 쓰기의 100배인 서비스를 설계할 때 가장 먼저 고려해야 할 확장 전략은?","o":["쓰기 마스터를 여러 대로 늘려 쓰기 분산","읽기 복제본과 캐시 계층으로 읽기 부하 분산","모든 요청을 단일 DB로 강한 일관성 유지","트랜잭션 격리 수준을 SERIALIZABLE로 상향"],"a":1,"ex":"읽기 우세(read-heavy) 워크로드는 읽기 복제본과 캐시로 확장하는 것이 핵심이다.\n💡 개념: read:write 비율은 읽기 복제/캐시 vs 샤딩 중 무엇을 우선할지 결정한다.\n🛠 실무: 읽기 100:1이면 캐시 히트율을 높여 원본 DB 부하를 90% 이상 줄이는 것이 비용 효율적이다."},{"t":"input","k":"bandwidth","cat":"design","q":"평균 QPS가 10,000이고 응답 하나당 평균 200KB를 전송하는 API 서버의 아웃바운드 대역폭은 초당 몇 GB인가? (숫자만, 1GB=10^6 KB 근사)","a":["2","2GB","약 2"],"ex":"10,000 × 200KB = 200만 KB/s = 2GB/s.\n💡 개념: 대역폭 = QPS × 응답 크기. 저장량 추정과 함께 네트워크 병목을 사전에 파악한다.\n🛠 실무: 대용량 응답은 CDN 오프로드와 gzip/brotli 압축으로 원본 대역폭을 크게 절감한다."}],"th":{"sum":"**용량 추정**은 QPS·저장량·대역폭을 어림해 설계 규모를 정하는 첫 단계이고, **스테이트리스** 서버는 수평 확장의 전제다.","body":[{"h":"봉투 뒷면 계산","t":"평균 QPS ≈ (DAU × 사용자당 요청수) / 86,400초 로 어림한다. 피크는 평균의 몇 배로 몰리므로(보통 2~5배) 용량은 `평균 × 피크배수`를 기준으로 잡아야 한다. 저장량은 `건수 × 건당 크기`, 대역폭은 `QPS × 응답크기`로 계산한다."},{"h":"스테이트리스와 수평 확장","t":"세션을 서버 로컬 메모리에 두면 수평 확장 시 요청이 다른 서버로 가 상태를 잃는다(로그아웃). 근본 해법은 세션을 Redis 같은 외부 저장소로 빼는 것이다. 급할 땐 로드밸런서의 sticky session(세션 어피니티)으로 임시 봉합할 수 있으나, 서버 다운 시 여전히 상태를 잃는다."}],"code":{"c":"평균 쓰기 QPS = 1억 × 20 / 86,400 ≈ 23,000\n피크 QPS = 평균 × 4 (피크 배수)\n저장량/일 = 100만 × 1KB ≈ 1GB","cap":"DAU·요청수로 QPS와 저장량을 어림하는 예"},"key":["QPS = 총요청 / 86,400, 용량은 피크(평균×배수) 기준","읽기가 쓰기의 100배면 캐시·읽기복제 우선","세션을 외부화해야 진짜 스테이트리스·수평 확장","sticky session은 임시방편, 서버 장애엔 무력"]}},{"t":"로드밸런서·스테이트리스·수평 확장","q":[{"t":"choice","k":"stateless-scale","cat":"design","q":"웹 서버가 로그인 세션을 각 서버의 로컬 메모리에 저장하고 있다. 서버를 3대로 수평 확장했더니 사용자가 자꾸 로그아웃된다. 근본 원인과 올바른 해법은?","o":["LB 알고리즘을 랜덤으로 변경한다","세션을 Redis 등 외부 저장소로 옮겨 서버를 스테이트리스로 만든다","서버 메모리를 늘려 세션을 더 오래 유지한다","서버를 다시 1대로 줄인다"],"a":1,"ex":"로컬 세션은 상태를 서버에 묶어 수평 확장을 방해한다. 세션을 외부(Redis)로 분리해 스테이트리스로 만든다.\n💡 개념: 스테이트리스 서버는 어느 인스턴스로 요청이 가도 동일하게 처리되어 자유로운 수평 확장이 가능하다.\n🛠 실무: 세션을 외부화하거나 JWT 같은 무상태 토큰을 쓰면 배포·오토스케일·롤링 업데이트가 안전해진다."},{"t":"choice","k":"sticky-session","cat":"design","q":"세션을 아직 외부화하지 못한 상태에서 급하게 수평 확장을 해야 한다. 임시방편으로 로드밸런서에 적용할 수 있는 기능은?","o":["라운드로빈으로 균등 분산","스티키 세션(세션 어피니티)","최소 연결 수 기반 분산","가중치 기반 분산"],"a":1,"ex":"스티키 세션은 같은 사용자를 항상 같은 서버로 보내 로컬 세션 문제를 임시로 회피한다.\n💡 개념: 세션 어피니티는 상태를 특정 서버에 고정하지만, 그 서버 장애 시 세션이 유실된다.\n🛠 실무: 스티키는 부하 불균형과 확장 유연성 저하를 유발하므로 세션 외부화까지의 임시 조치로만 쓴다."},{"t":"choice","k":"lb-l4-l7","cat":"design","q":"URL 경로(/api vs /static)에 따라 서로 다른 서버 그룹으로 트래픽을 라우팅하려 한다. 필요한 로드밸런서 계층은?","o":["L4(전송 계층) 로드밸런서","L7(애플리케이션 계층) 로드밸런서","DNS 라운드로빈만으로 충분","단순 TCP 프록시"],"a":1,"ex":"경로·헤더·쿠키 기반 라우팅은 HTTP를 이해하는 L7 로드밸런서가 필요하다.\n💡 개념: L4는 IP/포트 기반으로 빠르지만 콘텐츠를 못 본다. L7은 콘텐츠 기반 라우팅과 TLS 종료가 가능하다.\n🛠 실무: L4는 처리량과 지연에 유리하고 L7은 유연성에 유리하다. 대규모는 L4 앞단 + L7 뒷단 조합을 쓴다."},{"t":"choice","k":"health-check","cat":"design","q":"로드밸런서가 죽은 서버로 계속 트래픽을 보내 502 에러가 발생한다. 이를 막는 로드밸런서의 핵심 메커니즘은?","o":["헬스 체크로 비정상 인스턴스를 풀에서 자동 제외","TTL을 낮춰 DNS 캐시 갱신","연결 타임아웃을 무한대로 설정","클라이언트에 재시도 로직 추가"],"a":0,"ex":"헬스 체크가 실패한 인스턴스를 자동으로 라우팅 대상에서 제거해 정상 서버로만 트래픽을 보낸다.\n💡 개념: 헬스 체크(액티브/패시브)는 자동 장애 격리의 기본이다.\n🛠 실무: 헬스 체크 경로는 DB 등 의존성까지 얕게 확인하되 과도한 확인은 헬스 체크 폭풍을 유발하니 주기와 임계값을 조율한다."},{"t":"input","k":"vertical-vs-horizontal","cat":"design","q":"한 대의 서버 사양(CPU/메모리)을 키워 성능을 올리는 확장 방식을 무엇이라 하는가? (수직/수평 중 한 단어)","a":["수직","수직 확장","vertical","scale up","스케일업"],"ex":"단일 노드의 사양을 키우는 것은 수직 확장(scale up)이다.\n💡 개념: 수직 확장은 단순하지만 하드웨어 상한과 단일 장애점 한계가 있다. 수평 확장(scale out)은 노드를 늘려 사실상 무한 확장한다.\n🛠 실무: 초기엔 수직 확장이 빠르고 저렴하지만, 대규모에서는 스테이트리스 설계 기반 수평 확장이 표준이다."}],"th":{"sum":"**용량 추정**은 QPS·저장량·대역폭을 어림해 설계 규모를 정하는 첫 단계이고, **스테이트리스** 서버는 수평 확장의 전제다.","body":[{"h":"봉투 뒷면 계산","t":"평균 QPS ≈ (DAU × 사용자당 요청수) / 86,400초 로 어림한다. 피크는 평균의 몇 배로 몰리므로(보통 2~5배) 용량은 `평균 × 피크배수`를 기준으로 잡아야 한다. 저장량은 `건수 × 건당 크기`, 대역폭은 `QPS × 응답크기`로 계산한다."},{"h":"스테이트리스와 수평 확장","t":"세션을 서버 로컬 메모리에 두면 수평 확장 시 요청이 다른 서버로 가 상태를 잃는다(로그아웃). 근본 해법은 세션을 Redis 같은 외부 저장소로 빼는 것이다. 급할 땐 로드밸런서의 sticky session(세션 어피니티)으로 임시 봉합할 수 있으나, 서버 다운 시 여전히 상태를 잃는다."}],"code":{"c":"평균 쓰기 QPS = 1억 × 20 / 86,400 ≈ 23,000\n피크 QPS = 평균 × 4 (피크 배수)\n저장량/일 = 100만 × 1KB ≈ 1GB","cap":"DAU·요청수로 QPS와 저장량을 어림하는 예"},"key":["QPS = 총요청 / 86,400, 용량은 피크(평균×배수) 기준","읽기가 쓰기의 100배면 캐시·읽기복제 우선","세션을 외부화해야 진짜 스테이트리스·수평 확장","sticky session은 임시방편, 서버 장애엔 무력"]}}]},{"t":"데이터 계층 확장","l":[{"t":"읽기 복제·샤딩","q":[{"t":"choice","k":"read-replica-lag","cat":"design","q":"사용자가 프로필을 수정한 직후 다시 조회했더니 옛날 값이 보인다. 읽기 복제본 구조에서 발생하는 이 현상의 원인과 해법은?","o":["복제 지연(replication lag) 때문이며, 방금 쓴 사용자는 마스터에서 읽는다(read-your-writes)","캐시 미스이며 캐시를 삭제한다","샤드 키 오류이며 리샤딩한다","네트워크 문제이며 재시도만 한다"],"a":0,"ex":"비동기 복제는 지연이 있어 방금 쓴 데이터가 복제본에 아직 없을 수 있다. 자기 쓰기 읽기 보장을 적용한다.\n💡 개념: 읽기 복제본은 최종 일관성을 제공하므로 복제 지연 동안 낡은 데이터가 보일 수 있다.\n🛠 실무: 쓰기 직후 일정 시간은 마스터에서 읽거나, 세션 고정으로 read-your-writes를 보장한다."},{"t":"choice","k":"shard-key","cat":"design","q":"주문 테이블을 샤딩할 때 order_id 자동증가값을 샤드 키로 쓰면 어떤 문제가 생기는가?","o":["조회가 느려진다","최신 주문이 항상 마지막 샤드에 몰려 핫스팟이 발생한다","데이터가 유실된다","트랜잭션이 불가능해진다"],"a":1,"ex":"순차 증가 키로 범위 샤딩하면 최신 쓰기가 한 샤드에 집중되어 핫스팟이 생긴다.\n💡 개념: 좋은 샤드 키는 카디널리티가 높고 쓰기가 고르게 분산되어야 한다.\n🛠 실무: 해시 샤딩이나 user_id 기반 키로 분산하되, 크로스 샤드 조인이 필요한 접근 패턴을 함께 고려해 키를 고른다."},{"t":"choice","k":"resharding","cat":"design","q":"샤드 수를 4개에서 8개로 늘릴 때 hash(key) % N 방식의 가장 큰 문제는?","o":["해시 충돌이 늘어난다","N이 바뀌면 거의 모든 키의 소속 샤드가 바뀌어 대규모 데이터 이동이 발생한다","키가 유실된다","조회가 불가능해진다"],"a":1,"ex":"모듈로 샤딩은 노드 수 변경 시 대부분의 키가 재배치되어야 해 리샤딩 비용이 크다.\n💡 개념: 일관된 해싱(consistent hashing)은 노드 추가/삭제 시 영향받는 키를 1/N 수준으로 최소화한다.\n🛠 실무: 미리 논리 샤드(예: 1024개)를 만들어 물리 노드에 매핑하면 리샤딩이 논리 샤드 이동만으로 끝난다."},{"t":"input","k":"consistent-hashing","cat":"design","q":"노드를 추가/제거할 때 재배치되는 키를 최소화하기 위해 분산 캐시·샤딩에서 널리 쓰는 해싱 기법의 이름은? (한글 또는 영문)","a":["일관된 해싱","컨시스턴트 해싱","consistent hashing","consistent-hashing"],"ex":"링 구조로 키와 노드를 배치하는 일관된 해싱이 정답이다.\n💡 개념: 일관된 해싱은 노드 변경 시 인접 구간의 키만 이동해 리밸런싱 비용을 크게 줄인다.\n🛠 실무: 가상 노드(virtual node)를 도입해 물리 노드 간 부하 불균형을 완화하는 것이 표준 구현이다."},{"t":"choice","k":"cross-shard","cat":"design","q":"user_id로 샤딩된 소셜 서비스에서 '특정 지역 사용자 전체 집계' 쿼리가 매우 느리다. 원인은?","o":["샤드 키(user_id)와 다른 축(지역)의 쿼리라 모든 샤드를 스캐터-개더해야 하기 때문","인덱스가 없어서","복제 지연 때문","캐시 미스 때문"],"a":0,"ex":"샤드 키와 무관한 조건의 조회는 전 샤드를 조회(scatter-gather)해야 하므로 느리다.\n💡 개념: 샤딩은 접근 패턴을 고정한다. 샤드 키 축 조회는 빠르지만 다른 축은 팬아웃이 필요하다.\n🛠 실무: 자주 쓰는 다른 축 조회는 별도 인덱스 테이블이나 검색엔진(ES) 비정규화 뷰로 미리 준비한다."}],"th":{"sum":"데이터 계층 확장은 **읽기 복제**와 **샤딩**, 그리고 캐싱으로 이룬다. 복제 지연·샤드 키·리샤딩·stampede가 대표 함정이다.","body":[{"h":"복제와 샤딩","t":"읽기 복제본은 비동기 복제 지연 때문에 방금 쓴 값을 못 읽는 read-your-writes 위반이 생긴다. 쓰기 직후는 프라이머리에서 읽거나 세션 고정으로 해결한다. 샤드 키를 자동증가 order_id로 쓰면 최신 샤드에 쓰기가 몰리고(핫스팟), `hash(key) % N`은 N을 바꾸면 대부분 키가 재배치된다. 그래서 컨시스턴트 해싱을 쓴다."},{"h":"캐싱 패턴","t":"가장 보편적인 패턴은 cache-aside(look-aside): 앱이 캐시를 먼저 보고 miss면 DB에서 읽어 캐시에 채운다. 인기 상품 캐시가 만료되는 순간 요청이 DB로 몰리는 cache stampede는 뮤텍스·조기 갱신·TTL 지터로 막는다. user_id 샤딩에서 지역 전체 집계는 모든 샤드를 훑는 scatter-gather라 느리다."}],"code":{"c":"hash(key) % 4  → % 8 로 변경 시 대부분 키 이동\n대안: consistent hashing (재배치 최소화)\n\n타임라인 저장량 = 2억 × 800 × 16B ≈ 2.56TB","cap":"모듈로 샤딩의 리샤딩 문제와 대안"},"key":["복제 지연 → read-your-writes 위반, 쓰기 후 프라이머리 읽기","hash%N은 리샤딩 취약, consistent hashing 사용","cache-aside = miss 시 DB→캐시 채움","stampede는 뮤텍스/TTL 지터로 완화"]}},{"t":"캐시·CDN·핫키","q":[{"t":"choice","k":"cache-aside","cat":"design","q":"애플리케이션이 먼저 캐시를 조회하고 없으면 DB에서 읽어 캐시에 채운 뒤 반환하는 가장 보편적인 캐싱 패턴은?","o":["Write-through","Cache-aside(Lazy loading)","Write-behind","Read-through 전용 프록시"],"a":1,"ex":"조회 시점에 필요할 때만 캐시를 채우는 방식이 캐시 어사이드(lazy loading)다.\n💡 개념: cache-aside는 앱이 캐시를 직접 관리하며 실제로 요청된 데이터만 캐싱한다.\n🛠 실무: 캐시 미스 시 DB 부하와 캐시 스탬피드를 막기 위해 TTL 지터와 뮤텍스(single-flight)를 함께 쓴다."},{"t":"choice","k":"cache-stampede","cat":"design","q":"인기 상품 캐시가 만료되는 순간 수천 개의 요청이 동시에 DB로 몰려 DB가 다운됐다. 이 현상의 이름과 완화책은?","o":["복제 지연 / 복제본 추가","캐시 스탬피드(썬더링 허드) / 단일 재계산 락과 TTL 지터","핫키 / 샤딩","캐시 오염 / 캐시 삭제"],"a":1,"ex":"동시 만료로 재계산 요청이 폭주하는 캐시 스탬피드다. 락으로 한 요청만 재계산하고 나머지는 대기시킨다.\n💡 개념: 썬더링 허드는 만료 순간 동시 미스가 원본으로 몰리는 문제다.\n🛠 실무: single-flight 락, TTL에 랜덤 지터, 만료 전 백그라운드 갱신(refresh-ahead)으로 완화한다."},{"t":"choice","k":"hot-key","cat":"design","q":"유명인 게시물처럼 특정 캐시 키 하나에 트래픽이 집중되어 그 키를 가진 Redis 노드만 CPU가 100%다. 이 핫키 문제의 해법은?","o":["TTL을 늘린다","키를 여러 복제본으로 분산 저장하거나 로컬 캐시로 앞단에 흡수한다","샤드 키를 바꾼다","캐시를 끈다"],"a":1,"ex":"단일 핫키는 샤딩으로 나눌 수 없으므로 키 복제나 앱 로컬 캐시로 부하를 분산한다.\n💡 개념: 핫키는 부하가 한 슬롯에 몰려 수평 확장으로 해결되지 않는 특수 케이스다.\n🛠 실무: key-v1..v10처럼 값을 복제해 무작위 읽기로 분산하거나, 다계층 캐시(L1 로컬 + L2 Redis)로 원본 접근을 줄인다."},{"t":"choice","k":"cdn","cat":"design","q":"전 세계 사용자에게 이미지·JS·CSS 정적 파일을 낮은 지연으로 제공하려 한다. 가장 적합한 계층은?","o":["원본 서버 수직 확장","CDN(엣지 캐시)","DB 읽기 복제본","메시지 큐"],"a":1,"ex":"정적 자산은 사용자와 가까운 엣지에 캐싱하는 CDN이 지연과 원본 부하를 동시에 낮춘다.\n💡 개념: CDN은 지리적으로 분산된 엣지 노드에서 콘텐츠를 캐싱해 RTT를 줄인다.\n🛠 실무: 자산에 콘텐츠 해시 파일명(cache busting)과 긴 TTL을 함께 써서 캐시 무효화 문제를 회피한다."},{"t":"input","k":"eviction-lru","cat":"design","q":"캐시 용량이 가득 찼을 때 '가장 오래 사용되지 않은' 항목을 먼저 제거하는 축출 정책의 약어는?","a":["LRU","lru","Least Recently Used"],"ex":"Least Recently Used, 즉 LRU 정책이다.\n💡 개념: LRU는 최근성(recency) 기반 축출로 일반 워크로드에서 히트율이 좋다.\n🛠 실무: 스캔성 트래픽이 많으면 LRU가 오염되므로 LFU나 LRU-K, ARC 같은 정책을 고려한다."}],"th":{"sum":"데이터 계층 확장은 **읽기 복제**와 **샤딩**, 그리고 캐싱으로 이룬다. 복제 지연·샤드 키·리샤딩·stampede가 대표 함정이다.","body":[{"h":"복제와 샤딩","t":"읽기 복제본은 비동기 복제 지연 때문에 방금 쓴 값을 못 읽는 read-your-writes 위반이 생긴다. 쓰기 직후는 프라이머리에서 읽거나 세션 고정으로 해결한다. 샤드 키를 자동증가 order_id로 쓰면 최신 샤드에 쓰기가 몰리고(핫스팟), `hash(key) % N`은 N을 바꾸면 대부분 키가 재배치된다. 그래서 컨시스턴트 해싱을 쓴다."},{"h":"캐싱 패턴","t":"가장 보편적인 패턴은 cache-aside(look-aside): 앱이 캐시를 먼저 보고 miss면 DB에서 읽어 캐시에 채운다. 인기 상품 캐시가 만료되는 순간 요청이 DB로 몰리는 cache stampede는 뮤텍스·조기 갱신·TTL 지터로 막는다. user_id 샤딩에서 지역 전체 집계는 모든 샤드를 훑는 scatter-gather라 느리다."}],"code":{"c":"hash(key) % 4  → % 8 로 변경 시 대부분 키 이동\n대안: consistent hashing (재배치 최소화)\n\n타임라인 저장량 = 2억 × 800 × 16B ≈ 2.56TB","cap":"모듈로 샤딩의 리샤딩 문제와 대안"},"key":["복제 지연 → read-your-writes 위반, 쓰기 후 프라이머리 읽기","hash%N은 리샤딩 취약, consistent hashing 사용","cache-aside = miss 시 DB→캐시 채움","stampede는 뮤텍스/TTL 지터로 완화"]}}]},{"t":"비동기·큐·스토리지","l":[{"t":"메시지 큐·이벤트 드리븐","q":[{"t":"choice","k":"why-queue","cat":"design","q":"주문 완료 시 이메일 발송·포인트 적립·추천 갱신을 동기로 처리하니 응답이 느리고 한 곳 장애가 전체를 막는다. 메시지 큐 도입의 핵심 이점은?","o":["데이터 일관성이 즉시 강해진다","생산자-소비자를 분리(decoupling)하고 부하를 완충(buffering)한다","저장 비용이 사라진다","네트워크가 빨라진다"],"a":1,"ex":"큐는 생산자와 소비자를 비동기로 분리하고 트래픽 급증을 버퍼링해 응답성과 내결함성을 높인다.\n💡 개념: 이벤트 드리븐 아키텍처는 큐를 통해 서비스 간 결합도를 낮춘다.\n🛠 실무: 핵심 경로(주문 저장)만 동기로 하고 부가 작업은 큐로 넘겨 지연을 줄이고 부분 장애를 격리한다."},{"t":"choice","k":"delivery-semantics","cat":"design","q":"대부분의 메시지 큐가 기본으로 보장하는 전달 시맨틱과, 이로 인해 소비자가 반드시 갖춰야 할 성질은?","o":["exactly-once 보장이라 아무 처리도 필요 없다","at-least-once 보장이라 소비자는 멱등하게 처리해야 한다","at-most-once 보장이라 메시지 유실을 감수한다","순서 보장이라 병렬 처리를 금지해야 한다"],"a":1,"ex":"큐는 보통 at-least-once를 보장해 중복 전달이 가능하므로 소비자는 멱등성이 필요하다.\n💡 개념: 정확히 한 번(exactly-once)은 비용이 크며, 실무는 at-least-once + 멱등 소비로 근사한다.\n🛠 실무: 메시지에 고유 ID를 넣고 처리 결과를 dedup 테이블에 기록해 중복을 흡수한다."},{"t":"choice","k":"dlq","cat":"design","q":"소비자가 특정 메시지를 계속 실패해 큐 전체 처리가 막혔다(poison message). 표준 해법은?","o":["큐를 비운다","실패 메시지를 데드레터 큐(DLQ)로 격리하고 나머지를 계속 처리한다","재시도 횟수를 무한대로 늘린다","소비자를 늘린다"],"a":1,"ex":"반복 실패 메시지는 DLQ로 옮겨 격리하고 정상 처리를 이어간 뒤 별도로 분석·재처리한다.\n💡 개념: DLQ는 처리 불가 메시지를 격리해 큐 전체 정체를 막는 안전장치다.\n🛠 실무: 최대 재시도 후 DLQ로 보내고, DLQ에는 알람을 걸어 근본 원인을 조사·재투입한다."},{"t":"choice","k":"ordering","cat":"design","q":"결제 이벤트는 '승인 -&gt; 취소' 순서가 뒤바뀌면 안 된다. 파티션 기반 큐(Kafka)에서 순서를 보장하는 방법은?","o":["파티션을 무한정 늘린다","같은 엔티티(예: 주문ID)를 항상 같은 파티션 키로 보내 파티션 내 순서를 보장한다","소비자를 랜덤 배치한다","순서는 보장할 수 없으니 포기한다"],"a":1,"ex":"Kafka는 파티션 내에서만 순서를 보장하므로 같은 키를 같은 파티션으로 라우팅한다.\n💡 개념: 전역 순서는 비싸고, 엔티티 단위 순서(파티션 키)로 충분한 경우가 많다.\n🛠 실무: 주문ID를 파티션 키로 쓰면 병렬성을 유지하면서 엔티티별 순서를 지킬 수 있다."},{"t":"input","k":"backpressure","cat":"design","q":"소비자가 처리 속도를 못 따라갈 때 생산 속도를 늦추거나 조절해 시스템 붕괴를 막는 흐름 제어 메커니즘을 무엇이라 하는가? (한글 또는 영문)","a":["백프레셔","배압","backpressure","back pressure"],"ex":"소비 능력에 맞춰 생산을 억제하는 백프레셔가 정답이다.\n💡 개념: 백프레셔는 큐 무한 적체와 메모리 폭발을 막는 흐름 제어다.\n🛠 실무: 큐 깊이를 모니터링해 임계 초과 시 생산자 스로틀링·오토스케일 소비자로 대응한다."}],"th":{"sum":"비동기·큐로 **응답 분리**와 장애 격리를 얻고, 대용량 파일은 **오브젝트 스토리지**에 두며 presigned URL로 직접 업로드한다.","body":[{"h":"메시지 큐의 이점","t":"주문 후 이메일·포인트·추천을 동기로 처리하면 응답이 느리고 한 곳 장애가 전체를 막는다. 큐를 두면 비동기·느슨한 결합으로 응답을 빠르게 하고 장애를 격리한다. 대부분 큐는 at-least-once라 소비자는 멱등해야 하고, poison message는 DLQ로 뺀다. Kafka는 파티션 키로 순서를 보장하고, 소비자가 못 따라오면 백프레셔로 흐름을 조절한다."},{"h":"스토리지 선택","t":"동영상·이미지 원본을 RDB BLOB에 넣으면 DB 크기·백업 시간이 폭증하므로, 오브젝트 스토리지(S3 등)에 저장하고 DB엔 URL만 둔다. 모바일에서 서버를 거치지 않고 스토리지로 직접 업로드하되 인증된 사용자만 허용하려면 presigned URL(사전 서명 URL)을 발급한다."}],"code":{"c":"동기: 응답 = 저장+이메일+포인트+추천 (느림, 결합)\n비동기: 저장 후 큐 발행 → 응답 즉시, 워커가 처리\n\n대용량 업로드: 서버가 presigned URL 발급 → 클라 직접 PUT","cap":"큐로 응답 분리, presigned URL로 직접 업로드"},"key":["큐 이점 = 비동기 응답 + 장애 격리 + 느슨한 결합","기본은 at-least-once, 소비자 멱등 + DLQ","원본 파일은 오브젝트 스토리지, DB엔 URL","직접 업로드는 presigned URL로 인증 제한"]}},{"t":"오브젝트 스토리지·검색엔진","q":[{"t":"choice","k":"blob-store","cat":"design","q":"사용자 업로드 동영상·이미지 원본을 RDB의 BLOB 컬럼에 저장했더니 DB 크기와 백업 시간이 폭증했다. 올바른 저장 방식은?","o":["동영상은 오브젝트 스토리지(S3 등)에 저장하고 DB엔 메타데이터·URL만 보관","컬럼 압축을 켠다","동영상 테이블을 별도 샤딩한다","캐시에 저장한다"],"a":0,"ex":"대용량 바이너리는 오브젝트 스토리지에 두고 DB는 경로·메타데이터만 관리한다.\n💡 개념: blob/오브젝트 스토리지는 대용량 비정형 파일에 저렴하고 무한 확장 가능한 저장을 제공한다.\n🛠 실무: 클라이언트가 presigned URL로 스토리지에 직접 업/다운로드하게 해 앱 서버 대역폭 부하를 없앤다."},{"t":"choice","k":"presigned-url","cat":"design","q":"모바일 앱에서 대용량 파일을 서버를 거치지 않고 오브젝트 스토리지로 직접 업로드하되, 인증된 사용자만 허용하려 한다. 적절한 방법은?","o":["스토리지 버킷을 공개(public)로 연다","서버가 발급한 만료 시간이 있는 presigned URL을 사용한다","앱에 스토리지 루트 자격증명을 심는다","모든 업로드를 서버로 프록시한다"],"a":1,"ex":"서버가 짧은 만료의 서명 URL을 발급하면 클라이언트가 안전하게 직접 업로드할 수 있다.\n💡 개념: presigned URL은 임시·범위 제한 권한을 부여해 서버 우회 전송을 안전하게 한다.\n🛠 실무: URL 만료를 짧게 두고 업로드 완료 이벤트로 후처리(썸네일·인코딩)를 큐로 트리거한다."},{"t":"choice","k":"search-engine","cat":"design","q":"상품 설명 전문(full-text)에서 형태소·오타 보정·연관도 랭킹 검색이 필요하다. RDB의 LIKE '%키워드%'로는 느리다. 적합한 컴포넌트는?","o":["읽기 복제본 추가","역색인 기반 검색엔진(Elasticsearch/OpenSearch)","캐시 계층","메시지 큐"],"a":1,"ex":"전문 검색·랭킹·오타 보정은 역색인 기반 검색엔진이 담당한다.\n💡 개념: 검색엔진은 역인덱스(inverted index)로 텍스트 검색을 빠르게 수행하고 스코어링을 제공한다.\n🛠 실무: DB를 원본(source of truth)으로 두고 CDC/큐로 검색 인덱스를 비동기 동기화한다."},{"t":"input","k":"inverted-index","cat":"design","q":"검색엔진이 '단어 -&gt; 그 단어를 포함한 문서 목록'을 미리 만들어 두는 자료구조의 이름은? (한글 또는 영문)","a":["역색인","역인덱스","inverted index","inverted-index","역방향 인덱스"],"ex":"단어를 키로 문서를 매핑하는 역색인(inverted index)이다.\n💡 개념: 역색인은 문서-&gt;단어가 아닌 단어-&gt;문서 매핑으로 전문 검색을 빠르게 만든다.\n🛠 실무: 인덱싱은 무겁고 지연이 있으므로 검색엔진은 최종 일관성 뷰로 취급하고 정합성 검증 배치를 둔다."},{"t":"choice","k":"cdc","cat":"design","q":"원본 DB 변경을 검색엔진·캐시·데이터 웨어하우스로 지연 없이 전파하고 싶다. DB의 트랜잭션 로그를 읽어 변경을 스트리밍하는 기법은?","o":["폴링(주기적 전체 스캔)","CDC(Change Data Capture, 예: binlog 구독)","이중 쓰기(애플리케이션이 두 곳에 직접 쓰기)","수동 배치 덤프"],"a":1,"ex":"트랜잭션 로그(binlog 등)를 구독해 변경만 스트리밍하는 CDC가 정답이다.\n💡 개념: CDC는 이중 쓰기의 정합성 문제 없이 원본 변경을 안정적으로 하류 시스템에 전파한다.\n🛠 실무: Debezium 같은 CDC 커넥터로 Kafka에 변경을 흘리고 소비자가 검색·캐시·DW를 갱신한다."}],"th":{"sum":"비동기·큐로 **응답 분리**와 장애 격리를 얻고, 대용량 파일은 **오브젝트 스토리지**에 두며 presigned URL로 직접 업로드한다.","body":[{"h":"메시지 큐의 이점","t":"주문 후 이메일·포인트·추천을 동기로 처리하면 응답이 느리고 한 곳 장애가 전체를 막는다. 큐를 두면 비동기·느슨한 결합으로 응답을 빠르게 하고 장애를 격리한다. 대부분 큐는 at-least-once라 소비자는 멱등해야 하고, poison message는 DLQ로 뺀다. Kafka는 파티션 키로 순서를 보장하고, 소비자가 못 따라오면 백프레셔로 흐름을 조절한다."},{"h":"스토리지 선택","t":"동영상·이미지 원본을 RDB BLOB에 넣으면 DB 크기·백업 시간이 폭증하므로, 오브젝트 스토리지(S3 등)에 저장하고 DB엔 URL만 둔다. 모바일에서 서버를 거치지 않고 스토리지로 직접 업로드하되 인증된 사용자만 허용하려면 presigned URL(사전 서명 URL)을 발급한다."}],"code":{"c":"동기: 응답 = 저장+이메일+포인트+추천 (느림, 결합)\n비동기: 저장 후 큐 발행 → 응답 즉시, 워커가 처리\n\n대용량 업로드: 서버가 presigned URL 발급 → 클라 직접 PUT","cap":"큐로 응답 분리, presigned URL로 직접 업로드"},"key":["큐 이점 = 비동기 응답 + 장애 격리 + 느슨한 결합","기본은 at-least-once, 소비자 멱등 + DLQ","원본 파일은 오브젝트 스토리지, DB엔 URL","직접 업로드는 presigned URL로 인증 제한"]}}]},{"t":"일관성과 신뢰성","l":[{"t":"일관성·멱등성","q":[{"t":"choice","k":"strong-vs-eventual","cat":"design","q":"'좋아요 수' 표시와 '은행 계좌 잔액'에 각각 어떤 일관성을 택하는 것이 합리적인가?","o":["둘 다 강한 일관성","좋아요는 최종 일관성, 잔액은 강한 일관성","둘 다 최종 일관성","좋아요는 강한 일관성, 잔액은 최종 일관성"],"a":1,"ex":"허용 오차가 큰 좋아요는 최종 일관성으로 확장성을, 금전은 강한 일관성으로 정확성을 택한다.\n💡 개념: 일관성은 비용과 트레이드오프다. 도메인 허용 오차에 맞춰 수준을 고른다.\n🛠 실무: 잔액은 트랜잭션·직렬화로 정확히, 좋아요는 캐시 카운터로 근사 후 주기적 정합화한다."},{"t":"choice","k":"cap","cat":"design","q":"네트워크 분단(파티션)이 발생한 분산 DB에서 CAP 정리에 따라 반드시 포기해야 하는 것은?","o":["파티션 감내(P)를 포기한다","일관성(C)과 가용성(A) 중 하나를 포기한다","셋 다 유지할 수 있다","내구성(D)을 포기한다"],"a":1,"ex":"분단 상황에서는 일관성(C)과 가용성(A)을 동시에 만족할 수 없어 하나를 택해야 한다.\n💡 개념: CAP은 파티션(P)이 불가피한 분산 시스템에서 C와 A의 선택을 강제한다.\n🛠 실무: 결제는 CP(일관성 우선, 요청 거부), 소셜 피드는 AP(가용성 우선, 낡은 데이터 허용)를 흔히 택한다."},{"t":"choice","k":"idempotency","cat":"design","q":"결제 요청 후 타임아웃이 나 클라이언트가 재시도했는데 카드가 두 번 청구됐다. 이를 막는 서버 측 설계는?","o":["재시도를 금지한다","클라이언트가 보낸 멱등성 키(idempotency key)로 중복 요청을 한 번만 처리한다","타임아웃을 늘린다","결제를 비동기로 바꾼다"],"a":1,"ex":"멱등성 키로 같은 요청의 재실행을 감지해 결과를 한 번만 반영한다.\n💡 개념: 멱등성은 같은 연산을 여러 번 실행해도 결과가 동일하도록 보장한다.\n🛠 실무: 클라이언트가 요청당 고유 키를 생성해 보내고, 서버는 키-결과를 저장해 재요청 시 저장된 결과를 반환한다."},{"t":"input","k":"idempotent-key","cat":"design","q":"동일 요청이 여러 번 도착해도 부작용이 한 번만 발생하도록 클라이언트가 요청에 부여하는 고유 식별자를 무엇이라 하는가? (한글 또는 영문)","a":["멱등성 키","아이뎀포턴시 키","idempotency key","idempotency-key","멱등 키"],"ex":"멱등성 키(idempotency key)가 정답이다.\n💡 개념: 멱등성 키는 재시도 안전성을 확보하는 핵심 수단이다.\n🛠 실무: 결제·주문 API는 멱등성 키를 필수로 요구하고 키 저장에 TTL을 둬 무한 증가를 막는다."},{"t":"choice","k":"quorum","cat":"design","q":"복제본 5개인 분산 저장소에서 강한 일관성 읽기를 위해 W(쓰기)+R(읽기) 정족수를 어떻게 잡아야 하는가?","o":["W=1, R=1","W+R &gt; N (예: W=3, R=3, N=5)","W=5, R=5만 유일한 방법","W=0, R=0"],"a":1,"ex":"W+R &gt; N이면 읽기·쓰기 정족수가 겹쳐 최신 값을 반드시 읽는다.\n💡 개념: 정족수(quorum)로 일관성과 가용성의 균형을 조절한다.\n🛠 실무: 읽기 우세면 W를 크게 R을 작게, 쓰기 우세면 반대로 조정해 지연을 최적화한다."}],"th":{"sum":"일관성·신뢰성은 **CAP/정족수**, 멱등성, 재시도(백오프·지터), **서킷 브레이커**의 조합이다. 데이터 성격에 맞는 일관성을 고른다.","body":[{"h":"일관성과 정족수","t":"'좋아요 수'는 최종 일관성으로 충분하지만 '계좌 잔액'은 강일관성이 필요하다. 네트워크 분단 시 CAP에 따라 가용성(A)이나 일관성(C) 중 하나를 포기해야 한다. 복제본 N개에서 강일관성 읽기는 `W + R > N` 정족수를 만족시켜 최신 쓰기를 반드시 읽도록 한다(예: N=5, W=3, R=3)."},{"h":"멱등성과 복원력","t":"결제 타임아웃 후 재시도로 이중 청구되는 것은 서버가 멱등키로 중복을 걸러 막는다. 모든 클라이언트가 동일 간격으로 즉시 재시도하면 thundering herd가 생기므로, 지수 백오프 + 지터를 쓴다. 다운된 하위 서비스로 계속 요청해 스레드 풀이 고갈되는 연쇄 장애는 서킷 브레이커로 차단한다."}],"code":{"c":"강일관성 읽기: W + R > N  (N=5 → W=3, R=3)\n재시도: delay = base × 2^n + random_jitter\n하위 장애: 실패 임계 초과 → circuit OPEN (즉시 차단)","cap":"정족수·백오프·서킷 브레이커 핵심 식"},"key":["데이터 성격에 맞는 일관성 (좋아요=최종, 잔액=강)","분단 시 CAP은 C 또는 A 포기","강일관성 읽기 조건 W+R>N","재시도는 백오프+지터, 연쇄장애는 서킷브레이커"]}},{"t":"재시도·서킷브레이커·멀티리전/DR","q":[{"t":"choice","k":"retry-backoff","cat":"design","q":"의존 서비스가 일시 과부하일 때 모든 클라이언트가 즉시 동일 간격으로 재시도하면 어떤 문제가 생기며, 올바른 재시도 전략은?","o":["문제 없음 / 고정 간격 재시도","재시도 폭풍으로 장애 악화 / 지수 백오프 + 지터","응답이 빨라짐 / 무한 재시도","비용 절감 / 즉시 재시도"],"a":1,"ex":"동시 재시도는 장애를 증폭한다. 지수 백오프에 무작위 지터를 더해 요청을 분산한다.\n💡 개념: 지터 없는 백오프는 재시도가 동기화되어 다시 몰린다.\n🛠 실무: 최대 재시도 횟수·상한 지연을 두고 4xx 같은 비재시도성 오류는 재시도하지 않는다."},{"t":"choice","k":"circuit-breaker","cat":"design","q":"다운된 하위 서비스로 계속 요청을 보내다 스레드 풀이 고갈되어 상위 서비스까지 연쇄 장애가 났다. 이를 막는 패턴은?","o":["타임아웃 제거","서킷 브레이커로 실패율이 임계 초과 시 호출을 즉시 차단(open)","재시도 횟수 증가","캐시 삭제"],"a":1,"ex":"서킷 브레이커가 실패율 임계 초과 시 회로를 열어 빠르게 실패시키고 자원 고갈을 막는다.\n💡 개념: 서킷 브레이커는 open-&gt;half-open-&gt;closed 상태로 장애 전파를 차단한다.\n🛠 실무: 열린 동안 폴백(캐시·기본값)을 반환하고, half-open에서 소량 요청으로 복구를 탐지한다."},{"t":"input","k":"rpo","cat":"design","q":"재해 복구에서 '데이터를 얼마나 잃어도 되는가(허용 데이터 손실 시점)'를 나타내는 지표의 약어는?","a":["RPO","rpo","Recovery Point Objective"],"ex":"허용 데이터 손실을 뜻하는 RPO(Recovery Point Objective)다.\n💡 개념: RPO는 마지막 백업 시점 손실 허용, RTO는 복구까지 허용 시간이다.\n🛠 실무: RPO를 낮추려면 복제 주기를 짧게(연속 복제) 하고, RTO를 낮추려면 핫 스탠바이·자동 페일오버를 둔다."},{"t":"choice","k":"multiregion","cat":"design","q":"단일 리전 장애로 전 서비스가 중단됐다. 가장 높은 가용성을 제공하지만 비용·복잡도가 큰 멀티리전 구성은?","o":["단일 리전 + 백업","콜드 스탠바이(장애 시 수동 기동)","액티브-액티브(여러 리전이 동시에 트래픽 처리)","단일 AZ 다중화"],"a":2,"ex":"액티브-액티브는 여러 리전이 동시 서비스해 리전 장애에도 무중단이지만 데이터 동기화·충돌 처리가 복잡하다.\n💡 개념: 액티브-패시브는 저렴하나 페일오버 지연이, 액티브-액티브는 가용성 최고이나 일관성·비용 부담이 크다.\n🛠 실무: 지연 민감·규제 데이터는 리전 고정(지오 파티셔닝)하고, 전역 데이터만 리전 간 복제해 충돌을 줄인다."},{"t":"choice","k":"bulkhead","cat":"design","q":"한 종류의 느린 요청이 공용 스레드 풀을 모두 점유해 다른 정상 요청까지 처리 못 하게 됐다. 자원을 격리해 이를 막는 패턴은?","o":["벌크헤드(bulkhead)로 요청 유형별 자원 풀 분리","서킷 브레이커만으로 해결","캐시 추가","재시도 증가"],"a":0,"ex":"벌크헤드 패턴은 자원 풀을 분리해 한 영역의 고갈이 전체로 번지지 않게 한다.\n💡 개념: 배의 격벽처럼 자원을 격리해 장애 폭발 반경(blast radius)을 줄인다.\n🛠 실무: 엔드포인트·의존성별 스레드/커넥션 풀과 동시성 한도를 나눠 상호 간섭을 차단한다."}],"th":{"sum":"일관성·신뢰성은 **CAP/정족수**, 멱등성, 재시도(백오프·지터), **서킷 브레이커**의 조합이다. 데이터 성격에 맞는 일관성을 고른다.","body":[{"h":"일관성과 정족수","t":"'좋아요 수'는 최종 일관성으로 충분하지만 '계좌 잔액'은 강일관성이 필요하다. 네트워크 분단 시 CAP에 따라 가용성(A)이나 일관성(C) 중 하나를 포기해야 한다. 복제본 N개에서 강일관성 읽기는 `W + R > N` 정족수를 만족시켜 최신 쓰기를 반드시 읽도록 한다(예: N=5, W=3, R=3)."},{"h":"멱등성과 복원력","t":"결제 타임아웃 후 재시도로 이중 청구되는 것은 서버가 멱등키로 중복을 걸러 막는다. 모든 클라이언트가 동일 간격으로 즉시 재시도하면 thundering herd가 생기므로, 지수 백오프 + 지터를 쓴다. 다운된 하위 서비스로 계속 요청해 스레드 풀이 고갈되는 연쇄 장애는 서킷 브레이커로 차단한다."}],"code":{"c":"강일관성 읽기: W + R > N  (N=5 → W=3, R=3)\n재시도: delay = base × 2^n + random_jitter\n하위 장애: 실패 임계 초과 → circuit OPEN (즉시 차단)","cap":"정족수·백오프·서킷 브레이커 핵심 식"},"key":["데이터 성격에 맞는 일관성 (좋아요=최종, 잔액=강)","분단 시 CAP은 C 또는 A 포기","강일관성 읽기 조건 W+R>N","재시도는 백오프+지터, 연쇄장애는 서킷브레이커"]}}]},{"t":"대표 설계 사례와 트레이드오프","l":[{"t":"URL 단축기·뉴스피드","q":[{"t":"choice","k":"url-shortener-key","cat":"design","q":"URL 단축기에서 짧고 충돌 없는 7자 코드를 생성하려 한다. 대규모에서 가장 견고한 방식은?","o":["랜덤 문자열 생성 후 충돌 시 재시도(고부하 시 충돌 급증)","전역 유일 ID(예: 분산 ID 생성기)를 base62로 인코딩","원본 URL의 MD5 앞 7자","입력 순서대로 1씩 증가하는 예측 가능한 숫자"],"a":1,"ex":"유일 ID를 base62 변환하면 충돌 없이 짧은 코드를 결정적으로 만든다.\n💡 개념: base62(0-9a-zA-Z) 7자리는 62^7 약 3.5조 개 조합으로 충분한 공간을 준다.\n🛠 실무: 순차 ID는 예측 가능·나열 위험이 있어 ID 공간을 섞거나 범위 사전 할당(counter range)으로 보완한다."},{"t":"choice","k":"url-read-heavy","cat":"design","q":"URL 단축기는 리다이렉트(읽기)가 생성(쓰기)보다 압도적으로 많다. 리다이렉트 지연을 최소화하는 핵심 설계는?","o":["매 요청마다 원본 DB 조회","코드-&gt;원본 URL 매핑을 캐시(Redis)에 두고 캐시 우선 조회","리다이렉트를 큐로 비동기 처리","쓰기 마스터를 늘림"],"a":1,"ex":"읽기 우세 서비스이므로 인기 매핑을 캐시에 두면 대부분의 리다이렉트를 캐시에서 처리한다.\n💡 개념: read-heavy 설계의 표준은 캐시 히트율 극대화다.\n🛠 실무: 301 대신 302를 써 클릭 분석을 유지하거나, 분석이 불필요하면 301로 브라우저·CDN 캐싱을 활용한다."},{"t":"choice","k":"feed-fanout","cat":"design","q":"월 수억 사용자 뉴스피드에서 팔로우가 적은 일반 사용자의 게시물은 팬아웃-온-라이트(쓰기 시 팔로워 피드에 미리 배포)를 쓴다. 그런데 팔로워 수천만인 유명인은 왜 이 방식이 문제이며 어떻게 처리하나?","o":["문제 없음, 유명인도 동일하게 쓰기 팬아웃","유명인 1건 게시가 수천만 개 쓰기로 폭증(팬아웃 폭풍)하므로, 유명인 글은 팬아웃-온-리드(읽기 시 합류)로 처리하는 하이브리드","유명인 계정을 삭제","유명인 글은 캐시하지 않음"],"a":1,"ex":"유명인은 쓰기 팬아웃이 폭증하므로 읽기 시점에 병합하는 풀 방식을 섞는 하이브리드가 표준이다.\n💡 개념: fan-out on write는 읽기가 빠르나 팔로워가 많으면 쓰기가 폭발한다. fan-out on read는 반대다.\n🛠 실무: 일반 사용자는 푸시(미리 배포), 유명인은 풀(읽기 시 합류)로 나누는 하이브리드로 비용·지연을 균형 잡는다."},{"t":"input","k":"fanout-model","cat":"design","q":"뉴스피드에서 게시 시점에 모든 팔로워의 피드에 글을 미리 배포해 두는 방식을 '팬아웃-온-___'라고 한다. 빈칸은? (read/write 중)","a":["write","쓰기","라이트","fan-out on write","팬아웃 온 라이트"],"ex":"쓰기 시점에 미리 배포하는 팬아웃-온-라이트(push)다.\n💡 개념: 팬아웃-온-라이트는 읽기를 빠르게 하는 대신 쓰기·저장 비용이 크다.\n🛠 실무: 활성 사용자 위주로 미리 배포하고 비활성 사용자는 읽기 시 생성해 저장 낭비를 줄인다."},{"t":"choice","k":"feed-storage","cat":"design","q":"각 사용자의 사전 계산된 피드(타임라인)를 저장할 때, 시간 역순 조회와 빠른 삽입이 중요하다. 적합한 저장소 선택은?","o":["단일 RDB 테이블에 전 사용자 피드 저장","사용자별 피드를 Redis 리스트/정렬셋 등 인메모리 구조에 캐싱","오브젝트 스토리지에 JSON 파일로 저장","검색엔진에 저장"],"a":1,"ex":"타임라인은 사용자별로 정렬된 인메모리 구조(정렬셋)에 캐싱하면 삽입·역순 조회가 빠르다.\n💡 개념: 피드는 최근성이 중요하므로 최근 N개만 캐시하고 나머지는 온디맨드 생성한다.\n🛠 실무: 정렬셋에 게시 시각을 점수로 저장하고 상한 크기를 둬 메모리를 통제한다."}],"th":{"sum":"대표 설계 사례(URL 단축·뉴스피드·채팅)로 **읽기 최적화**, 팬아웃, 실시간 푸시의 정석 패턴을 익힌다.","body":[{"h":"URL 단축·뉴스피드","t":"짧고 충돌 없는 코드는 전역 유일 ID(카운터·Snowflake)를 base62 인코딩하는 방식이 대규모에서 가장 견고하다. 리다이렉트(읽기)가 압도적이므로 캐시로 지연을 낮춘다. 뉴스피드는 일반 사용자에게 fanout-on-write, 유명인은 read 시점 병합의 하이브리드를 쓴다."},{"h":"피드 저장·채팅","t":"사전 계산된 피드는 시간 역순 조회와 빠른 삽입이 중요해 Redis Sorted Set 같은 정렬 자료구조가 적합하다. 실시간 채팅은 폴링 대신 서버 푸시가 가능한 WebSocket을 쓴다. 수신자가 오프라인이면 메시지를 큐·저장소에 보관했다 접속 시 전달하는 store-and-forward가 필요하다."}],"code":{"c":"URL 단축: id(Snowflake) → base62 → 7자 코드\n리다이렉트: 캐시 우선 (읽기 >> 쓰기)\n피드 저장: Redis ZSET (score=timestamp)\n채팅: WebSocket + 오프라인 큐(store-and-forward)","cap":"각 사례의 핵심 저장소·프로토콜 선택"},"key":["단축코드 = 유일 ID를 base62 인코딩","fanout-on-write, 유명인은 read로 하이브리드","역순 피드엔 Sorted Set","실시간 푸시=WebSocket, 오프라인=store-and-forward"]}},{"t":"채팅·알림·레이트리밋","q":[{"t":"choice","k":"chat-connection","cat":"design","q":"실시간 채팅에서 서버가 클라이언트로 메시지를 즉시 밀어(push) 보내려 한다. 폴링 대비 적합한 프로토콜은?","o":["요청마다 새 HTTP 연결(단순 폴링)","웹소켓(WebSocket) 지속 연결","일반 REST GET 반복","이메일"],"a":1,"ex":"양방향 실시간 푸시에는 지속 연결인 웹소켓이 폴링보다 지연·오버헤드 면에서 우수하다.\n💡 개념: 웹소켓은 하나의 연결로 서버-&gt;클라이언트 실시간 푸시를 지원한다.\n🛠 실무: 수백만 동시 연결은 상태를 갖는 게이트웨이 계층으로 분리하고, 어느 서버에 연결됐는지 세션 레지스트리로 관리한다."},{"t":"choice","k":"chat-delivery","cat":"design","q":"채팅에서 수신자가 오프라인일 때 메시지를 잃지 않고 나중에 전달하려면 어떤 설계가 필요한가?","o":["오프라인이면 메시지 폐기","메시지를 영속 저장하고 수신자 접속 시 미수신분을 동기화(오프라인 메시지 큐)","송신자에게 재전송 요구","웹소켓 재연결만으로 해결"],"a":1,"ex":"메시지를 서버에 영속 저장하고 접속 시 미수신 메시지를 순서대로 전달한다.\n💡 개념: 실시간 전달과 별개로 내구성 있는 저장이 메시지 유실을 막는다.\n🛠 실무: 메시지 시퀀스 번호로 클라이언트가 마지막 수신 위치를 알려 델타만 동기화한다."},{"t":"choice","k":"notification-fanout","cat":"design","q":"알림 시스템에서 이메일·SMS·푸시(APNs/FCM) 등 다양한 채널로 발송해야 한다. 확장성 있는 구조는?","o":["앱 서버가 각 외부 API를 동기로 직접 호출","알림 요청을 큐에 넣고 채널별 워커가 비동기로 각 프로바이더에 발송","모든 알림을 이메일로 통일","알림을 DB에만 기록"],"a":1,"ex":"큐 기반으로 채널별 워커가 비동기 발송하면 프로바이더 지연·장애를 격리하고 확장할 수 있다.\n💡 개념: 알림은 이벤트 드리븐·비동기 구조가 표준이며 채널을 어댑터로 분리한다.\n🛠 실무: 프로바이더 장애 시 재시도·DLQ, 사용자 설정(수신 거부)·레이트리밋·중복 제거를 발송 파이프라인에 넣는다."},{"t":"choice","k":"rate-limit-algo","cat":"design","q":"레이트 리밋 서비스에서 순간 버스트를 어느 정도 허용하면서 평균 속도를 제한하려 한다. 널리 쓰는 알고리즘은?","o":["고정 윈도우 카운터(경계에서 2배 버스트 허용 문제)","토큰 버킷","단순 카운터 초기화","무제한 허용"],"a":1,"ex":"토큰 버킷은 버킷에 쌓인 토큰만큼 버스트를 허용하면서 리필 속도로 평균을 제한한다.\n💡 개념: 고정 윈도우는 경계에서 버스트가 몰리는 결함이 있어 슬라이딩 윈도우/토큰 버킷을 선호한다.\n🛠 실무: 분산 환경에서는 Redis에 토큰 상태를 두고 Lua 스크립트로 원자적으로 소비 처리한다."},{"t":"input","k":"rate-limit-token","cat":"design","q":"일정 속도로 토큰이 채워지는 버킷에서 요청마다 토큰을 소비하고, 토큰이 없으면 거부하는 레이트리밋 알고리즘의 이름은? (한글 또는 영문)","a":["토큰 버킷","token bucket","토큰버킷"],"ex":"토큰 버킷(token bucket) 알고리즘이다.\n💡 개념: 버킷 용량이 버스트 허용치, 리필 속도가 평균 허용률을 결정한다.\n🛠 실무: 429 응답과 함께 Retry-After 헤더를 내려 클라이언트가 백오프하도록 유도한다."}],"th":{"sum":"대표 설계 사례(URL 단축·뉴스피드·채팅)로 **읽기 최적화**, 팬아웃, 실시간 푸시의 정석 패턴을 익힌다.","body":[{"h":"URL 단축·뉴스피드","t":"짧고 충돌 없는 코드는 전역 유일 ID(카운터·Snowflake)를 base62 인코딩하는 방식이 대규모에서 가장 견고하다. 리다이렉트(읽기)가 압도적이므로 캐시로 지연을 낮춘다. 뉴스피드는 일반 사용자에게 fanout-on-write, 유명인은 read 시점 병합의 하이브리드를 쓴다."},{"h":"피드 저장·채팅","t":"사전 계산된 피드는 시간 역순 조회와 빠른 삽입이 중요해 Redis Sorted Set 같은 정렬 자료구조가 적합하다. 실시간 채팅은 폴링 대신 서버 푸시가 가능한 WebSocket을 쓴다. 수신자가 오프라인이면 메시지를 큐·저장소에 보관했다 접속 시 전달하는 store-and-forward가 필요하다."}],"code":{"c":"URL 단축: id(Snowflake) → base62 → 7자 코드\n리다이렉트: 캐시 우선 (읽기 >> 쓰기)\n피드 저장: Redis ZSET (score=timestamp)\n채팅: WebSocket + 오프라인 큐(store-and-forward)","cap":"각 사례의 핵심 저장소·프로토콜 선택"},"key":["단축코드 = 유일 ID를 base62 인코딩","fanout-on-write, 유명인은 read로 하이브리드","역순 피드엔 Sorted Set","실시간 푸시=WebSocket, 오프라인=store-and-forward"]}}]},{"t":"심화 — 시니어/스태프 난이도","l":[{"t":"시니어 심화 I","q":[{"t":"choice","k":"PACELC","q":"어떤 시스템이 PACELC 분류에서 PC/EL 로 특징지어진다. 다음 중 이 시스템의 실제 동작을 가장 정확히 설명한 것은?","a":1,"ex":"PC는 파티션(P) 상황에서 일관성(C)을 택하고, EL은 정상(E, else) 상황에서 낮은 지연(L)을 택한다는 의미다. 즉 파티션 때는 요청을 거부하더라도 일관성을 지키지만, 평상시에는 강한 일관성을 다소 희생해 낮은 지연을 취한다.","o":["네트워크 파티션 시에는 일관성보다 가용성을 택하고, 정상 시에는 지연을 택한다","네트워크 파티션 시에는 가용성보다 일관성을 택하고, 정상 시에는 일관성보다 낮은 지연을 택한다","항상 일관성을 우선하며 지연은 고려하지 않는다","파티션과 무관하게 항상 가용성과 낮은 지연을 동시에 보장한다"],"cat":"design"},{"t":"choice","k":"쿼럼R+W","q":"N=5, W=3, R=3 인 쿼럼 시스템에서 R+W&gt;N 을 만족한다. 그런데도 클라이언트가 방금 성공적으로 쓴 값을 뒤이은 읽기에서 못 볼 수 있는 경우로 가장 대표적인 것은?","a":1,"ex":"엄격 쿼럼이면 R+W&gt;N 은 읽기/쓰기 노드 집합의 교집합을 보장한다. 하지만 sloppy quorum과 hinted handoff에서는 원래 담당 노드가 아닌 임시 노드에 쓰기가 저장될 수 있어, 이후 읽기 쿼럼이 그 임시 노드를 포함하지 않으면 최신 값을 놓친다. R와 W가 겹치는지는 산술적으로 보장되므로 4번은 오답이다.","o":["R+W&gt;N 이므로 그런 경우는 원리적으로 절대 발생하지 않는다","쓰기가 W개 노드에 커밋되기 전에 코디네이터가 성공을 반환하는(sloppy quorum/hinted handoff) 구성일 때","읽기 쿼럼이 항상 가장 최근 쓰기 노드를 포함하도록 강제될 때","R=3 이 W=3 보다 크지 않아서 겹침이 보장되지 않기 때문"],"cat":"design"},{"t":"choice","k":"선형화가능","q":"선형화가능성(linearizability)과 순차 일관성(sequential consistency)의 핵심 차이는?","a":0,"ex":"둘 다 모든 연산의 단일 전역 순서가 각 프로세스의 프로그램 순서와 일치해야 한다. 차이는 선형화가능성이 추가로 실시간 순서를 요구한다는 점이다. 즉 op A가 op B 시작 전에 끝났다면 전역 순서에서도 A가 B보다 앞서야 한다. 순차 일관성은 이 실시간 제약이 없어 더 약하다.","o":["선형화가능성은 실시간(real-time) 순서를 존중하지만 순차 일관성은 그렇지 않다","순차 일관성이 선형화가능성보다 더 강한 보장이다","둘은 단일 객체에서 완전히 동일하며 차이는 이름뿐이다","선형화가능성은 여러 객체 간 순서만 보장하고 단일 객체는 보장하지 않는다"],"cat":"design"},{"t":"choice","k":"정확히한번","q":"메시지 큐에서 '정확히 한 번(exactly-once) 전달'에 관한 가장 정확한 설명은?","a":1,"ex":"두 장군 문제 때문에 실패 가능한 네트워크에서 순수한 전달(delivery)의 정확히 한 번은 불가능하다. 실무의 'exactly-once'는 at-least-once 전달 + 멱등성/중복 제거로 부수효과를 한 번만 나타나게 하는 effectively-once다. TCP는 세그먼트 재전송을 하며 애플리케이션 수준 정확히 한 번을 보장하지 않는다.","o":["TCP를 쓰면 네트워크 계층에서 정확히 한 번 전달이 보장된다","네트워크 상 전달은 근본적으로 최소 한 번 또는 최대 한 번만 가능하며, 정확히 한 번은 멱등 처리나 중복 제거로 '효과의' 정확히 한 번을 흉내낼 뿐이다","2단계 커밋을 쓰면 전달 자체를 정확히 한 번으로 만들 수 있다","정확히 한 번은 소비자 측 자동 재시도를 끄면 자연히 달성된다"],"cat":"design"},{"t":"choice","k":"재시도폭풍","q":"많은 클라이언트가 백엔드 과부하 시 고정 간격으로 재시도하다가 동기화되어 부하가 파도처럼 몰리는 문제를 완화하는 가장 효과적인 방법은?","a":1,"ex":"고정 간격 백오프는 클라이언트들이 동일 시점에 몰리는 thundering herd를 유발한다. 지수 백오프에 full jitter(0~현재상한 사이 난수)를 더하면 재시도 시점이 분산되어 부하 파도가 평탄해진다. 간격 단축이나 무제한 재시도는 오히려 부하를 키운다.","o":["재시도 간격을 더 짧게 고정한다","지수 백오프에 무작위 지터(full jitter)를 추가한다","재시도 횟수를 무제한으로 늘린다","모든 클라이언트가 정확히 같은 시각에 재시도하도록 동기화한다"],"cat":"design"},{"t":"choice","k":"캐시스탬피드","q":"인기 캐시 키가 만료되는 순간 수천 요청이 동시에 원본 DB를 때리는 cache stampede를 막는 기법으로 적절하지 않은 것은?","a":3,"ex":"TTL을 동일 시각으로 정렬하면 다수 키가 한꺼번에 만료되어 stampede가 오히려 악화된다. 나머지 셋(재계산 락, TTL 지터, probabilistic early recomputation)은 모두 동시 재계산을 분산/억제하는 정석 기법이다.","o":["재계산 락(단일 요청만 재생성, 나머지는 대기/과거값 반환)","TTL에 무작위 지터를 주어 만료 시점 분산","확률적 조기 만료(probabilistic early expiration)로 만료 전에 미리 갱신","모든 키의 TTL을 동일한 정각 값으로 정렬해 일괄 만료"],"cat":"design"},{"t":"choice","k":"일관해싱","q":"기본 consistent hashing(노드당 링 위 1개 지점)의 잘 알려진 약점과 그 표준 해결책으로 맞는 것은?","a":1,"ex":"노드당 링 위 한 지점만 두면 구간 크기가 불균등해져 특정 노드에 부하가 몰린다. 각 노드를 다수의 가상 노드로 링에 흩뿌리면 통계적으로 부하가 고르게 분산된다. 일관 해싱의 장점 자체가 재해싱 시 K/N 키만 이동한다는 것이므로 모듈로로 교체하는 건 퇴행이다.","o":["키 조회가 O(N)이라 느리다; 해결책은 노드 수 줄이기","노드가 링에 불균등하게 배치되어 부하가 치우친다; 해결책은 노드당 다수의 가상 노드(virtual node) 도입","재해싱 시 모든 키가 이동한다; 해결책은 모듈로 해싱으로 교체","해시 충돌이 잦다; 해결책은 더 짧은 해시 사용"],"cat":"design"}],"th":{"sum":"시니어 심화: **PACELC**, 정족수의 미묘함, **선형화가능성 vs 순차 일관성**, exactly-once의 실체를 트레이드오프 관점에서 정확히 구분한다.","body":[{"h":"PACELC와 정족수의 한계","t":"PACELC는 분단(P) 시 A/C, 정상(E) 시 지연(L)/일관성(C) 중 무엇을 택하는지 분류한다. PC/EL은 분단 시 일관성, 정상 시 지연을 우선한다. R+W>N을 만족해도 stale read가 날 수 있다: 쓰기가 일부 복제본만 반영된 채 성공 응답이 갔거나(비동기), 읽기 정족수가 아직 갱신 안 된 노드들로 구성되거나, read repair 전 타이밍 때문이다."},{"h":"일관성 모델과 exactly-once","t":"선형화가능성은 순차 일관성에 더해 '실시간 순서'까지 보장한다(전역 실시간 시계 기준 순서). 순차 일관성은 각 프로세스 내 순서만 지키면 전역 순서는 자유다. 큐의 exactly-once '전달'은 원칙적으로 불가능하며, 실제로는 at-least-once + 멱등(effectively-once 처리)로 구현된다. 재시도 동기화 파도는 지터가 가장 효과적이다."}],"code":{"c":"PACELC: if Partition → (A|C) else → (L|C)\nPC/EL = 분단 시 일관성, 정상 시 지연 우선\n\nexactly-once 전달 ✗ → at-least-once + idempotency ✓","cap":"PACELC 표기와 exactly-once의 실체"},"key":["PC/EL = 분단 시 C, 정상 시 L 선택","R+W>N도 비동기 복제·타이밍으로 stale 가능","선형화 = 순차 일관성 + 실시간 순서","exactly-once 전달은 환상, 멱등으로 effectively-once"]}},{"t":"시니어 심화 II","q":[{"t":"choice","k":"스플릿브레인","q":"리더 선출에서 네트워크 파티션 후 두 노드가 각자 리더라 믿는 split-brain을 방지하는 핵심 메커니즘은?","a":1,"ex":"과반수 정족수를 요구하면 파티션의 양쪽이 동시에 과반을 얻을 수 없어(다수결의 유일성), 소수파는 리더가 될 수 없다. fencing token까지 더하면 뒤처진 옛 리더의 쓰기를 스토리지가 거부해 split-brain 손상을 막는다. '가장 빠른 노드' 같은 규칙은 두 파티션이 각자 로컬 최속 노드를 뽑을 수 있어 무의미하다.","o":["가장 빠른 노드를 항상 리더로 지정","과반수(quorum) 기반 선출로 소수파는 스스로 리더 자격을 내려놓게 함","리더에게 무제한 임기 부여","모든 노드가 동시에 쓰기를 수락하도록 허용"],"cat":"design"},{"t":"choice","k":"토큰버킷","q":"토큰 버킷(token bucket)과 고정 윈도우(fixed window) 카운터 방식 rate limiter의 중요한 차이는?","a":0,"ex":"토큰 버킷은 버킷 용량만큼 버스트를 허용하면서 리필 속도로 평균을 제한한다. 고정 윈도우는 한 윈도우 끝과 다음 윈도우 시작에 요청이 몰리면 경계 부근 짧은 구간에 한도의 최대 2배가 통과할 수 있다. 이를 완화한 것이 sliding window 계열이다.","o":["토큰 버킷은 버스트를 허용하되 평균 속도를 제한하고, 고정 윈도우는 윈도우 경계에서 최대 2배 버스트가 새는 문제가 있다","둘은 동작이 동일하다","고정 윈도우가 항상 더 부드럽게 트래픽을 제한한다","토큰 버킷은 버스트를 전혀 허용하지 않는다"],"cat":"design"},{"t":"choice","k":"사가vs2PC","q":"마이크로서비스 간 분산 트랜잭션에서 2PC 대신 saga를 택할 때 받아들여야 하는 트레이드오프는?","a":1,"ex":"2PC는 원자성과 격리를 제공하지만 조정자 장애 시 블로킹과 자원 잠금이 문제다. saga는 각 단계를 로컬 커밋하고 실패 시 보상으로 되돌리므로 격리성이 없어 더티 리드/중간 상태 노출이 발생한다. 대신 잠금을 오래 잡지 않아 확장성과 가용성이 좋다.","o":["saga는 원자성과 격리성을 모두 강하게 보장한다","saga는 격리성을 포기하며(중간 상태가 외부에 보임), 실패 시 보상 트랜잭션으로 되돌리는 최종 일관성 모델이다","saga는 2PC보다 더 강한 격리를 제공한다","saga는 조정자(coordinator)가 반드시 잠금을 오래 유지해야 한다"],"cat":"design"},{"t":"choice","k":"클럭스큐","q":"Google Spanner의 TrueTime이 클럭 불확실성(clock skew)을 다루는 방식으로 맞는 것은?","a":1,"ex":"TrueTime은 시각을 점이 아니라 경계된 오차 구간 [earliest, latest]로 반환한다. 트랜잭션 커밋 시 구간의 latest가 지날 때까지 기다리는 commit-wait으로, 나중에 시작한 트랜잭션이 반드시 더 큰 타임스탬프를 갖도록 해 외부 일관성(선형화가능)을 보장한다. 물리 시계를 0 오차로 만들 수는 없다.","o":["모든 노드의 시계를 완벽히 동기화해 오차를 0으로 만든다","시각을 [earliest, latest] 구간으로 노출하고, 커밋 시 불확실성 구간이 지나갈 때까지 commit-wait으로 대기해 외부 일관성을 보장한다","NTP만으로 밀리초 단위 정확도를 달성한다","타임스탬프를 버리고 논리 시계만 사용한다"],"cat":"design"},{"t":"choice","k":"인과일관성","q":"인과 일관성(causal consistency)이 결과적 일관성(eventual consistency)보다 강하게 보장하는 것은?","a":1,"ex":"인과 일관성은 happens-before 관계에 있는 연산들의 순서를 모든 관찰자에게 보존한다(예: 질문 후 답변이 답변 먼저로 보이지 않음). 동시적/무관한 연산은 노드마다 다른 순서로 보여도 된다. 즉시 동일값이나 전역 순서는 더 강한 모델(선형화)의 성질이다.","o":["모든 복제본이 즉시 동일한 값을 갖는다","인과적으로 관련된(happens-before) 연산들은 모든 노드에서 그 순서대로 관찰된다; 무관한 연산은 순서가 달라도 됨","전 노드에서 완전한 전역 순서(선형화)를 보장한다","쓰기 손실이 절대 없다"],"cat":"design"},{"t":"choice","k":"복제지연","q":"단일 리더 비동기 복제에서 사용자가 자신이 방금 쓴 값을 팔로워에서 못 읽는 문제를 해결하는 보장은?","a":1,"ex":"자신의 쓰기가 뒤처진 팔로워에서 안 보이는 문제는 read-your-writes 보장이 해결한다(자신이 쓴 것은 반드시 읽음). 단조 읽기는 시간이 거꾸로 가는 걸 막고, 일관된 프리픽스는 인과 순서 뒤바뀜을 막는 서로 다른 보장이다.","o":["단조 읽기(monotonic reads)","자기 쓰기 읽기(read-your-writes / read-after-write consistency)","일관된 프리픽스 읽기(consistent prefix reads)","경계된 지연(bounded staleness)"],"cat":"design"},{"t":"choice","k":"백프레셔","q":"생산자가 소비자보다 빠른 스트리밍 파이프라인에서 무한 버퍼로 대응할 때의 근본적 위험과 올바른 대안은?","a":1,"ex":"무한(또는 과대) 버퍼는 부하가 지속되면 메모리를 소진하고 큐잉 지연이 무한히 증가한다(bufferbloat). 경계된 버퍼로 생산자에게 역압을 전달하거나, 감당 못 할 요청을 조기에 버리는 load shedding으로 시스템을 보호해야 한다.","o":["위험 없음; 버퍼는 크면 클수록 항상 좋다","버퍼가 무한정 쌓여 메모리 고갈과 지연 폭증을 부르므로, 경계 버퍼 + 백프레셔(생산자 속도 조절)나 부하 제거(load shedding)가 필요하다","소비자를 무한히 늘리면 백프레셔가 불필요하다","백프레셔 대신 재시도를 늘리면 된다"],"cat":"design"}],"th":{"sum":"시니어 심화: **PACELC**, 정족수의 미묘함, **선형화가능성 vs 순차 일관성**, exactly-once의 실체를 트레이드오프 관점에서 정확히 구분한다.","body":[{"h":"PACELC와 정족수의 한계","t":"PACELC는 분단(P) 시 A/C, 정상(E) 시 지연(L)/일관성(C) 중 무엇을 택하는지 분류한다. PC/EL은 분단 시 일관성, 정상 시 지연을 우선한다. R+W>N을 만족해도 stale read가 날 수 있다: 쓰기가 일부 복제본만 반영된 채 성공 응답이 갔거나(비동기), 읽기 정족수가 아직 갱신 안 된 노드들로 구성되거나, read repair 전 타이밍 때문이다."},{"h":"일관성 모델과 exactly-once","t":"선형화가능성은 순차 일관성에 더해 '실시간 순서'까지 보장한다(전역 실시간 시계 기준 순서). 순차 일관성은 각 프로세스 내 순서만 지키면 전역 순서는 자유다. 큐의 exactly-once '전달'은 원칙적으로 불가능하며, 실제로는 at-least-once + 멱등(effectively-once 처리)로 구현된다. 재시도 동기화 파도는 지터가 가장 효과적이다."}],"code":{"c":"PACELC: if Partition → (A|C) else → (L|C)\nPC/EL = 분단 시 일관성, 정상 시 지연 우선\n\nexactly-once 전달 ✗ → at-least-once + idempotency ✓","cap":"PACELC 표기와 exactly-once의 실체"},"key":["PC/EL = 분단 시 C, 정상 시 L 선택","R+W>N도 비동기 복제·타이밍으로 stale 가능","선형화 = 순차 일관성 + 실시간 순서","exactly-once 전달은 환상, 멱등으로 effectively-once"]}},{"t":"시니어 심화 III","q":[{"t":"choice","k":"핫파티션","q":"키 기반 샤딩에서 특정 키(예: 유명인 계정)로 트래픽이 몰리는 hot partition을 완화하는 기법으로 부적절한 것은?","a":2,"ex":"핫 파티션의 본질은 부하가 한 샤드에 집중된 것이다. 트래픽을 단일 샤드에 더 집중시키는 것은 문제를 악화시킨다. 나머지는 모두 분산/캐싱/격리로 부하를 흩는 정석 기법이다. 다만 write sharding은 이후 읽기 시 여러 샤드를 팬아웃해야 하는 비용이 따른다.","o":["핫 키에 무작위 접미사를 붙여 여러 샤드로 분산(write sharding)","해당 키 전용 캐시/복제본 추가","핫 키의 읽기를 팬아웃 없이 단일 샤드에 더 집중시키기","요청 앞단에서 핫 키 트래픽을 별도 처리 경로로 분리"],"cat":"design"},{"t":"choice","k":"멱등성키","q":"결제 API에서 클라이언트가 idempotency key를 보내 재시도 안전성을 확보한다. 서버 구현에서 놓치기 쉬운 미묘한 실패 모드는?","a":1,"ex":"단순히 '키 있으면 반환, 없으면 처리'를 비원자적으로 하면 두 동시 요청이 모두 미존재를 보고 각자 처리하는 TOCTOU 경합이 생긴다. 처리 시작 전에 유니크 제약이나 원자적 insert/락으로 키를 선점해야 한다. 만료만으로는 동시 경합을 막지 못한다.","o":["키를 저장하기만 하면 어떤 경합에서도 안전하다","동일 키의 동시 요청 2건이 '아직 결과 없음'을 동시에 확인하고 둘 다 처리하는 경합; 키에 대한 원자적 예약(고유 제약/락)이 없으면 중복 실행된다","idempotency key는 GET 요청에만 필요하다","키 만료를 두면 절대 중복이 없다"],"cat":"design"},{"t":"choice","k":"테일지연","q":"수백 개 백엔드로 팬아웃하는 요청에서 개별 서비스의 p99가 낮은데도 전체 p99가 나빠지는 현상(tail latency amplification)의 원인과 완화책은?","a":1,"ex":"N개 백엔드의 응답을 모두 모아야 하면 전체 지연은 그중 가장 느린 것에 지배되어, 개별 tail 확률이 낮아도 N이 크면 어느 하나가 느릴 확률이 커진다. 여분 요청(hedged request)을 두 번째로 보내 먼저 온 응답을 쓰거나, 타임아웃으로 느린 응답을 잘라 완화한다. 평균은 문제를 가릴 뿐 해결하지 않는다.","o":["원인은 CPU 부족뿐; 완화책은 코어 추가","한 요청이 다수 백엔드 응답을 모두 기다리므로 하나만 느려도 전체가 느려짐; hedged/backup request나 타임아웃으로 완화","팬아웃을 늘리면 저절로 개선된다","p99 대신 평균을 보면 문제가 사라진다"],"cat":"design"},{"t":"choice","k":"WAL","q":"Write-Ahead Log(WAL)이 크래시 복구에서 원자성과 내구성을 보장하는 핵심 원리는?","a":1,"ex":"WAL의 규칙은 '데이터 페이지보다 그에 해당하는 로그 레코드를 먼저 디스크에 fsync한다'이다. 덕분에 크래시 후 커밋된 변경은 redo로 재적용하고 미완료 변경은 undo로 되돌릴 수 있다. 데이터 먼저 쓰기나 로그를 휘발 메모리에만 두면 내구성이 깨진다.","o":["데이터 페이지를 먼저 쓰고 로그를 나중에 쓴다","변경을 데이터 파일에 반영하기 전에 로그 레코드를 먼저 내구성 있게 기록한다(로그 우선), 그래서 크래시 후 redo/undo로 복구 가능","로그는 메모리에만 두고 디스크에는 쓰지 않는다","WAL은 읽기 성능만 높일 뿐 복구와 무관하다"],"cat":"design"},{"t":"choice","k":"CRDT","q":"오프라인 편집이 잦은 협업 앱에서 last-write-wins(LWW) 대신 CRDT를 택하는 근본 이유는?","a":1,"ex":"LWW는 타임스탬프가 큰 쓰기만 남겨 동시 변경 중 하나를 소실시킨다(lost update). CRDT는 교환/결합/멱등적 병합으로 어떤 순서로 합쳐도 같은 수렴 상태에 도달해 동시 편집을 손실 없이 반영한다. 다만 메타데이터 오버헤드로 공간을 더 쓸 수 있어 1번은 틀리다.","o":["CRDT는 LWW보다 저장 공간을 항상 덜 쓴다","LWW는 동시 쓰기 중 하나를 조용히 버려 업데이트 손실이 생기지만, CRDT는 병합 함수가 수렴적이라 동시 변경을 손실 없이 합칠 수 있다","CRDT는 네트워크가 필요 없다","LWW가 CRDT보다 강한 일관성을 제공한다"],"cat":"design"},{"t":"input","k":"펜싱토큰","q":"분산 락에서 클라이언트가 락을 잡은 뒤 GC 멈춤 등으로 임대(lease)가 만료됐는데도 뒤늦게 쓰기를 시도하는 문제를, 스토리지가 단조 증가하는 번호로 옛 쓰기를 거부하게 만들어 막는 기법의 이름은? (영문 용어)","a":["fencing token","fencing tokens","펜싱 토큰","펜싱토큰"],"ex":"락 획득 시 단조 증가 토큰을 발급하고, 스토리지는 지금까지 본 최대 토큰보다 작은 토큰의 쓰기를 거부한다. 그래서 멈췄다 깨어난 옛 클라이언트의 stale 쓰기가 차단된다. 락 서비스만으로는 프로세스 멈춤을 막을 수 없어 fencing이 필요하다."},{"t":"input","k":"합의알고리즘","q":"단일 리더가 로그 복제를 주도하며, leader election과 log replication을 분리해 Paxos보다 이해하기 쉽게 설계한 합의 알고리즘의 이름은?","a":["raft","래프트"],"ex":"Raft는 강한 리더 모델과 임기(term) 기반 선출, 로그 매칭 속성으로 이해가능성을 목표로 한 합의 알고리즘이다. Multi-Paxos와 동등한 안전성을 제공하면서 구현/교육이 쉬워 etcd, Consul 등에 채택됐다."}],"th":{"sum":"시니어 심화: **PACELC**, 정족수의 미묘함, **선형화가능성 vs 순차 일관성**, exactly-once의 실체를 트레이드오프 관점에서 정확히 구분한다.","body":[{"h":"PACELC와 정족수의 한계","t":"PACELC는 분단(P) 시 A/C, 정상(E) 시 지연(L)/일관성(C) 중 무엇을 택하는지 분류한다. PC/EL은 분단 시 일관성, 정상 시 지연을 우선한다. R+W>N을 만족해도 stale read가 날 수 있다: 쓰기가 일부 복제본만 반영된 채 성공 응답이 갔거나(비동기), 읽기 정족수가 아직 갱신 안 된 노드들로 구성되거나, read repair 전 타이밍 때문이다."},{"h":"일관성 모델과 exactly-once","t":"선형화가능성은 순차 일관성에 더해 '실시간 순서'까지 보장한다(전역 실시간 시계 기준 순서). 순차 일관성은 각 프로세스 내 순서만 지키면 전역 순서는 자유다. 큐의 exactly-once '전달'은 원칙적으로 불가능하며, 실제로는 at-least-once + 멱등(effectively-once 처리)로 구현된다. 재시도 동기화 파도는 지터가 가장 효과적이다."}],"code":{"c":"PACELC: if Partition → (A|C) else → (L|C)\nPC/EL = 분단 시 일관성, 정상 시 지연 우선\n\nexactly-once 전달 ✗ → at-least-once + idempotency ✓","cap":"PACELC 표기와 exactly-once의 실체"},"key":["PC/EL = 분단 시 C, 정상 시 L 선택","R+W>N도 비동기 복제·타이밍으로 stale 가능","선형화 = 순차 일관성 + 실시간 순서","exactly-once 전달은 환상, 멱등으로 effectively-once"]}},{"t":"시니어 심화 IV","q":[{"t":"input","k":"CAP선택","q":"네트워크 파티션이 발생했을 때, 시스템이 '모든 노드가 항상 최신 동일값을 반환'하는 성질을 포기하는 대신 계속 응답 가능하도록 택했다면, CAP의 세 글자 중 유지한 두 글자는 무엇인가? (예: 'AP' 또는 'CP' 형태로)","a":["AP","ap"],"ex":"파티션(P)은 분산 시스템에서 선택이 아니라 전제이므로 항상 감내해야 한다. 최신 동일값(강한 일관성 C)을 포기하고 응답 가능성(가용성 A)을 택했으므로 AP다. CAP에서 실제 선택은 파티션 발생 시 C와 A 중 무엇을 버릴지이다."}],"th":{"sum":"시니어 심화: **PACELC**, 정족수의 미묘함, **선형화가능성 vs 순차 일관성**, exactly-once의 실체를 트레이드오프 관점에서 정확히 구분한다.","body":[{"h":"PACELC와 정족수의 한계","t":"PACELC는 분단(P) 시 A/C, 정상(E) 시 지연(L)/일관성(C) 중 무엇을 택하는지 분류한다. PC/EL은 분단 시 일관성, 정상 시 지연을 우선한다. R+W>N을 만족해도 stale read가 날 수 있다: 쓰기가 일부 복제본만 반영된 채 성공 응답이 갔거나(비동기), 읽기 정족수가 아직 갱신 안 된 노드들로 구성되거나, read repair 전 타이밍 때문이다."},{"h":"일관성 모델과 exactly-once","t":"선형화가능성은 순차 일관성에 더해 '실시간 순서'까지 보장한다(전역 실시간 시계 기준 순서). 순차 일관성은 각 프로세스 내 순서만 지키면 전역 순서는 자유다. 큐의 exactly-once '전달'은 원칙적으로 불가능하며, 실제로는 at-least-once + 멱등(effectively-once 처리)로 구현된다. 재시도 동기화 파도는 지터가 가장 효과적이다."}],"code":{"c":"PACELC: if Partition → (A|C) else → (L|C)\nPC/EL = 분단 시 일관성, 정상 시 지연 우선\n\nexactly-once 전달 ✗ → at-least-once + idempotency ✓","cap":"PACELC 표기와 exactly-once의 실체"},"key":["PC/EL = 분단 시 C, 정상 시 L 선택","R+W>N도 비동기 복제·타이밍으로 stale 가능","선형화 = 순차 일관성 + 실시간 순서","exactly-once 전달은 환상, 멱등으로 effectively-once"]}}]},{"t":"시니어 실전 — 분산·일관성·아키텍처","l":[{"t":"시니어 실전 I","q":[{"t":"choice","k":"일관성 모델","q":"3개 노드에 복제된 저장소에서 클라이언트 A가 x=5를 쓰고 성공 응답(ack)을 받은 직후, 다른 클라이언트 B가 x를 읽었을 때 반드시 5(또는 그 이후의 값)를 보게 하려면 최소한 어떤 일관성 모델이 필요한가?","o":["Linearizability","Sequential consistency","Causal consistency","Eventual consistency"],"a":0,"ex":"실시간(real-time) 최신성 보장, 즉 '완료된 쓰기 이후 시작된 읽기는 그 쓰기를 본다'는 조건은 linearizability에서만 성립한다. sequential consistency는 전역 순서는 있으나 wall-clock 실시간 순서를 강제하지 않아 방금 완료된 쓰기를 못 볼 수 있다. causal은 인과 관계만, eventual은 최종 수렴만 보장한다."},{"t":"choice","k":"인과 일관성","q":"소셜 앱에서 '원글'보다 '답글'이 먼저 화면에 나타나는 이상 현상을 방지하고 싶다. 이를 막는 데 필요한 '가장 약한(비용이 낮은)' 일관성 모델은?","o":["Eventual consistency","Causal consistency","Read-your-writes consistency","Linearizability"],"a":1,"ex":"원글-&gt;답글의 인과(happens-before) 관계만 보존하면 순서 역전이 사라지므로 causal consistency로 충분하다. eventual은 순서를 보장하지 않아 역전이 가능하다. read-your-writes는 자신의 쓰기만 보장하며 타인의 인과 순서를 보장하지 않는다. linearizability는 충분하지만 전역 실시간 순서까지 강제해 과한 비용이 든다."},{"t":"choice","k":"쿼럼","q":"leaderless 복제 시스템에서 N=6, W=4로 설정했다. 읽기가 항상 '가장 최근에 완료된 쓰기'를 반드시 포함하도록 보장하려면 R의 최소값은?","o":["2","3","4","5"],"a":1,"ex":"읽기와 쓰기 쿼럼이 최소 한 노드에서 겹치려면 R+W&gt;N이어야 한다. 4+R&gt;6 이므로 R&gt;2, 즉 R의 최소값은 3이다. R=2이면 R+W=6=N으로 겹침이 보장되지 않아 stale read가 가능하다."},{"t":"choice","k":"쿼럼·복제","q":"R+W&gt;N을 만족하도록 설정했는데도 여전히 stale read가 관측될 수 있는 대표적인 원인은?","o":["R+W&gt;N이면 겹치는 노드가 아예 존재하지 않기 때문","sloppy quorum과 hinted handoff에서 쓰기가 원래 담당 노드가 아닌 임시 노드에 저장되어, 이후 읽기 쿼럼이 그 노드를 포함하지 않으면 최신 값을 놓치기 때문","R+W&gt;N이면 물리적으로 stale read가 절대 불가능하기 때문","N이 짝수일 때만 쿼럼이 성립하기 때문"],"a":1,"ex":"정상 경로에서 R+W&gt;N은 겹침을 보장한다. 그러나 노드 장애 시 sloppy quorum이 임시(hinted handoff) 노드에 쓰기를 저장하면, 이후 읽기 쿼럼이 그 임시 노드를 포함하지 않아 겹침이 깨질 수 있다. 즉 R+W&gt;N은 '정상 경로에서의 겹침 보장'일 뿐 절대적 보장이 아니다."},{"t":"choice","k":"PACELC","q":"PACELC 분류에서 Dynamo 스타일 시스템이 'PA/EL'로 분류된다는 것은 무슨 의미인가?","o":["분할 시에는 일관성(C)을, 정상 시에는 지연(L)을 우선한다","네트워크 분할(P) 시에는 가용성(A)을, 분할이 없는 정상(E) 시에는 낮은 지연(L)을 각각 일관성(C)보다 우선한다","분할 시에는 가용성(A)을, 정상 시에는 강한 일관성(C)을 우선한다","분할 여부와 무관하게 항상 강한 일관성을 보장한다"],"a":1,"ex":"PACELC는 CAP을 확장해 '분할이 없을 때(Else)'의 트레이드오프까지 명시한다. PA/EL은 분할 시 가용성을, 정상 시 낮은 지연을 각각 일관성보다 우선한다는 뜻이다. 반대로 CP/EC 시스템(예: 전통적 동기 복제 RDBMS)은 분할 시 일관성을, 정상 시에도 일관성을 우선한다."},{"t":"choice","k":"CAP·분할","q":"동기 복제 기반의 leader 시스템(CP 성향)이 네트워크 분할 중 과반(quorum)을 확보하지 못한 소수파(minority) 쪽에서 쓰기를 거부하는 근본 이유는?","o":["소수파의 하드웨어 성능이 낮기 때문","양쪽이 독립적으로 쓰기를 받으면 데이터가 발산(split-brain)하므로, 과반을 확보한 쪽만 쓰기를 허용해 일관성을 지키기 위해","가용성을 극대화하기 위해","읽기 지연을 줄이기 위해"],"a":1,"ex":"분할된 양측이 모두 쓰기를 수용하면 서로 다른 최신 상태가 두 개 생겨 split-brain이 발생한다. 이를 막기 위해 과반(majority)을 확보한 파티션만 진행하고 소수파는 쓰기를 거부한다. 그 대가로 소수파는 가용성을 잃는다(CAP의 C 선택)."},{"t":"choice","k":"Raft·리더선출","q":"Raft에서 candidate가 새로운 리더가 되기 위한 조건으로 옳은 것은?","o":["클러스터의 모든 노드로부터 투표를 받아야 한다","같은 term 내에서 클러스터 과반수(majority)의 투표를 획득해야 한다","가장 긴 로그를 가진 노드가 자동으로 리더가 된다","이전 리더가 후임을 직접 지명한다"],"a":1,"ex":"Raft 리더 선출은 같은 term에서 과반수 득표로 결정된다. 각 노드는 term당 한 표만 주며, 투표자는 candidate의 로그가 자신만큼 최신(up-to-date)일 때만 표를 준다. 과반수 요구가 두 리더 동시 선출(split-brain)을 방지한다."}],"th":{"sum":"시니어 실전: 정족수·인과 일관성·**Raft** 리더 선출·PACELC를 실제 시나리오로 판단한다. CP 시스템이 소수파 쓰기를 왜 거부하는지가 핵심.","body":[{"h":"정족수와 인과 일관성","t":"쓰기 ack 직후 읽기가 반드시 그 값을 보게 하려면 W+R>N이 필요하다. N=6, W=4면 R은 최소 3이어야 정족수가 겹친다(4+3>6). '원글보다 답글이 먼저' 보이는 이상을 막는 가장 약한 모델은 인과 일관성(causal consistency)이다. R+W>N에도 stale read가 나는 대표 원인은 비동기 복제 지연·읽기가 갱신 안 된 노드로 구성됨이다."},{"h":"CP 시스템과 Raft","t":"동기 복제 leader(CP)가 분단 중 소수파에서 쓰기를 거부하는 이유는, 소수파가 커밋하면 다수파와 충돌해 split-brain·데이터 불일치가 생기기 때문이다. 과반 정족수를 못 얻으면 안전하게 거부한다. Raft에서 candidate가 리더가 되려면 과반 노드의 투표를 얻어야 하고, 자신의 로그가 최소한 투표자만큼 최신이어야 한다."}],"code":{"c":"N=6, W=4 → R ≥ 3  (W+R>N: 4+3>6)\nPA/EL(Dynamo): 분단 시 가용성, 정상 시 지연 우선\n\nRaft 리더 조건: 과반 득표 + 최신 로그(up-to-date)","cap":"정족수 계산과 Raft 선출 조건"},"key":["N=6, W=4면 R 최소 3 (W+R>N)","답글 역전 방지 = 인과 일관성(최소 비용)","CP 소수파 쓰기 거부 = split-brain 방지","Raft 리더 = 과반 득표 + 최신 로그"]}},{"t":"시니어 실전 II","q":[{"t":"choice","k":"Raft·로그커밋","q":"Raft 리더가 '이전 term'에 만들어진 로그 엔트리를 과반수에 복제했다는 사실만으로 그것을 커밋으로 표시하면 안 되는 이유는?","o":["과반수에 복제되면 언제나 안전하므로 사실 표시해도 된다","이전 term의 엔트리는 이후 다른 리더에 의해 덮어써질 가능성이 남아 있어, 리더가 현재 term의 엔트리를 커밋할 때 함께(간접적으로) 커밋되어야 안전하기 때문","Raft는 term 개념을 사용하지 않기 때문","로그 엔트리는 커밋 없이 즉시 적용되기 때문"],"a":1,"ex":"Raft 논문 Figure 8 시나리오처럼, 이전 term 엔트리가 과반수에 복제되어 있어도 이후 선출된 리더가 이를 덮어쓸 수 있다. 그래서 Raft는 리더가 '자신의 현재 term' 엔트리를 과반수에 복제해 커밋할 때 이전 엔트리들도 간접적으로 커밋 처리한다. 이 규칙이 커밋된 엔트리의 불변성을 보장한다."},{"t":"choice","k":"저장엔진","q":"쓰기 집약적(write-heavy) 워크로드에서 LSM-tree가 in-place B-tree보다 높은 쓰기 처리량을 내는 근본 이유는?","o":["LSM-tree는 읽기 증폭이 전혀 없기 때문","무작위 in-place 갱신 대신, 메모리 버퍼에 모아 순차적으로 append하고 배치 compaction으로 정리하여 쓰기를 순차 I/O로 변환하기 때문","LSM-tree는 항상 더 적은 디스크 공간을 사용하기 때문","LSM-tree는 WAL이 필요 없기 때문"],"a":1,"ex":"LSM-tree는 쓰기를 memtable에 모아 SSTable로 순차 flush하고 백그라운드 compaction으로 병합한다. 무작위 페이지 in-place 갱신을 피하고 순차 쓰기로 바꾸는 것이 핵심 이점이다. 대신 여러 SSTable을 뒤져야 해 읽기 증폭과 compaction으로 인한 쓰기 증폭 비용이 있고, 공간을 항상 덜 쓰지도 않는다."},{"t":"choice","k":"LSM·compaction","q":"LSM-tree의 leveled compaction과 size-tiered compaction을 비교할 때 옳은 설명은?","o":["leveled는 쓰기 증폭이 더 크지만 읽기 증폭과 공간 증폭은 더 작다","leveled는 쓰기·읽기·공간 증폭 모두에서 항상 더 우수하다","size-tiered는 읽기 증폭과 공간 증폭이 더 작다","두 방식의 증폭 특성은 동일하다"],"a":0,"ex":"leveled compaction은 각 레벨을 겹치지 않게 정렬 유지해 읽기 시 확인할 SSTable 수와 중복 공간을 줄이지만, 잦은 재작성으로 쓰기 증폭이 크다. 반대로 size-tiered는 비슷한 크기의 SSTable을 모아 한 번에 병합해 쓰기 증폭은 낮지만, 같은 키가 여러 tier에 흩어져 읽기·공간 증폭이 커진다."},{"t":"choice","k":"샤딩·핫스팟","q":"단조 증가하는 타임스탬프를 샤드 키로 사용했더니 특정 샤드에만 쓰기 부하가 집중된다. 근본 원인은?","o":["해시 충돌이 잦아서","단조 증가 키는 항상 동일한(가장 최신) 범위 샤드로 라우팅되어, 모든 신규 쓰기가 한 샤드에 몰리는 쓰기 hotspot이 생기기 때문","복제 지연 때문","네트워크 분할 때문"],"a":1,"ex":"타임스탬프처럼 단조 증가하는 키를 범위 파티셔닝하면 항상 마지막 샤드가 모든 신규 쓰기를 받아 hotspot이 된다. 다른 샤드는 놀고 한 샤드만 포화된다. 완화책으로는 키 앞에 해시/버킷 접두어를 붙이는 salting이나 해시 기반 파티셔닝이 있다."},{"t":"choice","k":"파티셔닝·재분배","q":"노드 수 N에 대해 hash(key) mod N으로 파티션을 결정하는 방식의 근본적 문제와 그 해결책으로 옳은 것은?","o":["노드를 추가/제거해 N이 바뀌면 거의 모든 키의 매핑이 변해 대량 재배치가 발생한다 -&gt; consistent hashing(가상 노드)으로 이동량을 최소화한다","해시 계산 자체가 너무 느리다 -&gt; 캐시로 해결한다","키를 균등하게 분산할 수 없다 -&gt; 복제로 해결한다","키를 정렬할 수 없다 -&gt; 인덱스로 해결한다"],"a":0,"ex":"mod N 방식은 N이 하나만 바뀌어도 대부분의 키 매핑이 어긋나 대규모 데이터 이동을 유발한다. consistent hashing은 노드/키를 원형 해시 공간에 배치해 노드 변화 시 인접 구간의 키만 이동하게 하고(K/N 규모), 가상 노드로 부하를 고르게 분산한다."},{"t":"choice","k":"보조 인덱스","q":"분산 DB에서 document-partitioned(local) 보조 인덱스와 term-partitioned(global) 보조 인덱스의 트레이드오프로 옳은 것은?","o":["local 인덱스는 쓰기가 한 파티션에만 반영돼 저렴하지만 읽기 시 모든 파티션을 조회하는 scatter-gather가 필요하고, global 인덱스는 읽기가 효율적이지만 쓰기가 여러 파티션에 걸쳐 비동기/분산되어야 한다","local 인덱스가 읽기와 쓰기 모두에서 항상 우월하다","global 인덱스는 어떤 경우에도 항상 나쁘다","두 방식의 성능 특성에는 차이가 없다"],"a":0,"ex":"document-partitioned(local) 인덱스는 각 파티션이 자기 문서의 인덱스만 보유해 쓰기가 국소적이지만, 인덱스 값으로 검색하면 모든 파티션에 질의하는 scatter-gather가 된다. term-partitioned(global) 인덱스는 인덱스를 항(term)으로 파티셔닝해 읽기는 소수 파티션만 보면 되지만, 한 문서의 쓰기가 여러 인덱스 파티션을 갱신해야 해 대개 비동기로 반영된다."},{"t":"choice","k":"CDC","q":"로그 기반(log-based) Change Data Capture가 쿼리 기반(주기적 폴링) 방식보다 우수한 핵심 이유는?","o":["구현이 더 단순하기 때문","DB의 트랜잭션 로그(WAL/binlog)를 읽어 삭제를 포함한 모든 변경과 그 순서를 정확히 포착하면서 소스 DB에 주는 부하가 낮기 때문","스키마 변경에 항상 자유롭기 때문","지연 시간이 항상 더 크기 때문"],"a":1,"ex":"폴링 방식은 updated_at 컬럼 등에 의존해 삭제(row 제거)를 포착하기 어렵고, 반복 쿼리로 소스에 부하를 준다. 로그 기반 CDC는 트랜잭션 로그를 직접 소비하므로 삽입/수정/삭제 전부와 정확한 순서를 낮은 오버헤드, 낮은 지연으로 스트리밍할 수 있다."}],"th":{"sum":"시니어 실전: 정족수·인과 일관성·**Raft** 리더 선출·PACELC를 실제 시나리오로 판단한다. CP 시스템이 소수파 쓰기를 왜 거부하는지가 핵심.","body":[{"h":"정족수와 인과 일관성","t":"쓰기 ack 직후 읽기가 반드시 그 값을 보게 하려면 W+R>N이 필요하다. N=6, W=4면 R은 최소 3이어야 정족수가 겹친다(4+3>6). '원글보다 답글이 먼저' 보이는 이상을 막는 가장 약한 모델은 인과 일관성(causal consistency)이다. R+W>N에도 stale read가 나는 대표 원인은 비동기 복제 지연·읽기가 갱신 안 된 노드로 구성됨이다."},{"h":"CP 시스템과 Raft","t":"동기 복제 leader(CP)가 분단 중 소수파에서 쓰기를 거부하는 이유는, 소수파가 커밋하면 다수파와 충돌해 split-brain·데이터 불일치가 생기기 때문이다. 과반 정족수를 못 얻으면 안전하게 거부한다. Raft에서 candidate가 리더가 되려면 과반 노드의 투표를 얻어야 하고, 자신의 로그가 최소한 투표자만큼 최신이어야 한다."}],"code":{"c":"N=6, W=4 → R ≥ 3  (W+R>N: 4+3>6)\nPA/EL(Dynamo): 분단 시 가용성, 정상 시 지연 우선\n\nRaft 리더 조건: 과반 득표 + 최신 로그(up-to-date)","cap":"정족수 계산과 Raft 선출 조건"},"key":["N=6, W=4면 R 최소 3 (W+R>N)","답글 역전 방지 = 인과 일관성(최소 비용)","CP 소수파 쓰기 거부 = split-brain 방지","Raft 리더 = 과반 득표 + 최신 로그"]}},{"t":"시니어 실전 III","q":[{"t":"choice","k":"캐시 쓰기정책","q":"쓰기는 매우 잦지만 방금 쓴 데이터가 곧바로 다시 읽히지는 않는 워크로드에 가장 적합한 캐시 쓰기 정책은?","o":["write-through","write-back","write-around","read-through"],"a":2,"ex":"write-around는 쓰기를 캐시에 넣지 않고 DB에만 기록하며, 캐시는 이후 실제 읽기(miss) 때만 채운다. 곧 읽히지 않을 데이터로 캐시를 오염시키는 것을 막아 히트율을 지킨다. write-through는 매 쓰기마다 캐시도 갱신해 쓸데없이 캐시를 밀어내고, write-back은 유실 위험이 있으며, read-through는 읽기 경로 정책이다."},{"t":"choice","k":"캐시 만료","q":"다수의 캐시 키가 거의 같은 시각에 동시에 만료되어 주기적으로 백엔드에 부하 스파이크가 발생한다. 가장 적절한 완화책은?","o":["모든 키의 TTL을 0으로 설정한다","모든 키에 정확히 동일한 TTL을 부여한다","각 키의 TTL에 무작위 지터(jitter)를 더해 만료 시점을 분산시킨다","캐시를 비활성화한다"],"a":2,"ex":"동일 시각에 대량 키가 만료되면 재적재 요청이 몰려 스파이크가 생긴다(대량 만료). TTL에 랜덤 지터를 더하면 만료가 시간축에 퍼져 부하가 평탄해진다. 동일 TTL은 문제를 악화시키고, TTL=0이나 캐시 비활성화는 캐시 효과를 없앤다."},{"t":"choice","k":"캐시·부재키","q":"존재하지 않는 키(예: 없는 사용자 ID)에 대한 조회가 반복되어 매번 캐시 miss 후 DB를 계속 때린다. 이 부하를 막는 표준 기법은?","o":["캐시 TTL을 무한대로 설정한다","'존재하지 않음' 결과 자체를 짧은 TTL로 캐싱(negative caching)하거나 Bloom filter로 부재를 선판별한다","캐시를 제거한다","샤드 수를 늘린다"],"a":1,"ex":"부재 결과를 캐싱하지 않으면 존재하지 않는 키가 매번 캐시를 통과해 DB로 간다(cache penetration). negative caching은 '없음'을 짧은 TTL로 저장해 반복 조회를 캐시에서 차단하고, Bloom filter는 존재하지 않는 키를 빠르게 걸러낸다. TTL 무한은 부재가 실제 생성으로 바뀔 때 stale이 되어 위험하다."},{"t":"choice","k":"멱등성·전달보장","q":"결제 API가 at-least-once 전달 특성 때문에 동일 요청을 중복 수신할 수 있다. 중복 청구를 막는 표준 기법으로, 구현 시 놓치기 쉬운 미묘한 실패 모드까지 옳게 짚은 것은?","o":["재시도를 전면 금지하면 중복이 사라진다","클라이언트가 고유 idempotency key를 부여하고 서버가 그 키로 중복을 식별하되, 키 선점을 원자적(유니크 제약/락)으로 하지 않으면 동시 요청 2건이 모두 '미존재'를 보고 중복 실행하는 경합(TOCTOU)이 생긴다","idempotency key는 GET 요청에만 필요하다","키에 만료만 설정하면 어떤 동시 경합에서도 안전하다"],"a":1,"ex":"네트워크에서 at-least-once는 중복을 피할 수 없으므로 처리 측을 멱등하게 만든다. 단순히 '키 있으면 반환, 없으면 처리'를 비원자적으로 하면 두 동시 요청이 모두 미존재를 보고 각자 실행하는 TOCTOU 경합이 생긴다. 처리 시작 전 유니크 제약이나 원자적 insert/락으로 키를 선점해야 한다."},{"t":"choice","k":"재시도·백오프","q":"수천 개의 클라이언트가 다운스트림 실패 후 '고정 간격'으로 동시에 재시도하여 서버 회복을 방해한다(retry storm). 올바른 전략은?","o":["즉시, 무한히 재시도한다","항상 정확히 같은 고정 간격으로 재시도한다","재시도 간격을 지수적으로 늘리되 무작위 jitter를 섞는다(exponential backoff with jitter)","재시도를 완전히 비활성화한다"],"a":2,"ex":"고정 간격이나 순수 지수 백오프는 클라이언트들의 재시도가 같은 순간에 정렬(동기화)되어 파도처럼 몰리는 문제를 남긴다. 지수 백오프에 jitter를 더하면 재시도 시점이 분산되어 thundering herd를 깨고 서버가 회복할 여유를 준다. 여기에 circuit breaker를 결합하면 더 안전하다."},{"t":"choice","k":"백프레셔·과부하","q":"생산자가 소비자보다 빠른 스트리밍 파이프라인에서 '무한 버퍼'로 대응할 때의 근본적 위험과 올바른 대안은?","o":["위험이 없다; 버퍼는 크면 클수록 항상 좋다","버퍼가 무한정 쌓여 메모리 고갈과 큐잉 지연 폭증(bufferbloat)을 부르므로, 경계 버퍼 + 백프레셔(생산자 속도 조절)나 load shedding으로 대응해야 한다","소비자를 무한히 늘리기만 하면 백프레셔가 불필요하다","백프레셔 대신 재시도를 늘리면 해결된다"],"a":1,"ex":"무한/과대 버퍼는 부하가 지속되면 메모리를 소진하고 큐 대기 시간이 무한히 증가한다(bufferbloat). 경계된 버퍼로 상류에 역압(backpressure)을 전달해 생산 속도를 늦추거나, 감당 못 할 요청을 조기에 버리는 load shedding으로 시스템을 보호해야 한다. 재시도를 늘리면 오히려 부하가 커진다."},{"t":"input","k":"용량·Little's Law","q":"어떤 서비스의 평균 요청 도착률이 4000 req/s이고 요청당 평균 응답 시간이 25ms이다. Little's Law(L = 람다 x W)로 계산할 때, 시스템 내에 동시에 존재하는 평균 요청 수(concurrency)는 몇 개인가? 숫자만 답하라.","a":["100","100개","L=100"],"ex":"L = 람다 x W = 4000(req/s) x 0.025(s) = 100. 정상 상태에서 시스템은 평균 100개의 요청을 동시에 처리 중이며, 이는 필요한 스레드/동시성 슬롯 규모 산정의 기준이 된다. 25ms를 0.025s로 환산하는 단위 변환이 핵심이다."}],"th":{"sum":"시니어 실전: 정족수·인과 일관성·**Raft** 리더 선출·PACELC를 실제 시나리오로 판단한다. CP 시스템이 소수파 쓰기를 왜 거부하는지가 핵심.","body":[{"h":"정족수와 인과 일관성","t":"쓰기 ack 직후 읽기가 반드시 그 값을 보게 하려면 W+R>N이 필요하다. N=6, W=4면 R은 최소 3이어야 정족수가 겹친다(4+3>6). '원글보다 답글이 먼저' 보이는 이상을 막는 가장 약한 모델은 인과 일관성(causal consistency)이다. R+W>N에도 stale read가 나는 대표 원인은 비동기 복제 지연·읽기가 갱신 안 된 노드로 구성됨이다."},{"h":"CP 시스템과 Raft","t":"동기 복제 leader(CP)가 분단 중 소수파에서 쓰기를 거부하는 이유는, 소수파가 커밋하면 다수파와 충돌해 split-brain·데이터 불일치가 생기기 때문이다. 과반 정족수를 못 얻으면 안전하게 거부한다. Raft에서 candidate가 리더가 되려면 과반 노드의 투표를 얻어야 하고, 자신의 로그가 최소한 투표자만큼 최신이어야 한다."}],"code":{"c":"N=6, W=4 → R ≥ 3  (W+R>N: 4+3>6)\nPA/EL(Dynamo): 분단 시 가용성, 정상 시 지연 우선\n\nRaft 리더 조건: 과반 득표 + 최신 로그(up-to-date)","cap":"정족수 계산과 Raft 선출 조건"},"key":["N=6, W=4면 R 최소 3 (W+R>N)","답글 역전 방지 = 인과 일관성(최소 비용)","CP 소수파 쓰기 거부 = split-brain 방지","Raft 리더 = 과반 득표 + 최신 로그"]}},{"t":"시니어 실전 IV","q":[{"t":"input","k":"내구성·로그","q":"데이터 페이지를 실제로 갱신하기 '전에' 변경 내용을 먼저 순차적으로 디스크 로그에 기록하여, 크래시 복구 시 redo/undo로 커밋된 트랜잭션의 원자성과 durability를 보장하는 기법의 약어(3글자)는?","a":["WAL","write-ahead log","write ahead log","선행 기록 로그","선행기록로그"],"ex":"WAL(Write-Ahead Log)의 규칙은 '데이터 페이지보다 그에 해당하는 로그 레코드를 먼저 디스크에 fsync한다'이다. 덕분에 크래시 후 커밋된 변경은 redo로 재적용, 미완료 변경은 undo로 롤백할 수 있다. 순차 append라 쓰기 성능도 좋아 대부분의 RDBMS와 LSM 엔진의 내구성 기반이다."},{"t":"input","k":"캐시 스탬피드","q":"인기 있는 캐시 키의 TTL이 만료되는 바로 그 순간, 캐시된 값을 기다리던 다수의 요청이 동시에 원본 DB로 몰려 백엔드를 과부하시키는 현상을 가리키는 영문 용어를 하나 답하라.","a":["cache stampede","thundering herd","dog-pile","dogpile","dog pile","캐시 스탬피드"],"ex":"cache stampede(= thundering herd, dog-piling)는 hot key 만료 순간 다수 요청이 동시에 재계산에 돌입해 DB를 때리는 문제다. 완화책으로는 하나의 요청만 재계산하는 단일비행(single-flight) 락, 만료 전 확률적 조기 갱신(probabilistic early expiration), TTL 지터 등이 있다."},{"t":"input","k":"분산 락·펜싱","q":"분산 락에서 클라이언트가 락을 잡은 뒤 GC 멈춤 등으로 임대(lease)가 만료됐는데도 뒤늦게 쓰기를 시도하는 문제를, 스토리지가 단조 증가하는 번호로 옛(stale) 쓰기를 거부하게 만들어 막는 기법의 이름은? (영문 용어)","a":["fencing token","fencing tokens","fencing","펜싱 토큰","펜싱토큰"],"ex":"락 획득 시 단조 증가하는 fencing token을 발급하고, 스토리지는 지금까지 본 최대 토큰보다 작은 토큰의 쓰기를 거부한다. 그래서 멈췄다 깨어난 옛 클라이언트의 stale 쓰기가 차단된다. 락 서비스만으로는 프로세스 멈춤을 막을 수 없어 fencing이 필요하다."}],"th":{"sum":"시니어 실전: 정족수·인과 일관성·**Raft** 리더 선출·PACELC를 실제 시나리오로 판단한다. CP 시스템이 소수파 쓰기를 왜 거부하는지가 핵심.","body":[{"h":"정족수와 인과 일관성","t":"쓰기 ack 직후 읽기가 반드시 그 값을 보게 하려면 W+R>N이 필요하다. N=6, W=4면 R은 최소 3이어야 정족수가 겹친다(4+3>6). '원글보다 답글이 먼저' 보이는 이상을 막는 가장 약한 모델은 인과 일관성(causal consistency)이다. R+W>N에도 stale read가 나는 대표 원인은 비동기 복제 지연·읽기가 갱신 안 된 노드로 구성됨이다."},{"h":"CP 시스템과 Raft","t":"동기 복제 leader(CP)가 분단 중 소수파에서 쓰기를 거부하는 이유는, 소수파가 커밋하면 다수파와 충돌해 split-brain·데이터 불일치가 생기기 때문이다. 과반 정족수를 못 얻으면 안전하게 거부한다. Raft에서 candidate가 리더가 되려면 과반 노드의 투표를 얻어야 하고, 자신의 로그가 최소한 투표자만큼 최신이어야 한다."}],"code":{"c":"N=6, W=4 → R ≥ 3  (W+R>N: 4+3>6)\nPA/EL(Dynamo): 분단 시 가용성, 정상 시 지연 우선\n\nRaft 리더 조건: 과반 득표 + 최신 로그(up-to-date)","cap":"정족수 계산과 Raft 선출 조건"},"key":["N=6, W=4면 R 최소 3 (W+R>N)","답글 역전 방지 = 인과 일관성(최소 비용)","CP 소수파 쓰기 거부 = split-brain 방지","Raft 리더 = 과반 득표 + 최신 로그"]}}]},{"t":"용량 산정 심화: QPS·저장량·대역폭 실무 추정","l":[{"t":"QPS와 피크 배수 추정하기","q":[{"t":"choice","k":"sysd-cap-qps-basic","q":"하루 100만 건의 요청이 균등하게 들어온다면 평균 QPS는 대략 얼마인가?","ex":"1,000,000 ÷ 86,400 ≈ 11.6이므로 약 12 QPS다.\n💡 개념: 하루는 86,400초이고 실무에서는 10만 초로 근사해 자릿수를 빠르게 잡는다.\n🛠 실무: '하루 100만 = 약 12 QPS'를 기준점으로 외워두면 어떤 규모든 곱셈만으로 감을 잡을 수 있다.","o":["약 12 QPS","약 1.2 QPS","약 120 QPS","약 1,200 QPS"],"a":0},{"t":"choice","k":"sysd-cap-qps-dau","q":"DAU 1,000만 명이 하루 평균 20건의 쓰기를 한다면 평균 쓰기 QPS는?","ex":"1,000만 × 20 = 2억 건/일, 2억 ÷ 86,400 ≈ 2,315 QPS다.\n💡 개념: 건수를 먼저 하루 총량으로 만든 뒤 86,400으로 나누는 순서가 실수를 줄인다.\n🛠 실무: 이 정도면 단일 인스턴스 RDB의 쓰기 한계에 근접하므로 샤딩이나 큐 완충을 검토하기 시작한다.","o":["약 230 QPS","약 23,000 QPS","약 2,300 QPS","약 230,000 QPS"],"a":2},{"t":"choice","k":"sysd-cap-peak","q":"평균 QPS만 기준으로 서버 대수를 산정하면 생기는 대표적인 문제는?","ex":"트래픽은 균등하지 않으므로 평균 기준 산정은 피크에서 반드시 부족해진다.\n💡 개념: 보통 평균의 2~5배를 피크 배수로 잡고, 그 값으로 설계 목표를 세운다.\n🛠 실무: 실제 서비스의 시간대별 트래픽 그래프에서 최대/평균 비율을 뽑아 자기 서비스 고유의 피크 배수를 쓰는 것이 가장 정확하다.","o":["저장 용량이 부족해진다","네트워크 대역폭 요금이 줄어든다","데이터 일관성이 깨진다","피크 시간대에 처리 용량이 모자라 지연과 오류가 폭증한다"],"a":3},{"t":"choice","k":"sysd-cap-rw-ratio","q":"읽기와 쓰기 비율이 100:1이고 쓰기가 평균 2,000 QPS라면 읽기 QPS는?","ex":"2,000 × 100 = 200,000 QPS다.\n💡 개념: 읽기 편향이 심한 서비스에서는 읽기 경로가 아키텍처를 지배한다.\n🛠 실무: 이 규모의 읽기는 원본 DB로 감당할 수 없으므로 캐시 계층과 읽기 복제본이 사실상 필수가 된다.","o":["약 200,000 QPS","약 2,000 QPS","약 20,000 QPS","약 2,000,000 QPS"],"a":0},{"t":"input","k":"sysd-cap-qps-calc","q":"하루 4억 3,200만 건의 요청이 균등하게 들어올 때 평균 QPS는 정확히 얼마인가? (숫자만)","ex":"432,000,000 ÷ 86,400 = 5,000 QPS다.\n💡 개념: 86,400으로 나누어떨어지는 값을 예시로 쓰면 검산이 쉬워진다.\n🛠 실무: 산정표를 만들 때는 이렇게 깔끔한 기준값을 하나 두고 배수로 확장하면 계산 실수가 줄어든다.","a":["5000","5,000"]},{"t":"choice","k":"sysd-cap-little","q":"리틀의 법칙 L = λW를 적용해, 평균 도착률 2,000 QPS와 평균 응답 시간 50ms에서 시스템에 동시에 머무르는 요청 수는?","ex":"L = 2,000 × 0.05 = 100건이다.\n💡 개념: 리틀의 법칙은 대기열 이론의 기본 항등식으로, 도착률과 체류 시간만 알면 동시성을 알 수 있다.\n🛠 실무: 이 값이 스레드 풀·커넥션 풀 크기 산정의 출발점이며, 풀이 이보다 작으면 큐잉이 생긴다.","o":["10건","1,000건","100건","4,000건"],"a":2}],"th":{"sum":"설계 면접과 실무 모두에서 첫 단계는 봉투 뒷면 계산이다. DAU와 행동 빈도에서 QPS를 뽑고, 레코드 크기에서 저장량을, 응답 크기에서 대역폭을 뽑아 규모의 자릿수를 먼저 맞춘다.","body":[{"h":"왜 자릿수부터 맞추는가","t":"용량 산정의 목적은 정확한 숫자가 아니라 올바른 자릿수다. 초당 100건짜리 시스템과 초당 10만 건짜리 시스템은 같은 아키텍처를 쓸 수 없기 때문이다. 자릿수가 정해지면 단일 DB로 갈지, 샤딩이 필요한지, 캐시가 필수인지가 자동으로 결정된다. 그래서 계산은 거칠어도 되지만 지수는 틀리면 안 된다."},{"h":"QPS 추정과 피크 배수","t":"하루는 86,400초이므로 실무에서는 약 10만 초로 근사한다. 즉 하루 100만 건은 대략 12 QPS다. 그런데 트래픽은 하루 종일 균등하지 않으므로 평균 QPS에 보통 2~5배의 피크 배수를 곱해 설계 목표를 잡는다. 평균만 보고 서버를 산정하면 점심시간이나 이벤트 시간대에 그대로 무너진다."},{"h":"저장량은 원본이 아니라 총량으로","t":"저장량은 레코드 크기 × 건수로 시작하지만 그게 끝이 아니다. 복제본 개수, 인덱스, 백업과 스냅샷, 로그와 파생 데이터가 붙으면 실제 필요한 원시 용량은 2~3배가 된다. 여기에 보존 기간을 곱해야 정상 상태(steady state) 용량이 나온다. 보존 정책이 없는 시스템은 용량 산정 자체가 불가능하다."},{"h":"대역폭과 동시성","t":"대역폭은 QPS × 평균 페이로드 크기이고, 네트워크 단위는 비트이므로 바이트에 8을 곱해야 한다. 동시 처리 개수는 리틀의 법칙 L = λ × W로 잡는다. 초당 2,000건이 들어오고 평균 응답이 50ms라면 항상 100건이 시스템 안에 머무른다는 뜻이고, 이 값이 스레드 풀과 커넥션 풀 크기의 출발점이 된다."}],"code":{"c":"[1] QPS\nDAU 1,000만 × 쓰기 20건/일 = 2억 건/일\n2억 ÷ 86,400초 ≈ 2,315 QPS  (평균)\n피크 배수 3배 → 약 7,000 QPS (설계 목표)\n읽기:쓰기 = 100:1 → 읽기 약 231,500 QPS → 캐시 필수\n\n[2] 저장량\n건당 레코드 1KB × 2억 = 200GB/일\n200GB × 365 ≈ 73TB/년\n복제 3벌 → 약 219TB/년 (인덱스·백업 별도)\n\n[3] 대역폭\n7,000 QPS × 1KB = 7MB/s = 56Mbps\n\n[4] 동시성 (리틀의 법칙 L = λW)\nλ = 2,000/s, W = 50ms → L = 100건 동시 처리","cap":"하루 86,400초, 바이트→비트 ×8, L = λW 세 가지만 외우면 대부분 산정이 된다."},"key":["하루 100만 건 ≈ 12 QPS, 하루는 86,400초(≈10만 초)로 근사한다","평균 QPS가 아니라 피크 QPS(보통 평균의 2~5배)로 용량을 잡는다","저장량은 복제·인덱스·백업까지 더해야 실제 원시 용량이 된다"]}},{"t":"저장량·보존 기간·복제 산정","q":[{"t":"choice","k":"sysd-cap-storage-day","q":"하루 2억 건의 레코드가 생기고 건당 크기가 1KB라면 하루 저장 증가량은?","ex":"2억 × 1KB = 2×10^8 KB = 2×10^5 MB = 200GB다.\n💡 개념: KB→MB→GB로 한 단계씩 1,000으로 나누며 자릿수를 확인하면 실수가 없다.\n🛠 실무: 하루 증가량을 알면 디스크 알람 임계값과 확장 주기를 바로 계산할 수 있다.","o":["약 20GB","약 2TB","약 20TB","약 200GB"],"a":3},{"t":"choice","k":"sysd-cap-storage-year","q":"하루 200GB씩 쌓이는 데이터를 1년간 보존한다면 필요한 논리 저장량은?","ex":"200GB × 365 = 73,000GB = 73TB다.\n💡 개념: 1년은 약 365일이므로 하루 용량에 365를 곱하면 연간 논리 용량이 나온다.\n🛠 실무: 보존 기간 정책이 없으면 이 값이 무한대로 발산하므로, 용량 산정 전에 TTL과 아카이빙 정책을 먼저 정해야 한다.","o":["약 7.3TB","약 73TB","약 730TB","약 2.4TB"],"a":1},{"t":"choice","k":"sysd-cap-replica","q":"논리 저장량이 73TB인 데이터를 3중 복제로 저장할 때 필요한 원시(raw) 저장 용량은 대략 얼마인가?","ex":"73TB × 3 = 219TB이며, 인덱스와 백업은 여기에 더 추가된다.\n💡 개념: 복제 계수는 내구성을 위한 비용이며 저장 단가를 그대로 배수로 키운다.\n🛠 실무: 소거 부호(erasure coding)를 쓰면 1.5배 수준으로 낮출 수 있지만 복구 비용과 지연이 커지는 트레이드오프가 있다.","o":["약 219TB","약 73TB","약 146TB","약 24TB"],"a":0},{"t":"choice","k":"sysd-cap-photo","q":"하루 500만 장의 사진이 업로드되고 평균 크기가 2MB라면 1년치 원본 저장량은 대략?","ex":"500만 × 2MB = 10,000,000MB = 10TB/일이고, 10TB × 365 = 3,650TB = 3.65PB다.\n💡 개념: PB 단위가 나오면 오브젝트 스토리지와 계층형 저장이 전제가 된다.\n🛠 실무: 이 규모에서는 썸네일 등 파생 이미지가 원본의 20~50%를 추가로 차지하므로 함께 산정해야 한다.","o":["약 365TB","약 36.5TB","약 3.65PB","약 36.5PB"],"a":2},{"t":"input","k":"sysd-cap-retention","q":"하루 1TB씩 데이터가 쌓이고 90일이 지나면 자동 삭제되는 시스템의 정상 상태 저장량은 몇 TB인가? (복제 미고려, 숫자만)","ex":"1TB × 90일 = 90TB에서 유입과 삭제가 균형을 이루어 더 이상 늘지 않는다.\n💡 개념: 보존 기간이 있는 시스템은 저장량이 발산하지 않고 특정 값으로 수렴한다.\n🛠 실무: 정상 상태 값을 알면 디스크를 한 번만 제대로 프로비저닝하면 되므로 운영이 훨씬 단순해진다.","a":["90","90TB"]}],"th":{"sum":"설계 면접과 실무 모두에서 첫 단계는 봉투 뒷면 계산이다. DAU와 행동 빈도에서 QPS를 뽑고, 레코드 크기에서 저장량을, 응답 크기에서 대역폭을 뽑아 규모의 자릿수를 먼저 맞춘다.","body":[{"h":"왜 자릿수부터 맞추는가","t":"용량 산정의 목적은 정확한 숫자가 아니라 올바른 자릿수다. 초당 100건짜리 시스템과 초당 10만 건짜리 시스템은 같은 아키텍처를 쓸 수 없기 때문이다. 자릿수가 정해지면 단일 DB로 갈지, 샤딩이 필요한지, 캐시가 필수인지가 자동으로 결정된다. 그래서 계산은 거칠어도 되지만 지수는 틀리면 안 된다."},{"h":"QPS 추정과 피크 배수","t":"하루는 86,400초이므로 실무에서는 약 10만 초로 근사한다. 즉 하루 100만 건은 대략 12 QPS다. 그런데 트래픽은 하루 종일 균등하지 않으므로 평균 QPS에 보통 2~5배의 피크 배수를 곱해 설계 목표를 잡는다. 평균만 보고 서버를 산정하면 점심시간이나 이벤트 시간대에 그대로 무너진다."},{"h":"저장량은 원본이 아니라 총량으로","t":"저장량은 레코드 크기 × 건수로 시작하지만 그게 끝이 아니다. 복제본 개수, 인덱스, 백업과 스냅샷, 로그와 파생 데이터가 붙으면 실제 필요한 원시 용량은 2~3배가 된다. 여기에 보존 기간을 곱해야 정상 상태(steady state) 용량이 나온다. 보존 정책이 없는 시스템은 용량 산정 자체가 불가능하다."},{"h":"대역폭과 동시성","t":"대역폭은 QPS × 평균 페이로드 크기이고, 네트워크 단위는 비트이므로 바이트에 8을 곱해야 한다. 동시 처리 개수는 리틀의 법칙 L = λ × W로 잡는다. 초당 2,000건이 들어오고 평균 응답이 50ms라면 항상 100건이 시스템 안에 머무른다는 뜻이고, 이 값이 스레드 풀과 커넥션 풀 크기의 출발점이 된다."}],"code":{"c":"[1] QPS\nDAU 1,000만 × 쓰기 20건/일 = 2억 건/일\n2억 ÷ 86,400초 ≈ 2,315 QPS  (평균)\n피크 배수 3배 → 약 7,000 QPS (설계 목표)\n읽기:쓰기 = 100:1 → 읽기 약 231,500 QPS → 캐시 필수\n\n[2] 저장량\n건당 레코드 1KB × 2억 = 200GB/일\n200GB × 365 ≈ 73TB/년\n복제 3벌 → 약 219TB/년 (인덱스·백업 별도)\n\n[3] 대역폭\n7,000 QPS × 1KB = 7MB/s = 56Mbps\n\n[4] 동시성 (리틀의 법칙 L = λW)\nλ = 2,000/s, W = 50ms → L = 100건 동시 처리","cap":"하루 86,400초, 바이트→비트 ×8, L = λW 세 가지만 외우면 대부분 산정이 된다."},"key":["하루 100만 건 ≈ 12 QPS, 하루는 86,400초(≈10만 초)로 근사한다","평균 QPS가 아니라 피크 QPS(보통 평균의 2~5배)로 용량을 잡는다","저장량은 복제·인덱스·백업까지 더해야 실제 원시 용량이 된다"]}},{"t":"대역폭·캐시·산정 함정 실무","q":[{"t":"choice","k":"sysd-cap-bandwidth","q":"5,000 QPS로 평균 1KB 응답을 내보낼 때 필요한 네트워크 대역폭은 대략 얼마인가?","ex":"5,000 × 1KB = 5MB/s이고, 바이트를 비트로 바꾸면 5 × 8 = 40Mbps다.\n💡 개념: 저장 용량은 바이트, 네트워크는 비트 단위이므로 8배 차이를 늘 확인해야 한다.\n🛠 실무: 이 계산을 빠뜨리면 대역폭을 8배 과소 산정해 인스턴스 네트워크 한계에 부딪힌다.","o":["약 5Mbps","약 400Mbps","약 5Gbps","약 40Mbps"],"a":3},{"t":"choice","k":"sysd-cap-video","q":"동시 시청자 10,000명에게 각각 5Mbps 비트레이트로 영상을 내보낼 때 총 출력 대역폭은?","ex":"10,000 × 5Mbps = 50,000Mbps = 50Gbps다.\n💡 개념: 스트리밍은 QPS가 아니라 동시 연결 수 × 비트레이트가 지배한다.\n🛠 실무: 이 규모의 이그레스는 원본 서버가 아니라 CDN이 흡수해야 하며, 전송 요금이 인프라 비용의 최대 항목이 되기 쉽다.","o":["약 50Gbps","약 50Mbps","약 5Gbps","약 500Gbps"],"a":0},{"t":"choice","k":"sysd-cap-cache-node","q":"하루 읽기 대상 데이터가 1TB이고 80/20 법칙에 따라 그중 20%만 캐시한다고 하자. 캐시 노드 한 대의 가용 메모리가 64GB일 때 최소 몇 대가 필요한가?","ex":"1TB의 20%는 200GB이고, 200 ÷ 64 = 3.125이므로 올림하여 4대가 필요하다.\n💡 개념: 캐시 용량 산정은 항상 올림해야 하며, 여기에 복제와 여유분이 더 붙는다.\n🛠 실무: 실제로는 직렬화 오버헤드와 메모리 단편화 때문에 계산값보다 20~30% 더 잡는 것이 안전하다.","o":["2대","3대","4대","8대"],"a":2},{"t":"choice","k":"sysd-cap-pitfall","q":"저장 용량을 산정할 때 자주 빠뜨려서 실제 필요 용량이 2~3배로 커지게 만드는 요소들은?","ex":"복제·인덱스·백업·로그는 모두 실제 디스크를 차지하지만 초기 산정에서 자주 누락된다.\n💡 개념: 사용자 데이터 크기는 총 저장량의 절반도 안 되는 경우가 흔하다.\n🛠 실무: 산정표에 '오버헤드 계수'를 명시적으로 한 줄 넣어두면 팀 간 합의가 쉬워진다.","o":["CPU 코어 수와 클럭","로드 밸런서의 연결 수","DNS TTL 설정","복제본, 인덱스, 백업과 스냅샷, 로그"],"a":3},{"t":"input","k":"sysd-cap-bit-byte","q":"초당 10MB의 데이터를 전송할 때 필요한 대역폭은 몇 Mbps인가? (숫자만)","ex":"1바이트는 8비트이므로 10MB/s × 8 = 80Mbps다.\n💡 개념: MB/s와 Mbps는 8배 차이가 나며 이를 혼동하는 것이 용량 산정의 대표적 실수다.\n🛠 실무: 클라우드 인스턴스의 네트워크 사양은 Gbps로 표기되므로 항상 비트 단위로 환산해 비교해야 한다.","a":["80","80Mbps"]}],"th":{"sum":"설계 면접과 실무 모두에서 첫 단계는 봉투 뒷면 계산이다. DAU와 행동 빈도에서 QPS를 뽑고, 레코드 크기에서 저장량을, 응답 크기에서 대역폭을 뽑아 규모의 자릿수를 먼저 맞춘다.","body":[{"h":"왜 자릿수부터 맞추는가","t":"용량 산정의 목적은 정확한 숫자가 아니라 올바른 자릿수다. 초당 100건짜리 시스템과 초당 10만 건짜리 시스템은 같은 아키텍처를 쓸 수 없기 때문이다. 자릿수가 정해지면 단일 DB로 갈지, 샤딩이 필요한지, 캐시가 필수인지가 자동으로 결정된다. 그래서 계산은 거칠어도 되지만 지수는 틀리면 안 된다."},{"h":"QPS 추정과 피크 배수","t":"하루는 86,400초이므로 실무에서는 약 10만 초로 근사한다. 즉 하루 100만 건은 대략 12 QPS다. 그런데 트래픽은 하루 종일 균등하지 않으므로 평균 QPS에 보통 2~5배의 피크 배수를 곱해 설계 목표를 잡는다. 평균만 보고 서버를 산정하면 점심시간이나 이벤트 시간대에 그대로 무너진다."},{"h":"저장량은 원본이 아니라 총량으로","t":"저장량은 레코드 크기 × 건수로 시작하지만 그게 끝이 아니다. 복제본 개수, 인덱스, 백업과 스냅샷, 로그와 파생 데이터가 붙으면 실제 필요한 원시 용량은 2~3배가 된다. 여기에 보존 기간을 곱해야 정상 상태(steady state) 용량이 나온다. 보존 정책이 없는 시스템은 용량 산정 자체가 불가능하다."},{"h":"대역폭과 동시성","t":"대역폭은 QPS × 평균 페이로드 크기이고, 네트워크 단위는 비트이므로 바이트에 8을 곱해야 한다. 동시 처리 개수는 리틀의 법칙 L = λ × W로 잡는다. 초당 2,000건이 들어오고 평균 응답이 50ms라면 항상 100건이 시스템 안에 머무른다는 뜻이고, 이 값이 스레드 풀과 커넥션 풀 크기의 출발점이 된다."}],"code":{"c":"[1] QPS\nDAU 1,000만 × 쓰기 20건/일 = 2억 건/일\n2억 ÷ 86,400초 ≈ 2,315 QPS  (평균)\n피크 배수 3배 → 약 7,000 QPS (설계 목표)\n읽기:쓰기 = 100:1 → 읽기 약 231,500 QPS → 캐시 필수\n\n[2] 저장량\n건당 레코드 1KB × 2억 = 200GB/일\n200GB × 365 ≈ 73TB/년\n복제 3벌 → 약 219TB/년 (인덱스·백업 별도)\n\n[3] 대역폭\n7,000 QPS × 1KB = 7MB/s = 56Mbps\n\n[4] 동시성 (리틀의 법칙 L = λW)\nλ = 2,000/s, W = 50ms → L = 100건 동시 처리","cap":"하루 86,400초, 바이트→비트 ×8, L = λW 세 가지만 외우면 대부분 산정이 된다."},"key":["하루 100만 건 ≈ 12 QPS, 하루는 86,400초(≈10만 초)로 근사한다","평균 QPS가 아니라 피크 QPS(보통 평균의 2~5배)로 용량을 잡는다","저장량은 복제·인덱스·백업까지 더해야 실제 원시 용량이 된다"]}}]},{"t":"큐와 백프레셔 심화: 부하 차단(load shedding) 실무","l":[{"t":"큐, 지연, 백프레셔의 원리","q":[{"t":"choice","k":"sysd-q-lambda-mu","q":"도착률이 처리율보다 큰 상태가 지속될 때, 경계 없는(unbounded) 큐를 사용하면 어떤 일이 벌어지는가?","ex":"λ &gt; μ가 지속되면 큐 길이는 선형으로 증가하고 지연과 메모리 사용량이 함께 발산한다.\n💡 개념: 큐는 평균 처리 능력을 바꾸지 못하며 오직 순간 버스트만 흡수한다.\n🛠 실무: 그래서 프로덕션 큐에는 반드시 최대 크기와 초과 시 거절 정책을 설정한다.","o":["큐가 자동으로 처리율을 높여 균형을 맞춘다","대기 시간이 계속 늘어나다가 메모리가 고갈되어 프로세스가 죽는다","오래된 메시지가 자동으로 폐기되어 안정 상태가 된다","도착률이 자동으로 낮아진다"],"a":1},{"t":"choice","k":"sysd-q-little-wait","q":"큐에 8,000건이 대기 중이고 처리율이 800건/초라면 지금 들어온 요청의 예상 대기 시간은?","ex":"8,000 ÷ 800 = 10초다.\n💡 개념: 대기 시간 = 큐 길이 ÷ 처리율이며 이는 리틀의 법칙의 변형이다.\n🛠 실무: 클라이언트 타임아웃이 3초라면 이 요청은 처리되어도 이미 버려진 뒤이므로 차라리 즉시 거절하는 편이 낫다.","o":["약 10초","약 0.1초","약 1초","약 100초"],"a":0},{"t":"choice","k":"sysd-q-saturate","q":"도착률 1,000 req/s, 처리율 800 req/s, 큐 상한 10,000일 때 큐가 가득 차기까지 걸리는 시간은?","ex":"초과분이 200 req/s이므로 10,000 ÷ 200 = 50초다.\n💡 개념: 큐가 사주는 것은 용량이 아니라 시간이며, 그 시간 안에 대응이 끝나야 한다.\n🛠 실무: 오토스케일이 붙는 데 3분이 걸린다면 50초짜리 큐는 아무것도 구해주지 못하므로 부하 차단이 함께 필요하다.","o":["약 10초","약 100초","약 50초","약 125초"],"a":2},{"t":"choice","k":"sysd-q-backpressure-def","q":"백프레셔(backpressure)를 가장 정확하게 설명한 것은?","ex":"백프레셔는 버퍼에 쌓는 대신 상류의 생산 속도를 낮추도록 신호를 되돌리는 것이다.\n💡 개념: 문제를 하류에 축적하지 않고 상류로 밀어 올리는 것이 핵심이다.\n🛠 실무: 백프레셔가 없는 파이프라인은 결국 어딘가에서 메모리로 터진다.","o":["실패한 요청을 자동으로 재시도하는 기능","큐 크기를 무제한으로 늘려 요청을 모두 받아들이는 전략","부하가 높을 때 응답 데이터를 압축하는 기법","소비자가 감당 가능한 속도를 생산자에게 되돌려 알려 유입 자체를 늦추는 메커니즘"],"a":3},{"t":"choice","k":"sysd-q-backpressure-ex","q":"다음 중 백프레셔 메커니즘의 예로 볼 수 없는 것은?","ex":"무한 즉시 재시도는 유입을 줄이기는커녕 증폭시키므로 백프레셔의 정반대다.\n💡 개념: 백프레셔는 수요를 표현하는 신호이지 실패 처리 정책이 아니다.\n🛠 실무: 재시도 로직을 넣을 때는 반드시 백오프와 상한을 함께 넣어야 한다.","o":["실패한 요청을 즉시 무한 재시도하는 클라이언트","TCP 수신 윈도우를 통한 흐름 제어","Reactive Streams의 request(n) 기반 수요 신호","gRPC 스트리밍의 흐름 제어"],"a":0},{"t":"input","k":"sysd-q-little-name","q":"평균 대기 개수 L, 도착률 λ, 체류 시간 W 사이에 L = λW가 성립한다는 대기열 이론의 법칙 이름은? (한글 또는 영문)","ex":"정답은 리틀의 법칙(Little's law)이다.\n💡 개념: 이 법칙은 도착 분포와 무관하게 정상 상태에서 항상 성립한다.\n🛠 실무: 큐 길이, 처리율, 대기 시간 중 두 개만 측정해도 나머지를 계산할 수 있어 용량 산정에 매우 유용하다.","a":["리틀의 법칙","리틀 법칙","Little's law","little's law","littles law"]}],"th":{"sum":"큐는 순간적인 버스트를 흡수하는 버퍼일 뿐, 평균 처리 용량을 늘려주지 않는다. 도착률이 처리율을 지속적으로 넘으면 남은 선택지는 백프레셔로 유입을 줄이거나 부하를 차단하는 것뿐이다.","body":[{"h":"큐는 용량이 아니라 시간을 산다","t":"도착률 λ가 처리율 μ보다 크면 큐는 매초 (λ - μ)만큼 쌓인다. 큐를 아무리 크게 잡아도 λ > μ가 지속되는 한 언젠가는 가득 찬다. 큐가 사주는 것은 용량이 아니라 시간이며, 그 시간 동안 오토스케일이 붙거나 트래픽이 잦아들어야만 의미가 있다. 그래서 큐를 넣는 결정에는 항상 '언제까지 버티는가'라는 계산이 따라야 한다."},{"h":"무한 큐가 가장 위험하다","t":"경계 없는 큐는 장애를 즉시 드러내지 않고 지연으로 바꿔 숨긴다. 요청은 계속 받아들여지지만 응답은 점점 느려지고, 결국 클라이언트 타임아웃 뒤에도 서버는 이미 버려진 요청을 계속 처리한다. 여기에 메모리까지 차오르면 OOM으로 프로세스 전체가 죽는다. 그래서 실무의 기본은 항상 상한이 있는 큐와 명시적 거절이다."},{"h":"백프레셔: 상류에 신호를 되돌린다","t":"백프레셔는 소비자가 감당 가능한 속도를 생산자에게 알려 유입 자체를 늦추는 메커니즘이다. TCP의 수신 윈도우, Reactive Streams의 request(n), gRPC의 흐름 제어가 모두 같은 원리다. 핵심은 '버퍼에 쌓기' 대신 '받지 않기'로 문제를 상류로 밀어 올리는 것이다. 상류가 사람이라면 결국 요청 속도가 자연스럽게 줄어든다."},{"h":"부하 차단과 재시도 폭풍","t":"부하 차단은 과부하 상황에서 일부 요청을 빠르게 거절해 나머지 요청을 SLO 안에서 처리하는 전략이다. 이때 429나 503을 즉시 반환해야 클라이언트가 자원을 붙잡고 있지 않는다. 다만 클라이언트가 즉시 재시도하면 오히려 부하가 증폭되는 재시도 폭풍이 생기므로, 지수 백오프에 지터를 더하고 재시도 예산을 두어야 한다. 서킷 브레이커는 실패가 임계치를 넘으면 호출 자체를 끊어 회복 시간을 벌어준다."}],"code":{"c":"[포화까지 남은 시간]\n도착률 λ = 1,000 req/s, 처리율 μ = 800 req/s\n초과분 = 200 req/s\n큐 상한 10,000 → 10,000 ÷ 200 = 50초 후 포화\n\n[큐 대기 시간 = 리틀의 법칙]\n큐에 8,000건 대기, μ = 800/s\nW = L ÷ μ = 8,000 ÷ 800 = 10초  ← 이미 SLO 초과\n\n[처리 순서]\n1) 유입 제한(rate limit) → 2) 백프레셔(수용 속도 하향)\n3) 부하 차단(저우선순위부터 429/503) → 4) 서킷 브레이커\n\n재시도는 지수 백오프 + 지터:\n  wait = random(0, base * 2^attempt)","cap":"큐 대기 시간이 클라이언트 타임아웃을 넘는 순간, 그 처리는 전부 낭비다."},"key":["큐는 버스트를 흡수할 뿐 평균 처리 용량(μ)을 늘리지 않는다","경계 없는 큐는 지연 폭발과 OOM으로 장애를 키우므로 상한과 거절이 기본이다","과부하에서는 느린 성공보다 빠른 거절이 낫고, 재시도에는 지수 백오프와 지터가 필수다"]}},{"t":"부하 차단과 우선순위 설계","q":[{"t":"choice","k":"sysd-shed-def","q":"부하 차단(load shedding)의 목적을 가장 잘 설명한 것은?","ex":"전부를 느리게 실패시키는 대신 일부를 명시적으로 포기해 나머지를 살리는 전략이다.\n💡 개념: 과부하에서 100%의 성공률을 고집하면 결국 0%에 수렴한다.\n🛠 실무: 차단 비율과 기준을 대시보드에 노출해 두어야 장애 대응 시 판단이 빨라진다.","o":["모든 요청을 반드시 처리하기 위해 큐를 늘리는 것","장애가 난 서버를 자동으로 재부팅하는 것","과부하 시 일부 요청을 빠르게 거절해 남은 요청은 SLO 안에서 처리하는 것","요청 데이터를 압축해 대역폭을 절약하는 것"],"a":2},{"t":"choice","k":"sysd-shed-fast-fail","q":"과부하 상황에서 요청을 타임아웃까지 붙잡고 있는 것보다 즉시 429나 503으로 거절하는 편이 나은 이유는?","ex":"빠른 거절은 점유 중인 자원을 즉시 돌려주어 시스템 전체가 회복할 여지를 만든다.\n💡 개념: 이미 클라이언트 타임아웃을 넘긴 요청을 처리하는 것은 순수한 낭비다.\n🛠 실무: 큐에서 꺼낼 때 요청의 데드라인을 확인해 이미 만료된 것은 처리하지 않고 버리는 패턴이 널리 쓰인다.","o":["HTTP 상태 코드가 더 짧아 대역폭을 아끼기 때문","거절된 요청은 과금되지 않기 때문","느린 응답은 로그에 남지 않기 때문","서버와 클라이언트 양쪽의 스레드·커넥션 자원을 즉시 해제해 회복을 앞당기기 때문"],"a":3},{"t":"choice","k":"sysd-shed-priority","q":"부하 차단을 적용할 때 가장 먼저 버려야 하는 트래픽은?","ex":"사업적으로 중요도가 낮고 나중에 다시 해도 되는 트래픽부터 버려야 한다.\n💡 개념: 부하 차단은 무작위 폐기가 아니라 우선순위 기반 결정이어야 한다.\n🛠 실무: 요청에 우선순위 클래스를 부여하고 게이트웨이에서 클래스별 임계값을 다르게 두는 구성이 일반적이다.","o":["결제 완료 요청","프리페치, 추천 갱신, 배치성 재시도 같은 저우선순위 트래픽","로그인 요청","헬스 체크 요청"],"a":1},{"t":"choice","k":"sysd-shed-retry-storm","q":"장애 직후 모든 클라이언트가 동시에 재시도하면서 부하가 오히려 증폭되는 현상을 막는 가장 효과적인 조합은?","ex":"지수 백오프로 간격을 늘리고 지터로 시점을 흩뜨리며, 재시도 예산으로 전체 재시도 비율에 상한을 둔다.\n💡 개념: 고정 간격 재시도는 클라이언트들을 오히려 동기화시켜 주기적 스파이크를 만든다.\n🛠 실무: 재시도 예산은 보통 '전체 요청의 10% 이내'처럼 비율로 설정한다.","o":["지수 백오프 + 지터(jitter) + 재시도 예산(retry budget)","재시도 횟수를 무제한으로 늘리기","타임아웃을 아주 길게 설정하기","모든 클라이언트가 정확히 1초 간격으로 재시도하기"],"a":0},{"t":"choice","k":"sysd-shed-retry-myth","q":"재시도에 대한 설명 중 옳은 것은?","ex":"일시적 네트워크 오류에는 재시도가 유효하지만, 과부하로 인한 실패에는 재시도가 기름을 붓는다.\n💡 개념: 실패 원인을 구분하지 않는 재시도는 장애 증폭기다.\n🛠 실무: 429나 503처럼 과부하를 뜻하는 응답에는 Retry-After를 존중하고 백오프를 크게 잡아야 한다.","o":["재시도 횟수를 늘릴수록 가용성은 항상 올라간다","재시도는 서버 자원을 소모하지 않는다","과부하가 원인인 실패에 대한 재시도는 부하를 증폭시켜 상황을 악화시킬 수 있다","재시도는 멱등하지 않은 연산에도 항상 안전하다"],"a":2},{"t":"input","k":"sysd-shed-jitter","q":"지수 백오프에 무작위성을 더해 여러 클라이언트의 재시도 시점을 흩뜨리는 기법을 무엇이라 하는가? (한글 또는 영문)","ex":"정답은 지터(jitter)다.\n💡 개념: 백오프만 있고 지터가 없으면 클라이언트들이 같은 시점에 몰려 다시 스파이크를 만든다.\n🛠 실무: full jitter 방식(0부터 상한까지 균등 난수)이 실측에서 가장 안정적인 것으로 알려져 있다.","a":["지터","jitter","Jitter"]}],"th":{"sum":"큐는 순간적인 버스트를 흡수하는 버퍼일 뿐, 평균 처리 용량을 늘려주지 않는다. 도착률이 처리율을 지속적으로 넘으면 남은 선택지는 백프레셔로 유입을 줄이거나 부하를 차단하는 것뿐이다.","body":[{"h":"큐는 용량이 아니라 시간을 산다","t":"도착률 λ가 처리율 μ보다 크면 큐는 매초 (λ - μ)만큼 쌓인다. 큐를 아무리 크게 잡아도 λ > μ가 지속되는 한 언젠가는 가득 찬다. 큐가 사주는 것은 용량이 아니라 시간이며, 그 시간 동안 오토스케일이 붙거나 트래픽이 잦아들어야만 의미가 있다. 그래서 큐를 넣는 결정에는 항상 '언제까지 버티는가'라는 계산이 따라야 한다."},{"h":"무한 큐가 가장 위험하다","t":"경계 없는 큐는 장애를 즉시 드러내지 않고 지연으로 바꿔 숨긴다. 요청은 계속 받아들여지지만 응답은 점점 느려지고, 결국 클라이언트 타임아웃 뒤에도 서버는 이미 버려진 요청을 계속 처리한다. 여기에 메모리까지 차오르면 OOM으로 프로세스 전체가 죽는다. 그래서 실무의 기본은 항상 상한이 있는 큐와 명시적 거절이다."},{"h":"백프레셔: 상류에 신호를 되돌린다","t":"백프레셔는 소비자가 감당 가능한 속도를 생산자에게 알려 유입 자체를 늦추는 메커니즘이다. TCP의 수신 윈도우, Reactive Streams의 request(n), gRPC의 흐름 제어가 모두 같은 원리다. 핵심은 '버퍼에 쌓기' 대신 '받지 않기'로 문제를 상류로 밀어 올리는 것이다. 상류가 사람이라면 결국 요청 속도가 자연스럽게 줄어든다."},{"h":"부하 차단과 재시도 폭풍","t":"부하 차단은 과부하 상황에서 일부 요청을 빠르게 거절해 나머지 요청을 SLO 안에서 처리하는 전략이다. 이때 429나 503을 즉시 반환해야 클라이언트가 자원을 붙잡고 있지 않는다. 다만 클라이언트가 즉시 재시도하면 오히려 부하가 증폭되는 재시도 폭풍이 생기므로, 지수 백오프에 지터를 더하고 재시도 예산을 두어야 한다. 서킷 브레이커는 실패가 임계치를 넘으면 호출 자체를 끊어 회복 시간을 벌어준다."}],"code":{"c":"[포화까지 남은 시간]\n도착률 λ = 1,000 req/s, 처리율 μ = 800 req/s\n초과분 = 200 req/s\n큐 상한 10,000 → 10,000 ÷ 200 = 50초 후 포화\n\n[큐 대기 시간 = 리틀의 법칙]\n큐에 8,000건 대기, μ = 800/s\nW = L ÷ μ = 8,000 ÷ 800 = 10초  ← 이미 SLO 초과\n\n[처리 순서]\n1) 유입 제한(rate limit) → 2) 백프레셔(수용 속도 하향)\n3) 부하 차단(저우선순위부터 429/503) → 4) 서킷 브레이커\n\n재시도는 지수 백오프 + 지터:\n  wait = random(0, base * 2^attempt)","cap":"큐 대기 시간이 클라이언트 타임아웃을 넘는 순간, 그 처리는 전부 낭비다."},"key":["큐는 버스트를 흡수할 뿐 평균 처리 용량(μ)을 늘리지 않는다","경계 없는 큐는 지연 폭발과 OOM으로 장애를 키우므로 상한과 거절이 기본이다","과부하에서는 느린 성공보다 빠른 거절이 낫고, 재시도에는 지수 백오프와 지터가 필수다"]}},{"t":"큐 기반 시스템 운영 실무","q":[{"t":"choice","k":"sysd-q-capacity-myth","q":"'앞에 메시지 큐를 넣으면 시스템 처리 용량이 늘어난다'는 주장에 대한 올바른 평가는?","ex":"평균 처리 용량은 소비자의 처리율 μ가 결정하며, 큐는 시간 축에서 부하를 평탄화할 뿐이다.\n💡 개념: 큐는 지연을 늘리는 대신 스파이크를 흡수하는 교환 거래다.\n🛠 실무: 큐를 도입할 때는 반드시 소비자 확장 전략을 함께 설계해야 한다.","o":["맞다. 큐는 처리율을 직접 높여준다","맞다. 큐가 요청을 병렬로 실행해 주기 때문이다","틀리다. 큐는 처리량을 항상 떨어뜨리기만 한다","틀리다. 큐는 순간 버스트를 흡수할 뿐 평균 처리 용량은 소비자 성능이 결정한다"],"a":3},{"t":"choice","k":"sysd-q-lag","q":"컨슈머 랙(consumer lag)이 지속적으로 증가하고 있다면 가장 정확한 해석은?","ex":"랙은 아직 처리되지 않은 메시지 수이며, 증가 추세는 μ &lt; λ를 뜻한다.\n💡 개념: 랙의 절댓값보다 기울기(증가율)가 더 중요한 신호다.\n🛠 실무: 랙 증가율과 파티션 수를 함께 보고 소비자 인스턴스 또는 파티션을 늘릴지 결정한다.","o":["소비 속도가 생산 속도를 따라가지 못하고 있다","메시지 생산이 멈췄다","네트워크 대역폭이 남아돈다","메시지가 중복 처리되고 있다"],"a":0},{"t":"choice","k":"sysd-q-dlq","q":"데드 레터 큐(DLQ)의 주된 목적은?","ex":"독성 메시지(poison message) 하나가 파티션 전체를 멈추는 것을 막기 위해 격리 보관한다.\n💡 개념: DLQ는 버리는 곳이 아니라 나중에 조사하고 재처리하는 대기실이다.\n🛠 실무: DLQ 유입 건수에 알람을 걸지 않으면 조용히 데이터가 사라지는 결과가 된다.","o":["메시지 전송 속도를 높이기 위해","메시지를 압축해 저장하기 위해","반복 실패하는 메시지를 격리해 정상 처리 흐름이 막히는 것을 막기 위해","메시지 순서를 보장하기 위해"],"a":2},{"t":"choice","k":"sysd-q-adaptive","q":"적응형 동시성 제한(adaptive concurrency limit)이나 CoDel 같은 기법의 공통된 아이디어는?","ex":"고정 임계값 대신 실시간 지연 신호를 피드백으로 삼아 스스로 한계를 조정한다.\n💡 개념: 정적 설정값은 트래픽 패턴이 바뀌면 금방 틀려지므로 자기 조정이 필요하다.\n🛠 실무: 기준 지연(최소 관측 RTT) 대비 현재 지연의 비율로 동시성 한계를 늘리고 줄이는 방식이 대표적이다.","o":["큐 크기를 고정값으로 크게 잡는다","모든 요청을 우선순위 없이 무작위로 처리한다","실패한 요청을 즉시 무한 재시도한다","관측된 지연 변화에 따라 허용 동시 처리량이나 큐 체류 시간을 동적으로 조절한다"],"a":3},{"t":"input","k":"sysd-q-dlq-term","q":"반복 실패한 메시지를 별도로 격리 보관하는 큐를 뜻하는 세 글자 영문 약어는?","ex":"정답은 DLQ(Dead Letter Queue)다.\n💡 개념: DLQ가 없으면 실패 메시지가 무한 재시도되며 정상 메시지의 처리를 막는다.\n🛠 실무: DLQ에 들어간 메시지는 원인 분석 후 수정하여 원래 큐로 재투입하는 절차를 문서화해 두어야 한다.","a":["DLQ","dlq"]}],"th":{"sum":"큐는 순간적인 버스트를 흡수하는 버퍼일 뿐, 평균 처리 용량을 늘려주지 않는다. 도착률이 처리율을 지속적으로 넘으면 남은 선택지는 백프레셔로 유입을 줄이거나 부하를 차단하는 것뿐이다.","body":[{"h":"큐는 용량이 아니라 시간을 산다","t":"도착률 λ가 처리율 μ보다 크면 큐는 매초 (λ - μ)만큼 쌓인다. 큐를 아무리 크게 잡아도 λ > μ가 지속되는 한 언젠가는 가득 찬다. 큐가 사주는 것은 용량이 아니라 시간이며, 그 시간 동안 오토스케일이 붙거나 트래픽이 잦아들어야만 의미가 있다. 그래서 큐를 넣는 결정에는 항상 '언제까지 버티는가'라는 계산이 따라야 한다."},{"h":"무한 큐가 가장 위험하다","t":"경계 없는 큐는 장애를 즉시 드러내지 않고 지연으로 바꿔 숨긴다. 요청은 계속 받아들여지지만 응답은 점점 느려지고, 결국 클라이언트 타임아웃 뒤에도 서버는 이미 버려진 요청을 계속 처리한다. 여기에 메모리까지 차오르면 OOM으로 프로세스 전체가 죽는다. 그래서 실무의 기본은 항상 상한이 있는 큐와 명시적 거절이다."},{"h":"백프레셔: 상류에 신호를 되돌린다","t":"백프레셔는 소비자가 감당 가능한 속도를 생산자에게 알려 유입 자체를 늦추는 메커니즘이다. TCP의 수신 윈도우, Reactive Streams의 request(n), gRPC의 흐름 제어가 모두 같은 원리다. 핵심은 '버퍼에 쌓기' 대신 '받지 않기'로 문제를 상류로 밀어 올리는 것이다. 상류가 사람이라면 결국 요청 속도가 자연스럽게 줄어든다."},{"h":"부하 차단과 재시도 폭풍","t":"부하 차단은 과부하 상황에서 일부 요청을 빠르게 거절해 나머지 요청을 SLO 안에서 처리하는 전략이다. 이때 429나 503을 즉시 반환해야 클라이언트가 자원을 붙잡고 있지 않는다. 다만 클라이언트가 즉시 재시도하면 오히려 부하가 증폭되는 재시도 폭풍이 생기므로, 지수 백오프에 지터를 더하고 재시도 예산을 두어야 한다. 서킷 브레이커는 실패가 임계치를 넘으면 호출 자체를 끊어 회복 시간을 벌어준다."}],"code":{"c":"[포화까지 남은 시간]\n도착률 λ = 1,000 req/s, 처리율 μ = 800 req/s\n초과분 = 200 req/s\n큐 상한 10,000 → 10,000 ÷ 200 = 50초 후 포화\n\n[큐 대기 시간 = 리틀의 법칙]\n큐에 8,000건 대기, μ = 800/s\nW = L ÷ μ = 8,000 ÷ 800 = 10초  ← 이미 SLO 초과\n\n[처리 순서]\n1) 유입 제한(rate limit) → 2) 백프레셔(수용 속도 하향)\n3) 부하 차단(저우선순위부터 429/503) → 4) 서킷 브레이커\n\n재시도는 지수 백오프 + 지터:\n  wait = random(0, base * 2^attempt)","cap":"큐 대기 시간이 클라이언트 타임아웃을 넘는 순간, 그 처리는 전부 낭비다."},"key":["큐는 버스트를 흡수할 뿐 평균 처리 용량(μ)을 늘리지 않는다","경계 없는 큐는 지연 폭발과 OOM으로 장애를 키우므로 상한과 거절이 기본이다","과부하에서는 느린 성공보다 빠른 거절이 낫고, 재시도에는 지수 백오프와 지터가 필수다"]}}]},{"t":"멱등성 심화: at-least-once와 '정확히 한 번'의 실무 현실","l":[{"t":"전달 보장의 현실","q":[{"t":"choice","k":"sysd-idem-delivery","q":"메시지 유실을 막기 위해 재시도를 하되 중복 수신은 허용하는 전달 보장 수준은?","ex":"재시도를 하면 유실은 막지만 응답 유실로 인한 중복이 생기므로 at-least-once다.\n💡 개념: at-most-once는 재시도를 하지 않아 유실 위험을 받아들이는 쪽이다.\n🛠 실무: 결제나 주문처럼 유실이 치명적인 도메인은 at-least-once를 택하고 중복은 멱등성으로 흡수한다.","o":["at-most-once","at-least-once","exactly-once","best-effort-once"],"a":1},{"t":"choice","k":"sysd-idem-eo-myth","q":"'정확히 한 번(exactly-once)'에 대한 설명 중 옳은 것은?","ex":"응답 유실을 구분할 수 없기 때문에 전달 수준의 exactly-once는 원리적으로 불가능하다.\n💡 개념: 통제 대상은 '전달 횟수'가 아니라 '처리의 효과'다.\n🛠 실무: 벤더가 exactly-once를 광고할 때는 그 보장이 어느 경계 안에서만 성립하는지 반드시 확인해야 한다.","o":["네트워크 전달 수준에서는 보장할 수 없고, at-least-once 전달 위에 멱등 처리를 얹어 효과를 한 번으로 만든다","TCP를 쓰면 네트워크 수준에서 exactly-once 전달이 보장된다","메시지 브로커를 쓰면 전달 자체가 항상 exactly-once가 된다","재시도를 하지 않으면 exactly-once가 된다"],"a":0},{"t":"choice","k":"sysd-idem-two-generals","q":"서버가 요청을 정상 처리했는데 응답만 네트워크에서 유실된 경우 클라이언트의 상황은?","ex":"이것이 두 장군 문제의 실제 형태이며, 재시도와 중복은 피할 수 없는 결과다.\n💡 개념: 타임아웃은 실패를 뜻하지 않고 '결과를 모름'을 뜻한다.\n🛠 실무: 그래서 타임아웃 후 재시도 경로에는 반드시 멱등 키가 있어야 한다.","o":["처리 성공 여부를 확실히 알 수 있으므로 재시도하지 않는다","서버가 자동으로 롤백하므로 아무 일도 일어나지 않는다","성공과 실패를 구분할 수 없어 재시도하게 되고 그 결과 중복 처리가 발생할 수 있다","TCP가 응답을 반드시 재전송하므로 문제가 없다"],"a":2},{"t":"choice","k":"sysd-idem-http","q":"HTTP 메서드의 멱등성에 대한 설명으로 옳은 것은?","ex":"명세상 GET, PUT, DELETE는 멱등하고 POST는 멱등하지 않다.\n💡 개념: 멱등은 '같은 요청을 여러 번 보내도 최종 상태가 같다'는 뜻이며 응답 코드까지 같아야 한다는 뜻은 아니다.\n🛠 실무: 자원 생성에 POST를 쓸 때는 Idempotency-Key 헤더로 멱등성을 보완하는 것이 표준적인 방식이다.","o":["POST와 PUT은 멱등하고 GET은 멱등하지 않다","모든 HTTP 메서드는 멱등하다","DELETE는 두 번 호출하면 상태가 달라지므로 멱등하지 않다","GET, PUT, DELETE는 멱등하지만 POST는 일반적으로 멱등하지 않다"],"a":3},{"t":"choice","k":"sysd-idem-natural","q":"재시도가 반복되어도 안전한 자연 멱등 설계에 해당하는 것은?","ex":"절대값 설정은 몇 번 반복해도 결과가 동일하지만 증분 연산은 반복될수록 값이 어긋난다.\n💡 개념: 상태를 '어떻게 바꿀지'가 아니라 '무엇이 되어야 하는지'로 표현하면 멱등해진다.\n🛠 실무: 증분이 꼭 필요하면 요청 ID 기반 중복 제거 테이블을 같이 두어야 한다.","o":["balance = 100 처럼 최종 값을 절대값으로 지정하는 연산","balance = balance + 10 처럼 현재 값에 증분을 더하는 연산","매 요청마다 새 주문 행을 INSERT 하는 연산","호출될 때마다 카운터를 1 증가시키는 연산"],"a":0},{"t":"input","k":"sysd-idem-key-name","q":"재시도 시 중복 처리를 막기 위해 클라이언트가 생성해 요청에 붙이는 고유 값을 무엇이라 하는가? (한글 또는 영문)","ex":"정답은 멱등 키(Idempotency-Key)다.\n💡 개념: 이 키는 반드시 클라이언트가 만들어야 하며 재시도 시 같은 값이어야 의미가 있다.\n🛠 실무: 결제 API들은 대부분 Idempotency-Key 헤더를 표준으로 지원한다.","a":["멱등키","멱등 키","Idempotency-Key","idempotency key","idempotency-key","아이덤포턴시 키"]}],"th":{"sum":"네트워크 위에서 정확히 한 번 전달은 원리적으로 불가능하다. 현실의 해법은 at-least-once 전달을 받아들이고 멱등 키와 중복 제거로 '효과는 한 번'을 만드는 것이다.","body":[{"h":"전달 보장 세 가지","t":"at-most-once는 재시도하지 않아 유실될 수 있고, at-least-once는 재시도하되 중복이 생길 수 있으며, exactly-once는 유실도 중복도 없다는 이상적인 목표다. 실제 분산 시스템에서 선택 가능한 것은 앞의 두 가지뿐이다. 대부분의 서비스는 유실보다 중복이 낫다고 판단해 at-least-once를 고른다."},{"h":"왜 전달 수준의 exactly-once는 불가능한가","t":"서버가 요청을 처리한 뒤 응답이 유실되면, 클라이언트는 요청이 도달하지 않은 것인지 응답만 사라진 것인지 구분할 수 없다. 이는 두 장군 문제로 알려진 근본적 한계다. 따라서 클라이언트는 재시도할 수밖에 없고 서버는 같은 요청을 두 번 받게 된다. 결론은 전달 횟수를 통제하려 하지 말고 처리의 효과를 통제하라는 것이다."},{"h":"멱등 키와 중복 제거","t":"클라이언트가 요청마다 고유한 멱등 키를 만들고 재시도 시에도 같은 키를 보내면, 서버는 그 키로 이미 처리했는지 조회해 저장된 결과를 그대로 돌려줄 수 있다. 중요한 것은 부수 효과와 멱등 키 기록을 같은 트랜잭션에서 커밋하는 것이다. 둘이 분리되면 결제는 됐는데 키는 기록되지 않아 중복 결제가 발생한다. 키에는 TTL을 두어 저장소가 무한히 커지는 것을 막는다."},{"h":"'효과의 exactly-once'와 아웃박스","t":"카프카의 exactly-once semantics는 카프카 내부의 읽기-처리-쓰기 트랜잭션 범위에서만 성립하며, 이메일 발송 같은 외부 부수 효과까지 보장하지 않는다. DB 쓰기와 메시지 발행을 원자적으로 묶으려면 같은 로컬 트랜잭션 안에서 아웃박스 테이블에 이벤트를 기록하고, 별도 릴레이가 그 테이블을 읽어 발행하는 트랜잭셔널 아웃박스 패턴을 쓴다. 이렇게 하면 발행은 at-least-once가 되지만 소비자가 멱등하면 결과는 한 번이 된다."}],"code":{"c":"POST /payments\nIdempotency-Key: 9f2c-4a1b-...   ← 클라이언트가 생성, 재시도 시 동일 값\n\n서버 처리:\n  saved = dedup_store.get(key)\n  if saved:\n      return saved.response          # 재시도 → 저장된 결과 재사용\n\n  with transaction:                  # 하나의 트랜잭션 안에서\n      charge_card(amount)            #   1) 부수 효과\n      dedup_store.put(key, response, ttl=24h)   # 2) 키 기록\n  return response\n\n[안티패턴] 결제 성공 후 별도 트랜잭션으로 키 저장\n  → 그 사이 장애 시 재시도가 중복 결제로 이어진다\n\n[자연 멱등 설계]\n  balance = 100     (절대값 SET)  → 재시도에 안전\n  balance += 10     (증분)        → 재시도 시 값이 틀어짐","cap":"부수 효과와 멱등 키는 반드시 같은 트랜잭션에서 커밋되어야 한다."},"key":["네트워크 전달 수준의 exactly-once는 불가능하며, at-least-once + 멱등 처리로 효과의 한 번을 만든다","멱등 키는 클라이언트가 생성하고 재시도 시 동일해야 하며, 부수 효과와 같은 트랜잭션에서 기록한다","DB 변경과 메시지 발행의 원자성은 트랜잭셔널 아웃박스 패턴으로 해결한다"]}},{"t":"멱등 키와 중복 제거 설계","q":[{"t":"choice","k":"sysd-idem-same-tx","q":"부수 효과(예: 결제)와 멱등 키 기록을 같은 트랜잭션에서 커밋해야 하는 이유는?","ex":"효과와 기록이 원자적이지 않으면 중간 장애가 그대로 중복 결제로 이어진다.\n💡 개념: 멱등성은 '기록과 효과의 원자성' 문제로 환원된다.\n🛠 실무: 키 저장소를 외부 캐시로 분리하면 이 원자성이 깨지므로, 가능하면 같은 DB의 테이블을 쓰는 편이 안전하다.","o":["성능이 더 빠르기 때문","트랜잭션 로그 크기를 줄이기 위해","둘 사이에 장애가 나면 효과는 발생했는데 키는 없는 상태가 되어 재시도가 중복 처리로 이어지기 때문","키 저장소의 TTL을 정확히 맞추기 위해"],"a":2},{"t":"choice","k":"sysd-idem-ttl","q":"멱등 키 저장소에 TTL(예: 24시간)을 두는 주된 이유는?","ex":"TTL은 저장소 비용과 중복 방지 보장 구간 사이의 트레이드오프다.\n💡 개념: TTL이 클라이언트의 최대 재시도 기간보다 짧으면 중복 방지가 뚫린다.\n🛠 실무: 클라이언트 재시도 정책의 최대 기간을 먼저 정하고 그보다 넉넉하게 TTL을 잡는 순서가 옳다.","o":["키가 오래되면 보안상 위험해지기 때문","TTL이 있어야 트랜잭션이 커밋되기 때문","TTL이 짧을수록 중복 방지 효과가 강해지기 때문","저장소가 무한히 커지는 것을 막기 위해서이며, 대신 TTL을 넘긴 재시도는 중복으로 처리될 수 있다"],"a":3},{"t":"choice","k":"sysd-idem-server-key","q":"서버가 요청을 받을 때마다 랜덤 UUID를 만들어 멱등 키로 쓰면 안 되는 이유는?","ex":"멱등 키는 '같은 논리적 요청'을 식별해야 하므로 재시도 전반에 걸쳐 동일해야 한다.\n💡 개념: 키의 소유자는 재시도를 결정하는 쪽, 즉 클라이언트다.\n🛠 실무: 클라이언트가 키를 못 보내는 레거시 연동이라면 요청 본문의 안정적인 필드 조합으로 결정적 해시를 만들어 대체할 수 있다.","o":["UUID 생성 비용이 크기 때문","재시도 때마다 키가 달라져 같은 요청으로 인식되지 않아 중복 방지가 전혀 되지 않기 때문","UUID는 인덱스를 만들 수 없기 때문","서버가 만든 키는 TTL을 설정할 수 없기 때문"],"a":1},{"t":"choice","k":"sysd-idem-kafka-eos","q":"카프카의 exactly-once semantics(EOS)가 보장하는 범위로 옳은 것은?","ex":"EOS는 카프카 토픽 간 트랜잭션과 오프셋 커밋을 원자적으로 묶는 기능이지 외부 세계까지 확장되지 않는다.\n💡 개념: 트랜잭션 경계 밖의 부수 효과는 여전히 멱등하게 설계해야 한다.\n🛠 실무: 스트림 처리에서 외부 API를 호출한다면 그 호출에 별도의 멱등 키가 필요하다.","o":["카프카 내부의 읽기-처리-쓰기 트랜잭션 범위에서만 성립하며, 이메일 발송 같은 외부 부수 효과는 보장하지 않는다","카프카를 거치는 모든 외부 시스템 호출까지 정확히 한 번 실행됨을 보장한다","네트워크 패킷 수준에서 중복 전송을 없애 준다","소비자가 멱등하지 않아도 모든 중복이 사라진다"],"a":0},{"t":"choice","k":"sysd-idem-outbox","q":"DB 변경과 메시지 발행을 원자적으로 처리하기 위해 같은 로컬 트랜잭션에 이벤트 행을 기록하고, 별도 릴레이가 그것을 읽어 발행하는 패턴은?","ex":"아웃박스 테이블에 이벤트를 함께 커밋해 '저장은 됐는데 발행은 안 됨' 문제를 없앤다.\n💡 개념: 발행은 여전히 at-least-once이므로 소비자 쪽 멱등성이 짝을 이뤄야 한다.\n🛠 실무: 릴레이는 폴링 방식이나 CDC(변경 데이터 캡처)로 구현하며, 후자가 지연과 부하 면에서 유리하다.","o":["2단계 커밋(2PC)","리더-팔로워 복제","트랜잭셔널 아웃박스 패턴","사이드카 패턴"],"a":2},{"t":"input","k":"sysd-idem-outbox-name","q":"위 문제에서 설명한, 이벤트를 별도 테이블에 함께 커밋한 뒤 발행하는 패턴의 이름은? (한글 또는 영문)","ex":"정답은 아웃박스(Outbox) 패턴, 정확히는 트랜잭셔널 아웃박스 패턴이다.\n💡 개념: 반대 방향으로 외부에서 들어온 메시지를 먼저 기록하는 인박스(inbox) 패턴은 소비자 측 중복 제거에 쓰인다.\n🛠 실무: 아웃박스 테이블은 발행 완료 행을 주기적으로 정리하지 않으면 금세 비대해진다.","a":["아웃박스","아웃박스 패턴","트랜잭셔널 아웃박스","outbox","Outbox","transactional outbox"]}],"th":{"sum":"네트워크 위에서 정확히 한 번 전달은 원리적으로 불가능하다. 현실의 해법은 at-least-once 전달을 받아들이고 멱등 키와 중복 제거로 '효과는 한 번'을 만드는 것이다.","body":[{"h":"전달 보장 세 가지","t":"at-most-once는 재시도하지 않아 유실될 수 있고, at-least-once는 재시도하되 중복이 생길 수 있으며, exactly-once는 유실도 중복도 없다는 이상적인 목표다. 실제 분산 시스템에서 선택 가능한 것은 앞의 두 가지뿐이다. 대부분의 서비스는 유실보다 중복이 낫다고 판단해 at-least-once를 고른다."},{"h":"왜 전달 수준의 exactly-once는 불가능한가","t":"서버가 요청을 처리한 뒤 응답이 유실되면, 클라이언트는 요청이 도달하지 않은 것인지 응답만 사라진 것인지 구분할 수 없다. 이는 두 장군 문제로 알려진 근본적 한계다. 따라서 클라이언트는 재시도할 수밖에 없고 서버는 같은 요청을 두 번 받게 된다. 결론은 전달 횟수를 통제하려 하지 말고 처리의 효과를 통제하라는 것이다."},{"h":"멱등 키와 중복 제거","t":"클라이언트가 요청마다 고유한 멱등 키를 만들고 재시도 시에도 같은 키를 보내면, 서버는 그 키로 이미 처리했는지 조회해 저장된 결과를 그대로 돌려줄 수 있다. 중요한 것은 부수 효과와 멱등 키 기록을 같은 트랜잭션에서 커밋하는 것이다. 둘이 분리되면 결제는 됐는데 키는 기록되지 않아 중복 결제가 발생한다. 키에는 TTL을 두어 저장소가 무한히 커지는 것을 막는다."},{"h":"'효과의 exactly-once'와 아웃박스","t":"카프카의 exactly-once semantics는 카프카 내부의 읽기-처리-쓰기 트랜잭션 범위에서만 성립하며, 이메일 발송 같은 외부 부수 효과까지 보장하지 않는다. DB 쓰기와 메시지 발행을 원자적으로 묶으려면 같은 로컬 트랜잭션 안에서 아웃박스 테이블에 이벤트를 기록하고, 별도 릴레이가 그 테이블을 읽어 발행하는 트랜잭셔널 아웃박스 패턴을 쓴다. 이렇게 하면 발행은 at-least-once가 되지만 소비자가 멱등하면 결과는 한 번이 된다."}],"code":{"c":"POST /payments\nIdempotency-Key: 9f2c-4a1b-...   ← 클라이언트가 생성, 재시도 시 동일 값\n\n서버 처리:\n  saved = dedup_store.get(key)\n  if saved:\n      return saved.response          # 재시도 → 저장된 결과 재사용\n\n  with transaction:                  # 하나의 트랜잭션 안에서\n      charge_card(amount)            #   1) 부수 효과\n      dedup_store.put(key, response, ttl=24h)   # 2) 키 기록\n  return response\n\n[안티패턴] 결제 성공 후 별도 트랜잭션으로 키 저장\n  → 그 사이 장애 시 재시도가 중복 결제로 이어진다\n\n[자연 멱등 설계]\n  balance = 100     (절대값 SET)  → 재시도에 안전\n  balance += 10     (증분)        → 재시도 시 값이 틀어짐","cap":"부수 효과와 멱등 키는 반드시 같은 트랜잭션에서 커밋되어야 한다."},"key":["네트워크 전달 수준의 exactly-once는 불가능하며, at-least-once + 멱등 처리로 효과의 한 번을 만든다","멱등 키는 클라이언트가 생성하고 재시도 시 동일해야 하며, 부수 효과와 같은 트랜잭션에서 기록한다","DB 변경과 메시지 발행의 원자성은 트랜잭셔널 아웃박스 패턴으로 해결한다"]}},{"t":"중복·순서·재처리 운영 실무","q":[{"t":"choice","k":"sysd-idem-2pc","q":"마이크로서비스 환경에서 2단계 커밋(2PC)을 잘 쓰지 않는 주된 이유는?","ex":"2PC는 강한 원자성을 주지만 블로킹 프로토콜이라 부분 장애에 취약하고 지연이 커진다.\n💡 개념: 그래서 서비스 간에는 사가와 보상 트랜잭션 같은 최종 일관성 접근을 택한다.\n🛠 실무: 2PC는 서비스 경계 안의 소수 자원(예: DB와 메시지 브로커) 사이에서 제한적으로만 고려한다.","o":["구현할 수 있는 언어가 제한되기 때문","데이터 일관성을 전혀 보장하지 못하기 때문","네트워크 대역폭을 지나치게 많이 쓰기 때문","코디네이터 장애 시 참여자들이 잠금을 쥔 채 블로킹되어 가용성과 지연이 크게 나빠지기 때문"],"a":3},{"t":"choice","k":"sysd-idem-order","q":"카프카류 브로커에서 메시지 순서가 보장되는 범위는?","ex":"순서는 파티션 내부에서만 보장되므로 순서가 중요한 엔티티는 같은 키로 같은 파티션에 보내야 한다.\n💡 개념: 파티션을 늘리면 처리량은 오르지만 전역 순서는 포기하게 된다.\n🛠 실무: 사용자 ID나 주문 ID를 키로 써서 엔티티 단위 순서만 지키는 것이 일반적인 절충안이다.","o":["같은 파티션 안에서만 보장되며, 파티션은 보통 키로 결정된다","토픽 전체에 걸쳐 전역적으로 보장된다","소비자 그룹 단위로 보장된다","순서는 어떤 경우에도 보장되지 않는다"],"a":0},{"t":"choice","k":"sysd-idem-commit-timing","q":"소비자가 메시지를 처리하기 전에 오프셋을 먼저 커밋하면 어떤 전달 보장이 되는가?","ex":"먼저 커밋하면 처리 도중 죽었을 때 그 메시지는 다시 오지 않으므로 at-most-once다.\n💡 개념: 처리 후 커밋하면 반대로 at-least-once가 되어 중복 가능성이 생긴다.\n🛠 실무: 대부분 처리 후 커밋 + 멱등 처리 조합을 택한다.","o":["at-least-once가 되어 중복이 생길 수 있다","exactly-once가 보장된다","at-most-once가 되어 처리 중 장애 시 메시지가 유실될 수 있다","전달 보장과 무관하다"],"a":2},{"t":"choice","k":"sysd-idem-order-myth","q":"'처리를 멱등하게 만들면 메시지 순서 문제도 자동으로 해결된다'는 주장에 대한 평가는?","ex":"중복 제거와 순서 보장은 서로 다른 문제이며 해법도 다르다.\n💡 개념: 순서 역전 대비에는 엔티티 버전 비교나 last-write-wins 같은 별도 규칙이 필요하다.\n🛠 실무: 갱신 이벤트에 단조 증가 버전을 실어 보내고, 저장된 버전보다 낮으면 무시하는 방식이 흔히 쓰인다.","o":["맞다. 멱등성은 순서 무관성을 포함한다","맞다. 멱등 키가 순서를 기록하기 때문이다","틀리다. 멱등성은 순서를 오히려 뒤섞는다","틀리다. 멱등성은 중복만 해결하며, 순서 역전은 버전 번호나 타임스탬프 기반 처리로 따로 막아야 한다"],"a":3},{"t":"input","k":"sysd-idem-property","q":"같은 요청이나 메시지를 여러 번 처리해도 최종 결과가 한 번 처리한 것과 같아지는 성질을 무엇이라 하는가? (한글)","ex":"정답은 멱등성(idempotency)이다.\n💡 개념: 분산 시스템에서 재시도가 불가피하므로 멱등성은 선택이 아니라 전제 조건이다.\n🛠 실무: API 설계 리뷰에서 '이 엔드포인트를 두 번 호출하면?'을 항상 묻는 습관이 큰 사고를 막는다.","a":["멱등성","멱등","아이덤포턴시"]}],"th":{"sum":"네트워크 위에서 정확히 한 번 전달은 원리적으로 불가능하다. 현실의 해법은 at-least-once 전달을 받아들이고 멱등 키와 중복 제거로 '효과는 한 번'을 만드는 것이다.","body":[{"h":"전달 보장 세 가지","t":"at-most-once는 재시도하지 않아 유실될 수 있고, at-least-once는 재시도하되 중복이 생길 수 있으며, exactly-once는 유실도 중복도 없다는 이상적인 목표다. 실제 분산 시스템에서 선택 가능한 것은 앞의 두 가지뿐이다. 대부분의 서비스는 유실보다 중복이 낫다고 판단해 at-least-once를 고른다."},{"h":"왜 전달 수준의 exactly-once는 불가능한가","t":"서버가 요청을 처리한 뒤 응답이 유실되면, 클라이언트는 요청이 도달하지 않은 것인지 응답만 사라진 것인지 구분할 수 없다. 이는 두 장군 문제로 알려진 근본적 한계다. 따라서 클라이언트는 재시도할 수밖에 없고 서버는 같은 요청을 두 번 받게 된다. 결론은 전달 횟수를 통제하려 하지 말고 처리의 효과를 통제하라는 것이다."},{"h":"멱등 키와 중복 제거","t":"클라이언트가 요청마다 고유한 멱등 키를 만들고 재시도 시에도 같은 키를 보내면, 서버는 그 키로 이미 처리했는지 조회해 저장된 결과를 그대로 돌려줄 수 있다. 중요한 것은 부수 효과와 멱등 키 기록을 같은 트랜잭션에서 커밋하는 것이다. 둘이 분리되면 결제는 됐는데 키는 기록되지 않아 중복 결제가 발생한다. 키에는 TTL을 두어 저장소가 무한히 커지는 것을 막는다."},{"h":"'효과의 exactly-once'와 아웃박스","t":"카프카의 exactly-once semantics는 카프카 내부의 읽기-처리-쓰기 트랜잭션 범위에서만 성립하며, 이메일 발송 같은 외부 부수 효과까지 보장하지 않는다. DB 쓰기와 메시지 발행을 원자적으로 묶으려면 같은 로컬 트랜잭션 안에서 아웃박스 테이블에 이벤트를 기록하고, 별도 릴레이가 그 테이블을 읽어 발행하는 트랜잭셔널 아웃박스 패턴을 쓴다. 이렇게 하면 발행은 at-least-once가 되지만 소비자가 멱등하면 결과는 한 번이 된다."}],"code":{"c":"POST /payments\nIdempotency-Key: 9f2c-4a1b-...   ← 클라이언트가 생성, 재시도 시 동일 값\n\n서버 처리:\n  saved = dedup_store.get(key)\n  if saved:\n      return saved.response          # 재시도 → 저장된 결과 재사용\n\n  with transaction:                  # 하나의 트랜잭션 안에서\n      charge_card(amount)            #   1) 부수 효과\n      dedup_store.put(key, response, ttl=24h)   # 2) 키 기록\n  return response\n\n[안티패턴] 결제 성공 후 별도 트랜잭션으로 키 저장\n  → 그 사이 장애 시 재시도가 중복 결제로 이어진다\n\n[자연 멱등 설계]\n  balance = 100     (절대값 SET)  → 재시도에 안전\n  balance += 10     (증분)        → 재시도 시 값이 틀어짐","cap":"부수 효과와 멱등 키는 반드시 같은 트랜잭션에서 커밋되어야 한다."},"key":["네트워크 전달 수준의 exactly-once는 불가능하며, at-least-once + 멱등 처리로 효과의 한 번을 만든다","멱등 키는 클라이언트가 생성하고 재시도 시 동일해야 하며, 부수 효과와 같은 트랜잭션에서 기록한다","DB 변경과 메시지 발행의 원자성은 트랜잭셔널 아웃박스 패턴으로 해결한다"]}}]},{"t":"마이크로서비스 경계 심화: 동기·비동기 통신과 사가 실무","l":[{"t":"서비스 경계 나누기","q":[{"t":"choice","k":"sysd-ms-boundary","q":"마이크로서비스 경계를 나누는 기준으로 가장 적절한 것은?","ex":"경계의 목적은 변경의 독립성이므로 함께 바뀌는 것을 한데 모아야 한다.\n💡 개념: 도메인 주도 설계의 바운디드 컨텍스트가 이 기준의 대표적 표현이다.\n🛠 실무: 하나의 기능 변경이 항상 세 개 서비스를 동시에 배포하게 만든다면 경계가 잘못된 것이다.","o":["코드 줄 수가 균등해지도록 나눈다","함께 변경되는 도메인 개념과 데이터 소유권을 기준으로 나눈다","테이블 개수가 같아지도록 나눈다","팀원 수에 맞춰 1인당 1서비스로 나눈다"],"a":1},{"t":"choice","k":"sysd-ms-distributed-monolith","q":"'분산 모놀리스'의 대표적인 증상은?","ex":"물리적으로만 나뉘고 논리적 결합은 그대로인 상태가 분산 모놀리스다.\n💡 개념: 이 경우 모놀리스의 단순함은 잃고 분산의 복잡함만 얻는다.\n🛠 실무: 배포 단위가 실제로 독립적인지, 한 서비스만 롤백할 수 있는지로 자가 진단할 수 있다.","o":["서비스는 나뉘어 있지만 항상 함께 배포해야 하고 하나가 죽으면 전부 멈춘다","서비스마다 독립적으로 배포되고 장애도 격리된다","모든 서비스가 하나의 프로세스에서 실행된다","서비스 간 통신이 전부 비동기다"],"a":0},{"t":"choice","k":"sysd-ms-shared-db","q":"여러 서비스가 같은 데이터베이스 테이블을 직접 읽고 쓰는 구조의 가장 큰 문제는?","ex":"공유 DB는 숨은 강결합을 만들어 독립 배포라는 목적 자체를 무너뜨린다.\n💡 개념: 각 서비스가 자기 데이터를 독점 소유하고 외부에는 API나 이벤트로만 노출해야 한다.\n🛠 실무: 읽기 목적의 공유는 읽기 전용 복제본이나 이벤트 기반 조회 모델로 대체하는 것이 안전하다.","o":["쿼리 성능이 반드시 나빠진다","트랜잭션을 사용할 수 없다","스키마가 사실상 공용 API가 되어 한 서비스의 스키마 변경이 다른 서비스를 깨뜨린다","데이터 중복이 늘어난다"],"a":2},{"t":"choice","k":"sysd-ms-too-small","q":"'서비스를 잘게 쪼갤수록 항상 좋다'는 주장에 대한 평가는?","ex":"분할에는 통신 지연, 관측성, 데이터 일관성이라는 비용이 따르므로 이득과 저울질해야 한다.\n💡 개념: 마이크로서비스는 조직과 배포 독립성이 필요할 때 값을 하는 도구다.\n🛠 실무: 초기 제품은 잘 모듈화된 모놀리스로 시작하고 병목이 드러난 경계부터 떼어내는 편이 실패 확률이 낮다.","o":["맞다. 서비스가 많을수록 확장성이 항상 좋아진다","맞다. 서비스 크기는 작을수록 장애가 줄어든다","틀리다. 서비스는 항상 하나여야 한다","틀리다. 쪼갤수록 네트워크 홉, 운영 부담, 분산 트랜잭션 문제가 늘어나므로 적정 크기를 찾아야 한다"],"a":3},{"t":"input","k":"sysd-ms-conway","q":"시스템 아키텍처가 결국 그것을 만든 조직의 소통 구조를 닮게 된다는 법칙의 이름은? (한글 또는 영문)","ex":"정답은 콘웨이의 법칙이다.\n💡 개념: 원하는 아키텍처가 있다면 조직 구조를 먼저 그에 맞추는 역콘웨이 전략도 널리 쓰인다.\n🛠 실무: 서비스 오너십이 불명확한 조직에서는 어떤 경계 설계도 오래 유지되지 않는다.","a":["콘웨이의 법칙","콘웨이 법칙","Conway's law","conway's law","conways law"]}],"th":{"sum":"서비스 경계는 코드 크기가 아니라 함께 변경되는 도메인과 데이터 소유권이 정한다. 경계를 넘는 통신을 동기로 할지 비동기로 할지가 시스템의 가용성과 지연을 사실상 결정한다.","body":[{"h":"경계는 무엇이 정하는가","t":"좋은 경계는 함께 바뀌는 것을 한데 모으고 따로 바뀌는 것을 떼어낸다. 기준은 도메인 개념과 데이터 소유권, 그리고 팀 구조다. 콘웨이의 법칙대로 시스템 구조는 결국 조직의 소통 구조를 닮으므로, 팀 경계와 서비스 경계가 어긋나면 배포마다 조율 비용이 폭증한다. 서비스 수가 많은 것 자체는 아무 미덕이 아니다."},{"h":"동기 호출의 숨은 비용","t":"동기 호출은 이해하기 쉽지만 가용성이 곱해진다. 99.9%짜리 서비스 세 개를 직렬로 호출하면 전체는 약 99.7%가 되어 연간 다운타임이 8.8시간에서 26시간으로 늘어난다. 지연도 누적되어 p99 50ms인 서비스 다섯 개를 직렬 호출하면 최선의 경우에도 250ms가 든다. 팬아웃 호출에서는 가장 느린 하나가 전체 응답을 지배하는 꼬리 지연 증폭이 나타난다."},{"h":"비동기 이벤트의 이득과 대가","t":"이벤트 기반 통신은 호출자가 수신자의 가용성에 묶이지 않게 해주므로 결합도와 장애 전파를 줄인다. 대신 결과가 즉시 반영되지 않는 최종 일관성을 받아들여야 하고, 디버깅과 추적이 어려워진다. 사용자가 즉시 응답을 봐야 하는 질의는 동기가 맞고, 부가 처리와 알림, 통계는 비동기가 맞다. 판단 기준은 '호출자가 결과를 지금 알아야 하는가'다."},{"h":"사가와 보상 트랜잭션","t":"여러 서비스에 걸친 업무를 하나의 ACID 트랜잭션으로 묶을 수 없으므로 사가를 쓴다. 사가는 로컬 트랜잭션의 연쇄이며, 중간에 실패하면 앞 단계의 효과를 의미적으로 되돌리는 보상 트랜잭션을 역순으로 실행한다. 중앙 조정자가 흐름을 지휘하면 오케스트레이션, 각 서비스가 이벤트를 듣고 반응하면 코레오그래피다. 사가는 원자성을 흉내 낼 뿐 격리성은 제공하지 않아 중간 상태가 외부에 노출된다."}],"code":{"c":"[가용성은 곱해진다]\nA → B → C, 각 99.9%\n0.999^3 ≈ 0.997 → 연간 다운타임 약 26시간 (99.9%는 약 8.8시간)\n\n[지연은 누적된다]\np99 50ms 서비스 5개 직렬 → 최선 250ms\n팬아웃 10개 병렬 → 전체 p99 ≈ 가장 느린 하나 (꼬리 지연 증폭)\n\n[주문 사가]\n주문생성 → 결제승인 → 재고차감 → 배송요청\n     ↑ 실패 시 역순 보상 ↓\n주문취소 ← 결제취소 ← 재고복구 ← 배송취소\n\n오케스트레이션: 중앙 조정자가 다음 단계를 명령\n코레오그래피 : 각 서비스가 이벤트를 구독해 스스로 반응","cap":"동기 체인이 길어질수록 가용성은 곱해지고 지연은 더해진다."},"key":["서비스 경계는 도메인과 데이터 소유권, 팀 구조가 정하며 서비스 개수 자체는 목표가 아니다","동기 직렬 호출은 가용성을 곱하고 지연을 누적시킨다","사가는 보상 트랜잭션으로 원자성을 흉내 낼 뿐 격리성은 제공하지 않는다"]}},{"t":"동기 통신과 비동기 통신의 선택","q":[{"t":"choice","k":"sysd-ms-availability","q":"가용성 99.9%인 서비스 세 개를 직렬로 동기 호출하는 경로의 전체 가용성은 대략 얼마인가?","ex":"0.999^3 ≈ 0.997이므로 약 99.7%이며, 연간 다운타임은 8.8시간에서 26시간 수준으로 늘어난다.\n💡 개념: 직렬 의존은 가용성을 곱셈으로 깎는다.\n🛠 실무: 그래서 핵심 경로의 의존 개수를 줄이거나, 실패해도 되는 의존은 비동기나 폴백으로 빼낸다.","o":["약 99.7%","약 99.9%","약 99.99%","약 97%"],"a":0},{"t":"choice","k":"sysd-ms-latency-chain","q":"p99 지연이 각각 50ms인 서비스 다섯 개를 직렬로 호출할 때 전체 지연에 대한 설명으로 옳은 것은?","ex":"직렬 호출에서 지연은 더해지며, 각 단계의 꼬리가 겹치면 전체 p99는 단순 합보다도 커진다.\n💡 개념: 지연은 더해지고 가용성은 곱해진다는 것이 동기 체인의 두 가지 세금이다.\n🛠 실무: 독립적인 호출은 병렬화하고, 사용자 응답에 필수적이지 않은 호출은 응답 이후로 미룬다.","o":["전체 p99도 여전히 50ms 수준이다","가장 빠른 서비스의 지연이 전체를 결정한다","각 단계의 지연이 누적되어 최소 250ms 수준이 되고, 꼬리 지연 때문에 실제로는 더 나빠진다","직렬 호출은 지연에 영향을 주지 않는다"],"a":2},{"t":"choice","k":"sysd-ms-async-tradeoff","q":"동기 호출을 이벤트 기반 비동기 통신으로 바꿀 때 얻는 것과 치르는 대가를 올바르게 짝지은 것은?","ex":"비동기는 시간적 결합을 끊어주는 대신 즉시 일관성과 단순한 디버깅을 포기하게 만든다.\n💡 개념: 무엇을 얻고 무엇을 잃는지 명확히 말할 수 없다면 아직 설계 결정이 아니다.\n🛠 실무: 비동기 도입 시 분산 추적과 이벤트 스키마 관리 체계를 함께 갖추지 않으면 운영이 급격히 어려워진다.","o":["얻는 것: 강한 일관성 / 대가: 결합도 증가","얻는 것: 항상 더 낮은 응답 지연 / 대가: 없음","얻는 것: 트랜잭션 원자성 / 대가: 처리량 감소","얻는 것: 결합도와 장애 전파 감소 / 대가: 최종 일관성과 추적 난이도 증가"],"a":3},{"t":"choice","k":"sysd-ms-queue-latency-myth","q":"'메시지 큐를 도입하면 사용자 응답 지연이 항상 줄어든다'는 주장에 대한 평가는?","ex":"큐는 응답 시점에서 작업을 떼어낼 수 있을 때만 체감 지연을 줄인다.\n💡 개념: 사용자가 결과를 즉시 봐야 한다면 동기 호출이 옳은 선택이다.\n🛠 실무: 알림 발송, 통계 집계, 인덱싱처럼 사용자가 기다리지 않아도 되는 작업이 비동기의 전형적인 대상이다.","o":["맞다. 큐는 처리를 병렬화해 항상 빨라진다","틀리다. 사용자가 결과를 기다려야 하는 작업이라면 큐는 오히려 대기 단계를 하나 더 추가한다","맞다. 큐는 네트워크 왕복을 없애기 때문이다","틀리다. 큐는 지연과 무관하다"],"a":1},{"t":"choice","k":"sysd-ms-timeout","q":"서비스 간 동기 호출에 타임아웃을 설정하지 않으면 생기는 가장 위험한 결과는?","ex":"타임아웃이 없으면 하류의 지연이 상류의 자원 고갈로 전파되어 시스템 전체가 멈춘다.\n💡 개념: 타임아웃은 장애를 격리하는 가장 값싼 수단이다.\n🛠 실무: 타임아웃은 하류 p99보다 약간 크게 잡고, 벌크헤드로 호출별 자원 풀을 분리해 격리를 강화한다.","o":["느린 하류 서비스가 호출자의 스레드와 커넥션을 모두 붙잡아 연쇄 장애로 번진다","네트워크 대역폭이 낭비된다","로그가 지나치게 많이 쌓인다","응답 데이터가 손상된다"],"a":0},{"t":"input","k":"sysd-ms-cascading","q":"한 서비스의 장애가 그것을 호출하는 서비스들로 번져 시스템 전체가 멈추는 현상을 무엇이라 하는가? (한글 또는 영문)","ex":"정답은 연쇄 장애(cascading failure)다.\n💡 개념: 타임아웃, 서킷 브레이커, 벌크헤드, 부하 차단이 대표적인 방어 수단이다.\n🛠 실무: 장애 훈련에서 하류 서비스를 일부러 느리게 만들어 상류가 견디는지 확인하는 것이 좋은 검증 방법이다.","a":["연쇄 장애","연쇄장애","cascading failure","장애 전파","캐스케이딩 장애"]}],"th":{"sum":"서비스 경계는 코드 크기가 아니라 함께 변경되는 도메인과 데이터 소유권이 정한다. 경계를 넘는 통신을 동기로 할지 비동기로 할지가 시스템의 가용성과 지연을 사실상 결정한다.","body":[{"h":"경계는 무엇이 정하는가","t":"좋은 경계는 함께 바뀌는 것을 한데 모으고 따로 바뀌는 것을 떼어낸다. 기준은 도메인 개념과 데이터 소유권, 그리고 팀 구조다. 콘웨이의 법칙대로 시스템 구조는 결국 조직의 소통 구조를 닮으므로, 팀 경계와 서비스 경계가 어긋나면 배포마다 조율 비용이 폭증한다. 서비스 수가 많은 것 자체는 아무 미덕이 아니다."},{"h":"동기 호출의 숨은 비용","t":"동기 호출은 이해하기 쉽지만 가용성이 곱해진다. 99.9%짜리 서비스 세 개를 직렬로 호출하면 전체는 약 99.7%가 되어 연간 다운타임이 8.8시간에서 26시간으로 늘어난다. 지연도 누적되어 p99 50ms인 서비스 다섯 개를 직렬 호출하면 최선의 경우에도 250ms가 든다. 팬아웃 호출에서는 가장 느린 하나가 전체 응답을 지배하는 꼬리 지연 증폭이 나타난다."},{"h":"비동기 이벤트의 이득과 대가","t":"이벤트 기반 통신은 호출자가 수신자의 가용성에 묶이지 않게 해주므로 결합도와 장애 전파를 줄인다. 대신 결과가 즉시 반영되지 않는 최종 일관성을 받아들여야 하고, 디버깅과 추적이 어려워진다. 사용자가 즉시 응답을 봐야 하는 질의는 동기가 맞고, 부가 처리와 알림, 통계는 비동기가 맞다. 판단 기준은 '호출자가 결과를 지금 알아야 하는가'다."},{"h":"사가와 보상 트랜잭션","t":"여러 서비스에 걸친 업무를 하나의 ACID 트랜잭션으로 묶을 수 없으므로 사가를 쓴다. 사가는 로컬 트랜잭션의 연쇄이며, 중간에 실패하면 앞 단계의 효과를 의미적으로 되돌리는 보상 트랜잭션을 역순으로 실행한다. 중앙 조정자가 흐름을 지휘하면 오케스트레이션, 각 서비스가 이벤트를 듣고 반응하면 코레오그래피다. 사가는 원자성을 흉내 낼 뿐 격리성은 제공하지 않아 중간 상태가 외부에 노출된다."}],"code":{"c":"[가용성은 곱해진다]\nA → B → C, 각 99.9%\n0.999^3 ≈ 0.997 → 연간 다운타임 약 26시간 (99.9%는 약 8.8시간)\n\n[지연은 누적된다]\np99 50ms 서비스 5개 직렬 → 최선 250ms\n팬아웃 10개 병렬 → 전체 p99 ≈ 가장 느린 하나 (꼬리 지연 증폭)\n\n[주문 사가]\n주문생성 → 결제승인 → 재고차감 → 배송요청\n     ↑ 실패 시 역순 보상 ↓\n주문취소 ← 결제취소 ← 재고복구 ← 배송취소\n\n오케스트레이션: 중앙 조정자가 다음 단계를 명령\n코레오그래피 : 각 서비스가 이벤트를 구독해 스스로 반응","cap":"동기 체인이 길어질수록 가용성은 곱해지고 지연은 더해진다."},"key":["서비스 경계는 도메인과 데이터 소유권, 팀 구조가 정하며 서비스 개수 자체는 목표가 아니다","동기 직렬 호출은 가용성을 곱하고 지연을 누적시킨다","사가는 보상 트랜잭션으로 원자성을 흉내 낼 뿐 격리성은 제공하지 않는다"]}},{"t":"사가와 분산 트랜잭션 실무","q":[{"t":"choice","k":"sysd-ms-saga-def","q":"사가(Saga) 패턴을 가장 정확히 설명한 것은?","ex":"사가는 분산 원자성을 흉내 내기 위한 로컬 트랜잭션 연쇄 + 보상 전략이다.\n💡 개념: 각 단계는 자기 서비스 안에서만 ACID를 지킨다.\n🛠 실무: 사가 설계의 절반은 '어떻게 되돌릴 것인가'를 단계마다 정의하는 일이다.","o":["여러 서비스의 DB를 하나의 ACID 트랜잭션으로 묶는 기법","요청을 큐에 넣어 순차 처리하는 기법","여러 로컬 트랜잭션을 순서대로 실행하고 실패 시 앞 단계를 보상 트랜잭션으로 되돌리는 기법","데이터를 여러 노드에 복제해 내구성을 높이는 기법"],"a":2},{"t":"choice","k":"sysd-ms-orch-vs-chor","q":"사가의 오케스트레이션 방식과 코레오그래피 방식의 차이로 옳은 것은?","ex":"제어 흐름이 중앙에 있느냐 분산되어 있느냐가 핵심 차이다.\n💡 개념: 오케스트레이션은 흐름 파악이 쉽지만 조정자가 단일 지점이 되고, 코레오그래피는 결합도가 낮지만 전체 흐름을 읽기 어렵다.\n🛠 실무: 단계가 4~5개를 넘어가면 대체로 오케스트레이션이 운영과 디버깅에 유리하다.","o":["오케스트레이션은 비동기이고 코레오그래피는 동기다","오케스트레이션은 보상 트랜잭션이 필요 없다","코레오그래피는 항상 단일 서비스에서만 동작한다","오케스트레이션은 중앙 조정자가 다음 단계를 지시하고, 코레오그래피는 각 서비스가 이벤트를 구독해 스스로 반응한다"],"a":3},{"t":"choice","k":"sysd-ms-compensation","q":"보상 트랜잭션이 데이터베이스 롤백과 다른 점은?","ex":"이미 커밋된 효과는 물리적으로 되돌릴 수 없으므로 '취소'라는 새 업무 행위로 상쇄한다.\n💡 개념: 그래서 보상은 도메인 지식이 필요하며 완벽히 원래대로 돌아가지 않을 수도 있다(예: 발송된 알림).\n🛠 실무: 보상 트랜잭션 자체도 실패할 수 있으므로 재시도와 멱등성, 최종적으로는 수동 개입 경로가 필요하다.","o":["롤백은 커밋되지 않은 변경을 되돌리지만, 보상은 이미 커밋되어 외부에 보인 효과를 새로운 트랜잭션으로 의미상 되돌리는 것이다","보상 트랜잭션은 더 빠르다","보상 트랜잭션은 실패할 수 없다","보상 트랜잭션은 자동으로 생성된다"],"a":0},{"t":"choice","k":"sysd-ms-saga-isolation","q":"사가가 ACID 중 특히 제공하지 못하는 성질은?","ex":"각 단계가 개별 커밋되므로 사가 진행 중의 중간 상태가 다른 트랜잭션에 그대로 보인다.\n💡 개념: 원자성은 보상으로 흉내 낼 수 있지만 격리성은 흉내 낼 수 없다.\n🛠 실무: 시맨틱 락(상태를 PENDING으로 표시)이나 교환 가능한 갱신 설계로 격리성 부재의 부작용을 줄인다.","o":["원자성(Atomicity)","일관성(Consistency)","격리성(Isolation)","지속성(Durability)"],"a":2},{"t":"choice","k":"sysd-ms-saga-myth","q":"'사가는 2PC와 동일한 수준의 원자성과 격리성을 제공한다'는 주장에 대한 평가는?","ex":"사가는 가용성을 얻는 대신 격리성을 포기한 설계다.\n💡 개념: 무엇을 포기했는지 모르는 채 사가를 도입하면 중간 상태 노출로 인한 업무 사고가 난다.\n🛠 실무: 사가 진행 중인 주문은 UI에서 '처리 중'으로 명시해 사용자와 CS가 중간 상태를 인지하게 만든다.","o":["맞다. 사가는 2PC의 완전한 대체재다","맞다. 보상 트랜잭션이 격리성을 보장한다","틀리다. 사가는 원자성도 전혀 흉내 내지 못한다","틀리다. 사가는 최종 일관성 기반이며 중간 상태가 외부에 노출되므로 격리성이 없다"],"a":3},{"t":"input","k":"sysd-ms-compensation-name","q":"사가에서 중간 단계가 실패했을 때 이미 완료된 앞 단계의 효과를 되돌리기 위해 실행하는 트랜잭션을 무엇이라 하는가? (한글)","ex":"정답은 보상 트랜잭션(compensating transaction)이다.\n💡 개념: 보상은 역순으로 실행되며 각 단계마다 짝이 되는 보상 로직이 정의되어야 한다.\n🛠 실무: 보상 불가능한 단계(예: 실제 발송)는 사가의 마지막에 배치해 되돌릴 일이 없게 만든다.","a":["보상 트랜잭션","보상트랜잭션","보상 거래","compensating transaction"]}],"th":{"sum":"서비스 경계는 코드 크기가 아니라 함께 변경되는 도메인과 데이터 소유권이 정한다. 경계를 넘는 통신을 동기로 할지 비동기로 할지가 시스템의 가용성과 지연을 사실상 결정한다.","body":[{"h":"경계는 무엇이 정하는가","t":"좋은 경계는 함께 바뀌는 것을 한데 모으고 따로 바뀌는 것을 떼어낸다. 기준은 도메인 개념과 데이터 소유권, 그리고 팀 구조다. 콘웨이의 법칙대로 시스템 구조는 결국 조직의 소통 구조를 닮으므로, 팀 경계와 서비스 경계가 어긋나면 배포마다 조율 비용이 폭증한다. 서비스 수가 많은 것 자체는 아무 미덕이 아니다."},{"h":"동기 호출의 숨은 비용","t":"동기 호출은 이해하기 쉽지만 가용성이 곱해진다. 99.9%짜리 서비스 세 개를 직렬로 호출하면 전체는 약 99.7%가 되어 연간 다운타임이 8.8시간에서 26시간으로 늘어난다. 지연도 누적되어 p99 50ms인 서비스 다섯 개를 직렬 호출하면 최선의 경우에도 250ms가 든다. 팬아웃 호출에서는 가장 느린 하나가 전체 응답을 지배하는 꼬리 지연 증폭이 나타난다."},{"h":"비동기 이벤트의 이득과 대가","t":"이벤트 기반 통신은 호출자가 수신자의 가용성에 묶이지 않게 해주므로 결합도와 장애 전파를 줄인다. 대신 결과가 즉시 반영되지 않는 최종 일관성을 받아들여야 하고, 디버깅과 추적이 어려워진다. 사용자가 즉시 응답을 봐야 하는 질의는 동기가 맞고, 부가 처리와 알림, 통계는 비동기가 맞다. 판단 기준은 '호출자가 결과를 지금 알아야 하는가'다."},{"h":"사가와 보상 트랜잭션","t":"여러 서비스에 걸친 업무를 하나의 ACID 트랜잭션으로 묶을 수 없으므로 사가를 쓴다. 사가는 로컬 트랜잭션의 연쇄이며, 중간에 실패하면 앞 단계의 효과를 의미적으로 되돌리는 보상 트랜잭션을 역순으로 실행한다. 중앙 조정자가 흐름을 지휘하면 오케스트레이션, 각 서비스가 이벤트를 듣고 반응하면 코레오그래피다. 사가는 원자성을 흉내 낼 뿐 격리성은 제공하지 않아 중간 상태가 외부에 노출된다."}],"code":{"c":"[가용성은 곱해진다]\nA → B → C, 각 99.9%\n0.999^3 ≈ 0.997 → 연간 다운타임 약 26시간 (99.9%는 약 8.8시간)\n\n[지연은 누적된다]\np99 50ms 서비스 5개 직렬 → 최선 250ms\n팬아웃 10개 병렬 → 전체 p99 ≈ 가장 느린 하나 (꼬리 지연 증폭)\n\n[주문 사가]\n주문생성 → 결제승인 → 재고차감 → 배송요청\n     ↑ 실패 시 역순 보상 ↓\n주문취소 ← 결제취소 ← 재고복구 ← 배송취소\n\n오케스트레이션: 중앙 조정자가 다음 단계를 명령\n코레오그래피 : 각 서비스가 이벤트를 구독해 스스로 반응","cap":"동기 체인이 길어질수록 가용성은 곱해지고 지연은 더해진다."},"key":["서비스 경계는 도메인과 데이터 소유권, 팀 구조가 정하며 서비스 개수 자체는 목표가 아니다","동기 직렬 호출은 가용성을 곱하고 지연을 누적시킨다","사가는 보상 트랜잭션으로 원자성을 흉내 낼 뿐 격리성은 제공하지 않는다"]}}]},{"t":"비용·운영 트레이드오프 심화: 멀티리전과 재해복구 실무","l":[{"t":"RTO/RPO와 재해복구 전략","q":[{"t":"choice","k":"sysd-dr-rpo-def","q":"RPO(Recovery Point Objective)의 정의로 옳은 것은?","ex":"RPO는 '어느 시점까지의 데이터를 살릴 것인가'를 뜻하는 데이터 축의 목표다.\n💡 개념: 첫 번째 보기는 RTO의 정의다.\n🛠 실무: RPO를 정하면 백업 주기와 복제 방식(동기/비동기)이 자동으로 결정된다.","o":["장애 발생 후 서비스를 재개하기까지 허용되는 시간","장애 시 허용할 수 있는 데이터 손실의 시간 범위","연간 허용되는 총 장애 횟수","복구 작업에 투입 가능한 인원 수"],"a":1},{"t":"choice","k":"sysd-dr-rto-def","q":"RTO(Recovery Time Objective)가 30분이라는 요구사항이 의미하는 것은?","ex":"RTO는 다운타임의 상한이며 데이터 손실량과는 별개다.\n💡 개념: RTO가 짧을수록 대기 중인 예비 인프라를 더 많이 상시 가동해야 한다.\n🛠 실무: RTO에는 장애 인지 시간과 의사결정 시간까지 포함해야 실제 상황에서 지킬 수 있다.","o":["최대 30분치의 데이터 손실까지는 허용된다","장애 발생 후 30분 안에 서비스가 다시 정상 동작해야 한다","백업을 30분마다 받아야 한다","장애 알림이 30분 안에 전달되어야 한다"],"a":1},{"t":"choice","k":"sysd-dr-backup-rpo","q":"6시간마다 전체 백업만 받고 다른 복제 수단이 없는 시스템의 최악의 경우 RPO는?","ex":"직전 백업 직후부터 장애 직전까지의 데이터를 잃으므로 최악의 경우 6시간치가 손실된다.\n💡 개념: 백업 주기가 곧 RPO의 상한이 된다.\n🛠 실무: RPO를 분 단위로 줄이려면 백업 주기 단축이 아니라 트랜잭션 로그 연속 백업이나 복제가 필요하다.","o":["약 6시간","0","약 12시간","약 24시간"],"a":0},{"t":"choice","k":"sysd-dr-sync-repl","q":"RPO를 0에 가깝게 만들기 위해 동기 복제를 선택할 때 치러야 하는 대가는?","ex":"동기 복제는 커밋 응답 전에 상대 노드의 확인을 기다리므로 왕복 지연이 그대로 쓰기 지연에 더해진다.\n💡 개념: 리전 간 동기 복제는 수십에서 수백 ms의 RTT를 매 쓰기마다 지불하는 셈이다.\n🛠 실무: 같은 리전의 다른 가용 영역 간에는 동기 복제가 현실적이지만, 대륙을 넘는 동기 복제는 대부분 비현실적이다.","o":["저장 용량이 절반으로 줄어든다","읽기 일관성이 약해진다","모든 쓰기가 복제 대상까지의 왕복 지연을 기다려야 하므로 쓰기 지연이 늘어난다","백업을 받을 수 없게 된다"],"a":2},{"t":"choice","k":"sysd-dr-strategy","q":"재해복구 전략 중 비용이 가장 낮은 대신 RTO가 가장 긴 것은?","ex":"백업 및 복원은 평상시 비용이 거의 없지만 복구에 수 시간에서 수 일이 걸린다.\n💡 개념: RTO를 줄이는 값은 '평상시에 얼마나 많은 것을 미리 켜 두는가'로 지불된다.\n🛠 실무: 서비스별로 등급을 나눠 핵심 서비스만 웜 스탠바이, 나머지는 백업/복원으로 두는 혼합 전략이 비용 효율적이다.","o":["액티브-액티브 멀티사이트","웜 스탠바이","파일럿 라이트","백업 및 복원"],"a":3},{"t":"input","k":"sysd-dr-rpo-abbr","q":"'복구 시점 목표', 즉 허용 가능한 데이터 손실 범위를 뜻하는 세 글자 영문 약어는?","ex":"정답은 RPO(Recovery Point Objective)다.\n💡 개념: 짝이 되는 RTO(Recovery Time Objective)는 허용 다운타임을 뜻한다.\n🛠 실무: DR 문서의 첫 줄에는 항상 이 두 숫자가 명시되어 있어야 한다.","a":["RPO","rpo"]}],"th":{"sum":"가용성은 공짜가 아니라 구간마다 값이 급격히 오르는 상품이다. RTO와 RPO로 요구 수준을 숫자로 정의해야 어떤 재해복구 전략과 비용이 적정한지 판단할 수 있다.","body":[{"h":"RTO와 RPO는 다른 축이다","t":"RTO(복구 시간 목표)는 장애 발생 후 서비스를 다시 열기까지 허용되는 시간이고, RPO(복구 시점 목표)는 허용할 수 있는 데이터 손실 구간이다. 즉 RTO는 시간 축의 다운타임, RPO는 데이터 축의 유실량을 말한다. 6시간마다 백업을 받는다면 최악의 경우 6시간치를 잃으므로 RPO는 6시간이고, 복구 절차에 2시간이 걸린다면 RTO는 약 2시간이다. 두 값을 혼동하면 전혀 다른 아키텍처를 사게 된다."},{"h":"재해복구 전략 네 단계","t":"백업 및 복원은 가장 싸지만 RTO가 수 시간에서 수 일이다. 파일럿 라이트는 데이터 복제만 상시 유지하고 컴퓨트는 최소로 두어 수십 분 내 복구를 노린다. 웜 스탠바이는 축소된 규모의 전체 스택을 상시 가동해 수 분 내 전환한다. 액티브-액티브 멀티사이트는 두 리전이 모두 트래픽을 받아 RTO가 수 초 수준이지만 비용과 복잡도가 가장 크다."},{"h":"멀티리전의 진짜 비용","t":"멀티리전은 인프라를 두 배로 늘리는 데서 끝나지 않는다. 리전 간 데이터 전송 요금이 붙고, 동기 복제를 택하면 리전 간 왕복 지연이 모든 쓰기에 더해진다. 비동기 복제를 택하면 쓰기 지연은 지키지만 복제 지연만큼 RPO가 0이 아니게 된다. 액티브-액티브에서는 양쪽에서 같은 데이터를 바꿀 때의 충돌 해결까지 설계해야 한다."},{"h":"비용 최적화의 축","t":"비용은 컴퓨트, 스토리지, 네트워크 전송의 세 축에서 발생하며 각각 다른 지렛대를 쓴다. 컴퓨트는 오토스케일과 예약 인스턴스, 스팟으로 줄이고, 스토리지는 접근 빈도에 따른 계층화와 보존 정책으로 줄이며, 네트워크는 CDN과 리전 내 통신 설계로 줄인다. 다만 가용성 목표를 9 하나 올릴 때마다 비용은 대체로 몇 배씩 뛰므로, 사업적으로 정말 필요한 수준인지 먼저 합의해야 한다."}],"code":{"c":"RTO = 복구 시간 목표 (얼마나 빨리 다시 여는가)\nRPO = 복구 시점 목표 (얼마나 많은 데이터를 잃어도 되는가)\n\n백업 주기 6시간 + 복구 절차 2시간\n  → RPO 최대 6시간, RTO 약 2시간\n\n전략            RTO          RPO         상대 비용\n백업/복원       수시간~수일   수시간       낮음\n파일럿 라이트   수십 분      수 분        중간\n웜 스탠바이     수 분        수 초~수 분   높음\n액티브-액티브   수 초        0에 가까움    매우 높음\n\n[연간 허용 다운타임]\n99.9%   → 약 8.8시간\n99.99%  → 약 52.6분\n99.999% → 약 5.3분","cap":"RTO는 시간 축, RPO는 데이터 축이며 두 값이 전략과 비용을 결정한다."},"key":["RTO는 허용 다운타임, RPO는 허용 데이터 손실 구간으로 서로 다른 축이다","백업/복원 → 파일럿 라이트 → 웜 스탠바이 → 액티브-액티브 순으로 RTO는 짧아지고 비용은 급증한다","비동기 복제 멀티리전은 RPO가 0이 아니며, 동기 복제는 리전 간 왕복 지연을 쓰기마다 지불한다"]}},{"t":"멀티리전 설계와 그 대가","q":[{"t":"choice","k":"sysd-dr-active-active","q":"액티브-액티브 멀티리전 구성에서 가장 어려운 기술적 과제는?","ex":"양쪽이 모두 쓰기를 받으면 충돌이 필연적으로 발생하며 이를 도메인 규칙으로 해결해야 한다.\n💡 개념: last-write-wins, CRDT, 리전별 파티셔닝 등이 대표적인 해결 방향이다.\n🛠 실무: 사용자나 테넌트 단위로 홈 리전을 고정해 충돌 자체를 없애는 설계가 가장 현실적인 경우가 많다.","o":["두 리전에서 동시에 같은 데이터를 변경할 때의 쓰기 충돌 해결과 일관성 유지","로드 밸런서 설정","DNS 레코드 등록","로그 수집"],"a":0},{"t":"choice","k":"sysd-dr-async-rpo","q":"'멀티리전 구성이면 데이터 손실이 없으므로 RPO는 자동으로 0이다'는 주장에 대한 평가는?","ex":"복제 방식이 RPO를 결정하며, 비동기 복제에서는 아직 복제되지 않은 구간이 그대로 손실된다.\n💡 개념: 리전 개수가 아니라 복제의 동기/비동기 여부가 핵심 변수다.\n🛠 실무: 복제 지연(replication lag)을 상시 모니터링하고 알람을 걸어 실제 RPO를 관측 가능하게 만들어야 한다.","o":["맞다. 리전이 두 개면 손실이 없다","맞다. 클라우드가 자동으로 보장한다","틀리다. 비동기 복제를 쓰면 복제 지연 구간만큼 데이터가 손실될 수 있어 RPO는 0이 아니다","틀리다. 멀티리전은 RPO와 무관하다"],"a":2},{"t":"choice","k":"sysd-dr-rtt","q":"지리적으로 멀리 떨어진 두 리전 사이에 동기 복제를 적용했을 때 쓰기 지연에 대한 설명으로 옳은 것은?","ex":"물리적 거리는 광속의 한계로 인해 왕복 지연을 만들고, 동기 복제는 그 지연을 매 커밋마다 지불한다.\n💡 개념: 지연은 튜닝으로 없앨 수 없는 물리적 하한이 있다.\n🛠 실무: 대륙 간 구성에서는 대부분 비동기 복제를 쓰고 RPO를 수 초 수준으로 관리하는 절충을 택한다.","o":["지연은 변하지 않는다","지연이 오히려 줄어든다","읽기 지연만 늘어난다","리전 간 왕복 지연(RTT)이 매 쓰기마다 추가되어 수십에서 수백 ms가 늘어난다"],"a":3},{"t":"choice","k":"sysd-dr-drill","q":"재해복구 계획이 실제로 동작하는지 검증하는 가장 신뢰할 만한 방법은?","ex":"한 번도 실행해 보지 않은 복구 절차는 사실상 존재하지 않는 것과 같다.\n💡 개념: 훈련은 절차의 결함뿐 아니라 실제 소요 시간이라는 숫자를 준다.\n🛠 실무: 게임데이를 분기 단위로 정례화하고, 훈련에서 나온 RTO 실측치를 목표와 비교해 갱신한다.","o":["DR 문서를 정기적으로 검토한다","정기적으로 실제 페일오버 훈련을 수행해 RTO와 RPO를 측정한다","백업 파일의 크기를 확인한다","클라우드 벤더의 SLA 문서를 신뢰한다"],"a":1},{"t":"choice","k":"sysd-dr-blast","q":"셀 기반 아키텍처처럼 시스템을 독립된 단위로 쪼개는 설계의 주된 목적은?","ex":"셀 분리는 장애 영향 범위, 즉 폭발 반경을 제한하는 것이 목적이다.\n💡 개념: 전면 장애 대신 일부 사용자에게만 영향을 주는 부분 장애로 바꾸는 전략이다.\n🛠 실무: 배포도 셀 단위로 순차 진행하면 문제 발생 시 자동 롤백으로 피해를 한 셀에 가둘 수 있다.","o":["한 번의 장애나 잘못된 배포가 영향을 미치는 범위를 좁히기 위해","전체 처리량을 최대화하기 위해","인프라 비용을 최소화하기 위해","코드베이스를 단순하게 만들기 위해"],"a":0}],"th":{"sum":"가용성은 공짜가 아니라 구간마다 값이 급격히 오르는 상품이다. RTO와 RPO로 요구 수준을 숫자로 정의해야 어떤 재해복구 전략과 비용이 적정한지 판단할 수 있다.","body":[{"h":"RTO와 RPO는 다른 축이다","t":"RTO(복구 시간 목표)는 장애 발생 후 서비스를 다시 열기까지 허용되는 시간이고, RPO(복구 시점 목표)는 허용할 수 있는 데이터 손실 구간이다. 즉 RTO는 시간 축의 다운타임, RPO는 데이터 축의 유실량을 말한다. 6시간마다 백업을 받는다면 최악의 경우 6시간치를 잃으므로 RPO는 6시간이고, 복구 절차에 2시간이 걸린다면 RTO는 약 2시간이다. 두 값을 혼동하면 전혀 다른 아키텍처를 사게 된다."},{"h":"재해복구 전략 네 단계","t":"백업 및 복원은 가장 싸지만 RTO가 수 시간에서 수 일이다. 파일럿 라이트는 데이터 복제만 상시 유지하고 컴퓨트는 최소로 두어 수십 분 내 복구를 노린다. 웜 스탠바이는 축소된 규모의 전체 스택을 상시 가동해 수 분 내 전환한다. 액티브-액티브 멀티사이트는 두 리전이 모두 트래픽을 받아 RTO가 수 초 수준이지만 비용과 복잡도가 가장 크다."},{"h":"멀티리전의 진짜 비용","t":"멀티리전은 인프라를 두 배로 늘리는 데서 끝나지 않는다. 리전 간 데이터 전송 요금이 붙고, 동기 복제를 택하면 리전 간 왕복 지연이 모든 쓰기에 더해진다. 비동기 복제를 택하면 쓰기 지연은 지키지만 복제 지연만큼 RPO가 0이 아니게 된다. 액티브-액티브에서는 양쪽에서 같은 데이터를 바꿀 때의 충돌 해결까지 설계해야 한다."},{"h":"비용 최적화의 축","t":"비용은 컴퓨트, 스토리지, 네트워크 전송의 세 축에서 발생하며 각각 다른 지렛대를 쓴다. 컴퓨트는 오토스케일과 예약 인스턴스, 스팟으로 줄이고, 스토리지는 접근 빈도에 따른 계층화와 보존 정책으로 줄이며, 네트워크는 CDN과 리전 내 통신 설계로 줄인다. 다만 가용성 목표를 9 하나 올릴 때마다 비용은 대체로 몇 배씩 뛰므로, 사업적으로 정말 필요한 수준인지 먼저 합의해야 한다."}],"code":{"c":"RTO = 복구 시간 목표 (얼마나 빨리 다시 여는가)\nRPO = 복구 시점 목표 (얼마나 많은 데이터를 잃어도 되는가)\n\n백업 주기 6시간 + 복구 절차 2시간\n  → RPO 최대 6시간, RTO 약 2시간\n\n전략            RTO          RPO         상대 비용\n백업/복원       수시간~수일   수시간       낮음\n파일럿 라이트   수십 분      수 분        중간\n웜 스탠바이     수 분        수 초~수 분   높음\n액티브-액티브   수 초        0에 가까움    매우 높음\n\n[연간 허용 다운타임]\n99.9%   → 약 8.8시간\n99.99%  → 약 52.6분\n99.999% → 약 5.3분","cap":"RTO는 시간 축, RPO는 데이터 축이며 두 값이 전략과 비용을 결정한다."},"key":["RTO는 허용 다운타임, RPO는 허용 데이터 손실 구간으로 서로 다른 축이다","백업/복원 → 파일럿 라이트 → 웜 스탠바이 → 액티브-액티브 순으로 RTO는 짧아지고 비용은 급증한다","비동기 복제 멀티리전은 RPO가 0이 아니며, 동기 복제는 리전 간 왕복 지연을 쓰기마다 지불한다"]}},{"t":"비용과 운영의 트레이드오프","q":[{"t":"choice","k":"sysd-cost-egress","q":"클라우드 비용 산정에서 자주 과소평가되어 청구서를 놀라게 만드는 항목은?","ex":"컴퓨트와 스토리지는 예측하기 쉽지만 전송 요금은 트래픽 패턴에 따라 급증한다.\n💡 개념: 특히 가용 영역 간, 리전 간, 인터넷 방향 전송의 단가가 각각 다르다.\n🛠 실무: 서비스 간 호출을 같은 가용 영역으로 유도하고 사용자 대상 트래픽은 CDN으로 흡수시켜 전송 비용을 줄인다.","o":["인스턴스의 CPU 시간","오브젝트 스토리지의 저장 요금","리전 간 전송과 인터넷 이그레스 등 네트워크 데이터 전송 요금","관리 콘솔 사용료"],"a":2},{"t":"choice","k":"sysd-cost-autoscale","q":"오토스케일링에 전적으로 의존할 때 생기는 한계로 옳은 것은?","ex":"스케일아웃에는 수십 초에서 수 분의 지연이 있으며 상태를 가진 계층은 즉시 늘릴 수 없다.\n💡 개념: 그래서 오토스케일은 부하 차단, 큐, 사전 스케일링과 함께 써야 한다.\n🛠 실무: 예측 가능한 이벤트(세일, 티켓팅)는 스케줄 기반 사전 스케일링으로 대비하는 것이 안전하다.","o":["비용이 항상 증가한다","트래픽이 줄어도 축소되지 않는다","가용 영역을 하나만 쓸 수 있다","인스턴스 기동과 워밍업에 시간이 걸려 급격한 스파이크에는 늦고, 데이터베이스는 쉽게 확장되지 않는다"],"a":3},{"t":"choice","k":"sysd-cost-tier","q":"저장 데이터를 핫/쿨/아카이브 계층으로 나눌 때의 트레이드오프로 옳은 것은?","ex":"계층화는 저장 단가와 접근 비용/지연을 맞바꾸는 설계다.\n💡 개념: 아카이브 계층은 인출에 수 분에서 수 시간이 걸리고 인출량에 따라 별도 요금이 붙는다.\n🛠 실무: 자주 조회되는 최근 데이터가 아카이브로 내려가지 않도록 수명 주기 정책의 기준일을 실제 접근 패턴으로 검증해야 한다.","o":["차가운 계층일수록 저장 단가는 낮지만 조회 지연과 인출 비용이 커진다","차가운 계층일수록 저장 단가와 조회 비용이 모두 낮아진다","계층을 나누면 내구성이 떨어진다","아카이브 계층은 데이터를 영구히 읽을 수 없다"],"a":0},{"t":"choice","k":"sysd-cost-spot","q":"스팟(선점형) 인스턴스를 쓰기에 가장 적합한 워크로드는?","ex":"스팟은 언제든 회수될 수 있으므로 중단 내성이 있는 작업에만 안전하다.\n💡 개념: 체크포인트와 재시작 가능성이 스팟 활용의 전제 조건이다.\n🛠 실무: 스팟과 온디맨드를 섞은 혼합 용량 정책으로 비용은 낮추고 최소 가용 용량은 보장하는 구성이 일반적이다.","o":["결제 처리 API","주 데이터베이스","중단되어도 재시작할 수 있는 배치 처리나 상태 없는 렌더링 작업","사용자 세션을 메모리에 보관하는 서버"],"a":2},{"t":"choice","k":"sysd-cost-nines","q":"가용성 목표를 99.9%에서 99.99%로 올릴 때의 일반적인 성질은?","ex":"9를 하나 추가할 때마다 허용 다운타임은 1/10이 되고 그것을 달성하는 비용은 급격히 커진다.\n💡 개념: 가용성 비용은 선형이 아니라 계단식으로 뛴다.\n🛠 실무: 서비스마다 필요한 9의 개수를 사업 영향으로 산정하고, 전부에 최고 등급을 적용하지 않는 것이 핵심이다.","o":["비용이 대략 10% 정도만 증가한다","비용은 변하지 않고 설정만 바꾸면 된다","가용성이 올라가면 비용은 오히려 감소한다","허용 다운타임이 크게 줄어드는 만큼 이중화, 자동 페일오버, 운영 인력 비용이 몇 배로 증가한다"],"a":3},{"t":"choice","k":"sysd-cost-downtime","q":"가용성 99.99%가 허용하는 연간 다운타임은 대략 얼마인가?","ex":"1년은 약 8,760시간이고 0.01%는 0.876시간, 즉 약 52.6분이다.\n💡 개념: 99.9%는 약 8.8시간, 99.999%는 약 5.3분으로 자릿수가 한 단계씩 바뀐다.\n🛠 실무: 정기 배포와 유지보수까지 이 예산 안에 들어가야 하므로 무중단 배포가 사실상 필수가 된다.","o":["약 5분","약 53분","약 8.8시간","약 4.4일"],"a":1}],"th":{"sum":"가용성은 공짜가 아니라 구간마다 값이 급격히 오르는 상품이다. RTO와 RPO로 요구 수준을 숫자로 정의해야 어떤 재해복구 전략과 비용이 적정한지 판단할 수 있다.","body":[{"h":"RTO와 RPO는 다른 축이다","t":"RTO(복구 시간 목표)는 장애 발생 후 서비스를 다시 열기까지 허용되는 시간이고, RPO(복구 시점 목표)는 허용할 수 있는 데이터 손실 구간이다. 즉 RTO는 시간 축의 다운타임, RPO는 데이터 축의 유실량을 말한다. 6시간마다 백업을 받는다면 최악의 경우 6시간치를 잃으므로 RPO는 6시간이고, 복구 절차에 2시간이 걸린다면 RTO는 약 2시간이다. 두 값을 혼동하면 전혀 다른 아키텍처를 사게 된다."},{"h":"재해복구 전략 네 단계","t":"백업 및 복원은 가장 싸지만 RTO가 수 시간에서 수 일이다. 파일럿 라이트는 데이터 복제만 상시 유지하고 컴퓨트는 최소로 두어 수십 분 내 복구를 노린다. 웜 스탠바이는 축소된 규모의 전체 스택을 상시 가동해 수 분 내 전환한다. 액티브-액티브 멀티사이트는 두 리전이 모두 트래픽을 받아 RTO가 수 초 수준이지만 비용과 복잡도가 가장 크다."},{"h":"멀티리전의 진짜 비용","t":"멀티리전은 인프라를 두 배로 늘리는 데서 끝나지 않는다. 리전 간 데이터 전송 요금이 붙고, 동기 복제를 택하면 리전 간 왕복 지연이 모든 쓰기에 더해진다. 비동기 복제를 택하면 쓰기 지연은 지키지만 복제 지연만큼 RPO가 0이 아니게 된다. 액티브-액티브에서는 양쪽에서 같은 데이터를 바꿀 때의 충돌 해결까지 설계해야 한다."},{"h":"비용 최적화의 축","t":"비용은 컴퓨트, 스토리지, 네트워크 전송의 세 축에서 발생하며 각각 다른 지렛대를 쓴다. 컴퓨트는 오토스케일과 예약 인스턴스, 스팟으로 줄이고, 스토리지는 접근 빈도에 따른 계층화와 보존 정책으로 줄이며, 네트워크는 CDN과 리전 내 통신 설계로 줄인다. 다만 가용성 목표를 9 하나 올릴 때마다 비용은 대체로 몇 배씩 뛰므로, 사업적으로 정말 필요한 수준인지 먼저 합의해야 한다."}],"code":{"c":"RTO = 복구 시간 목표 (얼마나 빨리 다시 여는가)\nRPO = 복구 시점 목표 (얼마나 많은 데이터를 잃어도 되는가)\n\n백업 주기 6시간 + 복구 절차 2시간\n  → RPO 최대 6시간, RTO 약 2시간\n\n전략            RTO          RPO         상대 비용\n백업/복원       수시간~수일   수시간       낮음\n파일럿 라이트   수십 분      수 분        중간\n웜 스탠바이     수 분        수 초~수 분   높음\n액티브-액티브   수 초        0에 가까움    매우 높음\n\n[연간 허용 다운타임]\n99.9%   → 약 8.8시간\n99.99%  → 약 52.6분\n99.999% → 약 5.3분","cap":"RTO는 시간 축, RPO는 데이터 축이며 두 값이 전략과 비용을 결정한다."},"key":["RTO는 허용 다운타임, RPO는 허용 데이터 손실 구간으로 서로 다른 축이다","백업/복원 → 파일럿 라이트 → 웜 스탠바이 → 액티브-액티브 순으로 RTO는 짧아지고 비용은 급증한다","비동기 복제 멀티리전은 RPO가 0이 아니며, 동기 복제는 리전 간 왕복 지연을 쓰기마다 지불한다"]}}]},{"t":"설계 면접 — 45분을 끌고 가는 진행법","l":[{"t":"첫 5분: 요구사항 명확화","q":[{"t":"choice","k":"첫 행동","q":"'트위터 같은 서비스를 설계해 보세요'라는 문제를 받았을 때 가장 먼저 해야 할 일은?","ex":"설계 면접의 문제는 의도적으로 모호하게 주어진다. 범위를 좁히는 질문 자체가 평가 항목이며, 범위를 정하지 않으면 무엇을 설계해도 '그건 안 물어봤는데요'가 된다.\n면접에서는 '타임라인 조회, 게시, 팔로우 세 가지에 집중하고 DM과 검색은 제외해도 될까요?'처럼 먼저 제안하고 확인받으면 진행이 매끄럽다.","cat":"interview","o":["기능 범위(무엇을 만들고 무엇은 제외할지)와 비기능 요구(사용자 규모, 읽기/쓰기 비율, 지연 목표, 일관성 요구)를 질문해 확정한다","가장 최신 기술 스택을 나열해 아키텍처를 제안한다","데이터베이스 스키마부터 상세히 설계한다","바로 화이트보드에 로드밸런서와 서버, DB를 그리기 시작한다"],"a":0},{"t":"choice","k":"좋은 질문","q":"요구사항 명확화 단계에서 던지기 좋은 질문으로 가장 적절한 것은?","ex":"설계를 좌우하는 것은 언어나 벤더가 아니라 규모·비율·지연·일관성 요구다. 이 네 가지가 캐시 필요성, 저장소 선택, 팬아웃 전략을 모두 결정한다.\n면접에서는 답을 받으면 '그럼 읽기가 100배 많으니 읽기 경로 최적화에 집중하겠습니다'처럼 즉시 설계 방향으로 연결해야 한다.","cat":"interview","o":["'DAU는 어느 정도이고 읽기와 쓰기 비율은 어떻게 되나요? 타임라인은 몇 초 지연까지 허용되나요?'","'클라우드는 어느 벤더를 쓰나요?'","'팀 규모와 개발 기간은 얼마나 되나요?'","'어떤 프로그래밍 언어를 쓰면 되나요?'"],"a":0},{"t":"choice","k":"가정 선언","q":"면접관이 '그건 알아서 가정하세요'라고 답했을 때 올바른 대응은?","ex":"가정을 명시하면 이후 모든 판단에 근거가 생기고, 틀렸다면 면접관이 즉시 교정해 준다. 모든 경우를 다 지원하려는 설계는 초점이 사라져 시간만 잡아먹는다.\n면접에서는 '이 가정이 바뀌면 설계의 이 부분이 달라집니다'까지 말하면 민감도를 이해한 것으로 보인다.","cat":"interview","o":["질문을 접고 조용히 진행한다","'DAU 1,000만, 읽기:쓰기 = 100:1, 타임라인 지연 3초까지 허용으로 가정하겠습니다'처럼 구체적 숫자로 가정을 선언하고 칠판에 적은 뒤 진행한다","가정 없이 모든 경우를 다 지원하는 설계를 한다","가장 큰 규모를 가정해 항상 글로벌 분산 시스템으로 설계한다"],"a":1},{"t":"choice","k":"범위 축소","q":"45분 안에 '유튜브를 설계하라'는 문제를 받았다. 범위 설정으로 가장 적절한 것은?","ex":"모든 것을 다루면 아무것도 깊이 다루지 못한다. 핵심 흐름 두 개를 정하고 나머지를 명시적으로 배제하는 것이 곧 설계 판단력이다.\n면접에서는 '제외한다'가 아니라 '지금은 제외하고 시간이 남으면 다루겠습니다'라고 말하면 회피가 아닌 우선순위로 읽힌다.","cat":"interview","o":["업로드, 인코딩, 스트리밍, 추천, 광고, 댓글, 검색을 모두 다룬다","업로드/인코딩과 시청(스트리밍) 경로 두 가지로 좁히고, 추천·광고·검색은 명시적으로 범위 밖으로 선언한 뒤 필요하면 마지막에 언급한다","추천 알고리즘에 집중해 머신러닝 파이프라인을 상세히 설계한다","댓글 시스템만 아주 깊이 설계한다"],"a":1},{"t":"input","k":"비기능 요구","q":"규모·지연·가용성·일관성처럼 '무엇을 하는가'가 아니라 '얼마나 잘 해야 하는가'를 규정하는 요구사항을 무엇이라 하는가? (한글 용어)","ex":"기능 요구사항이 화면과 API를 정한다면, 비기능 요구사항이 아키텍처를 정한다.\n면접에서는 '기능은 3개로 좁히고 비기능은 숫자로 확정하겠습니다'라고 두 축을 나눠 말하면 정리된 인상을 준다.","cat":"interview","a":["비기능 요구사항","비기능적 요구사항","비기능 요구","non-functional requirements"]},{"t":"choice","k":"일관성 확인","q":"요구사항 단계에서 일관성에 관해 물어야 할 질문으로 가장 적절한 것은?","ex":"일관성 요구는 저장소 선택보다 앞선다. '몇 초 지연 허용'이라는 답 하나로 비동기 팬아웃과 최종 일관성 설계가 정당화된다.\n면접에서는 '반면 잔액이나 재고는 최종 일관성으로 두면 안 되므로 강한 일관성이 필요합니다'라고 대조하면 이해도가 잘 드러난다.","cat":"interview","o":["'인덱스는 몇 개나 만들까요?'","'DB는 MySQL을 쓸까요, MongoDB를 쓸까요?'","'게시물을 올린 뒤 팔로워 타임라인에 몇 초 안에 보여야 하나요? 잠깐 안 보여도 괜찮은가요?'","'트랜잭션 격리수준은 무엇으로 할까요?'"],"a":2}],"th":{"sum":"시스템 설계 면접은 정답을 맞히는 시험이 아니라, 모호한 요구를 좁혀 가며 설계를 함께 만들어 가는 대화다. 면접관은 당신이 어떤 순서로 생각하는지를 채점한다.","body":[{"h":"면접관이 보는 것","t":"면접관은 완성된 아키텍처 그림보다 '무엇을 먼저 물었는가'를 본다. 요구사항을 확정하지 않고 바로 컴포넌트를 그리기 시작하면 그 순간 감점이 시작된다. 범위를 스스로 좁히고, 가정을 소리 내어 말하고, 선택마다 대안을 언급하며 이유를 대는 사람이 높은 점수를 받는다. 또한 시간 배분을 관리하는지도 관찰 대상이라, 한 부분에 20분을 쓰고 전체 그림을 못 그리면 좋은 평가를 받기 어렵다."},{"h":"답변 구조","t":"45분 기준으로 요구사항 명확화 5~10분, 규모 추정 5분, 개략 설계 10~15분, 상세 설계 10~15분, 병목과 확장 5분으로 배분한다. 먼저 기능 요구사항 3~4개로 범위를 잘라내고, 비기능 요구사항(규모, 지연, 가용성, 일관성)을 숫자로 확정한다. 개략 설계에서는 클라이언트-API-저장소의 흐름과 핵심 API 시그니처, 데이터 모델까지만 그리고 멈춘 뒤 '어느 부분을 더 깊이 볼까요'라고 물어 면접관이 원하는 지점으로 들어간다. 마지막 5분은 단일 장애점과 확장 지점을 스스로 짚으며 마무리한다."}],"code":{"c":"0~7분   요구사항: 기능 3개로 범위 확정 + 규모·지연·일관성 숫자 확정\n7~12분  추정: DAU -> QPS, 저장량/년, 대역폭 (근사, 계산 과정을 말로)\n12~25분 개략: 클라이언트 - LB - API - 캐시 - DB/큐 + 핵심 API 3개 + 데이터 모델\n25~38분 상세: 면접관이 고른 한 부분 (샤딩 키, 팬아웃, 정합성 처리)\n38~45분 마무리: SPOF, 핫스팟, 모니터링, '시간이 더 있다면 볼 것'\n\n[말버릇] \"여기서는 A와 B가 있는데, 쓰기 폭증 때문에 B를 고르겠습니다. 대신 조회가 복잡해집니다.\"","cap":"설계 면접의 점수는 그림이 아니라 '고른 이유'와 '포기한 것'에서 나온다."},"key":["첫 5분에 요구사항을 좁히지 않으면 나머지 40분이 전부 흔들린다","가정은 반드시 소리 내어 말하고 칠판에 적는다 — 틀린 가정은 면접관이 고쳐 준다","모든 선택에는 '대신 무엇을 포기했는지'를 붙인다"]}},{"t":"개략 설계와 API·데이터 모델","q":[{"t":"choice","k":"개략 설계 범위","q":"개략 설계(high-level design) 단계에서 그려야 할 내용으로 가장 적절한 것은?","ex":"개략 설계는 '데이터가 어디로 흐르는가'를 보여 주는 단계다. 클래스 수준으로 내려가면 시간을 잃고, 제품명 나열은 설계 판단을 보여 주지 못한다.\n면접에서는 '읽기 경로와 쓰기 경로를 나눠 그리겠습니다'라고 선언하면 그림이 훨씬 명료해진다.","cat":"interview","o":["선택한 클라우드 서비스의 정확한 제품명과 인스턴스 타입","장애 대응 절차와 온콜 로테이션","각 서비스의 클래스 다이어그램과 함수 시그니처","클라이언트부터 저장소까지의 요청 흐름, 주요 컴포넌트(LB, API 서버, 캐시, DB, 큐, 오브젝트 스토리지)와 그 사이 데이터 이동, 그리고 핵심 API 2~3개와 데이터 모델"],"a":3},{"t":"choice","k":"API 정의","q":"설계 면접에서 API를 정의할 때 가장 좋은 방식은?","ex":"API 2~3개만으로도 데이터 모델과 접근 패턴이 드러나 이후 저장소 선택의 근거가 된다. 커서 기반 페이지네이션을 적어 두면 대규모 목록 처리에 대한 이해가 함께 전달된다.\n면접에서는 'OFFSET은 뒤로 갈수록 느려져 커서를 씁니다'라고 한 줄 붙이면 좋다.","code":"POST /v1/posts            {content, media_ids}      -&gt; {post_id, created_at}\nGET  /v1/feed?cursor=&amp;limit=20                     -&gt; {items[], next_cursor}\nPOST /v1/users/{id}/follow                          -&gt; 204","cat":"interview","o":["모든 CRUD 엔드포인트를 빠짐없이 나열한다","핵심 흐름을 대표하는 2~3개만 요청·응답 형태와 페이지네이션 방식까지 포함해 적는다","GraphQL 스키마 전체를 작성한다","API는 생략하고 컴포넌트 그림에 집중한다"],"a":1},{"t":"choice","k":"데이터 모델","q":"개략 설계에서 데이터 모델을 제시할 때 함께 말하면 좋은 것은?","ex":"대규모 설계에서 데이터 모델은 접근 패턴이 결정한다. 파티션 키를 왜 그렇게 잡았는지 설명하면 샤딩과 핫스팟 논의로 자연스럽게 이어진다.\n면접에서는 '이 키로 잡으면 한 사용자의 데이터가 한 파티션에 모여 조회가 한 번에 끝납니다'처럼 이유를 붙이면 좋다.","cat":"interview","o":["주요 테이블/컬렉션과 함께 '어떤 쿼리 패턴을 위해 이렇게 잡았는지', 그리고 기본 키와 인덱스(또는 파티션 키) 선택 이유","정규화 단계(3NF, BCNF)의 이론적 정의","ORM 엔티티 클래스 코드","모든 컬럼의 타입과 길이 제약"],"a":0},{"t":"choice","k":"읽기/쓰기 분리","q":"읽기가 쓰기보다 100배 많은 서비스의 개략 설계에서 우선 고려할 것은?","ex":"부하 비율이 설계의 방향을 결정한다. 읽기 우세 시스템은 캐시 히트율과 사전 계산이 핵심이고, 쓰기 우세라면 큐와 샤딩이 먼저다.\n면접에서는 '읽기:쓰기 = 100:1이라고 하셨으니 읽기 경로에 예산을 몰겠습니다'라고 요구사항과 연결하면 논리가 산다.","cat":"interview","o":["모든 요청을 단일 DB로 보내고 인덱스만 늘린다","쓰기 전용 샤딩을 먼저 도입한다","쓰기 경로에 큐를 넣어 쓰기를 비동기로 만든다","읽기 경로에 캐시를 두고 읽기 복제본으로 조회를 분산하며, 응답 형태를 미리 계산해 두는(사전 계산) 방안을 검토한다"],"a":3},{"t":"choice","k":"확인 후 진행","q":"개략 설계를 그린 직후 취해야 할 가장 좋은 행동은?","ex":"면접관은 보고 싶은 지점이 정해져 있는 경우가 많다. 방향을 물으면 원하는 곳에서 깊이를 보여 줄 수 있고 시간도 아낀다.\n면접에서는 '저는 팬아웃 부분이 가장 어렵다고 보는데 거기부터 볼까요?'처럼 본인 판단을 함께 제시하면 주도성이 드러난다.","cat":"interview","o":["곧바로 가장 어려운 부분의 상세 설계로 들어간다","전체 흐름을 30초로 요약해 되짚은 뒤 '어느 부분을 더 깊이 들어갈까요?'라고 면접관에게 물어 방향을 맞춘다","설계가 끝났다고 선언하고 질문을 기다린다","다른 대안 아키텍처를 처음부터 다시 그린다"],"a":1},{"t":"input","k":"설계 순서","q":"설계 면접의 표준 진행 순서에서 '요구사항 명확화' 다음에 오는 단계는? (한글 3~5자)","ex":"요구사항 → 규모 추정 → 개략 설계 → 상세 설계 → 병목·마무리가 표준 흐름이다. 추정 결과가 캐시 용량과 서버 수, 저장소 선택의 근거가 된다.\n면접에서는 추정을 건너뛰면 이후 선택의 근거가 사라지므로 짧게라도 반드시 하는 것이 좋다.","cat":"interview","a":["규모 추정","개략 추정","추정","용량 추정","규모추정"]}],"th":{"sum":"시스템 설계 면접은 정답을 맞히는 시험이 아니라, 모호한 요구를 좁혀 가며 설계를 함께 만들어 가는 대화다. 면접관은 당신이 어떤 순서로 생각하는지를 채점한다.","body":[{"h":"면접관이 보는 것","t":"면접관은 완성된 아키텍처 그림보다 '무엇을 먼저 물었는가'를 본다. 요구사항을 확정하지 않고 바로 컴포넌트를 그리기 시작하면 그 순간 감점이 시작된다. 범위를 스스로 좁히고, 가정을 소리 내어 말하고, 선택마다 대안을 언급하며 이유를 대는 사람이 높은 점수를 받는다. 또한 시간 배분을 관리하는지도 관찰 대상이라, 한 부분에 20분을 쓰고 전체 그림을 못 그리면 좋은 평가를 받기 어렵다."},{"h":"답변 구조","t":"45분 기준으로 요구사항 명확화 5~10분, 규모 추정 5분, 개략 설계 10~15분, 상세 설계 10~15분, 병목과 확장 5분으로 배분한다. 먼저 기능 요구사항 3~4개로 범위를 잘라내고, 비기능 요구사항(규모, 지연, 가용성, 일관성)을 숫자로 확정한다. 개략 설계에서는 클라이언트-API-저장소의 흐름과 핵심 API 시그니처, 데이터 모델까지만 그리고 멈춘 뒤 '어느 부분을 더 깊이 볼까요'라고 물어 면접관이 원하는 지점으로 들어간다. 마지막 5분은 단일 장애점과 확장 지점을 스스로 짚으며 마무리한다."}],"code":{"c":"0~7분   요구사항: 기능 3개로 범위 확정 + 규모·지연·일관성 숫자 확정\n7~12분  추정: DAU -> QPS, 저장량/년, 대역폭 (근사, 계산 과정을 말로)\n12~25분 개략: 클라이언트 - LB - API - 캐시 - DB/큐 + 핵심 API 3개 + 데이터 모델\n25~38분 상세: 면접관이 고른 한 부분 (샤딩 키, 팬아웃, 정합성 처리)\n38~45분 마무리: SPOF, 핫스팟, 모니터링, '시간이 더 있다면 볼 것'\n\n[말버릇] \"여기서는 A와 B가 있는데, 쓰기 폭증 때문에 B를 고르겠습니다. 대신 조회가 복잡해집니다.\"","cap":"설계 면접의 점수는 그림이 아니라 '고른 이유'와 '포기한 것'에서 나온다."},"key":["첫 5분에 요구사항을 좁히지 않으면 나머지 40분이 전부 흔들린다","가정은 반드시 소리 내어 말하고 칠판에 적는다 — 틀린 가정은 면접관이 고쳐 준다","모든 선택에는 '대신 무엇을 포기했는지'를 붙인다"]}},{"t":"상세 설계와 병목 마무리","q":[{"t":"choice","k":"깊이 파기","q":"면접관이 '피드 생성 부분을 더 자세히 보죠'라고 했을 때 좋은 전개는?","ex":"상세 설계는 대안 비교 → 데이터 근거 → 선택 → 구조 구체화의 흐름으로 가야 한다. 사례 나열이나 '캐시로 해결'은 판단을 보여 주지 못한다.\n면접에서는 '팔로워 1만 명 이상은 전체의 0.1%지만 팬아웃 비용의 대부분을 차지합니다'처럼 분포를 근거로 대면 강하다.","cat":"interview","o":["코드 수준의 함수 구현을 설명한다","다른 회사의 아키텍처 사례를 그대로 나열한다","피드는 캐시로 해결된다고 답하고 다음 주제로 넘어간다","팬아웃 방식 두 가지(쓰기 시 배포 vs 읽기 시 병합)를 비교하고, 팔로워 수 분포를 근거로 하이브리드를 제안한 뒤 저장 구조와 갱신 흐름을 구체화한다"],"a":3},{"t":"choice","k":"병목 지목","q":"설계 마무리 단계에서 스스로 짚어야 할 항목으로 가장 적절한 것은?","ex":"면접관이 묻기 전에 약점을 스스로 짚으면 설계를 객관적으로 보는 능력이 드러난다. '10배 성장하면 무엇이 먼저 깨지나'는 단골 마무리 질문이다.\n면접에서는 '지금 설계는 100배까지는 이 구조로 가고, 그 이상은 샤딩 키를 바꿔야 합니다'처럼 한계선을 말하면 좋다.","cat":"interview","o":["사용할 프레임워크 버전과 라이브러리 목록","단일 장애점, 트래픽 급증 시 가장 먼저 포화되는 지점, 핫 키·핫 샤드 가능성, 데이터가 10배로 늘었을 때 깨지는 부분","팀 구성과 개발 일정","코드 리뷰 정책"],"a":1},{"t":"choice","k":"시간 관리","q":"설계 면접에서 시간 관리 실패의 전형적인 모습은?","ex":"설계 면접은 넓이를 먼저 확보하고 깊이를 나중에 채우는 순서가 안전하다. 한 부분에 매몰되면 평가 항목 대부분을 보여 주지 못한 채 끝난다.\n면접에서는 스스로 '이 부분은 이 정도로 두고 전체를 먼저 완성하겠습니다'라고 선언하면 시간 관리 능력이 드러난다.","cat":"interview","o":["요구사항 질문을 세 개만 하고 넘어가는 것","초반 20분을 데이터베이스 스키마 세부에 쓰다가 전체 아키텍처와 확장 논의를 못 하고 끝나는 것","추정을 어림수로 빠르게 끝내는 것","면접관에게 다음에 볼 부분을 묻는 것"],"a":1},{"t":"choice","k":"지적 수용","q":"면접관이 '그 방식은 팔로워가 많으면 문제가 되지 않나요?'라고 지적했을 때 가장 좋은 반응은?","ex":"면접관의 지적은 대부분 힌트다. 방어는 협업 신호를 해치고, 통째로 버리면 일관성을 잃는다. 인정 → 원인 설명 → 수정이 최선이다.\n면접에서는 '좋은 지적입니다. 팔로워 수 임계값을 기준으로 두 경로를 나누겠습니다'처럼 즉시 설계에 반영하면 매우 좋다.","cat":"interview","o":["처음 설계를 끝까지 방어한다","지적을 인정하고 그 조건에서 왜 깨지는지 스스로 설명한 뒤 대안을 제시하고, 어떤 기준으로 두 방식을 나눌지 말한다","설계를 통째로 버리고 완전히 새로 시작한다","'그 경우는 요구사항에 없었습니다'라고 답한다"],"a":1},{"t":"choice","k":"모른다 대응","q":"설계 도중 잘 모르는 기술 세부(예: 특정 DB의 내부 압축 방식)를 질문받았을 때 가장 좋은 대응은?","ex":"설계 면접에서 중요한 것은 특정 제품 지식이 아니라 그 특성이 설계에 미치는 영향을 다룰 수 있는가다. 추측을 사실로 말하면 신뢰를 잃는다.\n면접에서는 '벤치마크로 확인하고 아니면 다른 저장소로 바꿀 수 있게 추상화해 두겠습니다'라고 하면 리스크 관리로 읽힌다.","cat":"interview","o":["다른 주제로 화제를 돌린다","아는 척하고 추측을 사실처럼 말한다","'그 세부는 정확히 모릅니다'라고 인정한 뒤, 설계 관점에서 그것이 어떤 영향을 주는지(저장 비용, 읽기 지연)와 어떻게 검증할지를 말한다","질문이 설계와 무관하다고 지적한다"],"a":2},{"t":"input","k":"마무리 질문","q":"설계 면접 마지막에 흔히 나오는 '지금 설계에서 절대 죽으면 안 되는데 이중화되지 않은 지점'을 가리키는 영문 약어는?","ex":"SPOF(단일 장애점)를 스스로 짚고 이중화 방안을 제시하는 것이 마무리의 정석이다.\n면접에서는 '지금은 이 조정 서비스가 SPOF라, 리더 선출로 다중화하겠습니다'처럼 구체적 지점과 해법을 함께 말하면 좋다.","cat":"interview","a":["SPOF","spof","single point of failure","단일 장애점"]}],"th":{"sum":"시스템 설계 면접은 정답을 맞히는 시험이 아니라, 모호한 요구를 좁혀 가며 설계를 함께 만들어 가는 대화다. 면접관은 당신이 어떤 순서로 생각하는지를 채점한다.","body":[{"h":"면접관이 보는 것","t":"면접관은 완성된 아키텍처 그림보다 '무엇을 먼저 물었는가'를 본다. 요구사항을 확정하지 않고 바로 컴포넌트를 그리기 시작하면 그 순간 감점이 시작된다. 범위를 스스로 좁히고, 가정을 소리 내어 말하고, 선택마다 대안을 언급하며 이유를 대는 사람이 높은 점수를 받는다. 또한 시간 배분을 관리하는지도 관찰 대상이라, 한 부분에 20분을 쓰고 전체 그림을 못 그리면 좋은 평가를 받기 어렵다."},{"h":"답변 구조","t":"45분 기준으로 요구사항 명확화 5~10분, 규모 추정 5분, 개략 설계 10~15분, 상세 설계 10~15분, 병목과 확장 5분으로 배분한다. 먼저 기능 요구사항 3~4개로 범위를 잘라내고, 비기능 요구사항(규모, 지연, 가용성, 일관성)을 숫자로 확정한다. 개략 설계에서는 클라이언트-API-저장소의 흐름과 핵심 API 시그니처, 데이터 모델까지만 그리고 멈춘 뒤 '어느 부분을 더 깊이 볼까요'라고 물어 면접관이 원하는 지점으로 들어간다. 마지막 5분은 단일 장애점과 확장 지점을 스스로 짚으며 마무리한다."}],"code":{"c":"0~7분   요구사항: 기능 3개로 범위 확정 + 규모·지연·일관성 숫자 확정\n7~12분  추정: DAU -> QPS, 저장량/년, 대역폭 (근사, 계산 과정을 말로)\n12~25분 개략: 클라이언트 - LB - API - 캐시 - DB/큐 + 핵심 API 3개 + 데이터 모델\n25~38분 상세: 면접관이 고른 한 부분 (샤딩 키, 팬아웃, 정합성 처리)\n38~45분 마무리: SPOF, 핫스팟, 모니터링, '시간이 더 있다면 볼 것'\n\n[말버릇] \"여기서는 A와 B가 있는데, 쓰기 폭증 때문에 B를 고르겠습니다. 대신 조회가 복잡해집니다.\"","cap":"설계 면접의 점수는 그림이 아니라 '고른 이유'와 '포기한 것'에서 나온다."},"key":["첫 5분에 요구사항을 좁히지 않으면 나머지 40분이 전부 흔들린다","가정은 반드시 소리 내어 말하고 칠판에 적는다 — 틀린 가정은 면접관이 고쳐 준다","모든 선택에는 '대신 무엇을 포기했는지'를 붙인다"]}}]},{"t":"설계 면접 — 규모 추정 질문 (QPS·저장량 계산)","l":[{"t":"QPS 계산 질문","q":[{"t":"input","k":"하루 초","q":"QPS 계산의 기준이 되는 하루의 총 초 수는? (숫자만, 쉼표 없이)","ex":"24 × 60 × 60 = 86,400초다. 암산에서는 약 10만 초로 어림해 자릿수를 빠르게 잡는다.\n면접에서는 '86,400을 10만으로 어림해 계산하고 마지막에 약 15% 정도 과소평가된다는 점을 감안하겠습니다'라고 말하면 근사의 방향까지 아는 사람으로 보인다.","cat":"interview","a":["86400","86,400","86400초"]},{"t":"choice","k":"평균 QPS","q":"DAU 1,000만 명이 하루 평균 20번 피드를 조회한다. 평균 읽기 QPS는 약 얼마인가?","ex":"1,000만 × 20 = 2억 요청/일이고 2억 ÷ 86,400 ≈ 2,314이므로 약 2,300 QPS다.\n면접에서는 '2,300 QPS면 애플리케이션 서버 몇 대와 캐시로 충분히 감당되는 규모라, 여기서부터 과한 분산 설계는 하지 않겠습니다'라고 결론을 붙이면 좋다.","cat":"interview","o":["약 230 QPS","약 2,300 QPS","약 23,000 QPS","약 230,000 QPS"],"a":1},{"t":"choice","k":"피크 QPS","q":"평균 2,300 QPS인 서비스의 피크를 산정할 때 설계 면접에서 통용되는 접근은?","ex":"용량은 평균이 아니라 피크로 잡아야 한다. 서비스 특성에 따라 다르지만 2~3배가 일반적인 출발점이며, 이벤트성 서비스라면 훨씬 커진다.\n면접에서는 '커머스 세일처럼 순간 스파이크가 큰 도메인이면 큐로 완충하고 대기열을 두겠습니다'라고 도메인 특성을 반영하면 좋다.","cat":"interview","o":["피크는 예측 불가능하므로 무한 확장만 가정한다","평균과 피크는 같다고 보고 2,300으로 설계한다","트래픽이 하루 중 특정 시간대에 몰리므로 평균의 2~3배인 약 5,000~7,000 QPS를 피크로 잡고 그 값으로 용량을 산정한다","평균의 100배인 230,000 QPS로 잡는다"],"a":2},{"t":"choice","k":"쓰기 QPS","q":"하루에 게시물 500만 건이 작성된다. 평균 쓰기 QPS는 약 얼마인가?","ex":"500만 ÷ 86,400 ≈ 57.9이므로 약 58 QPS다. 생각보다 작은 수치라는 점이 중요하다.\n면접에서는 '쓰기 58 QPS는 단일 마스터 DB로 충분하니 샤딩은 저장 용량 때문에 필요할 뿐 처리량 때문은 아닙니다'처럼 설계 판단으로 연결하면 매우 좋다.","cat":"interview","o":["약 5,800 QPS","약 5.8 QPS","약 58 QPS","약 580 QPS"],"a":2},{"t":"choice","k":"비율 해석","q":"읽기 2,300 QPS, 쓰기 58 QPS로 추정됐다. 이 비율이 설계에 주는 시사점으로 가장 적절한 것은?","ex":"추정의 목적은 자원을 어디에 쓸지 정하는 것이다. 읽기 우세면 캐시와 복제, 쓰기 우세면 큐와 샤딩이 우선이다.\n면접에서는 '캐시 히트율 90%면 DB로 가는 읽기는 230 QPS로 줄어듭니다'처럼 효과를 수치로 보여 주면 강하다.","cat":"interview","o":["쓰기가 병목이므로 쓰기 샤딩을 최우선으로 한다","비율은 설계와 무관하다","읽기와 쓰기가 비슷하므로 균형 있게 설계한다","읽기가 약 40배 많은 읽기 우세 시스템이므로 캐시 히트율과 읽기 복제본, 사전 계산된 응답에 자원을 집중하고 쓰기 경로는 단순하게 유지한다"],"a":3},{"t":"choice","k":"근사 원칙","q":"규모 추정에서 바람직한 계산 태도는?","ex":"설계 결정은 자릿수에서 갈린다. 100 QPS와 10만 QPS는 완전히 다른 시스템이지만 2,300과 2,500은 같은 설계다.\n면접에서는 '여기서는 10만 초로 어림했으니 실제 QPS는 계산값보다 약 15% 높습니다'라고 오차 방향을 언급하면 신뢰가 커진다.","cat":"interview","o":["10의 거듭제곱 단위로 어림해 자릿수를 맞추는 데 집중하고, 근사한 지점과 방향(과대·과소)을 말로 밝힌다","계산을 생략하고 경험적 직관으로 결론만 말한다","가장 큰 값을 가정해 항상 최악으로 잡는다","소수점까지 정확히 계산해 정밀도를 보여 준다"],"a":0}],"th":{"sum":"규모 추정은 정확한 값을 맞히는 문제가 아니라, 자릿수를 틀리지 않고 계산 과정을 소리 내어 말할 수 있는지를 보는 문제다. 추정 결과가 이후 설계 선택의 근거가 된다.","body":[{"h":"면접관이 보는 것","t":"면접관은 계산기가 아니라 감각을 본다. 초당 100건인지 10만 건인지가 캐시·샤딩·큐의 필요성을 통째로 바꾸기 때문에, 자릿수만 맞아도 대부분 통과한다. 계산을 머릿속으로만 하고 결과만 말하면 검증할 수 없으니 반드시 과정을 말해야 하고, 중간에 어림수로 바꾸는 근거도 밝혀야 한다. 추정을 하고도 설계에 연결하지 않으면 '왜 계산했나'라는 인상만 남으니, 항상 '따라서 단일 DB로는 부족합니다' 같은 결론으로 이어야 한다."},{"h":"답변 구조","t":"가정 → 단위 정리 → 계산 → 결론 순으로 말한다. 하루는 86,400초지만 계산 편의를 위해 10만 초로 어림한다고 먼저 선언하면 이후가 빨라진다. 트래픽은 DAU × 사용자당 행위 수로, 저장량은 건수 × 건당 크기 × 보관 기간으로, 대역폭은 QPS × 응답 크기로 일관되게 접근하면 어떤 문제도 같은 틀로 풀린다. 마지막에 피크 배수(평균의 2~3배)와 복제 배수(보통 3배)를 곱해 현실 값에 가깝게 만든 뒤 설계 결론을 붙인다."}],"code":{"c":"[가정] DAU 1,000만, 1인당 하루 조회 20회, 게시 0.5회, 응답 20KB, 레코드 200B\n\nQPS      = 1,000만 × 20 / 86,400초 ≈ 2억 / 86,400 ≈ 2,300 QPS\n피크 QPS  = 2,300 × 3 ≈ 7,000 QPS\n쓰기 QPS  = 1,000만 × 0.5 / 86,400 ≈ 500만 / 86,400 ≈ 58 QPS\n저장량/일 = 500만 × 200B = 10^9 B = 1GB/일 -> 5년 약 1.8TB (복제 3배면 5.5TB)\n대역폭    = 2,300 × 20KB ≈ 46MB/s ≈ 370Mbps\n\n[결론] 읽기 2,300 QPS는 캐시 + 읽기 복제본으로 충분, 쓰기 58 QPS는 단일 마스터로 가능","cap":"숫자보다 중요한 건 '그래서 무엇을 안 해도 되는가'라는 결론이다."},"key":["하루 = 86,400초 ≈ 10만 초로 어림한다 — 자릿수만 맞으면 된다","QPS = 일일 요청 ÷ 86,400, 피크는 평균의 2~3배로 잡는다","저장량 = 건수 × 건당 크기 × 기간 × 복제 수 — 복제와 인덱스를 빼먹지 않는다"]}},{"t":"저장량·대역폭 계산 질문","q":[{"t":"choice","k":"일일 저장량","q":"하루 5,000만 건의 이벤트가 쌓이고 한 건이 200바이트다. 하루 저장 증가량은 약 얼마인가?","ex":"5,000만 × 200B = 100억 바이트 = 10^10 B ≈ 10GB다.\n면접에서는 '인덱스와 메타데이터를 감안해 실제로는 1.3~2배 정도로 잡습니다'라고 현실 보정을 덧붙이면 좋다.","cat":"interview","o":["약 1GB","약 10GB","약 100GB","약 1TB"],"a":1},{"t":"choice","k":"5년 보관량","q":"하루 10GB씩 쌓이는 데이터를 5년간 보관한다면 총 저장량은 약 얼마인가?","ex":"10GB × 365 = 3,650GB ≈ 3.65TB/년이고 5년이면 약 18TB다.\n면접에서는 '3중 복제를 감안하면 약 55TB가 필요하고, 오래된 데이터는 콜드 스토리지로 계층화해 비용을 줄이겠습니다'까지 말하면 완성도가 높다.","cat":"interview","o":["약 18TB","약 180TB","약 1.8PB","약 1.8TB"],"a":0},{"t":"input","k":"사진 저장량","q":"하루에 사진 200만 장이 업로드되고 평균 크기가 500KB다. 하루에 필요한 저장 용량은 약 몇 TB인가? (숫자만, 1TB = 10^12 바이트로 계산)","ex":"200만 × 500KB = 2×10^6 × 5×10^5 B = 10^12 B = 1TB다.\n면접에서는 '썸네일 등 파생 이미지가 원본의 20~30%를 더하고 3중 복제까지 하면 실제로는 하루 4TB에 가깝습니다'라고 현실 요소를 더하면 좋다.","cat":"interview","a":["1","1TB","약 1","1 TB"]},{"t":"choice","k":"대역폭 계산","q":"5,000 QPS로 평균 20KB의 응답을 내보낸다. 필요한 아웃바운드 대역폭은 약 얼마인가?","ex":"5,000 × 20KB = 100,000KB/s = 약 100MB/s이고, 바이트를 비트로 바꾸면 약 800Mbps다.\n면접에서는 '1Gbps 회선 한 개에 근접하므로 정적 리소스는 CDN으로 빼서 오리진 대역폭을 줄이겠습니다'라고 대응까지 말하면 좋다.","cat":"interview","o":["약 100KB/s","약 10MB/s","약 100MB/s (약 800Mbps)","약 1GB/s"],"a":2},{"t":"choice","k":"캐시 용량","q":"하루 고유 조회 키가 2,000만 개이고 값 하나가 평균 2KB다. 상위 20%만 캐시한다면 필요한 캐시 메모리는 약 얼마인가?","ex":"2,000만 × 20% = 400만 개, 400만 × 2KB = 8×10^9 B ≈ 8GB다. 전부 캐시하면 40GB가 필요하다.\n면접에서는 '80/20 법칙을 근거로 상위 20%만 담아 메모리를 5분의 1로 줄였고, 실제 히트율은 도입 후 측정해 조정하겠습니다'라고 말하면 좋다.","cat":"interview","o":["약 40GB","약 400GB","약 800MB","약 8GB"],"a":3},{"t":"choice","k":"복제 배수","q":"저장량 추정에서 자주 빠뜨리는 요소로 가장 중요한 것은?","ex":"실제 인프라에서는 원본 1TB가 복제 3배와 인덱스, 백업까지 더해 4~6TB로 불어난다.\n면접에서는 '원본 18TB에 3중 복제와 인덱스 30%를 더해 약 70TB로 계획하겠습니다'처럼 배수를 명시하면 실무 감각이 드러난다.","cat":"interview","o":["복제본 수(보통 3배), 인덱스 오버헤드, 백업 보관본 — 원본 데이터 크기만 계산하면 실제 필요량을 크게 과소평가한다","네트워크 지연","CPU 코어 수","로그 파일 크기"],"a":0}],"th":{"sum":"규모 추정은 정확한 값을 맞히는 문제가 아니라, 자릿수를 틀리지 않고 계산 과정을 소리 내어 말할 수 있는지를 보는 문제다. 추정 결과가 이후 설계 선택의 근거가 된다.","body":[{"h":"면접관이 보는 것","t":"면접관은 계산기가 아니라 감각을 본다. 초당 100건인지 10만 건인지가 캐시·샤딩·큐의 필요성을 통째로 바꾸기 때문에, 자릿수만 맞아도 대부분 통과한다. 계산을 머릿속으로만 하고 결과만 말하면 검증할 수 없으니 반드시 과정을 말해야 하고, 중간에 어림수로 바꾸는 근거도 밝혀야 한다. 추정을 하고도 설계에 연결하지 않으면 '왜 계산했나'라는 인상만 남으니, 항상 '따라서 단일 DB로는 부족합니다' 같은 결론으로 이어야 한다."},{"h":"답변 구조","t":"가정 → 단위 정리 → 계산 → 결론 순으로 말한다. 하루는 86,400초지만 계산 편의를 위해 10만 초로 어림한다고 먼저 선언하면 이후가 빨라진다. 트래픽은 DAU × 사용자당 행위 수로, 저장량은 건수 × 건당 크기 × 보관 기간으로, 대역폭은 QPS × 응답 크기로 일관되게 접근하면 어떤 문제도 같은 틀로 풀린다. 마지막에 피크 배수(평균의 2~3배)와 복제 배수(보통 3배)를 곱해 현실 값에 가깝게 만든 뒤 설계 결론을 붙인다."}],"code":{"c":"[가정] DAU 1,000만, 1인당 하루 조회 20회, 게시 0.5회, 응답 20KB, 레코드 200B\n\nQPS      = 1,000만 × 20 / 86,400초 ≈ 2억 / 86,400 ≈ 2,300 QPS\n피크 QPS  = 2,300 × 3 ≈ 7,000 QPS\n쓰기 QPS  = 1,000만 × 0.5 / 86,400 ≈ 500만 / 86,400 ≈ 58 QPS\n저장량/일 = 500만 × 200B = 10^9 B = 1GB/일 -> 5년 약 1.8TB (복제 3배면 5.5TB)\n대역폭    = 2,300 × 20KB ≈ 46MB/s ≈ 370Mbps\n\n[결론] 읽기 2,300 QPS는 캐시 + 읽기 복제본으로 충분, 쓰기 58 QPS는 단일 마스터로 가능","cap":"숫자보다 중요한 건 '그래서 무엇을 안 해도 되는가'라는 결론이다."},"key":["하루 = 86,400초 ≈ 10만 초로 어림한다 — 자릿수만 맞으면 된다","QPS = 일일 요청 ÷ 86,400, 피크는 평균의 2~3배로 잡는다","저장량 = 건수 × 건당 크기 × 기간 × 복제 수 — 복제와 인덱스를 빼먹지 않는다"]}},{"t":"서버 산정·지연 감각 질문","q":[{"t":"choice","k":"서버 대수","q":"피크 7,000 QPS를 처리해야 하고 서버 한 대가 안정적으로 500 QPS를 감당한다. 필요한 서버 대수 산정으로 가장 적절한 것은?","ex":"14대는 여유가 0인 값이라 한 대만 죽어도 포화된다. 배포 중 롤링 교체와 AZ 장애까지 감안해 20~30% 여유를 둔다.\n면접에서는 '한 AZ가 통째로 빠져도 견디도록 3개 AZ에 분산하겠습니다'라고 가용성까지 연결하면 좋다.","cat":"interview","o":["1대로 충분하며 수직 확장만 하면 된다","7,000 ÷ 500 = 14대를 그대로 배치한다","14대가 최소값이므로 장애 여유와 배포 중 용량 감소를 감안해 약 18~20대로 잡고, 오토스케일링 하한을 그 근처로 둔다","500대가 필요하다"],"a":2},{"t":"input","k":"동시 처리 수","q":"목표 처리량이 1,000 QPS이고 요청 하나의 평균 처리 시간이 200ms일 때, 리틀의 법칙으로 계산한 동시 처리 요청 수는? (숫자만)","ex":"동시 처리 수 = 처리량 × 응답 시간 = 1,000 × 0.2초 = 200이다. 스레드 풀이나 워커 수 산정의 기본식이다.\n면접에서는 '응답 시간이 400ms로 나빠지면 같은 처리량에 400개가 필요해져, 지연 악화가 자원 고갈로 이어진다는 점이 중요합니다'라고 연결하면 좋다.","cat":"interview","a":["200","200개","200건"]},{"t":"choice","k":"지연 감각","q":"설계 면접에서 흔히 쓰는 대략적인 지연 수치로 옳게 짝지어진 것은?","ex":"메모리는 나노초, SSD는 마이크로초, 같은 DC 네트워크는 밀리초 미만, 대륙 간은 100ms 이상이라는 자릿수 감각이 핵심이다.\n면접에서는 '대륙 간 왕복이 150ms이므로 사용자 근처에 엣지 캐시를 두는 것이 지연 개선의 가장 큰 지렛대입니다'라고 결론을 끌어내면 좋다.","cat":"interview","o":["메모리 접근 약 100ns, SSD 랜덤 읽기 약 100µs, 같은 데이터센터 내 왕복 약 0.5ms, 대륙 간 왕복 약 100~150ms","메모리 접근 약 1ms, SSD 읽기 약 10ms, 같은 데이터센터 내 왕복 약 100ms","메모리 접근 약 1µs, SSD 읽기 약 1ns, 대륙 간 왕복 약 1ms","모든 접근이 대략 1ms 수준으로 비슷하다"],"a":0},{"t":"choice","k":"추정의 목적","q":"규모 추정을 마친 뒤 반드시 해야 할 일은?","ex":"추정이 설계로 이어지지 않으면 시간 낭비다. 각 숫자마다 '그래서 무엇을 하고 무엇을 안 해도 되는가'가 따라와야 한다.\n면접에서는 '이 규모에서는 마이크로서비스나 글로벌 분산이 필요 없다'는 결론도 훌륭한 답변이 된다.","cat":"interview","o":["계산 결과를 칠판에 적어 두고 다음 단계로 넘어간다","추정치를 설계 결정으로 연결한다 — 예: '쓰기 58 QPS이므로 단일 마스터로 충분', '저장 70TB이므로 샤딩 필요', '대역폭 800Mbps이므로 CDN 필요'","더 정확한 수치를 얻기 위해 재계산한다","추정치는 참고용이므로 잊고 설계를 진행한다"],"a":1},{"t":"choice","k":"과대 설계 경계","q":"추정 결과 읽기 300 QPS, 저장량 500GB로 나왔다. 이때 좋은 설계 판단은?","ex":"규모에 맞지 않는 복잡도는 그 자체가 장애 요인이다. 다만 '언제 다음 단계로 갈지' 기준을 정해 두는 것이 성숙한 태도다.\n면접에서는 'DB CPU 60%나 저장량 2TB를 넘으면 샤딩을 검토하겠습니다'처럼 트리거를 제시하면 매우 좋은 인상을 준다.","cat":"interview","o":["NoSQL로 바꿔 미래 확장에 대비한다","대규모 시스템처럼 샤딩, 다중 리전, 이벤트 소싱을 모두 적용한다","단일 관계형 DB와 읽기 복제본, 캐시 한 겹으로 충분하다고 판단하고 운영 단순성을 우선하며, 어느 지표를 넘으면 다음 단계로 갈지 기준만 정해 둔다","규모가 작으므로 캐시나 모니터링은 생략한다"],"a":2},{"t":"choice","k":"추정 실수","q":"규모 추정 중 계산이 꼬여 자릿수가 이상해졌을 때 가장 좋은 대응은?","ex":"추정에서 흔한 실수는 KB/MB/GB 혼동과 일/초 혼동이다. 알아채고 스스로 교정하는 모습은 오히려 신뢰를 준다.\n면접에서는 '단위를 먼저 통일하고 가겠습니다'라고 습관처럼 말하면 실수 자체가 줄어든다.","cat":"interview","o":["면접관에게 답을 알려 달라고 한다","그대로 진행하고 결과만 그럴듯하게 맞춘다","'단위가 꼬인 것 같습니다'라고 말하고 바이트·초·건수 단위를 다시 정리해 처음부터 다시 계산한다","계산을 포기하고 감으로 결론을 낸다"],"a":2}],"th":{"sum":"규모 추정은 정확한 값을 맞히는 문제가 아니라, 자릿수를 틀리지 않고 계산 과정을 소리 내어 말할 수 있는지를 보는 문제다. 추정 결과가 이후 설계 선택의 근거가 된다.","body":[{"h":"면접관이 보는 것","t":"면접관은 계산기가 아니라 감각을 본다. 초당 100건인지 10만 건인지가 캐시·샤딩·큐의 필요성을 통째로 바꾸기 때문에, 자릿수만 맞아도 대부분 통과한다. 계산을 머릿속으로만 하고 결과만 말하면 검증할 수 없으니 반드시 과정을 말해야 하고, 중간에 어림수로 바꾸는 근거도 밝혀야 한다. 추정을 하고도 설계에 연결하지 않으면 '왜 계산했나'라는 인상만 남으니, 항상 '따라서 단일 DB로는 부족합니다' 같은 결론으로 이어야 한다."},{"h":"답변 구조","t":"가정 → 단위 정리 → 계산 → 결론 순으로 말한다. 하루는 86,400초지만 계산 편의를 위해 10만 초로 어림한다고 먼저 선언하면 이후가 빨라진다. 트래픽은 DAU × 사용자당 행위 수로, 저장량은 건수 × 건당 크기 × 보관 기간으로, 대역폭은 QPS × 응답 크기로 일관되게 접근하면 어떤 문제도 같은 틀로 풀린다. 마지막에 피크 배수(평균의 2~3배)와 복제 배수(보통 3배)를 곱해 현실 값에 가깝게 만든 뒤 설계 결론을 붙인다."}],"code":{"c":"[가정] DAU 1,000만, 1인당 하루 조회 20회, 게시 0.5회, 응답 20KB, 레코드 200B\n\nQPS      = 1,000만 × 20 / 86,400초 ≈ 2억 / 86,400 ≈ 2,300 QPS\n피크 QPS  = 2,300 × 3 ≈ 7,000 QPS\n쓰기 QPS  = 1,000만 × 0.5 / 86,400 ≈ 500만 / 86,400 ≈ 58 QPS\n저장량/일 = 500만 × 200B = 10^9 B = 1GB/일 -> 5년 약 1.8TB (복제 3배면 5.5TB)\n대역폭    = 2,300 × 20KB ≈ 46MB/s ≈ 370Mbps\n\n[결론] 읽기 2,300 QPS는 캐시 + 읽기 복제본으로 충분, 쓰기 58 QPS는 단일 마스터로 가능","cap":"숫자보다 중요한 건 '그래서 무엇을 안 해도 되는가'라는 결론이다."},"key":["하루 = 86,400초 ≈ 10만 초로 어림한다 — 자릿수만 맞으면 된다","QPS = 일일 요청 ÷ 86,400, 피크는 평균의 2~3배로 잡는다","저장량 = 건수 × 건당 크기 × 기간 × 복제 수 — 복제와 인덱스를 빼먹지 않는다"]}}]},{"t":"설계 면접 — 대표 문제의 핵심 결정 (단축 URL·피드·채팅·알림)","l":[{"t":"단축 URL 설계 질문","q":[{"t":"choice","k":"키 생성","q":"'단축 URL의 7자 코드를 어떻게 만드시겠어요?'라는 질문에 가장 견고한 답변은?","ex":"해시 앞자리 절단은 충돌이 발생하고, 랜덤 재시도는 공간이 차면 충돌률이 급증한다. 순차 10진수는 짧지 않고 전량 열거가 쉬워진다.\n면접에서는 '순차 ID의 예측 가능성이 문제라면 ID를 뒤섞거나 난수 코드와 병행하겠습니다'라고 보완책을 붙이면 좋다.","cat":"interview","o":["랜덤 문자열을 만들고 충돌하면 계속 재시도한다","입력 순서대로 1씩 증가하는 10진수를 그대로 쓴다","원본 URL을 MD5 해시해 앞 7자를 쓴다","전역 유일 ID(분산 ID 생성기나 사전 할당된 카운터 범위)를 발급받아 base62로 인코딩한다. 충돌이 구조적으로 발생하지 않고 길이도 예측 가능하다"],"a":3},{"t":"input","k":"키 공간","q":"62개 문자(0-9, a-z, A-Z)로 7자리 코드를 만들 때 표현 가능한 경우의 수는 62의 몇 제곱인가? (숫자만)","ex":"62^7 ≈ 3.5조 개로, 하루 1,000만 개씩 만들어도 수백 년을 쓸 수 있는 공간이다.\n면접에서는 '필요 개수를 먼저 추정하고 그에 맞는 자릿수를 고르는 순서로 설명하겠습니다'라고 말하면 계산 근거가 명확해진다.","cat":"interview","a":["7","7제곱","62^7"]},{"t":"choice","k":"읽기 우세","q":"단축 URL 서비스의 리다이렉트 지연을 최소화하는 핵심 설계는?","ex":"불변에 가까운 데이터에 읽기가 몰리는 전형적 캐시 적합 사례다. 리다이렉트는 응답 자체가 작아 지연의 대부분이 조회 시간이다.\n면접에서는 '읽기:쓰기가 100:1이라면 캐시 히트율 95%만 확보해도 DB 부하가 20분의 1로 줄어듭니다'라고 수치로 말하면 좋다.","cat":"interview","o":["코드에서 원본 URL로 가는 매핑은 변경이 거의 없고 읽기가 압도적이므로 캐시를 앞에 두고 캐시 우선 조회하며, 인기 키는 CDN/엣지까지 밀어낸다","리다이렉트 요청을 큐에 넣어 비동기로 처리한다","쓰기 마스터를 늘려 처리량을 확보한다","매 요청마다 원본 DB에서 조회한다"],"a":0},{"t":"choice","k":"301 vs 302","q":"리다이렉트에 301과 302 중 무엇을 쓸지 묻는 꼬리 질문에 좋은 답변은?","ex":"선택 기준은 캐시 여부와 분석 필요성의 교환이다. 요구사항에 클릭 통계가 있으면 302, 순수 성능이 목적이면 301이 낫다.\n면접에서는 '만료나 대상 변경 가능성이 있는 링크라면 301 캐시가 오히려 위험합니다'라고 부작용을 짚으면 좋다.","cat":"interview","o":["301이 항상 옳다. 표준이 그렇게 정하고 있기 때문이다","302는 SEO에 유리하므로 무조건 302를 쓴다","둘의 차이는 없고 상태 코드만 다르다","301은 영구 이동이라 브라우저와 중간 캐시가 결과를 캐시해 서버 부하가 크게 줄지만 이후 클릭을 집계할 수 없고, 302는 매번 서버를 거쳐 분석은 가능하지만 부하가 커진다. 클릭 분석이 제품 가치라면 302를 택하겠다"],"a":3},{"t":"choice","k":"저장소 선택","q":"단축 URL 매핑 저장소로 무엇을 쓸지 묻는 질문에 좋은 답변은?","ex":"접근 패턴이 단건 키 조회뿐이면 저장소 선택의 자유도가 높고, 샤딩도 코드 기반 해시로 쉽게 된다. 캐시만 쓰면 영속성이 없어 데이터가 유실된다.\n면접에서는 '키 조회만 필요한 단순 패턴이라 오히려 운영 익숙도로 고르겠습니다'라고 실용적 기준을 대면 좋다.","cat":"interview","o":["그래프 DB가 링크 구조에 가장 적합하다","모든 데이터를 캐시에만 저장하면 DB가 필요 없다","접근 패턴이 코드로 단건 조회하는 키-값 조회뿐이므로 키-값 저장소나 단순한 관계형 테이블 모두 가능하며, 규모가 커지면 코드 해시 기반 샤딩으로 수평 확장하겠다고 답한다","조인이 필요하니 반드시 관계형 DB여야 한다"],"a":2},{"t":"choice","k":"부가 요구","q":"단축 URL 설계에서 면접관이 자주 던지는 확장 요구와 대응으로 옳게 짝지어진 것은?","ex":"만료는 TTL과 정리 배치로 처리하는 것이 정석이다. 커스텀 별칭은 유일성 검사가 반드시 필요하고, 클릭 통계는 동기 카운트 대신 이벤트를 큐로 흘려 집계해야 리다이렉트 지연을 지키며, 악성 링크는 사전 검사 목록과 자동 스캔이 필요하다.\n면접에서는 '통계는 정확성보다 지연이 중요해 비동기 집계로 근사치를 씁니다'라고 우선순위를 밝히면 좋다.","cat":"interview","o":["클릭 통계 요구 - 조회 요청마다 동기적으로 DB에 카운트를 올린다","악성 링크 차단 요구 - 사용자 신고만으로 충분하다","만료 링크 요구 - TTL 필드를 두고 조회 시 검증하며 만료 데이터는 배치로 정리한다","커스텀 별칭 요구 - 충돌 검사가 불필요하다"],"a":2}],"th":{"sum":"설계 면접의 단골 문제들은 각각 '반드시 답해야 하는 한두 개의 핵심 결정'을 품고 있다. 그 결정을 알고 들어가면 45분을 주도할 수 있다.","body":[{"h":"면접관이 보는 것","t":"면접관은 문제마다 확인하고 싶은 포인트가 정해져 있다. 단축 URL은 키 생성과 읽기 우세 처리, 뉴스피드는 팬아웃 전략, 채팅은 연결 유지와 메시지 순서, 알림은 대량 발송과 중복 방지다. 이 지점을 스스로 짚어 내면 '준비된 사람'으로 보이고, 반대로 로드밸런서와 캐시만 그리다 끝나면 어떤 문제를 풀어도 같은 답을 하는 사람으로 보인다. 외운 아키텍처를 그대로 옮기는 것이 아니라, 그 선택이 왜 이 요구사항에서 타당한지 설명해야 점수가 된다."},{"h":"답변 구조","t":"문제마다 핵심 결정을 먼저 선언하고 시작한다. '이 문제의 핵심은 팔로워 수 분포에 따른 팬아웃 전략이라고 봅니다'라고 말한 뒤 대안을 비교하고 하나를 고르면 대화의 주도권이 생긴다. 그다음 데이터 모델과 저장소를 결정에 맞춰 붙이고, 마지막으로 극단 사례(팔로워 수천만, 그룹 채팅 1만 명, 알림 동시 발송 1,000만 건)를 스스로 꺼내 어떻게 버틸지 말한다. 극단 사례를 먼저 꺼내는 것만으로도 시니어 신호가 된다."}],"code":{"c":"[단축 URL] 핵심 = 짧고 충돌 없는 키 + 읽기 우세\n  -> 유일 ID를 base62 인코딩(7자 = 62^7 ≈ 3.5조), 매핑은 캐시 우선 조회\n\n[뉴스피드] 핵심 = 팬아웃 전략\n  -> 일반 사용자는 쓰기 시 배포(푸시), 유명인은 읽기 시 병합(풀) = 하이브리드\n\n[채팅] 핵심 = 연결 유지 + 메시지 순서/유실\n  -> WebSocket + 접속 서버 레지스트리, 서버가 부여한 시퀀스로 순서, 클라이언트 메시지 ID로 중복 제거\n\n[알림] 핵심 = 대량 발송 + 중복/재시도\n  -> 큐 기반 워커 + 채널별 어댑터(FCM/APNs/SMS) + 멱등 키 + DLQ","cap":"문제별 '핵심 결정'을 한 줄로 선언하고 들어가면 45분이 정리된다."},"key":["단축 URL의 승부처는 키 생성 방식과 리다이렉트 캐싱이다","피드의 승부처는 팬아웃이며, 유명인 때문에 하이브리드가 필요하다","채팅·알림의 승부처는 유실과 중복 — 순서와 멱등성을 어떻게 보장하는지 말한다"]}},{"t":"뉴스피드 설계 질문","q":[{"t":"choice","k":"팬아웃 선택","q":"'뉴스피드를 어떻게 만드시겠어요?'라는 질문에서 핵심 결정으로 먼저 꺼내야 할 것은?","ex":"피드 문제의 채점 포인트는 팬아웃이다. 읽기를 빠르게 할지, 쓰기를 싸게 할지의 교환을 먼저 정해야 나머지 설계가 따라온다.\n면접에서는 '읽기가 40배 많다고 하셨으니 기본은 쓰기 시 배포로 가겠습니다'처럼 추정치와 연결하면 좋다.","cat":"interview","o":["이미지 저장소를 무엇으로 할지","댓글 정렬 방식을 어떻게 할지","어떤 프레임워크로 API를 만들지","게시 시점에 팔로워 피드에 미리 배포할지(팬아웃 온 라이트), 조회 시점에 팔로우 대상 글을 병합할지(팬아웃 온 리드)의 선택과 그 근거"],"a":3},{"t":"choice","k":"유명인 문제","q":"팔로워 3,000만 명인 계정이 글을 올릴 때 팬아웃 온 라이트가 문제가 되는 이유와 대응은?","ex":"팬아웃 폭풍은 피드 설계의 대표적 함정이다. 임계값 기반 하이브리드가 업계 표준 해법이며, 임계값 자체를 데이터로 정한다고 말하면 더 좋다.\n면접에서는 '읽기 시 병합 대상은 보통 수십 개 계정이라 조회 비용이 감당 가능합니다'라고 근거를 대면 설득력이 있다.","cat":"interview","o":["유명인 계정의 게시를 제한한다","유명인 글은 캐시하지 않으면 해결된다","글 1건이 3,000만 건의 쓰기로 폭증해 지연과 비용이 급증한다. 임계값 이상 팔로워를 가진 계정의 글은 읽기 시 병합하는 방식으로 처리하는 하이브리드를 쓴다","문제 없다. 배치로 처리하면 순식간에 끝난다"],"a":2},{"t":"choice","k":"피드 저장","q":"사용자별로 미리 계산된 타임라인을 저장할 저장소 요구사항으로 가장 적절한 것은?","ex":"타임라인은 최근 N건만 유지하면 되는 append-and-trim 구조라, 전체를 무한히 보관할 필요가 없다. 대개 최근 수백 건만 캐시하고 그 이전은 요청 시 조회한다.\n면접에서는 '비활성 사용자에게는 미리 배포하지 않아 저장 낭비를 줄이겠습니다'라고 최적화를 덧붙이면 좋다.","cat":"interview","o":["복잡한 조인과 트랜잭션이 필요하다","사용자 키로 최근 N건을 시간 역순으로 빠르게 읽고 앞쪽에 빠르게 삽입할 수 있어야 하며, 오래된 항목은 잘라낼 수 있어야 한다(캐시나 와이드 컬럼 저장소의 리스트 구조가 적합)","전문 검색 기능이 가장 중요하다","강한 일관성이 반드시 필요하다"],"a":1},{"t":"choice","k":"일관성 수준","q":"피드 반영 일관성에 대해 답할 때 가장 적절한 태도는?","ex":"피드는 최종 일관성으로 충분한 대표적 영역이지만, 본인 글이 안 보이면 버그로 인식되므로 read-your-writes만 별도로 보장한다.\n면접에서는 '자기 글은 클라이언트에서 낙관적으로 먼저 그려 주는 방법도 있습니다'라고 대안을 말하면 좋다.","cat":"interview","o":["몇 초에서 수십 초의 지연이 허용되는 최종 일관성으로 충분하다고 요구사항 단계에서 합의하고, 대신 본인이 올린 글은 자기 피드에서 즉시 보이게 처리한다","일관성은 피드 설계와 무관하다","지연이 발생하면 사용자에게 오류를 표시한다","모든 팔로워에게 즉시 동시에 보여야 하므로 강한 일관성이 필요하다"],"a":0},{"t":"input","k":"팬아웃 용어","q":"게시 시점에 모든 팔로워의 피드에 글을 미리 배포해 두는 방식을 '팬아웃 온 ___'라고 한다. 빈칸에 들어갈 영단어는?","ex":"쓰기 시 배포(push)는 읽기를 빠르게 하지만 쓰기 증폭이 크고, 읽기 시 병합(pull, fan-out on read)은 그 반대다.\n면접에서는 두 방식의 이름과 비용 방향을 한 문장으로 정리해 두면 답변이 빨라진다.","cat":"interview","a":["write","라이트","쓰기","fan-out on write"]},{"t":"choice","k":"랭킹 확장","q":"'시간 역순이 아니라 관심도 기반 랭킹 피드로 바꿔 달라'는 요구가 추가됐다. 설계상 가장 큰 변화는?","ex":"랭킹이 들어오면 '미리 계산된 순서'라는 전제가 깨져 후보 생성과 랭킹을 분리하는 구조가 표준이 된다.\n면접에서는 '랭킹 점수를 짧은 TTL로 캐시하고, 신규 항목만 실시간 계산하는 절충안을 쓰겠습니다'라고 하면 좋다.","cat":"interview","o":["저장소만 바꾸면 되고 나머지는 동일하다","순서가 사용자·시점마다 달라져 단순 미리 배포로 끝나지 않는다. 후보군을 팬아웃으로 모으고 조회 시점에 점수를 매겨 정렬하는 2단계(후보 생성 - 랭킹) 구조로 가야 하며, 점수 계산 비용과 캐싱 전략이 새 병목이 된다","랭킹은 클라이언트에서 정렬하면 되므로 서버 변경이 없다","랭킹을 넣으면 팬아웃이 필요 없어진다"],"a":1}],"th":{"sum":"설계 면접의 단골 문제들은 각각 '반드시 답해야 하는 한두 개의 핵심 결정'을 품고 있다. 그 결정을 알고 들어가면 45분을 주도할 수 있다.","body":[{"h":"면접관이 보는 것","t":"면접관은 문제마다 확인하고 싶은 포인트가 정해져 있다. 단축 URL은 키 생성과 읽기 우세 처리, 뉴스피드는 팬아웃 전략, 채팅은 연결 유지와 메시지 순서, 알림은 대량 발송과 중복 방지다. 이 지점을 스스로 짚어 내면 '준비된 사람'으로 보이고, 반대로 로드밸런서와 캐시만 그리다 끝나면 어떤 문제를 풀어도 같은 답을 하는 사람으로 보인다. 외운 아키텍처를 그대로 옮기는 것이 아니라, 그 선택이 왜 이 요구사항에서 타당한지 설명해야 점수가 된다."},{"h":"답변 구조","t":"문제마다 핵심 결정을 먼저 선언하고 시작한다. '이 문제의 핵심은 팔로워 수 분포에 따른 팬아웃 전략이라고 봅니다'라고 말한 뒤 대안을 비교하고 하나를 고르면 대화의 주도권이 생긴다. 그다음 데이터 모델과 저장소를 결정에 맞춰 붙이고, 마지막으로 극단 사례(팔로워 수천만, 그룹 채팅 1만 명, 알림 동시 발송 1,000만 건)를 스스로 꺼내 어떻게 버틸지 말한다. 극단 사례를 먼저 꺼내는 것만으로도 시니어 신호가 된다."}],"code":{"c":"[단축 URL] 핵심 = 짧고 충돌 없는 키 + 읽기 우세\n  -> 유일 ID를 base62 인코딩(7자 = 62^7 ≈ 3.5조), 매핑은 캐시 우선 조회\n\n[뉴스피드] 핵심 = 팬아웃 전략\n  -> 일반 사용자는 쓰기 시 배포(푸시), 유명인은 읽기 시 병합(풀) = 하이브리드\n\n[채팅] 핵심 = 연결 유지 + 메시지 순서/유실\n  -> WebSocket + 접속 서버 레지스트리, 서버가 부여한 시퀀스로 순서, 클라이언트 메시지 ID로 중복 제거\n\n[알림] 핵심 = 대량 발송 + 중복/재시도\n  -> 큐 기반 워커 + 채널별 어댑터(FCM/APNs/SMS) + 멱등 키 + DLQ","cap":"문제별 '핵심 결정'을 한 줄로 선언하고 들어가면 45분이 정리된다."},"key":["단축 URL의 승부처는 키 생성 방식과 리다이렉트 캐싱이다","피드의 승부처는 팬아웃이며, 유명인 때문에 하이브리드가 필요하다","채팅·알림의 승부처는 유실과 중복 — 순서와 멱등성을 어떻게 보장하는지 말한다"]}},{"t":"채팅·알림 설계 질문","q":[{"t":"choice","k":"연결 방식","q":"실시간 채팅에서 전송 방식을 묻는 질문에 좋은 답변은?","ex":"선택지를 비교하고 폴백까지 말하는 답이 좋다. 폴링은 지연과 낭비가 크고, 방화벽 환경에서는 WebSocket이 막힐 수 있어 폴백 설계가 실무적이다.\n면접에서는 '연결 유지 비용 때문에 접속 서버는 상태를 가지므로 확장 방식이 달라집니다'라고 다음 논점을 스스로 열면 좋다.","cat":"interview","o":["양방향 실시간성이 필요하므로 WebSocket을 기본으로 하고, 서버에서 클라이언트로의 단방향 전송만 필요하면 SSE, 환경 제약이 있으면 롱 폴링으로 폴백하는 순서로 설명한다","메시지마다 새 HTTP 요청을 만드는 방식이 확장에 유리하다","채팅은 반드시 UDP 기반 커스텀 프로토콜이 필요하다","짧은 주기의 폴링이 가장 단순하므로 최선이다"],"a":0},{"t":"choice","k":"접속 라우팅","q":"A가 보낸 메시지를 다른 서버에 접속해 있는 B에게 전달하려면 무엇이 필요한가?","ex":"연결이 특정 서버에 묶이는 상태 저장 구조라 라우팅 정보가 필수다. 레지스트리는 TTL과 하트비트로 유지하고, 서버 장애 시 정리되어야 한다.\n면접에서는 '접속 서버가 죽으면 클라이언트가 재연결하고 레지스트리가 갱신되는 흐름까지 설계했습니다'라고 이어 가면 좋다.","cat":"interview","o":["클라이언트끼리 직접 연결(P2P)하게 한다","모든 서버가 모든 사용자와 연결을 유지한다","어떤 사용자가 어느 접속 서버에 붙어 있는지 기록하는 세션 레지스트리(예: Redis)를 두고, 메시지를 해당 서버로 라우팅하거나 서버 간 발행-구독 채널로 전달한다","메시지를 DB에 저장만 하고 B가 폴링하도록 한다"],"a":2},{"t":"choice","k":"순서와 중복","q":"채팅 메시지의 순서와 중복 문제에 대한 좋은 답변은?","ex":"기기 시계는 서로 어긋나므로 정렬 기준이 될 수 없고, TCP는 한 연결 안의 순서만 보장할 뿐 서버 여러 대와 재전송이 얽힌 순서는 보장하지 못한다.\n면접에서는 '클라이언트 메시지 ID를 유일 키로 저장해 네트워크 재시도 시 중복 저장을 막았습니다'라고 구현을 말하면 좋다.","cat":"interview","o":["TCP를 쓰면 순서와 중복이 모두 해결된다","클라이언트 기기의 타임스탬프로 정렬하면 충분하다","대화방 단위로 서버가 단조 증가하는 시퀀스나 정렬 가능한 ID를 부여해 순서를 정하고, 클라이언트가 만든 메시지 ID로 재전송 중복을 제거한다","메시지는 도착 순서대로 보여 주면 되므로 별도 처리가 필요 없다"],"a":2},{"t":"choice","k":"오프라인 전달","q":"수신자가 오프라인일 때 메시지 처리로 가장 적절한 설계는?","ex":"'저장 후 전달'이 원칙이고, 재접속 시에는 마지막 시퀀스 기준 증분 동기화가 표준이다. 메모리 보관은 서버 재시작에 유실된다.\n면접에서는 '읽음 표시도 같은 시퀀스 개념으로 처리하면 일관되게 설계됩니다'라고 확장하면 좋다.","cat":"interview","o":["수신자 기기에 직접 연결될 때까지 서버 메모리에 보관한다","전달에 실패했으므로 메시지를 버린다","메시지를 영속 저장소에 먼저 저장한 뒤 전달을 시도하고, 오프라인이면 미전달 상태로 남겨 두었다가 재접속 시 마지막으로 받은 시퀀스 이후를 동기화하며, 필요하면 푸시 알림으로 알린다","발신자에게 재전송을 요청한다"],"a":2},{"t":"choice","k":"알림 아키텍처","q":"대량 푸시 알림 시스템 설계에서 핵심 컴포넌트 구성으로 가장 적절한 것은?","ex":"외부 제공자는 느리고 실패하므로 동기 호출은 애플리케이션을 함께 죽인다. 큐와 채널 어댑터 분리, 설정 확인, 재시도/DLQ가 표준 구성이다.\n면접에서는 '제공자 장애 시 서킷 브레이커로 끊고 큐에 쌓아 두었다가 복구 후 흘려보내겠습니다'라고 하면 좋다.","cat":"interview","o":["알림 저장 없이 발송만 하고 결과는 추적하지 않는다","애플리케이션 서버가 직접 외부 푸시 제공자를 동기 호출한다","알림 요청을 큐에 넣고 워커가 소비하며, 채널별(모바일 푸시·이메일·SMS) 어댑터로 분리하고, 사용자 설정과 수신 거부를 발송 전에 확인하며, 실패는 재시도 후 DLQ로 보낸다","모든 알림을 하나의 배치로 하루 한 번 발송한다"],"a":2},{"t":"choice","k":"알림 중복·과다","q":"알림 시스템에서 반드시 다뤄야 할 문제로 옳게 짝지어진 것은?","ex":"at-least-once 재시도 때문에 중복은 반드시 발생하므로 멱등 키와 발송 이력이 필요하다. 알림 과다는 이탈과 수신 거부를 부르므로 묶음 발송과 사용자별 빈도 제한이 필요하고, 무한 재시도는 자원을 태우므로 상한과 DLQ가 있어야 한다.\n면접에서는 '같은 종류의 알림은 일정 시간 동안 묶어 하나로 보내는 집계 규칙을 두었습니다'라고 하면 제품 감각까지 보인다.","cat":"interview","o":["알림 과다 - 사용자 설정은 불필요하며 모두 발송하는 것이 참여율에 좋다","발송 실패 - 무한 재시도로 반드시 성공시킨다","발송 순서 - 전역 순서를 엄격히 보장해야 한다","중복 발송 - 이벤트마다 멱등 키를 두고 발송 이력을 확인해 재시도 시 중복을 막는다"],"a":3}],"th":{"sum":"설계 면접의 단골 문제들은 각각 '반드시 답해야 하는 한두 개의 핵심 결정'을 품고 있다. 그 결정을 알고 들어가면 45분을 주도할 수 있다.","body":[{"h":"면접관이 보는 것","t":"면접관은 문제마다 확인하고 싶은 포인트가 정해져 있다. 단축 URL은 키 생성과 읽기 우세 처리, 뉴스피드는 팬아웃 전략, 채팅은 연결 유지와 메시지 순서, 알림은 대량 발송과 중복 방지다. 이 지점을 스스로 짚어 내면 '준비된 사람'으로 보이고, 반대로 로드밸런서와 캐시만 그리다 끝나면 어떤 문제를 풀어도 같은 답을 하는 사람으로 보인다. 외운 아키텍처를 그대로 옮기는 것이 아니라, 그 선택이 왜 이 요구사항에서 타당한지 설명해야 점수가 된다."},{"h":"답변 구조","t":"문제마다 핵심 결정을 먼저 선언하고 시작한다. '이 문제의 핵심은 팔로워 수 분포에 따른 팬아웃 전략이라고 봅니다'라고 말한 뒤 대안을 비교하고 하나를 고르면 대화의 주도권이 생긴다. 그다음 데이터 모델과 저장소를 결정에 맞춰 붙이고, 마지막으로 극단 사례(팔로워 수천만, 그룹 채팅 1만 명, 알림 동시 발송 1,000만 건)를 스스로 꺼내 어떻게 버틸지 말한다. 극단 사례를 먼저 꺼내는 것만으로도 시니어 신호가 된다."}],"code":{"c":"[단축 URL] 핵심 = 짧고 충돌 없는 키 + 읽기 우세\n  -> 유일 ID를 base62 인코딩(7자 = 62^7 ≈ 3.5조), 매핑은 캐시 우선 조회\n\n[뉴스피드] 핵심 = 팬아웃 전략\n  -> 일반 사용자는 쓰기 시 배포(푸시), 유명인은 읽기 시 병합(풀) = 하이브리드\n\n[채팅] 핵심 = 연결 유지 + 메시지 순서/유실\n  -> WebSocket + 접속 서버 레지스트리, 서버가 부여한 시퀀스로 순서, 클라이언트 메시지 ID로 중복 제거\n\n[알림] 핵심 = 대량 발송 + 중복/재시도\n  -> 큐 기반 워커 + 채널별 어댑터(FCM/APNs/SMS) + 멱등 키 + DLQ","cap":"문제별 '핵심 결정'을 한 줄로 선언하고 들어가면 45분이 정리된다."},"key":["단축 URL의 승부처는 키 생성 방식과 리다이렉트 캐싱이다","피드의 승부처는 팬아웃이며, 유명인 때문에 하이브리드가 필요하다","채팅·알림의 승부처는 유실과 중복 — 순서와 멱등성을 어떻게 보장하는지 말한다"]}}]},{"t":"설계 면접 — 트레이드오프 질문 (SQL vs NoSQL·동기 vs 비동기·일관성)","l":[{"t":"SQL vs NoSQL 질문","q":[{"t":"choice","k":"선택 기준","q":"'왜 NoSQL을 선택하셨나요?'라는 질문에 좋은 답변은?","ex":"NoSQL은 속도가 아니라 확장 모델과 접근 패턴의 선택이다. 스키마 유연성은 부수 효과이며 오히려 애플리케이션이 스키마 책임을 떠안는다.\n면접에서는 '접근 패턴이 나중에 바뀌면 데이터 모델을 다시 만들어야 하는 위험이 가장 큽니다'라고 대가를 짚으면 좋다.","cat":"interview","o":["관계형보다 빠르고 요즘 표준이기 때문입니다","접근 패턴이 키 기반 단건 조회로 고정되어 있고 쓰기량이 단일 마스터 한계를 넘을 것으로 추정돼, 수평 확장이 쉬운 대신 임의 질의와 교차 엔티티 트랜잭션을 포기하는 거래가 타당하다고 판단했습니다","스키마를 정의하지 않아도 되어 개발이 빠르기 때문입니다","조인이 필요 없는 시스템에는 관계형 DB를 쓸 수 없기 때문입니다"],"a":1},{"t":"choice","k":"관계형 유지","q":"'요즘은 다 NoSQL 쓰지 않나요?'라는 압박 질문에 좋은 답변은?","ex":"관계형 DB도 읽기 복제본·파티셔닝·샤딩으로 상당한 규모까지 확장된다. 도메인별로 저장소를 나눠 쓰는 것이 오히려 일반적이다.\n면접에서는 '초기에 잘못 고른 NoSQL 모델을 되돌리는 비용이 더 크다는 점도 고려했습니다'라고 하면 좋다.","cat":"interview","o":["관계형 DB는 확장이 불가능하므로 언젠가는 반드시 바꿔야 합니다","둘을 함께 쓰면 운영이 복잡해지므로 하나로 통일해야 합니다","맞습니다. 신규 서비스는 NoSQL로 시작하는 것이 정석입니다","대부분의 서비스 규모에서는 관계형 DB 한 대로 충분하고, 트랜잭션·조인·임의 질의·성숙한 운영 도구라는 이점이 큽니다. 정말 필요한 지점(쓰기 폭증, 단일 노드 용량 초과)이 확인되면 그 도메인만 옮기겠습니다"],"a":3},{"t":"choice","k":"NoSQL 유형","q":"NoSQL 저장소 유형과 적합한 용도를 옳게 짝지은 것은?","ex":"키-값은 세션·캐시, 와이드 컬럼은 시계열·메시지처럼 대량 쓰기와 키 범위 조회, 문서는 유연한 구조의 엔티티, 그래프는 관계 탐색에 적합하다.\n면접에서는 '유형별 강점을 접근 패턴 기준으로 나눠 설명하겠습니다'라고 프레임을 잡으면 정리된 인상을 준다.","cat":"interview","o":["와이드 컬럼 - 복잡한 다중 조인 질의가 필요한 경우","문서 저장소 - 강한 다중 문서 트랜잭션이 핵심인 경우","그래프 DB - 대량 시계열 쓰기가 핵심인 경우","키-값 저장소 - 세션·캐시처럼 키로 단건 조회가 지배적인 경우"],"a":3},{"t":"choice","k":"스키마 유연성","q":"'스키마가 없어서 편하다'는 주장에 대한 정확한 반론은?","ex":"'schema-less'가 아니라 'schema-on-read'다. 초기 속도는 빠르지만 데이터가 오래 살아남으면 형태 다양성이 부채가 된다.\n면접에서는 '문서에 스키마 버전 필드를 두고 읽기 시 승격하는 방식으로 관리했습니다'라고 실무 기법을 말하면 좋다.","cat":"interview","o":["스키마가 사라진 것이 아니라 DB에서 애플리케이션 코드로 옮겨 간 것이다. 시간이 지나면 버전이 다른 문서가 섞여 읽는 쪽이 모든 형태를 처리해야 하므로, 결국 스키마 버전 관리와 마이그레이션이 필요해진다","스키마가 없으면 인덱스를 만들 수 없다","스키마 없는 저장소는 데이터 유실이 잦다","스키마 없는 저장소는 성능이 나쁘다"],"a":0},{"t":"choice","k":"폴리글랏","q":"한 시스템에서 관계형과 NoSQL을 함께 쓰는 설계에 대한 균형 잡힌 설명은?","ex":"폴리글랏 저장소는 이득과 운영 비용의 교환이다. 특히 두 저장소에 걸친 정합성은 아웃박스나 보상 트랜잭션으로 직접 처리해야 한다.\n면접에서는 '팀이 감당할 수 있는 저장소 개수인지도 선택 기준에 넣습니다'라고 조직 관점을 더하면 좋다.","cat":"interview","o":["도메인마다 접근 패턴이 달라 각각에 맞는 저장소를 쓰면 이득이 크지만, 저장소 수만큼 운영·백업·모니터링 부담과 교차 저장소 정합성 문제가 늘어난다","저장소는 많을수록 좋으므로 도메인마다 다르게 고른다","여러 저장소를 쓰면 정합성이 자동으로 보장된다","한 시스템에 두 종류 저장소를 쓰는 것은 안티패턴이다"],"a":0},{"t":"input","k":"정합성 패턴","q":"여러 서비스·저장소에 걸친 작업을 하나의 분산 트랜잭션 대신 로컬 트랜잭션과 보상 트랜잭션의 연쇄로 처리하는 패턴의 이름은? (영문)","ex":"사가는 2단계 커밋의 가용성 문제를 피하는 대신, 중간 상태 노출과 보상 로직 구현 부담을 받아들이는 패턴이다.\n면접에서는 '보상이 불가능한 작업(발송된 메일 등)이 있는지 먼저 확인합니다'라고 한계를 짚으면 좋다.","cat":"interview","a":["saga","사가","saga pattern","사가 패턴"]}],"th":{"sum":"트레이드오프 질문에 '더 좋은 쪽'을 고르면 틀린 답이 된다. 면접관은 '어떤 조건에서 무엇이 유리하고 무엇을 잃는가'를 말한 뒤 하나를 고르는 능력을 본다.","body":[{"h":"면접관이 보는 것","t":"'요즘은 NoSQL이 대세죠', '비동기가 더 빠릅니다' 같은 답은 유행어를 외운 것으로 읽혀 감점된다. 면접관은 판단 기준을 요구하고, 선택의 대가를 인정하는지 확인한다. 특히 CAP와 일관성 질문은 오개념이 많은 영역이라 정확도 자체가 변별력이 된다. 결론을 내지 않고 '상황에 따라 다릅니다'로만 끝내는 것도 감점이니, 반드시 조건을 붙여 하나를 골라야 한다."},{"h":"답변 구조","t":"판단 기준 제시 → 각 선택지의 강점과 대가 → 이 요구사항에서의 결정 → 결정을 되돌릴 조건 순으로 답한다. 기준을 먼저 세우면 답변이 취향이 아니라 논리가 된다. '지금 규모에서는 A로 가고, 쓰기 QPS가 5,000을 넘으면 B를 검토하겠습니다'처럼 전환 조건을 말하면 결정을 관리할 줄 아는 사람으로 보인다. 마지막에 '어느 쪽을 골라도 이 문제는 남습니다'라고 잔여 위험을 짚으면 완성도가 높아진다."}],"code":{"c":"[기준] 데이터 접근 패턴 / 정합성 요구 / 규모와 성장 속도 / 팀 운영 역량\n\n관계형    강점: 트랜잭션, 조인, 유연한 임의 질의, 성숙한 도구\n          대가: 단일 노드 쓰기 한계, 스키마 변경 비용\nNoSQL     강점: 수평 확장, 유연한 스키마, 특정 접근 패턴에 최적\n          대가: 접근 패턴을 미리 고정해야 함, 교차 엔티티 정합성 직접 처리\n\n[결정] 주문·결제는 관계형(트랜잭션 필수), 활동 로그·피드는 NoSQL(쓰기 폭증)\n[전환 조건] 관계형 쓰기가 마스터 한계에 닿으면 도메인 분리 -> 샤딩 순으로 검토","cap":"'상황에 따라 다르다'로 끝내지 말고, 기준을 대고 결정까지 내려야 한다."},"key":["CAP는 네트워크 분단이 일어났을 때 일관성과 가용성 중 무엇을 포기할지의 문제다","NoSQL은 '빠른 DB'가 아니라 '접근 패턴을 고정하는 대신 확장을 얻는 선택'이다","비동기는 응답을 빠르게 하는 대신 복잡도와 최종 일관성을 데려온다"]}},{"t":"동기 vs 비동기 질문","q":[{"t":"choice","k":"선택 기준","q":"'이 처리를 동기로 할까요, 비동기로 할까요?'라는 질문에 좋은 판단 기준은?","ex":"기준은 속도가 아니라 즉시성 요구다. 비동기로 뺐다면 사용자에게 진행 상태를 알려 줄 방법(폴링, 웹훅, 알림)을 함께 설계해야 한다.\n면접에서는 '결제 승인은 동기, 영수증 메일과 적립은 비동기로 나눴습니다'처럼 경계를 예로 들면 좋다.","cat":"interview","o":["외부 시스템 호출은 무조건 비동기로 한다","비동기는 디버깅이 어려우므로 쓰지 않는다","느린 작업은 전부 비동기로 한다","사용자가 결과를 즉시 알아야 하는가, 실패 시 즉시 알려야 하는가, 지연 처리해도 비즈니스상 문제가 없는가를 기준으로 나눈다. 즉시성이 필요하면 동기, 아니면 비동기로 빼고 상태 조회 수단을 제공한다"],"a":3},{"t":"choice","k":"비동기 비용","q":"'비동기로 바꾸면 무엇을 잃나요?'라는 꼬리 질문에 정확한 답변은?","ex":"비동기는 응답 시간을 사는 대신 일관성 지연과 운영 복잡도를 지불한다. 이 비용을 말하지 못하면 큐를 남용하는 사람으로 보인다.\n면접에서는 '그래서 큐를 도입할 때 DLQ, 재처리 도구, 적체 알림을 함께 준비했습니다'라고 하면 좋다.","cat":"interview","o":["즉시 일관성이 사라져 사용자가 예전 상태를 볼 수 있고, 실패가 요청 시점에 드러나지 않아 재처리·모니터링·중복 방지 로직이 필요해지며, 흐름 추적과 디버깅이 어려워진다","메시지 브로커 비용만 늘어난다","순서 보장이 자동으로 이뤄져 오히려 단순해진다","잃는 것 없이 처리량과 응답 속도만 좋아진다"],"a":0},{"t":"choice","k":"완충 vs 처리량","q":"'큐를 넣으면 처리량이 늘어나나요?'라는 질문에 정확한 답변은?","ex":"큐는 완충 장치이지 처리 능력이 아니다. 소비자 확장이 없으면 적체가 쌓여 지연이 폭증한다.\n면접에서는 '가장 오래된 메시지의 나이를 지표로 보고 소비자를 오토스케일했습니다'라고 운영을 붙이면 좋다.","cat":"interview","o":["아니요. 큐는 순간 폭주를 완충하고 생산과 소비를 분리할 뿐, 최종 처리량은 소비자 능력이 결정합니다. 소비가 계속 밀리면 지연만 무한히 커집니다","네, 큐 크기를 늘리면 처리량도 비례해 늘어납니다","큐는 처리량과 무관하며 오직 순서 보장을 위한 장치입니다","네, 큐가 병렬 처리를 자동으로 늘려 줍니다"],"a":0},{"t":"choice","k":"요청 응답 패턴","q":"오래 걸리는 작업(영상 인코딩 등)의 API 설계로 가장 적절한 것은?","ex":"긴 작업을 동기로 잡아 두면 연결과 스레드가 점유되고 중간 실패 시 재개도 어렵다. 접수-폴링/웹훅 패턴이 표준이다.\n면접에서는 'POST 재요청 시 멱등성 키로 같은 작업이 중복 생성되지 않게 합니다'라고 이어 가면 좋다.","code":"POST /v1/videos          -&gt; 202 Accepted { job_id, status_url }\nGET  /v1/jobs/{job_id}   -&gt; { status: \"processing\" | \"done\" | \"failed\", result_url }","cat":"interview","o":["작업이 끝날 때까지 클라이언트가 1초 간격으로 같은 POST를 재요청한다","작업을 동기로 처리하되 타임아웃을 10분으로 늘린다","요청이 끝날 때까지 HTTP 연결을 유지해 결과를 반환한다","작업을 접수하고 202와 작업 ID를 즉시 반환한 뒤, 상태 조회 엔드포인트나 웹훅으로 완료를 알린다"],"a":3},{"t":"choice","k":"동기 유지 판단","q":"비동기로 빼면 안 되는 작업의 예로 가장 적절한 것은?","ex":"재고가 없는데 주문 성공을 먼저 알려 주면 취소·환불이라는 더 큰 비용이 발생한다. 즉시 확정이 필요한 작업은 동기로 남긴다.\n면접에서는 '정말 비동기로 빼야 한다면 예약(reserve) 후 확정하는 2단계로 나누겠습니다'라고 대안을 제시하면 좋다.","cat":"interview","o":["이미지 썸네일 생성","재고 차감과 주문 확정처럼 결과가 즉시 사용자 응답에 반영돼야 하고 실패 시 바로 알려야 하는 작업","일일 통계 집계","가입 환영 메일 발송"],"a":1},{"t":"choice","k":"혼합 설계","q":"동기와 비동기를 함께 쓰는 설계에서 흔히 놓치는 문제는?","ex":"부분 성공 상태를 어떻게 표현하고 어떻게 복구할지가 혼합 설계의 핵심이다. '처리 중' 상태를 명시적으로 두는 것이 출발점이다.\n면접에서는 '상태 머신을 그려 각 상태의 전이와 실패 경로를 정의했습니다'라고 말하면 설계자다운 인상을 준다.","cat":"interview","o":["비동기 처리가 동기보다 빨라 순서가 뒤집히는 것","메시지 브로커의 저장 비용","API 응답 형식이 통일되지 않는 것","동기 경로에서 성공했지만 비동기 후속 처리가 실패했을 때 사용자에게 보이는 상태와 실제 상태가 어긋나는 것 — 상태 모델과 보정(재처리·알림) 방법을 함께 설계해야 한다"],"a":3}],"th":{"sum":"트레이드오프 질문에 '더 좋은 쪽'을 고르면 틀린 답이 된다. 면접관은 '어떤 조건에서 무엇이 유리하고 무엇을 잃는가'를 말한 뒤 하나를 고르는 능력을 본다.","body":[{"h":"면접관이 보는 것","t":"'요즘은 NoSQL이 대세죠', '비동기가 더 빠릅니다' 같은 답은 유행어를 외운 것으로 읽혀 감점된다. 면접관은 판단 기준을 요구하고, 선택의 대가를 인정하는지 확인한다. 특히 CAP와 일관성 질문은 오개념이 많은 영역이라 정확도 자체가 변별력이 된다. 결론을 내지 않고 '상황에 따라 다릅니다'로만 끝내는 것도 감점이니, 반드시 조건을 붙여 하나를 골라야 한다."},{"h":"답변 구조","t":"판단 기준 제시 → 각 선택지의 강점과 대가 → 이 요구사항에서의 결정 → 결정을 되돌릴 조건 순으로 답한다. 기준을 먼저 세우면 답변이 취향이 아니라 논리가 된다. '지금 규모에서는 A로 가고, 쓰기 QPS가 5,000을 넘으면 B를 검토하겠습니다'처럼 전환 조건을 말하면 결정을 관리할 줄 아는 사람으로 보인다. 마지막에 '어느 쪽을 골라도 이 문제는 남습니다'라고 잔여 위험을 짚으면 완성도가 높아진다."}],"code":{"c":"[기준] 데이터 접근 패턴 / 정합성 요구 / 규모와 성장 속도 / 팀 운영 역량\n\n관계형    강점: 트랜잭션, 조인, 유연한 임의 질의, 성숙한 도구\n          대가: 단일 노드 쓰기 한계, 스키마 변경 비용\nNoSQL     강점: 수평 확장, 유연한 스키마, 특정 접근 패턴에 최적\n          대가: 접근 패턴을 미리 고정해야 함, 교차 엔티티 정합성 직접 처리\n\n[결정] 주문·결제는 관계형(트랜잭션 필수), 활동 로그·피드는 NoSQL(쓰기 폭증)\n[전환 조건] 관계형 쓰기가 마스터 한계에 닿으면 도메인 분리 -> 샤딩 순으로 검토","cap":"'상황에 따라 다르다'로 끝내지 말고, 기준을 대고 결정까지 내려야 한다."},"key":["CAP는 네트워크 분단이 일어났을 때 일관성과 가용성 중 무엇을 포기할지의 문제다","NoSQL은 '빠른 DB'가 아니라 '접근 패턴을 고정하는 대신 확장을 얻는 선택'이다","비동기는 응답을 빠르게 하는 대신 복잡도와 최종 일관성을 데려온다"]}},{"t":"일관성·CAP 질문","q":[{"t":"choice","k":"CAP 정확도","q":"'CAP 정리를 설명해 보세요'에 대한 정확한 설명은?","ex":"'셋 중 둘'이라는 요약은 흔한 오해다. 분단 내성은 포기할 수 있는 항목이 아니며, 분단이 없는 평상시에는 일관성과 지연 사이의 선택(PACELC의 EL 부분)이 남는다.\n면접에서는 'PACELC로 확장하면 평상시의 지연-일관성 교환까지 설명할 수 있습니다'라고 덧붙이면 깊이가 드러난다.","cat":"interview","o":["일관성, 가용성, 분단 내성 중 항상 두 가지만 선택할 수 있다","네트워크 분단이 발생한 상황에서 일관성과 가용성 중 하나를 포기해야 한다는 정리다. 분산 시스템에서 분단은 선택 사항이 아니라 언젠가 반드시 발생하므로, 실제 선택은 분단 시 CP로 갈지 AP로 갈지의 문제다","분산 시스템은 일관성을 절대 보장할 수 없다는 정리다","가용성을 높이면 지연이 반드시 증가한다는 정리다"],"a":1},{"t":"choice","k":"최종 일관성","q":"'최종 일관성이 무엇이고 언제 허용하나요?'에 대한 좋은 답변은?","ex":"최종 일관성은 도메인 단위로 선택하는 것이지 시스템 전체에 일괄 적용하는 것이 아니다.\n면접에서는 '수렴까지 걸리는 시간을 지표로 재고 임계치를 넘으면 알림을 받도록 했습니다'라고 운영을 붙이면 좋다.","cat":"interview","o":["복제 지연이 없는 시스템을 뜻한다","쓰기 성능을 높이기 위한 캐시 전략의 이름이다","데이터가 결국은 맞아지지만 절대 틀리지 않는다는 뜻으로, 모든 경우에 안전하다","새 쓰기가 없으면 언젠가 모든 복제본이 같은 값에 수렴한다는 보장이다. 좋아요 수나 피드처럼 잠깐 어긋나도 사용자 피해가 없는 영역에 허용하고, 잔액·재고·중복 가입처럼 어긋나면 금전·법적 문제가 되는 영역에는 쓰지 않는다"],"a":3},{"t":"choice","k":"정족수","q":"복제본 N=3인 시스템에서 쓰기 정족수 W와 읽기 정족수 R을 정할 때, 항상 최신 값을 읽으려면 만족해야 하는 조건은?","ex":"W + R &gt; N이면 읽기 집합과 쓰기 집합이 반드시 겹쳐 최신 값을 포함한다. N=3에서 W=2, R=2가 가장 흔한 균형점이다.\n면접에서는 'W=3, R=1로 하면 읽기는 빠르지만 노드 하나만 죽어도 쓰기가 막힌다는 점에서 가용성 교환이 드러납니다'라고 예를 대면 좋다.","cat":"interview","o":["W + R &gt; N (예: W=2, R=2)","W + R &lt; N (예: W=1, R=1)","W = R = N","W = 1, R = 1이면 충분하다"],"a":0},{"t":"choice","k":"CP vs AP 선택","q":"결제 잔액을 다루는 시스템과 상품 조회수를 다루는 시스템의 일관성 선택으로 옳은 것은?","ex":"일관성 선택은 데이터가 틀렸을 때의 비용으로 결정한다. 잔액 오류는 금전 손실이지만 조회수 오차는 무시할 수 있다.\n면접에서는 '한 시스템 안에서도 도메인별로 다르게 가져갑니다'라고 정리하면 좋은 마무리가 된다.","cat":"interview","o":["일관성 선택은 저장소 벤더가 정하므로 설계자가 고를 수 없다","둘 다 가용성을 우선해 분단 시에도 계속 응답한다","잔액은 분단 시 일관성을 지키고 일부 요청을 거절하는 쪽(CP), 조회수는 분단 시에도 계속 응답하고 나중에 수렴시키는 쪽(AP)이 적절하다","둘 다 강한 일관성이 필요하므로 동일하게 설계한다"],"a":2},{"t":"input","k":"읽기 보장","q":"사용자가 방금 자신이 쓴 데이터를 조회할 때 반드시 최신 값이 보이도록 하는 일관성 보장을 무엇이라 하는가? (영문)","ex":"복제 지연이 있어도 본인이 쓴 값은 즉시 보여야 사용자가 버그로 인식하지 않는다. 쓰기 직후 일정 시간 기본 노드로 읽게 하는 방식이 흔하다.\n면접에서는 '단조 읽기(monotonic reads)도 함께 챙겨야 값이 과거로 되돌아가 보이지 않습니다'라고 확장하면 좋다.","cat":"interview","a":["read-your-writes","read your writes","리드 유어 라이츠","read-after-write","자기 쓰기 읽기"]},{"t":"choice","k":"결론 내기","q":"트레이드오프 질문에 대한 답변 마무리로 가장 좋은 것은?","ex":"면접은 결정을 내리는 사람을 뽑는 자리다. 비교만 하고 결론이 없으면 지식은 있으나 판단은 없다는 평가를 받는다.\n면접에서는 전환 조건을 숫자로 말하는 것이 가장 강력한 마무리다.","cat":"interview","o":["'상황에 따라 다릅니다'로 마무리한다","'이 요구사항에서는 A를 고르겠습니다. 대신 B의 장점인 X를 잃고, 쓰기 QPS가 5,000을 넘으면 B로 전환을 검토하겠습니다'처럼 결정·대가·전환 조건을 함께 말한다","두 방식의 장단점만 길게 나열하고 선택은 면접관에게 맡긴다","더 새로운 기술 쪽을 고른다"],"a":1}],"th":{"sum":"트레이드오프 질문에 '더 좋은 쪽'을 고르면 틀린 답이 된다. 면접관은 '어떤 조건에서 무엇이 유리하고 무엇을 잃는가'를 말한 뒤 하나를 고르는 능력을 본다.","body":[{"h":"면접관이 보는 것","t":"'요즘은 NoSQL이 대세죠', '비동기가 더 빠릅니다' 같은 답은 유행어를 외운 것으로 읽혀 감점된다. 면접관은 판단 기준을 요구하고, 선택의 대가를 인정하는지 확인한다. 특히 CAP와 일관성 질문은 오개념이 많은 영역이라 정확도 자체가 변별력이 된다. 결론을 내지 않고 '상황에 따라 다릅니다'로만 끝내는 것도 감점이니, 반드시 조건을 붙여 하나를 골라야 한다."},{"h":"답변 구조","t":"판단 기준 제시 → 각 선택지의 강점과 대가 → 이 요구사항에서의 결정 → 결정을 되돌릴 조건 순으로 답한다. 기준을 먼저 세우면 답변이 취향이 아니라 논리가 된다. '지금 규모에서는 A로 가고, 쓰기 QPS가 5,000을 넘으면 B를 검토하겠습니다'처럼 전환 조건을 말하면 결정을 관리할 줄 아는 사람으로 보인다. 마지막에 '어느 쪽을 골라도 이 문제는 남습니다'라고 잔여 위험을 짚으면 완성도가 높아진다."}],"code":{"c":"[기준] 데이터 접근 패턴 / 정합성 요구 / 규모와 성장 속도 / 팀 운영 역량\n\n관계형    강점: 트랜잭션, 조인, 유연한 임의 질의, 성숙한 도구\n          대가: 단일 노드 쓰기 한계, 스키마 변경 비용\nNoSQL     강점: 수평 확장, 유연한 스키마, 특정 접근 패턴에 최적\n          대가: 접근 패턴을 미리 고정해야 함, 교차 엔티티 정합성 직접 처리\n\n[결정] 주문·결제는 관계형(트랜잭션 필수), 활동 로그·피드는 NoSQL(쓰기 폭증)\n[전환 조건] 관계형 쓰기가 마스터 한계에 닿으면 도메인 분리 -> 샤딩 순으로 검토","cap":"'상황에 따라 다르다'로 끝내지 말고, 기준을 대고 결정까지 내려야 한다."},"key":["CAP는 네트워크 분단이 일어났을 때 일관성과 가용성 중 무엇을 포기할지의 문제다","NoSQL은 '빠른 DB'가 아니라 '접근 패턴을 고정하는 대신 확장을 얻는 선택'이다","비동기는 응답을 빠르게 하는 대신 복잡도와 최종 일관성을 데려온다"]}}]},{"t":"설계 면접 — 실패·운영 질문 (SPOF·장애 대응·모니터링)","l":[{"t":"SPOF·가용성 질문","q":[{"t":"choice","k":"SPOF 식별","q":"'이 설계의 단일 장애점은 어디인가요?'라는 질문에 좋은 답변 방식은?","ex":"면접관은 완벽한 설계를 기대하지 않고, 약점을 스스로 찾을 수 있는지를 본다. 관리형 서비스도 리전 장애나 설정 오류로 죽는다.\n면접에서는 '지금 남은 SPOF는 이것이고, 우선순위상 다음 단계에서 처리하겠습니다'라고 말하면 현실적인 판단으로 읽힌다.","cat":"interview","o":["각 컴포넌트를 순서대로 짚으며 '이것이 죽으면 무엇이 멈추는지'를 말하고, 아직 이중화되지 않은 지점(예: 단일 리더 조정 서비스, 단일 리전 저장소)을 스스로 지목한 뒤 대응을 제시한다","클라우드 관리형 서비스를 쓰므로 장애는 벤더 책임이라고 답한다","장애는 예측할 수 없으므로 대비할 수 없다고 답한다","'이중화했으므로 단일 장애점은 없습니다'라고 답한다"],"a":0},{"t":"input","k":"가용성 계산","q":"가용성 99.9%(스리 나인)일 때 연간 허용되는 다운타임은 약 몇 시간인가? (숫자만, 소수 첫째 자리까지)","ex":"1년은 약 525,600분이고 0.1%는 525.6분 = 8.76시간이다. 99.99%면 52.6분, 99.999%면 약 5.3분이다.\n면접에서는 '나인 하나를 더 붙이는 비용이 기하급수적으로 커지므로 서비스 특성에 맞는 목표를 정하는 게 먼저입니다'라고 말하면 좋다.","cat":"interview","a":["8.8","8.76","8.7","약 8.8"]},{"t":"choice","k":"직렬 의존","q":"가용성 99.9%인 컴포넌트 3개를 직렬로 거쳐야 요청이 완료된다. 전체 가용성에 대한 설명으로 옳은 것은?","ex":"0.999^3 ≈ 0.997로 약 99.7%가 된다. 의존이 늘수록 가용성이 나빠지므로, 핵심 경로의 의존을 줄이고 부가 기능은 실패해도 응답이 나가게 설계한다.\n면접에서는 '추천 서비스가 죽어도 상품 페이지는 기본 목록으로 응답하게 했습니다'처럼 선택적 의존 예를 들면 좋다.","cat":"interview","o":["99.9%의 3배인 99.97%로 올라간다","가용성은 컴포넌트 수와 무관하다","여전히 99.9%다. 각 컴포넌트가 독립적이기 때문이다","약 99.7%로 떨어진다. 직렬 의존은 가용성이 곱해지기 때문이며, 그래서 의존 수를 줄이거나 일부 의존을 선택적(실패해도 진행)으로 만든다"],"a":3},{"t":"choice","k":"성능 저하 모드","q":"'캐시 클러스터가 통째로 죽으면 어떻게 되나요?'라는 질문에 가장 좋은 답변은?","ex":"캐시는 부가 기능이 아니라 용량 계획의 일부다. 캐시가 흡수하던 부하가 DB로 몰리면 연쇄 장애가 된다. 전부 아니면 전무 대신 축소 운영이 정답이다.\n면접에서는 '핵심 기능만 남기는 기준을 미리 정해 기능 플래그로 껐다 켤 수 있게 했습니다'라고 하면 좋다.","cat":"interview","o":["DB가 즉시 포화될 수 있으므로, 캐시 장애를 감지하면 회로를 차단하고 요청 수를 제한하며 비핵심 기능을 끄는 성능 저하 모드로 전환해 핵심 기능만 유지합니다","서비스를 전면 중단하고 캐시를 복구합니다","캐시는 부가 기능이므로 아무 영향이 없습니다","모든 요청이 DB로 가지만 DB가 감당할 것이므로 문제 없습니다"],"a":0},{"t":"choice","k":"다중 AZ/리전","q":"다중 가용 영역(AZ)과 다중 리전 구성에 대한 설명으로 옳은 것은?","ex":"다중 AZ는 대부분의 서비스에서 기본값에 가깝고, 다중 리전은 요구되는 RTO/RPO가 명확할 때 도입한다. 리전 간 복제는 지연 때문에 강한 일관성을 유지하기 어렵다.\n면접에서는 '먼저 다중 AZ로 가고, 리전 장애까지 견뎌야 한다는 요구가 확정되면 다중 리전을 검토하겠습니다'라고 단계를 제시하면 좋다.","cat":"interview","o":["다중 AZ 구성만으로 리전 전체 장애를 견딜 수 있다","다중 AZ는 같은 지역 내 물리적으로 분리된 영역에 분산해 지연 손실이 거의 없이 가용성을 올리는 기본 구성이고, 다중 리전은 재해 복구와 지역 지연 개선까지 얻지만 데이터 복제 지연과 정합성, 비용 문제가 크게 늘어난다","다중 AZ와 다중 리전은 같은 말이다","다중 리전은 비용만 늘 뿐 가용성에는 도움이 되지 않는다"],"a":1},{"t":"input","k":"복구 목표","q":"재해 복구에서 '데이터 손실을 어디까지 감수할 것인가(복구 시점 목표)'를 나타내는 영문 약어는?","ex":"RPO는 얼마나 과거 시점까지 되돌아가도 되는지(=손실 허용 데이터 양), RTO는 얼마나 빨리 복구해야 하는지다.\n면접에서는 'RPO 5분이면 최소 5분 주기 복제나 로그 백업이 필요합니다'처럼 목표를 설계 요구로 번역하면 좋다.","cat":"interview","a":["RPO","rpo","Recovery Point Objective"]}],"th":{"sum":"면접 후반의 '이 컴포넌트가 죽으면 어떻게 되나요?'는 설계자의 성숙도를 가르는 질문이다. 실패를 예외가 아니라 기본 조건으로 다루는지를 본다.","body":[{"h":"면접관이 보는 것","t":"면접관은 정상 흐름만 그리는 사람과 실패 경로까지 그리는 사람을 나눈다. 그래서 각 컴포넌트를 하나씩 죽여 보며 무엇이 멈추고 무엇이 부분적으로 살아남는지 묻는다. 좋은 답변은 '이중화했습니다'가 아니라 '이 경우 기능이 이렇게 축소되고, 사용자는 이 정도 영향을 받으며, 복구는 이렇게 됩니다'까지 간다. 모니터링 질문에서는 무엇을 지표로 삼고 언제 사람을 깨울지 기준이 있는지가 핵심이며, 알림을 많이 건다는 답은 오히려 감점이다."},{"h":"답변 구조","t":"실패 지점 열거 → 영향 범위 → 격리 수단 → 감지 → 복구 순으로 답한다. 먼저 SPOF를 스스로 짚고, 각각에 대해 이중화·격벽·회로 차단 중 무엇을 쓸지 말한다. 그다음 '이 장애를 몇 초 안에 어떤 지표로 감지하는가'를 붙여야 설계가 운영과 연결된다. 마지막으로 성능 저하 모드(graceful degradation)를 제시하면, 전부 아니면 전무가 아닌 현실적인 설계자로 평가된다."}],"code":{"c":"[컴포넌트별 실패 시나리오]\n캐시 다운   -> DB 직격. 대응: 회로 차단 + 요청 제한 + 일부 기능 축소\nDB 마스터   -> 쓰기 중단. 대응: 자동 승격(수십 초) + 그동안 읽기 전용 모드\n큐 지연     -> 알림 지연. 대응: 가장 오래된 메시지 나이 알림, 우선순위 큐 분리\n외부 결제사 -> 결제 실패. 대응: 타임아웃 + 서킷 브레이커 + 대체 채널 안내\n한 AZ 상실  -> 용량 1/3 감소. 대응: 3개 AZ 분산 + 여유 용량 30%\n\n[감지] 증상 기반 알림 — 오류율/지연 SLO 소진 속도로 호출, 원인 지표는 대시보드로\n[복구] 롤백 6분 목표, 되돌릴 수 없는 변경은 기능 플래그로 차단","cap":"실패 목록을 먼저 꺼내는 사람이 설계 면접 후반을 가져간다."},"key":["직렬로 의존하는 컴포넌트가 늘수록 전체 가용성은 곱해져 낮아진다","재시도는 타임아웃·지수 백오프·지터·상한과 함께가 아니면 장애를 키운다","알림은 원인이 아니라 사용자 영향(증상) 기준으로 걸고, 나머지는 대시보드로 본다"]}},{"t":"장애 전파·대응 질문","q":[{"t":"choice","k":"연쇄 장애","q":"한 하위 서비스가 느려졌을 뿐인데 전체 서비스가 죽었다. 가장 흔한 원인은?","ex":"가용성 문제는 대개 '느림'에서 시작해 자원 고갈로 번진다. 타임아웃, 동시 호출 제한(격벽), 회로 차단이 전파를 끊는 3종 세트다.\n면접에서는 '전체 요청 예산 500ms 안에서 외부 호출은 200ms로 잘랐습니다'처럼 숫자로 말하면 좋다.","cat":"interview","o":["네트워크 대역폭이 부족했기 때문","로그 양이 늘어 디스크가 찼기 때문","하위 서비스의 CPU가 높아 상위 서비스 CPU도 함께 올라갔기 때문","타임아웃이 없거나 너무 길어 상위 서비스의 스레드·커넥션이 대기 상태로 모두 점유되고, 재시도가 부하를 더해 연쇄적으로 무너졌기 때문"],"a":3},{"t":"choice","k":"서킷 브레이커","q":"서킷 브레이커의 동작을 정확히 설명한 것은?","ex":"회로가 열리면 헛된 대기 없이 즉시 실패해 자원을 지키고, 반열림 상태의 시험 호출로 회복을 탐지한다. 이 즉시 실패가 대체 응답(캐시된 값, 기본값)과 짝을 이룬다.\n면접에서는 '회로가 열렸을 때 무엇을 대신 보여 줄지 정하는 게 더 중요합니다'라고 사용자 경험을 짚으면 좋다.","cat":"interview","o":["요청을 큐에 쌓아 두었다가 서비스가 회복되면 모두 전송한다","장애가 난 서비스를 자동으로 재시작한다","실패율이 임계치를 넘으면 회로를 열어 일정 시간 호출 자체를 즉시 실패시키고, 이후 소수의 시험 호출로 회복을 확인한 뒤 닫는다","실패한 요청을 자동으로 다른 서버로 재전송한다"],"a":2},{"t":"choice","k":"재시도 폭풍","q":"장애가 잠깐 발생했다가 회복되는 순간 트래픽이 폭증해 다시 죽었다. 원인과 대응은?","ex":"지터 없는 지수 백오프는 재시도 시점이 같은 순간에 정렬돼 다시 몰린다. 클라이언트와 서버 양쪽 방어가 필요하다.\n면접에서는 '복구 직후에는 트래픽을 단계적으로 열어 주는 램프업도 함께 씁니다'라고 하면 운영 경험이 드러난다.","cat":"interview","o":["DNS 전파 지연 때문이므로 TTL을 줄인다","로드밸런서 설정 오류이므로 재배포한다","모든 클라이언트가 동시에 재시도해 몰린 것이다. 지수 백오프에 무작위 지터를 더하고 재시도 횟수를 제한하며, 서버 측에도 요청 제한과 대기열을 둔다","캐시가 비어 있었기 때문이므로 캐시 TTL을 늘린다"],"a":2},{"t":"choice","k":"부하 차단","q":"처리 능력을 초과하는 트래픽이 들어올 때 가장 적절한 설계는?","ex":"전부 받으려다 전부 실패하는 것이 최악이다. 일부를 빠르게 거절해 나머지를 지키는 것이 가용성 관점의 정답이며, 대기열이 길어지면 어차피 사용자는 이미 떠난 뒤다.\n면접에서는 '결제는 살리고 추천과 통계 요청부터 버리는 우선순위를 정했습니다'라고 예를 들면 좋다.","cat":"interview","o":["모든 요청을 큐에 넣고 순서대로 처리해 하나도 버리지 않는다","우선순위가 낮은 요청부터 빠르게 거절(load shedding)하고 429로 알려, 남은 용량으로 핵심 요청을 정상 처리한다","타임아웃을 늘려 모든 요청이 결국 성공하게 한다","서버를 즉시 10배로 늘려 모두 처리한다"],"a":1},{"t":"choice","k":"안전한 배포","q":"'배포로 인한 장애를 어떻게 줄이시겠어요?'라는 질문에 좋은 답변은?","ex":"테스트로 모든 문제를 잡을 수 없으므로 '작게 노출하고 빨리 되돌리는' 구조가 핵심이다. 스키마 변경은 추가 → 이중 쓰기 → 전환 → 제거 순으로 나눠야 롤백이 가능하다.\n면접에서는 '배포 후 5분간 오류율과 지연을 자동 검증하는 게이트를 두었습니다'라고 하면 좋다.","cat":"interview","o":["일부 트래픽에만 먼저 적용하는 카나리 배포로 지표를 관찰하고, 이상 시 자동 롤백하며, 되돌리기 어려운 변경(스키마 등)은 하위 호환 단계로 나눠 배포하고 기능 플래그로 노출을 제어한다","배포는 트래픽이 적은 새벽에만 하면 안전하다","한 번에 전체를 배포해야 상태가 일관되어 안전하다","배포 전에 테스트를 충분히 하면 장애는 발생하지 않는다"],"a":0},{"t":"input","k":"격리 패턴","q":"한 종류의 요청이 자원을 모두 소진해 다른 요청까지 막는 것을 방지하려고, 스레드 풀이나 커넥션 풀을 용도별로 분리해 격리하는 패턴을 무엇이라 하는가? (한글 또는 영문)","ex":"배의 격벽처럼 한 구역의 침수가 배 전체로 번지지 않게 하는 개념이다. 서킷 브레이커와 함께 장애 전파를 끊는 대표 패턴이다.\n면접에서는 '외부 연동용 커넥션 풀을 내부 DB 풀과 분리해 외부 지연이 핵심 기능을 막지 않게 했습니다'라고 예를 들면 좋다.","cat":"interview","a":["벌크헤드","bulkhead","격벽","bulkhead pattern","격벽 패턴"]}],"th":{"sum":"면접 후반의 '이 컴포넌트가 죽으면 어떻게 되나요?'는 설계자의 성숙도를 가르는 질문이다. 실패를 예외가 아니라 기본 조건으로 다루는지를 본다.","body":[{"h":"면접관이 보는 것","t":"면접관은 정상 흐름만 그리는 사람과 실패 경로까지 그리는 사람을 나눈다. 그래서 각 컴포넌트를 하나씩 죽여 보며 무엇이 멈추고 무엇이 부분적으로 살아남는지 묻는다. 좋은 답변은 '이중화했습니다'가 아니라 '이 경우 기능이 이렇게 축소되고, 사용자는 이 정도 영향을 받으며, 복구는 이렇게 됩니다'까지 간다. 모니터링 질문에서는 무엇을 지표로 삼고 언제 사람을 깨울지 기준이 있는지가 핵심이며, 알림을 많이 건다는 답은 오히려 감점이다."},{"h":"답변 구조","t":"실패 지점 열거 → 영향 범위 → 격리 수단 → 감지 → 복구 순으로 답한다. 먼저 SPOF를 스스로 짚고, 각각에 대해 이중화·격벽·회로 차단 중 무엇을 쓸지 말한다. 그다음 '이 장애를 몇 초 안에 어떤 지표로 감지하는가'를 붙여야 설계가 운영과 연결된다. 마지막으로 성능 저하 모드(graceful degradation)를 제시하면, 전부 아니면 전무가 아닌 현실적인 설계자로 평가된다."}],"code":{"c":"[컴포넌트별 실패 시나리오]\n캐시 다운   -> DB 직격. 대응: 회로 차단 + 요청 제한 + 일부 기능 축소\nDB 마스터   -> 쓰기 중단. 대응: 자동 승격(수십 초) + 그동안 읽기 전용 모드\n큐 지연     -> 알림 지연. 대응: 가장 오래된 메시지 나이 알림, 우선순위 큐 분리\n외부 결제사 -> 결제 실패. 대응: 타임아웃 + 서킷 브레이커 + 대체 채널 안내\n한 AZ 상실  -> 용량 1/3 감소. 대응: 3개 AZ 분산 + 여유 용량 30%\n\n[감지] 증상 기반 알림 — 오류율/지연 SLO 소진 속도로 호출, 원인 지표는 대시보드로\n[복구] 롤백 6분 목표, 되돌릴 수 없는 변경은 기능 플래그로 차단","cap":"실패 목록을 먼저 꺼내는 사람이 설계 면접 후반을 가져간다."},"key":["직렬로 의존하는 컴포넌트가 늘수록 전체 가용성은 곱해져 낮아진다","재시도는 타임아웃·지수 백오프·지터·상한과 함께가 아니면 장애를 키운다","알림은 원인이 아니라 사용자 영향(증상) 기준으로 걸고, 나머지는 대시보드로 본다"]}},{"t":"모니터링·관측성 질문","q":[{"t":"choice","k":"핵심 지표","q":"'무엇을 모니터링하시겠어요?'라는 질문에 좋은 출발점은?","ex":"자원 지표만 보면 사용자가 겪는 문제를 놓치고, 모든 예외에 알림을 걸면 알림 피로로 진짜 장애를 놓친다. 골든 시그널이 표준 출발점이다.\n면접에서는 '핵심 사용자 여정별로 성공률과 지연을 별도 지표로 뽑았습니다'라고 하면 제품 관점까지 보인다.","cat":"interview","o":["로그를 전부 수집해 나중에 검색할 수 있게 한다","에러가 발생하면 알림을 받도록 모든 예외에 알림을 건다","CPU, 메모리, 디스크 사용률을 모두 수집한다","사용자 영향을 나타내는 지표부터 잡는다 — 지연(특히 p95/p99), 트래픽, 오류율, 포화도의 네 가지 골든 시그널을 서비스별로 두고, 자원 지표는 원인 분석용으로 둔다"],"a":3},{"t":"choice","k":"알림 기준","q":"새벽에 사람을 깨우는 알림의 기준으로 가장 적절한 것은?","ex":"CPU 80%는 정상일 수도 있어 알림 가치가 낮다. 조치 불가능한 알림은 무시 습관을 만들어 실제 장애 대응을 늦춘다.\n면접에서는 '알림마다 대응 수칙 문서를 링크해 두고, 한 달간 아무 조치도 하지 않은 알림은 삭제했습니다'라고 하면 매우 좋다.","cat":"interview","o":["배포가 완료될 때마다","CPU 사용률이 80%를 넘을 때","사용자에게 영향이 나타나는 증상(오류율 상승, 지연 급증, SLO 소진 속도 초과)이면서 사람이 즉시 조치해야 하는 경우로 한정하고, 원인 지표는 대시보드에서 확인한다","어떤 예외든 로그에 ERROR가 찍힐 때"],"a":2},{"t":"choice","k":"관측성 3요소","q":"관측성을 이루는 세 가지 데이터와 각각의 역할로 옳은 것은?","ex":"지표는 넓고 싸게, 로그는 깊고 비싸게, 추적은 요청 단위 인과관계를 본다. 셋을 요청 ID로 연결하는 것이 관측성의 핵심이다.\n면접에서는 '추적 ID를 로그에 함께 남겨 지표에서 이상 -&gt; 추적에서 느린 구간 -&gt; 로그에서 원인 순으로 내려갑니다'라고 흐름을 말하면 좋다.","cat":"interview","o":["지표, 로그, 알림이 세 요소이며 셋 다 같은 정보를 다른 형태로 저장한다","로그만 충분히 남기면 지표와 추적은 필요 없다","분산 추적은 마이크로서비스에서만 의미가 있고 단일 애플리케이션에서는 쓸 수 없다","지표는 무엇이 언제 나빠졌는지 추세로 알려 주고, 로그는 개별 사건의 맥락을 남기며, 분산 추적은 하나의 요청이 서비스들을 지나며 어디서 시간을 썼는지 보여 준다"],"a":3},{"t":"input","k":"목표 지표","q":"'월간 성공률 99.9% 이상'처럼 서비스가 지켜야 할 신뢰성 목표를 뜻하는 영문 약어는?","ex":"SLI는 측정하는 지표, SLO는 그 목표치, SLA는 외부와 맺은 계약이다. SLO에서 남은 여유가 에러 버짓이 된다.\n면접에서는 '에러 버짓이 빠르게 소진되면 새 기능 배포를 멈추고 안정화에 투자하는 규칙을 두었습니다'라고 하면 운영 성숙도가 드러난다.","cat":"interview","a":["SLO","slo","Service Level Objective"]},{"t":"choice","k":"지표 집계","q":"응답 시간 모니터링에서 평균만 보는 것의 문제와 대안은?","ex":"평균 80ms에 p99 3초인 상황은 흔하고, 그 1%가 가장 활동적인 사용자일 수 있다. 분위수와 세분화가 필요하다.\n면접에서는 '분위수를 여러 인스턴스에서 단순 평균하면 왜곡되므로 원본 분포에서 집계해야 합니다'라고 짚으면 정확한 인상을 준다.","cat":"interview","o":["평균은 소수의 매우 느린 요청을 희석해 꼬리 지연을 숨기므로, p50/p95/p99 분위수를 함께 보고 사용자·엔드포인트별로 나눠 본다","평균은 정확하므로 문제 없고 분위수는 오차가 크다","응답 시간 대신 처리량만 보면 충분하다","평균은 계산 비용이 커서 문제이고 최댓값만 보면 된다"],"a":0},{"t":"choice","k":"장애 훈련","q":"'설계한 대로 실제로 버티는지 어떻게 확인하시겠어요?'라는 질문에 좋은 답변은?","ex":"쓰이지 않는 복구 절차는 장애 때 반드시 실패한다. 카오스 실험과 리허설이 설계와 현실의 간극을 드러낸다.\n면접에서는 '분기마다 마스터 DB 승격을 실제로 수행해 복구 시간을 측정했습니다'라고 하면 매우 강한 인상을 준다.","cat":"interview","o":["운영에서 문제가 생기면 그때 확인한다","부하 테스트로 한계 용량을 재고, 통제된 환경에서 인스턴스나 의존 서비스를 의도적으로 죽여 보는 장애 주입 훈련과 정기적인 장애 대응 리허설로 복구 절차와 알림이 실제로 동작하는지 검증한다","테스트 커버리지를 100%로 올린다","설계 문서를 상세히 작성해 리뷰를 받는다"],"a":1}],"th":{"sum":"면접 후반의 '이 컴포넌트가 죽으면 어떻게 되나요?'는 설계자의 성숙도를 가르는 질문이다. 실패를 예외가 아니라 기본 조건으로 다루는지를 본다.","body":[{"h":"면접관이 보는 것","t":"면접관은 정상 흐름만 그리는 사람과 실패 경로까지 그리는 사람을 나눈다. 그래서 각 컴포넌트를 하나씩 죽여 보며 무엇이 멈추고 무엇이 부분적으로 살아남는지 묻는다. 좋은 답변은 '이중화했습니다'가 아니라 '이 경우 기능이 이렇게 축소되고, 사용자는 이 정도 영향을 받으며, 복구는 이렇게 됩니다'까지 간다. 모니터링 질문에서는 무엇을 지표로 삼고 언제 사람을 깨울지 기준이 있는지가 핵심이며, 알림을 많이 건다는 답은 오히려 감점이다."},{"h":"답변 구조","t":"실패 지점 열거 → 영향 범위 → 격리 수단 → 감지 → 복구 순으로 답한다. 먼저 SPOF를 스스로 짚고, 각각에 대해 이중화·격벽·회로 차단 중 무엇을 쓸지 말한다. 그다음 '이 장애를 몇 초 안에 어떤 지표로 감지하는가'를 붙여야 설계가 운영과 연결된다. 마지막으로 성능 저하 모드(graceful degradation)를 제시하면, 전부 아니면 전무가 아닌 현실적인 설계자로 평가된다."}],"code":{"c":"[컴포넌트별 실패 시나리오]\n캐시 다운   -> DB 직격. 대응: 회로 차단 + 요청 제한 + 일부 기능 축소\nDB 마스터   -> 쓰기 중단. 대응: 자동 승격(수십 초) + 그동안 읽기 전용 모드\n큐 지연     -> 알림 지연. 대응: 가장 오래된 메시지 나이 알림, 우선순위 큐 분리\n외부 결제사 -> 결제 실패. 대응: 타임아웃 + 서킷 브레이커 + 대체 채널 안내\n한 AZ 상실  -> 용량 1/3 감소. 대응: 3개 AZ 분산 + 여유 용량 30%\n\n[감지] 증상 기반 알림 — 오류율/지연 SLO 소진 속도로 호출, 원인 지표는 대시보드로\n[복구] 롤백 6분 목표, 되돌릴 수 없는 변경은 기능 플래그로 차단","cap":"실패 목록을 먼저 꺼내는 사람이 설계 면접 후반을 가져간다."},"key":["직렬로 의존하는 컴포넌트가 늘수록 전체 가용성은 곱해져 낮아진다","재시도는 타임아웃·지수 백오프·지터·상한과 함께가 아니면 장애를 키운다","알림은 원인이 아니라 사용자 영향(증상) 기준으로 걸고, 나머지는 대시보드로 본다"]}}]},{"t":"코드 리뷰 — 설계 결함 찾기","l":[{"t":"코드 리뷰 I","q":[{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"async function getUser(id) {\n  const cached = await redis.get('user:' + id);\n  if (cached) return JSON.parse(cached);\n  const user = await db.query('SELECT * FROM users WHERE id=$1', [id]);\n  await redis.set('user:' + id, JSON.stringify(user));\n  return user;\n}","items":[{"txt":"캐시에 만료 시간이 없어, 사용자 정보가 바뀌어도 영원히 옛 값을 돌려준다.","bad":true},{"txt":"같은 id 에 대한 동시 요청이 각각 DB 를 친다. 캐시 미스가 몰리면 DB 로 부하가 그대로 전달된다(스탬피드).","bad":true},{"txt":"DB 결과가 없을 때도 캐시하지 않아, 존재하지 않는 id 로 반복 요청하면 매번 DB 를 친다(캐시 관통).","bad":true},{"txt":"Redis 조회가 실패하면 함수 전체가 예외로 끝나므로, 캐시 장애가 곧 서비스 장애가 된다.","bad":false},{"txt":"JSON.parse 를 쓰면 숫자 정밀도가 손실되므로 반드시 바이너리 직렬화를 써야 한다.","bad":false},{"txt":"SELECT * 대신 필요한 컬럼만 조회하지 않아 캐시 크기가 커지는 것이 이 코드의 핵심 결함이다.","bad":false}],"ex":"결함 3가지: (1) TTL 없음 — 무효화 경로가 없으면 캐시는 영구 오답이 된다. (2) 스탬피드 — 진행 중인 조회를 공유하는 single-flight 가 필요하다. (3) 캐시 관통 — 빈 결과도 짧은 TTL 로 캐시한다. 디스트랙터: 네 번째는 실제로 고려할 만하지만 이 코드만으로는 상위 처리 여부를 알 수 없어 결함으로 단정하지 않는다. JSON 정밀도 손실은 아주 큰 정수에서만 문제이고, SELECT * 는 개선 여지일 뿐 '핵심 결함' 이 아니다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"POST /api/orders\n{ \"items\": [...], \"total\": 32000 }\n\n→ 서버: 주문 생성 후 201 + { orderId }\n→ 클라이언트: 네트워크 오류 시 같은 요청을 3회까지 재시도","items":[{"txt":"재시도에 멱등성 키가 없어, 응답만 유실된 경우 같은 주문이 여러 번 생성된다.","bad":true},{"txt":"금액(total)을 클라이언트가 보낸 값으로 신뢰한다. 서버가 상품 가격으로 다시 계산해야 한다.","bad":true},{"txt":"POST 는 멱등하지 않으므로 어떤 방법으로도 안전한 재시도가 불가능하다.","bad":false},{"txt":"201 대신 200 을 반환해야 클라이언트가 재시도 여부를 판단할 수 있다.","bad":false},{"txt":"orderId 를 응답에 담으면 순차 증가 값이 노출되어 반드시 UUID 를 써야 한다.","bad":false},{"txt":"재시도 횟수를 3회로 제한하면 일시적 장애에서 요청이 유실되므로 무제한이어야 한다.","bad":false}],"ex":"결함 2가지: (1) 멱등성 키 부재 — 결제·주문에서 가장 비싼 버그다. 클라이언트가 생성한 키를 헤더로 보내고 서버가 중복을 흡수한다. (2) 클라이언트 금액 신뢰 — 가격은 서버 권위 데이터로 재계산한다. 디스트랙터: 멱등성 키를 쓰면 POST 도 안전하게 재시도할 수 있다. 상태 코드는 이 문제와 무관하다. 순차 ID 노출은 별개 논점이고, 무제한 재시도는 오히려 장애를 키운다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"서비스 A → 서비스 B → 서비스 C  (동기 HTTP 체인)\nA 의 타임아웃 30s / B 의 타임아웃 30s / C 의 평균 응답 200ms","items":[{"txt":"호출 깊이가 늘어도 타임아웃이 줄지 않는다. C 가 느려지면 B 와 A 의 스레드가 함께 묶여 전체가 무너진다. 남은 예산에서 차감하는 방식이어야 한다.","bad":true},{"txt":"동기 체인이라 C 의 장애가 A 까지 그대로 전파된다. 회로 차단기나 비동기 경계가 없다.","bad":true},{"txt":"30초는 사용자 대기 한계를 훨씬 넘는다. 실패를 빨리 알리는 편이 낫다.","bad":true},{"txt":"서비스가 3단계면 반드시 이벤트 기반으로 바꿔야 하며 동기 호출은 어떤 경우에도 안티패턴이다.","bad":false},{"txt":"타임아웃을 동일하게 맞추면 재시도 폭풍이 방지되므로 이 구성이 오히려 안전하다.","bad":false},{"txt":"C 의 평균 응답이 200ms 이므로 타임아웃 값은 성능에 아무 영향을 주지 않는다.","bad":false}],"ex":"결함 3가지: (1) 타임아웃 예산 미차감 — 상류가 하류보다 짧아야 한다. (2) 격리 없음 — 회로 차단기·벌크헤드. (3) 과도한 타임아웃 값. 디스트랙터: 동기 호출이 항상 안티패턴은 아니다. 같은 타임아웃은 재시도 폭풍과 무관하고, 평균이 좋아도 꼬리 지연이 문제를 만든다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"주문 생성 트랜잭션:\n  BEGIN\n    INSERT INTO orders ...\n    UPDATE inventory SET stock = stock - 1 ...\n    HTTP POST https://payment.example.com/charge\n    INSERT INTO payments ...\n  COMMIT","items":[{"txt":"트랜잭션 안에서 외부 결제 API 를 호출한다. DB 커넥션을 쥔 채 네트워크를 기다리므로 결제사가 느려지면 커넥션 풀이 고갈된다.","bad":true},{"txt":"결제가 성공했는데 COMMIT 이 실패하면 돈은 빠져나가고 주문은 없다. 외부 부수효과는 롤백되지 않는다.","bad":true},{"txt":"결제 호출에 멱등성 키가 없어, 재시도 시 이중 청구가 발생한다.","bad":true},{"txt":"INSERT 와 UPDATE 를 한 트랜잭션에 묶으면 락 경합이 생기므로 분리해야 한다.","bad":false},{"txt":"stock = stock - 1 은 원자적이지 않으므로 반드시 SELECT FOR UPDATE 로 감싸야 한다.","bad":false},{"txt":"COMMIT 을 명시하면 자동 커밋과 충돌해 트랜잭션이 두 번 커밋된다.","bad":false}],"ex":"결함 3가지: (1) 트랜잭션 안의 외부 I/O. (2) 롤백 불가능한 부수효과 — 결제를 먼저 승인만 하고 커밋 후 확정하거나, Saga 로 보상 트랜잭션을 둔다. (3) 멱등성 키 부재. 디스트랙터: 주문과 재고를 한 트랜잭션에 두는 것은 정합성을 위해 오히려 맞다. stock = stock - 1 은 DB 가 원자적으로 처리한다. 명시적 COMMIT 은 정상이다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"class RateLimiter {\n  constructor() { this.counts = new Map(); }\n  allow(userId) {\n    const n = (this.counts.get(userId) || 0) + 1;\n    this.counts.set(userId, n);\n    return n &lt;= 100;\n  }\n}","items":[{"txt":"시간 창이 없어 카운터가 초기화되지 않는다. 한 번 100을 넘긴 사용자는 프로세스 재시작 전까지 영구 차단된다.","bad":true},{"txt":"인스턴스 메모리에 상태를 두어, 서버를 여러 대로 늘리면 실제 허용량이 대수만큼 늘어난다.","bad":true},{"txt":"Map 이 무한히 커진다. 사용자 수만큼 항목이 쌓이고 제거되지 않는다.","bad":true},{"txt":"Map 대신 객체를 쓰면 프로토타입 오염이 발생하므로 이 구현은 이미 안전하다.","bad":false},{"txt":"allow 가 동기 함수라 비동기 저장소로 바꿀 수 없어 확장이 불가능하다.","bad":false},{"txt":"100 이라는 상한을 하드코딩하면 사용자별 등급을 구분할 수 없는 것이 가장 심각한 결함이다.","bad":false}],"ex":"결함 3가지: (1) 시간 창 부재. (2) 인스턴스별 상태 — 공유 저장소(Redis)의 원자적 카운터가 필요하다. (3) 메모리 누수. 디스트랙터: 네 번째는 Map 을 쓴 것이 오히려 옳다는 설명이라 결함이 아니다. 시그니처는 리팩터링으로 바꿀 수 있고, 등급별 상한은 기능 요구이지 이 코드의 결함이 아니다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"이벤트 소싱:\n  주문 생성 → OrderCreated 발행\n  결제 완료 → PaymentCompleted 발행\n  소비자는 이벤트를 받아 읽기 모델을 갱신한다.\n  이벤트는 파티션 키 없이 발행된다.","items":[{"txt":"파티션 키가 없어 같은 주문의 이벤트가 다른 파티션으로 흩어진다. 순서가 보장되지 않아 결제 완료가 주문 생성보다 먼저 처리될 수 있다.","bad":true},{"txt":"소비자가 멱등하지 않으면 재배달 시 읽기 모델이 중복 반영된다. 최소 한 번 배달이 기본이다.","bad":true},{"txt":"이벤트 스키마 버전 관리가 없어, 필드를 바꾸면 옛 소비자가 깨진다.","bad":true},{"txt":"이벤트 소싱을 쓰면 읽기 모델이 항상 즉시 일관되므로 지연을 고려할 필요가 없다.","bad":false},{"txt":"이벤트를 발행하면 원본 트랜잭션이 자동으로 롤백 가능해진다.","bad":false},{"txt":"소비자가 여럿이면 이벤트를 각각 복제해야 하므로 저장소 비용이 소비자 수만큼 늘어난다.","bad":false}],"ex":"결함 3가지: (1) 순서 보장 없음. (2) 멱등하지 않은 소비. (3) 스키마 진화 전략 부재. 디스트랙터: 읽기 모델은 최종 일관성이라 지연을 반드시 고려해야 한다(서술이 반대). 이벤트 발행은 DB 트랜잭션과 원자적이지 않다. 로그 기반 브로커는 하나의 로그를 여러 소비자가 각자 오프셋으로 읽으므로 복제 비용이 소비자 수에 비례하지 않는다."}],"th":{"sum":"설계 리뷰는 **정상 경로가 아니라 실패·경쟁·확장 경로**를 본다: 이게 죽으면 무엇이 함께 죽는가, 동시에 오면 어떻게 되는가, 10배가 되면 어디가 먼저 무너지는가.","body":[{"h":"장애는 전파된다","t":"동기 호출 체인에서 하류가 느려지면 상류의 스레드·커넥션이 함께 묶인다. 타임아웃은 깊이가 늘수록 줄어야 하고(예산 차감), 의존성별로 자원을 나누고(벌크헤드), 반복 실패는 회로를 열어 끊어야 한다. liveness 에 외부 의존성을 넣으면 남의 장애가 우리 인스턴스 재시작으로 번진다. 관측 도구도 마찬가지다 — 로그 전송 실패가 요청 실패가 되면 안 된다."},{"h":"동시에 오면 무슨 일이 생기는가","t":"읽고 계산해 쓰는 모든 코드는 경쟁을 의심한다. 캐시 미스가 몰리면 DB 로 그대로 전달되고(스탬피드), 재시도에 백오프·지터가 없으면 부하가 동기화돼 장애를 키운다. 분산 락에는 만료·소유자 확인·작업 시간 초과 대비가 모두 필요하다. 재시도되는 쓰기에는 멱등성 키가 있어야 한다."},{"h":"최종 일관성은 UI 까지 온다","t":"복제 지연 때문에 방금 쓴 데이터가 안 보이고, 이벤트 순서가 뒤바뀌면 존재하지 않는 주문이 취소된다. DB 커밋과 이벤트 발행은 원자적이지 않으므로 Outbox 가 필요하고, 소비는 최소 한 번 배달을 전제로 멱등해야 한다. 캐시 무효화는 파생 캐시까지 함께 다뤄야 한다."},{"h":"10배가 되면 어디가 먼저 무너지는가","t":"무제한 큐·상한 없는 페이지 크기·깊은 OFFSET·전량 재계산 배치는 규모에 비례해 무너진다. 나머지 연산 샤딩은 확장 시 전면 재배치를 부른다. 지표 레이블에 사용자 ID 를 넣으면 시계열이 폭발한다. '지금 되는가' 가 아니라 '10배에서도 되는가' 를 묻는다."}],"code":{"c":"// 결함: 트랜잭션 안 외부 호출 + 롤백 불가 부수효과 + 멱등성 없음\nBEGIN\n  INSERT INTO orders ...\n  UPDATE inventory SET stock = stock - 1 ...\n  HTTP POST /charge          // 커넥션을 쥔 채 네트워크 대기\n  INSERT INTO payments ...\nCOMMIT                       // 여기서 실패하면 돈만 나간다\n\n// 고침: 경계를 나누고, 부수효과는 멱등하게, 실패는 보상한다\n1) BEGIN; 주문 생성(status=PENDING); 재고 예약; COMMIT\n2) 결제 호출 (Idempotency-Key: orderId, 타임아웃, 회로 차단기)\n3) BEGIN; 결과에 따라 CONFIRMED / 재고 반환; COMMIT\n   실패·타임아웃은 조회 API 로 실제 상태를 확인해 정리(보상 트랜잭션)","cap":"외부 부수효과는 롤백되지 않는다 — 경계를 나누고 보상 경로를 둔다"},"key":["트랜잭션 안에 외부 I/O 를 두지 않는다. 외부 부수효과는 롤백되지 않는다","재시도되는 쓰기에는 멱등성 키, 재시도에는 지수 백오프+지터","타임아웃은 호출 깊이만큼 차감하고, 의존성별로 자원을 격리한다","liveness·로그 전송 같은 부수 경로가 서비스를 인질로 잡지 않게 한다","최종 일관성은 화면까지 온다 — 순서 보장, 멱등 소비, read-your-writes","무제한 큐·상한 없는 페이지·깊은 OFFSET·전량 배치는 규모에서 먼저 무너진다"]}},{"t":"코드 리뷰 II","q":[{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"GET /api/products?page=1&amp;size=20   →  OFFSET 0  LIMIT 20\nGET /api/products?page=5000&amp;size=20 →  OFFSET 99980 LIMIT 20","items":[{"txt":"OFFSET 기반 페이지네이션은 뒤로 갈수록 앞의 행을 모두 훑어야 해 선형으로 느려진다. 커서 기반으로 바꿔야 한다.","bad":true},{"txt":"페이지를 넘기는 사이에 데이터가 삽입·삭제되면 같은 항목이 두 페이지에 나오거나 누락된다.","bad":true},{"txt":"size 에 상한이 없어 size=1000000 같은 요청 하나로 DB 를 마비시킬 수 있다.","bad":true},{"txt":"page 가 1부터 시작하면 0-based 인덱스와 어긋나 계산 오류가 나므로 0부터 시작해야 한다.","bad":false},{"txt":"OFFSET 은 인덱스를 사용하지 못하므로 어떤 경우에도 인덱스가 무의미하다.","bad":false},{"txt":"페이지네이션 응답에 전체 개수를 포함하지 않으면 클라이언트가 렌더링할 수 없다.","bad":false}],"ex":"결함 3가지: (1) 깊은 OFFSET 의 비용. (2) 불안정한 페이지 경계. (3) size 상한 없음. 디스트랙터: 1-based 는 관례 차이일 뿐이다. OFFSET 도 정렬 인덱스를 쓰지만 건너뛴 행을 세느라 느려지는 것이다. 전체 개수 없이도 '더 보기' UI 는 충분히 만들 수 있고, COUNT 는 오히려 비싸다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"파일 업로드:\n  클라이언트 → API 서버(멀티파트 수신) → S3 업로드 → DB 에 URL 저장 → 응답\n  API 서버는 오토스케일링 그룹, 파일 평균 200MB","items":[{"txt":"대용량 파일이 API 서버를 통과한다. 메모리·대역폭·요청 시간을 모두 소비해 일반 API 까지 영향을 준다. 사전 서명 URL 로 클라이언트가 직접 올려야 한다.","bad":true},{"txt":"S3 업로드 성공 후 DB 저장이 실패하면 참조 없는 고아 객체가 남는다. 정리 경로가 없다.","bad":true},{"txt":"업로드 시간이 길어 로드밸런서·프록시 타임아웃에 걸리기 쉽다.","bad":true},{"txt":"멀티파트 업로드는 HTTP 표준이 아니므로 반드시 base64 로 인코딩해 JSON 으로 보내야 한다.","bad":false},{"txt":"오토스케일링을 쓰면 업로드 중 인스턴스가 교체되어도 세션이 자동으로 이어진다.","bad":false},{"txt":"S3 는 강한 일관성을 보장하지 않으므로 업로드 직후 조회는 항상 실패한다.","bad":false}],"ex":"결함 3가지: (1) 서버 경유 업로드. (2) 고아 객체 — 먼저 DB 에 pending 레코드를 만들고 완료 콜백으로 확정하거나, 수명주기 정책으로 정리한다. (3) 타임아웃. 디스트랙터: 멀티파트는 표준이고 base64 는 크기를 33% 늘린다. 인스턴스가 교체되면 진행 중 업로드는 끊긴다. S3 는 현재 강한 읽기 일관성을 제공한다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"서비스 헬스체크:\n  GET /health → DB, Redis, 결제사 API, 메일 서버를 모두 확인하고 200/503 반환\n  오케스트레이터는 이 값으로 인스턴스를 재시작한다.","items":[{"txt":"외부 결제사·메일 서버의 상태가 우리 인스턴스의 생존 판정에 들어간다. 남의 장애가 우리 인스턴스 전체 재시작으로 번진다.","bad":true},{"txt":"liveness 와 readiness 를 구분하지 않았다. 의존성 검사는 트래픽 수용 여부(readiness)에 써야 하고, 프로세스 생존 판정에 쓰면 재시작 루프가 된다.","bad":true},{"txt":"검사에 타임아웃이 없으면 헬스체크 자체가 매달려 결국 실패로 처리된다.","bad":true},{"txt":"헬스체크는 인증을 걸어야 하므로 공개 엔드포인트인 것이 가장 큰 문제다.","bad":false},{"txt":"503 대신 500 을 반환해야 오케스트레이터가 상태를 올바르게 해석한다.","bad":false},{"txt":"모든 의존성을 순차로 확인하면 응답이 느려지므로 헬스체크는 항상 캐시된 값만 반환해야 한다.","bad":false}],"ex":"결함 3가지: (1) 외부 의존성 포함 — 연쇄 장애 증폭. (2) liveness/readiness 미분리. (3) 타임아웃 부재. 디스트랙터: 인증은 고려사항이지만 상태만 반환한다면 큰 문제가 아니다. 503 이 올바른 코드다. 캐시는 유용한 최적화지만 '항상' 은 과하다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"분산 락:\n  const ok = await redis.set('lock:' + jobId, '1', 'NX');\n  if (ok) { await runJob(); await redis.del('lock:' + jobId); }","items":[{"txt":"락에 만료 시간이 없다. 작업 중 프로세스가 죽으면 락이 영원히 남아 이후 실행이 모두 막힌다.","bad":true},{"txt":"소유자 확인 없이 삭제한다. 내 락이 만료된 뒤 남이 잡은 락을 내가 지울 수 있다.","bad":true},{"txt":"runJob 이 락 만료보다 오래 걸리면 두 인스턴스가 동시에 실행된다. 갱신(lease) 이나 펜싱 토큰이 필요하다.","bad":true},{"txt":"SET NX 는 원자적이지 않으므로 Lua 스크립트로 감싸야 한다.","bad":false},{"txt":"Redis 분산 락은 단일 인스턴스에서도 안전성이 보장되지 않으므로 어떤 경우에도 쓰면 안 된다.","bad":false},{"txt":"del 대신 expire 를 호출해야 락이 정상적으로 해제된다.","bad":false}],"ex":"결함 3가지: (1) 만료 없음. (2) 소유자 미확인 — 랜덤 토큰을 값으로 넣고 Lua 로 비교 후 삭제. (3) 작업 시간 > 락 수명. 디스트랙터: SET NX 자체는 원자적이다. Redis 락은 한계가 있지만 상황에 따라 실용적이며 '어떤 경우에도' 는 과하다. 해제는 del 이 맞다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"읽기 확장:\n  쓰기 → 프라이머리\n  읽기 → 리드 레플리카 (비동기 복제)\n  주문 생성 직후 주문 목록을 리드 레플리카에서 조회","items":[{"txt":"복제 지연 때문에 방금 만든 주문이 목록에 없을 수 있다. 사용자에게는 '저장이 안 됐다' 로 보인다.","bad":true},{"txt":"자기가 쓴 것은 자기가 읽어야 한다는 보장(read-your-writes)이 없다. 쓰기 직후 일정 시간은 프라이머리에서 읽어야 한다.","bad":true},{"txt":"비동기 복제를 쓰면 데이터가 반드시 유실되므로 동기 복제만이 유일한 선택지다.","bad":false},{"txt":"리드 레플리카는 쓰기를 받지 않으므로 트랜잭션 안에서는 아예 조회할 수 없다.","bad":false},{"txt":"복제 지연은 네트워크 문제이므로 애플리케이션에서 대응할 방법이 없다.","bad":false},{"txt":"읽기와 쓰기를 분리하면 커넥션 풀이 두 배로 필요해 리소스 낭비가 가장 큰 문제다.","bad":false}],"ex":"결함 2가지: 같은 뿌리 — 최종 일관성을 UI 흐름이 고려하지 않았다. 쓰기 직후 N초는 프라이머리로 라우팅하거나, 응답으로 받은 객체를 그대로 화면에 반영해 재조회를 피한다. 디스트랙터: 비동기 복제는 성능과 가용성의 정당한 선택이다. 레플리카에서 읽기 트랜잭션은 가능하다. 애플리케이션 레벨 대응은 존재한다(위의 해법). 커넥션 풀 증가는 감수할 만한 비용이다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"알림 발송:\n  cron 매분 → 발송 대상 조회 → for (user of users) await sendPush(user)\n  대상 평균 12만 명, sendPush 평균 80ms","items":[{"txt":"순차 발송이라 12만 명 × 80ms = 2시간 40분이 걸린다. 매분 실행되므로 실행이 무한히 겹친다.","bad":true},{"txt":"겹침 방지 장치가 없어 같은 대상에게 중복 발송된다.","bad":true},{"txt":"실패한 발송을 재시도하거나 기록하는 경로가 없어 조용히 유실된다.","bad":true},{"txt":"cron 대신 이벤트 기반으로 바꾸지 않으면 어떤 최적화도 효과가 없다.","bad":false},{"txt":"await 를 for 문에서 쓰면 병렬 실행되어 푸시 서버가 과부하되므로 순차가 옳다.","bad":false},{"txt":"12만 건을 한 번에 조회하면 메모리를 쓰므로 반드시 스트리밍 커서를 써야 하며 이것이 유일한 결함이다.","bad":false}],"ex":"결함 3가지: (1) 순차 처리로 인한 실행 시간. (2) 겹침 방지 없음 — 분산 락이나 실행 중 플래그. (3) 실패 처리 없음. 디스트랙터: 배치 자체가 잘못된 것은 아니고 동시성·분할로 해결된다. for-await 는 병렬이 아니라 순차다(서술이 반대). 스트리밍 조회는 좋은 개선이지만 '유일한 결함' 이 아니다."}],"th":{"sum":"설계 리뷰는 **정상 경로가 아니라 실패·경쟁·확장 경로**를 본다: 이게 죽으면 무엇이 함께 죽는가, 동시에 오면 어떻게 되는가, 10배가 되면 어디가 먼저 무너지는가.","body":[{"h":"장애는 전파된다","t":"동기 호출 체인에서 하류가 느려지면 상류의 스레드·커넥션이 함께 묶인다. 타임아웃은 깊이가 늘수록 줄어야 하고(예산 차감), 의존성별로 자원을 나누고(벌크헤드), 반복 실패는 회로를 열어 끊어야 한다. liveness 에 외부 의존성을 넣으면 남의 장애가 우리 인스턴스 재시작으로 번진다. 관측 도구도 마찬가지다 — 로그 전송 실패가 요청 실패가 되면 안 된다."},{"h":"동시에 오면 무슨 일이 생기는가","t":"읽고 계산해 쓰는 모든 코드는 경쟁을 의심한다. 캐시 미스가 몰리면 DB 로 그대로 전달되고(스탬피드), 재시도에 백오프·지터가 없으면 부하가 동기화돼 장애를 키운다. 분산 락에는 만료·소유자 확인·작업 시간 초과 대비가 모두 필요하다. 재시도되는 쓰기에는 멱등성 키가 있어야 한다."},{"h":"최종 일관성은 UI 까지 온다","t":"복제 지연 때문에 방금 쓴 데이터가 안 보이고, 이벤트 순서가 뒤바뀌면 존재하지 않는 주문이 취소된다. DB 커밋과 이벤트 발행은 원자적이지 않으므로 Outbox 가 필요하고, 소비는 최소 한 번 배달을 전제로 멱등해야 한다. 캐시 무효화는 파생 캐시까지 함께 다뤄야 한다."},{"h":"10배가 되면 어디가 먼저 무너지는가","t":"무제한 큐·상한 없는 페이지 크기·깊은 OFFSET·전량 재계산 배치는 규모에 비례해 무너진다. 나머지 연산 샤딩은 확장 시 전면 재배치를 부른다. 지표 레이블에 사용자 ID 를 넣으면 시계열이 폭발한다. '지금 되는가' 가 아니라 '10배에서도 되는가' 를 묻는다."}],"code":{"c":"// 결함: 트랜잭션 안 외부 호출 + 롤백 불가 부수효과 + 멱등성 없음\nBEGIN\n  INSERT INTO orders ...\n  UPDATE inventory SET stock = stock - 1 ...\n  HTTP POST /charge          // 커넥션을 쥔 채 네트워크 대기\n  INSERT INTO payments ...\nCOMMIT                       // 여기서 실패하면 돈만 나간다\n\n// 고침: 경계를 나누고, 부수효과는 멱등하게, 실패는 보상한다\n1) BEGIN; 주문 생성(status=PENDING); 재고 예약; COMMIT\n2) 결제 호출 (Idempotency-Key: orderId, 타임아웃, 회로 차단기)\n3) BEGIN; 결과에 따라 CONFIRMED / 재고 반환; COMMIT\n   실패·타임아웃은 조회 API 로 실제 상태를 확인해 정리(보상 트랜잭션)","cap":"외부 부수효과는 롤백되지 않는다 — 경계를 나누고 보상 경로를 둔다"},"key":["트랜잭션 안에 외부 I/O 를 두지 않는다. 외부 부수효과는 롤백되지 않는다","재시도되는 쓰기에는 멱등성 키, 재시도에는 지수 백오프+지터","타임아웃은 호출 깊이만큼 차감하고, 의존성별로 자원을 격리한다","liveness·로그 전송 같은 부수 경로가 서비스를 인질로 잡지 않게 한다","최종 일관성은 화면까지 온다 — 순서 보장, 멱등 소비, read-your-writes","무제한 큐·상한 없는 페이지·깊은 OFFSET·전량 배치는 규모에서 먼저 무너진다"]}},{"t":"코드 리뷰 III","q":[{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"API 게이트웨이:\n  모든 요청에서 인증 서버로 토큰 검증 HTTP 호출 (동기)\n  인증 서버는 단일 인스턴스","items":[{"txt":"모든 요청이 인증 서버를 거치는데 단일 인스턴스라 단일 장애점이다. 여기가 죽으면 전체 서비스가 멈춘다.","bad":true},{"txt":"요청마다 네트워크 왕복이 추가돼 지연이 붙는다. 서명 검증은 게이트웨이에서 로컬로 할 수 있다.","bad":true},{"txt":"검증 결과 캐시가 없어 같은 토큰을 반복 검증한다.","bad":true},{"txt":"토큰 검증을 게이트웨이에서 하면 각 서비스가 인증을 신뢰할 수 없으므로 서비스마다 다시 검증해야 한다.","bad":false},{"txt":"동기 호출이므로 인증 서버가 느려도 게이트웨이 성능에는 영향이 없다.","bad":false},{"txt":"단일 인스턴스라도 오토스케일링이 있으면 장애점이 아니다.","bad":false}],"ex":"결함 3가지: (1) 단일 장애점. (2) 불필요한 왕복 — JWT 라면 공개키로 로컬 검증. (3) 캐시 없음. 디스트랙터: 게이트웨이 검증 후 내부 신뢰 경계를 두는 것은 일반적인 설계다. 동기 호출은 당연히 성능에 영향을 준다. 오토스케일링이 있어도 인스턴스가 하나면 장애점이다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"멀티테넌트 SaaS:\n  모든 테넌트가 같은 테이블을 공유하고, 쿼리에 WHERE tenant_id = ? 를 붙인다.\n  ORM 의 기본 조회 메서드에는 자동 적용되지 않는다.","items":[{"txt":"테넌트 필터가 자동 적용되지 않아, 한 곳에서 빼먹으면 다른 회사의 데이터가 노출된다. 사고의 심각도가 매우 높다.","bad":true},{"txt":"한 테넌트의 대용량 데이터가 다른 테넌트의 쿼리 성능에 영향을 준다(노이지 네이버).","bad":true},{"txt":"테넌트별 백업·복구·삭제가 어렵다. 규정상 데이터 삭제 요구에 대응하기 힘들다.","bad":true},{"txt":"공유 테이블 방식은 어떤 경우에도 잘못된 설계이며 테넌트마다 DB 를 분리해야 한다.","bad":false},{"txt":"tenant_id 를 인덱스 선두 컬럼으로 두면 다른 조건의 인덱스를 쓸 수 없게 된다.","bad":false},{"txt":"ORM 을 쓰면 SQL 인젝션이 자동으로 방지되므로 보안 검토가 필요 없다.","bad":false}],"ex":"결함 3가지: (1) 강제되지 않는 격리 — 정책 레벨(RLS)이나 저장소 레이어에서 필터를 강제해야 한다. (2) 노이지 네이버. (3) 테넌트 단위 운영의 어려움. 디스트랙터: 공유 테이블은 비용 효율이 높아 널리 쓰이는 정당한 선택이다. tenant_id 선두 복합 인덱스는 오히려 표준 패턴이다. ORM 도 원시 쿼리에서는 인젝션이 가능하다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"배치 처리:\n  매일 새벽 전체 사용자의 포인트를 재계산한다.\n  UPDATE users SET points = (SELECT ...) ;   -- 단일 쿼리, 2,400만 행","items":[{"txt":"단일 트랜잭션으로 2,400만 행을 갱신해 락과 WAL 이 폭발한다. 배치로 쪼개야 한다.","bad":true},{"txt":"중간에 실패하면 전부 롤백되어 몇 시간의 작업이 사라지고, 재실행도 처음부터다. 진행 지점 기록이 필요하다.","bad":true},{"txt":"전량 재계산이라 변경되지 않은 사용자까지 다시 쓴다. 증분 계산이 가능한지 검토해야 한다.","bad":true},{"txt":"UPDATE 에 서브쿼리를 쓰면 항상 행마다 실행되므로 조인으로 바꾸는 것이 유일한 해법이다.","bad":false},{"txt":"새벽에 실행하면 트래픽이 적으므로 락 경합은 고려할 필요가 없다.","bad":false},{"txt":"포인트를 컬럼으로 저장하지 말고 매번 계산해야 하므로 이 설계 자체가 잘못이다.","bad":false}],"ex":"결함 3가지: (1) 거대 트랜잭션. (2) 재개 불가. (3) 전량 재계산. 디스트랙터: 서브쿼리는 최적화기가 조인으로 변환하기도 한다. 새벽에도 복제 지연과 백업 작업이 있어 락은 문제가 된다. 미리 계산해 저장하는 것은 조회 성능을 위한 정당한 선택이다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"검색 기능:\n  사용자 입력 → SELECT * FROM posts WHERE title LIKE '%' || $1 || '%' OR body LIKE '%' || $1 || '%'\n  posts 는 4,000만 행","items":[{"txt":"앞뒤 와일드카드 LIKE 는 인덱스를 쓸 수 없어 4,000만 행을 매번 전부 훑는다.","bad":true},{"txt":"검색어 길이·문자 제한이 없어 한 글자 검색이 사실상 전체 스캔 요청이 된다.","bad":true},{"txt":"결과 개수 제한이 없어 매칭이 많으면 한 요청으로 대량 데이터를 끌어온다.","bad":true},{"txt":"파라미터 바인딩을 쓰고 있으므로 SQL 인젝션 위험이 남아 있다.","bad":false},{"txt":"OR 조건을 쓰면 옵티마이저가 항상 인덱스를 무시하므로 UNION 으로 바꾸는 것이 유일한 해법이다.","bad":false},{"txt":"LIKE 는 대소문자를 구분하지 않으므로 검색 정확도가 떨어지는 것이 핵심 결함이다.","bad":false}],"ex":"결함 3가지: (1) 인덱스를 쓸 수 없는 검색 — 전문 검색 인덱스나 검색 엔진으로. (2) 최소 길이 제한 없음. (3) 결과 상한 없음. 디스트랙터: 바인딩을 쓰므로 인젝션은 없다(서술이 반대). OR 는 상황에 따라 인덱스 결합이 가능하고 UNION 이 '유일' 하지 않다. LIKE 의 대소문자 구분은 DB 설정에 따르며 여기서는 핵심이 아니다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"서비스 간 통신:\n  주문 서비스가 사용자 서비스의 users 테이블을 직접 조회한다 (같은 DB 인스턴스, 다른 스키마)","items":[{"txt":"다른 서비스의 데이터를 직접 읽어 스키마 결합이 생긴다. 사용자 서비스가 컬럼을 바꾸면 주문 서비스가 깨진다.","bad":true},{"txt":"데이터 소유권이 모호해져 변경 영향 범위를 알 수 없다. 서비스를 분리한 이점이 사라진다.","bad":true},{"txt":"독립 배포가 불가능해진다. 스키마 변경 시 두 서비스를 함께 배포해야 한다.","bad":true},{"txt":"같은 DB 인스턴스를 쓰면 트랜잭션이 자동으로 분산되어 정합성이 보장된다.","bad":false},{"txt":"직접 조회가 API 호출보다 느리므로 성능상 불리한 것이 주된 문제다.","bad":false},{"txt":"스키마를 분리했으므로 결합은 없고, 물리적으로 같은 인스턴스인 것만이 문제다.","bad":false}],"ex":"결함 3가지: 전부 같은 뿌리인 '공유 데이터베이스 안티패턴' 이다. (1) 스키마 결합. (2) 소유권 모호. (3) 독립 배포 불가. API 나 이벤트로만 접근하게 하고, 필요하면 읽기 전용 복제본을 별도로 제공한다. 디스트랙터: 같은 인스턴스여도 자동 분산 트랜잭션은 없다. 직접 조회는 오히려 빠르다 — 문제는 성능이 아니라 결합이다. 스키마 분리는 논리적 구분일 뿐 결합을 막지 못한다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"장애 대응:\n  결제 API 호출 실패 시 → 즉시 재시도 5회 (간격 없음)\n  모든 인스턴스가 같은 정책을 사용","items":[{"txt":"백오프가 없어 상대가 힘들어하는 순간에 부하를 5배로 키운다. 지수 백오프가 필요하다.","bad":true},{"txt":"모든 인스턴스가 동시에 재시도해 부하가 동기화된다. 무작위 지터가 필요하다.","bad":true},{"txt":"재시도 가능 여부를 구분하지 않는다. 400 처럼 재시도해도 성공할 수 없는 오류까지 5번 보낸다.","bad":true},{"txt":"재시도 횟수를 5회로 제한하면 일시적 장애를 넘기지 못하므로 무제한이어야 한다.","bad":false},{"txt":"모든 인스턴스가 같은 정책을 쓰면 동작이 예측 가능해지므로 오히려 장점이다.","bad":false},{"txt":"결제는 멱등하므로 재시도로 인한 중복은 어떤 경우에도 발생하지 않는다.","bad":false}],"ex":"결함 3가지: (1) 백오프 없음. (2) 지터 없음 — 동기화된 재시도는 그 자체로 공격이 된다. (3) 재시도 가능 여부 미판별. 디스트랙터: 무제한 재시도는 장애를 키운다. 정책이 같아서 부하가 겹치는 것이 바로 (2)의 문제다. 결제는 멱등성 키를 명시적으로 붙여야 멱등하다."}],"th":{"sum":"설계 리뷰는 **정상 경로가 아니라 실패·경쟁·확장 경로**를 본다: 이게 죽으면 무엇이 함께 죽는가, 동시에 오면 어떻게 되는가, 10배가 되면 어디가 먼저 무너지는가.","body":[{"h":"장애는 전파된다","t":"동기 호출 체인에서 하류가 느려지면 상류의 스레드·커넥션이 함께 묶인다. 타임아웃은 깊이가 늘수록 줄어야 하고(예산 차감), 의존성별로 자원을 나누고(벌크헤드), 반복 실패는 회로를 열어 끊어야 한다. liveness 에 외부 의존성을 넣으면 남의 장애가 우리 인스턴스 재시작으로 번진다. 관측 도구도 마찬가지다 — 로그 전송 실패가 요청 실패가 되면 안 된다."},{"h":"동시에 오면 무슨 일이 생기는가","t":"읽고 계산해 쓰는 모든 코드는 경쟁을 의심한다. 캐시 미스가 몰리면 DB 로 그대로 전달되고(스탬피드), 재시도에 백오프·지터가 없으면 부하가 동기화돼 장애를 키운다. 분산 락에는 만료·소유자 확인·작업 시간 초과 대비가 모두 필요하다. 재시도되는 쓰기에는 멱등성 키가 있어야 한다."},{"h":"최종 일관성은 UI 까지 온다","t":"복제 지연 때문에 방금 쓴 데이터가 안 보이고, 이벤트 순서가 뒤바뀌면 존재하지 않는 주문이 취소된다. DB 커밋과 이벤트 발행은 원자적이지 않으므로 Outbox 가 필요하고, 소비는 최소 한 번 배달을 전제로 멱등해야 한다. 캐시 무효화는 파생 캐시까지 함께 다뤄야 한다."},{"h":"10배가 되면 어디가 먼저 무너지는가","t":"무제한 큐·상한 없는 페이지 크기·깊은 OFFSET·전량 재계산 배치는 규모에 비례해 무너진다. 나머지 연산 샤딩은 확장 시 전면 재배치를 부른다. 지표 레이블에 사용자 ID 를 넣으면 시계열이 폭발한다. '지금 되는가' 가 아니라 '10배에서도 되는가' 를 묻는다."}],"code":{"c":"// 결함: 트랜잭션 안 외부 호출 + 롤백 불가 부수효과 + 멱등성 없음\nBEGIN\n  INSERT INTO orders ...\n  UPDATE inventory SET stock = stock - 1 ...\n  HTTP POST /charge          // 커넥션을 쥔 채 네트워크 대기\n  INSERT INTO payments ...\nCOMMIT                       // 여기서 실패하면 돈만 나간다\n\n// 고침: 경계를 나누고, 부수효과는 멱등하게, 실패는 보상한다\n1) BEGIN; 주문 생성(status=PENDING); 재고 예약; COMMIT\n2) 결제 호출 (Idempotency-Key: orderId, 타임아웃, 회로 차단기)\n3) BEGIN; 결과에 따라 CONFIRMED / 재고 반환; COMMIT\n   실패·타임아웃은 조회 API 로 실제 상태를 확인해 정리(보상 트랜잭션)","cap":"외부 부수효과는 롤백되지 않는다 — 경계를 나누고 보상 경로를 둔다"},"key":["트랜잭션 안에 외부 I/O 를 두지 않는다. 외부 부수효과는 롤백되지 않는다","재시도되는 쓰기에는 멱등성 키, 재시도에는 지수 백오프+지터","타임아웃은 호출 깊이만큼 차감하고, 의존성별로 자원을 격리한다","liveness·로그 전송 같은 부수 경로가 서비스를 인질로 잡지 않게 한다","최종 일관성은 화면까지 온다 — 순서 보장, 멱등 소비, read-your-writes","무제한 큐·상한 없는 페이지·깊은 OFFSET·전량 배치는 규모에서 먼저 무너진다"]}},{"t":"코드 리뷰 IV","q":[{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"로그 수집:\n  모든 서비스가 애플리케이션 코드에서 직접 로그 수집 SaaS 로 HTTP 전송 (동기)\n  전송 실패 시 예외를 던진다","items":[{"txt":"로그 전송 실패가 애플리케이션 요청 실패로 이어진다. 관측 도구의 장애가 서비스 장애가 된다.","bad":true},{"txt":"동기 전송이라 로그 한 줄마다 네트워크 왕복이 붙어 응답 시간이 늘어난다.","bad":true},{"txt":"SaaS 가 느려지면 요청 스레드가 함께 묶인다. 버퍼링과 비동기 전송이 필요하다.","bad":true},{"txt":"로그를 표준 출력으로 내보내면 컨테이너 환경에서 유실되므로 직접 전송이 옳다.","bad":false},{"txt":"로그에 민감 정보가 포함될 수 있다는 점이 이 설계의 유일한 결함이다.","bad":false},{"txt":"HTTP 대신 UDP 로 보내면 유실이 없어 신뢰성이 높아진다.","bad":false}],"ex":"결함 3가지: 전부 '관측이 서비스를 인질로 잡는' 문제다. 표준 출력으로 내보내고 사이드카·에이전트가 수집·버퍼링·재시도하게 분리한다. 디스트랙터: 표준 출력은 컨테이너 로깅의 표준 경로다. 민감 정보는 별개 문제이며 '유일한 결함' 이 아니다. UDP 는 유실을 허용하는 프로토콜이다(서술이 반대)."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"샤딩:\n  shard = hash(userId) % 8\n  사용자 증가로 샤드를 8 → 16 으로 확장 예정","items":[{"txt":"나머지 연산 방식은 샤드 수가 바뀌면 거의 모든 키의 위치가 달라져 대규모 재배치가 필요하다. 일관된 해싱이나 가상 샤드가 필요하다.","bad":true},{"txt":"재배치 중 읽기·쓰기를 어디로 보낼지에 대한 전략이 없다. 이중 쓰기나 라우팅 테이블이 필요하다.","bad":true},{"txt":"해시 샤딩을 쓰면 범위 조회가 불가능해지므로 항상 범위 샤딩을 써야 한다.","bad":false},{"txt":"샤드 수를 2의 거듭제곱으로 두면 재배치 시 데이터 이동이 전혀 없다.","bad":false},{"txt":"userId 를 샤드 키로 쓰면 사용자별 데이터가 한 곳에 모이므로 조인이 불가능해진다.","bad":false},{"txt":"샤딩을 하면 트랜잭션이 자동으로 분산 트랜잭션이 되어 성능이 떨어지는 것이 주된 문제다.","bad":false}],"ex":"결함 2가지: (1) 재배치 비용 — 가상 샤드(예: 1024개 슬롯)를 물리 샤드에 매핑하면 확장 시 슬롯 단위로만 옮기면 된다. (2) 마이그레이션 전략 부재. 디스트랙터: 해시 샤딩은 균등 분산이라는 장점이 있고 상황에 맞으면 옳다. 2의 거듭제곱이면 절반은 그대로지만 나머지 절반은 이동한다('전혀 없다'가 틀렸다). 같은 샤드에 모이는 것은 오히려 장점이다. 분산 트랜잭션은 설계로 피할 수 있다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"캐시 무효화:\n  상품 수정 → DB UPDATE → redis.del('product:' + id)\n  상품 목록 캐시 'products:page:1' 은 그대로 둔다","items":[{"txt":"개별 상품 캐시만 지우고 목록 캐시는 두어, 목록에서는 옛 정보가 계속 보인다.","bad":true},{"txt":"DB 갱신과 캐시 삭제 사이에 다른 요청이 옛 값을 읽어 다시 캐시에 심을 수 있다.","bad":true},{"txt":"캐시 삭제가 실패했을 때의 처리가 없다. 실패하면 무효화가 조용히 누락된다.","bad":true},{"txt":"del 대신 새 값으로 set 하면 경쟁 조건이 완전히 사라진다.","bad":false},{"txt":"Redis 는 트랜잭션을 지원하지 않으므로 원자적 무효화가 원리적으로 불가능하다.","bad":false},{"txt":"목록 캐시는 TTL 이 있으면 어차피 만료되므로 무효화 대상이 아니다.","bad":false}],"ex":"결함 3가지: (1) 파생 캐시 미무효화 — 태그나 버전 키로 관련 캐시를 함께 무효화한다. (2) 무효화 경쟁. (3) 실패 처리 없음. 디스트랙터: set 은 오히려 옛 값을 덮어쓸 경쟁을 만든다. Redis 는 MULTI/Lua 로 원자적 처리가 가능하다. TTL 만으로 버티는 것은 그 시간만큼 잘못된 데이터를 보여 주겠다는 뜻이라 무효화가 필요 없다는 근거가 되지 못한다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"비동기 작업 큐:\n  작업 등록 → 큐에 push → 워커가 pop 하여 처리\n  워커는 pop 즉시 큐에서 제거하고 처리 시작","items":[{"txt":"처리 중 워커가 죽으면 작업이 사라진다. 확인 응답(ack) 후 제거하는 방식이어야 한다.","bad":true},{"txt":"실패한 작업의 재시도·DLQ 경로가 없다.","bad":true},{"txt":"처리 시간이 긴 작업의 가시성 타임아웃이 없어, 다른 워커가 같은 작업을 집어갈 수 있다.","bad":true},{"txt":"pop 은 원자적이지 않으므로 여러 워커가 같은 작업을 가져가는 것을 막을 수 없다.","bad":false},{"txt":"큐에 우선순위가 없으면 어떤 작업도 처리 순서를 보장할 수 없어 사용할 수 없다.","bad":false},{"txt":"워커 수를 늘리면 큐의 순서 보장이 깨지므로 워커는 항상 하나여야 한다.","bad":false}],"ex":"결함 3가지: (1) at-most-once 소비 — 처리 완료 후 삭제(ack)해야 유실이 없다. (2) 재시도·DLQ 부재. (3) 가시성 타임아웃 부재. 디스트랙터: 대부분의 큐 구현에서 pop 은 원자적이다. 우선순위는 요구사항에 따른 기능이다. 워커를 하나로 두면 확장이 불가능하며, 순서가 필요하면 파티셔닝으로 푼다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"설정 관리:\n  애플리케이션 기동 시 설정 서버에서 설정을 받아온다.\n  설정 서버가 응답하지 않으면 기동을 중단한다.\n  기동 후에는 설정을 갱신하지 않는다.","items":[{"txt":"설정 서버가 기동의 강한 의존성이 되어, 그쪽 장애 시 전체 서비스가 새로 뜨지 못한다. 마지막 정상 설정을 캐시해 폴백해야 한다.","bad":true},{"txt":"기동 후 갱신이 없어, 설정을 바꾸려면 전체 재배포가 필요하다. 긴급 대응 수단이 없다.","bad":true},{"txt":"설정을 외부에서 받아오는 방식 자체가 12-factor 원칙에 어긋나므로 환경변수만 써야 한다.","bad":false},{"txt":"기동 실패 시 중단하는 것은 잘못된 설정으로 뜨는 것보다 위험하므로 기본값으로 진행해야 한다.","bad":false},{"txt":"설정에 시크릿이 포함되면 메모리에 남으므로 매 요청마다 다시 받아와야 한다.","bad":false},{"txt":"설정 서버를 쓰면 인스턴스마다 다른 설정을 받을 수 있어 일관성이 원리적으로 불가능하다.","bad":false}],"ex":"결함 2가지: (1) 기동 시 강한 의존성 — 캐시된 마지막 설정으로 폴백하면 설정 서버 장애가 확장·재시작을 막지 않는다. (2) 동적 갱신 부재 — 기능 플래그로 긴급 차단을 하려면 재시작 없이 반영돼야 한다. 디스트랙터: 중앙 설정 서버는 널리 쓰이는 패턴이다. 잘못된 설정으로 뜨는 것이 더 위험하므로 중단은 합리적이다(다만 캐시 폴백을 둔다). 매 요청 재조회는 과하다. 버전을 붙이면 일관성을 관리할 수 있다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"데이터 마이그레이션:\n  1) 새 컬럼 추가\n  2) 애플리케이션 배포 (새 컬럼에만 쓰기)\n  3) 기존 데이터 백필\n  4) 옛 컬럼 삭제\n  모두 한 번의 배포로 진행","items":[{"txt":"한 번에 진행하면 롤백 경로가 없다. 새 코드가 문제일 때 옛 컬럼이 이미 사라져 되돌릴 수 없다.","bad":true},{"txt":"배포 중에는 옛 버전과 새 버전이 함께 도는데, 옛 버전은 새 컬럼을 모른다. 이중 쓰기 구간이 필요하다.","bad":true},{"txt":"백필이 끝나기 전에 새 코드가 새 컬럼만 읽으면 과거 데이터가 비어 보인다.","bad":true},{"txt":"컬럼 추가는 항상 테이블 전체를 재작성하므로 어떤 순서로도 다운타임을 피할 수 없다.","bad":false},{"txt":"백필을 단일 UPDATE 로 처리하면 트랜잭션이 원자적이라 안전하다.","bad":false},{"txt":"옛 컬럼을 삭제하지 않고 두면 스토리지 비용이 늘어나는 것이 유일한 위험이다.","bad":false}],"ex":"결함 3가지: 전부 '단계를 나누지 않은' 문제다. 각 단계를 별도 배포로 분리하고, 사이에 이중 쓰기와 검증 구간을 둔다. 디스트랙터: 기본값 없는 컬럼 추가는 현대 DB 에서 즉시 끝난다. 대량 단일 UPDATE 는 락과 WAL 을 폭발시킨다. 옛 컬럼을 남기는 것은 안전 장치이지 위험이 아니다."}],"th":{"sum":"설계 리뷰는 **정상 경로가 아니라 실패·경쟁·확장 경로**를 본다: 이게 죽으면 무엇이 함께 죽는가, 동시에 오면 어떻게 되는가, 10배가 되면 어디가 먼저 무너지는가.","body":[{"h":"장애는 전파된다","t":"동기 호출 체인에서 하류가 느려지면 상류의 스레드·커넥션이 함께 묶인다. 타임아웃은 깊이가 늘수록 줄어야 하고(예산 차감), 의존성별로 자원을 나누고(벌크헤드), 반복 실패는 회로를 열어 끊어야 한다. liveness 에 외부 의존성을 넣으면 남의 장애가 우리 인스턴스 재시작으로 번진다. 관측 도구도 마찬가지다 — 로그 전송 실패가 요청 실패가 되면 안 된다."},{"h":"동시에 오면 무슨 일이 생기는가","t":"읽고 계산해 쓰는 모든 코드는 경쟁을 의심한다. 캐시 미스가 몰리면 DB 로 그대로 전달되고(스탬피드), 재시도에 백오프·지터가 없으면 부하가 동기화돼 장애를 키운다. 분산 락에는 만료·소유자 확인·작업 시간 초과 대비가 모두 필요하다. 재시도되는 쓰기에는 멱등성 키가 있어야 한다."},{"h":"최종 일관성은 UI 까지 온다","t":"복제 지연 때문에 방금 쓴 데이터가 안 보이고, 이벤트 순서가 뒤바뀌면 존재하지 않는 주문이 취소된다. DB 커밋과 이벤트 발행은 원자적이지 않으므로 Outbox 가 필요하고, 소비는 최소 한 번 배달을 전제로 멱등해야 한다. 캐시 무효화는 파생 캐시까지 함께 다뤄야 한다."},{"h":"10배가 되면 어디가 먼저 무너지는가","t":"무제한 큐·상한 없는 페이지 크기·깊은 OFFSET·전량 재계산 배치는 규모에 비례해 무너진다. 나머지 연산 샤딩은 확장 시 전면 재배치를 부른다. 지표 레이블에 사용자 ID 를 넣으면 시계열이 폭발한다. '지금 되는가' 가 아니라 '10배에서도 되는가' 를 묻는다."}],"code":{"c":"// 결함: 트랜잭션 안 외부 호출 + 롤백 불가 부수효과 + 멱등성 없음\nBEGIN\n  INSERT INTO orders ...\n  UPDATE inventory SET stock = stock - 1 ...\n  HTTP POST /charge          // 커넥션을 쥔 채 네트워크 대기\n  INSERT INTO payments ...\nCOMMIT                       // 여기서 실패하면 돈만 나간다\n\n// 고침: 경계를 나누고, 부수효과는 멱등하게, 실패는 보상한다\n1) BEGIN; 주문 생성(status=PENDING); 재고 예약; COMMIT\n2) 결제 호출 (Idempotency-Key: orderId, 타임아웃, 회로 차단기)\n3) BEGIN; 결과에 따라 CONFIRMED / 재고 반환; COMMIT\n   실패·타임아웃은 조회 API 로 실제 상태를 확인해 정리(보상 트랜잭션)","cap":"외부 부수효과는 롤백되지 않는다 — 경계를 나누고 보상 경로를 둔다"},"key":["트랜잭션 안에 외부 I/O 를 두지 않는다. 외부 부수효과는 롤백되지 않는다","재시도되는 쓰기에는 멱등성 키, 재시도에는 지수 백오프+지터","타임아웃은 호출 깊이만큼 차감하고, 의존성별로 자원을 격리한다","liveness·로그 전송 같은 부수 경로가 서비스를 인질로 잡지 않게 한다","최종 일관성은 화면까지 온다 — 순서 보장, 멱등 소비, read-your-writes","무제한 큐·상한 없는 페이지·깊은 OFFSET·전량 배치는 규모에서 먼저 무너진다"]}},{"t":"코드 리뷰 V","q":[{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"API 버전 관리:\n  /api/users 응답에서 name 필드를 firstName/lastName 으로 분리\n  기존 클라이언트를 위해 name 도 함께 유지하기로 결정\n  단, 서버는 name 을 더 이상 갱신하지 않는다","items":[{"txt":"name 을 남겨 두되 갱신하지 않으면, 옛 클라이언트는 조용히 낡은 값을 계속 보게 된다. 명시적 실패보다 나쁘다.","bad":true},{"txt":"폐기 일정과 공지 경로가 없다. 언제까지 유지할지 정하지 않으면 영원히 남는다.","bad":true},{"txt":"응답에 필드를 추가하는 것은 하위 호환을 깨는 변경이므로 새 버전 경로가 필수다.","bad":false},{"txt":"name 을 유지하면 응답 크기가 커지는 것이 주된 문제다.","bad":false},{"txt":"필드를 분리하려면 데이터베이스 컬럼도 반드시 같은 시점에 분리해야 한다.","bad":false},{"txt":"클라이언트가 모르는 필드를 받으면 파싱 오류가 나므로 필드 추가 자체가 위험하다.","bad":false}],"ex":"결함 2가지: (1) 조용히 낡는 필드 — 유지하려면 함께 갱신하고, 못 하겠으면 명시적으로 제거하고 알린다. (2) 폐기 계획 부재 — 지원 종료일·사용량 계측·경고 헤더. 디스트랙터: 필드 추가는 보통 하위 호환이다. 응답 크기는 사소하다. API 표현과 저장 구조는 분리할 수 있다. 잘 만든 클라이언트는 모르는 필드를 무시한다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"서킷 브레이커:\n  실패율 50% 초과 시 열림 → 60초 후 닫힘\n  열린 동안 모든 요청 즉시 실패","items":[{"txt":"60초 후 곧바로 완전히 닫혀 전체 트래픽이 한 번에 몰린다. 절반만 흘려보내는 반열림 단계가 필요하다.","bad":true},{"txt":"최소 요청 수 기준이 없어, 요청 2건 중 1건 실패만으로도 회로가 열린다.","bad":true},{"txt":"열린 동안의 폴백이 없다. 캐시된 값이나 기본 응답을 주면 사용자 경험이 유지된다.","bad":true},{"txt":"서킷 브레이커를 쓰면 재시도가 불필요해지므로 두 가지를 함께 쓰면 안 된다.","bad":false},{"txt":"실패율 임계치는 항상 90% 이상이어야 정상 트래픽을 차단하지 않는다.","bad":false},{"txt":"회로가 열리면 상대 서비스가 복구되었는지 알 방법이 없으므로 수동 개입이 필수다.","bad":false}],"ex":"결함 3가지: (1) 반열림 단계 부재. (2) 최소 표본 없음. (3) 폴백 없음. 디스트랙터: 재시도와 회로 차단기는 함께 쓰는 조합이다. 임계치는 서비스 특성에 따르며 90% 는 너무 늦다. 반열림으로 자동 탐색이 가능하다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"감사 로그:\n  중요 작업 시 audit_logs 테이블에 INSERT\n  같은 트랜잭션에서 비즈니스 데이터도 함께 변경\n  audit_logs 는 애플리케이션 계정으로 UPDATE/DELETE 가능","items":[{"txt":"애플리케이션 계정이 감사 로그를 수정·삭제할 수 있어, 침해 시 흔적을 지울 수 있다. 추가 전용이어야 한다.","bad":true},{"txt":"감사 로그가 비즈니스 트랜잭션과 같은 DB 에 있어 함께 유실될 수 있다. 별도 저장소나 외부 전송이 필요하다.","bad":true},{"txt":"같은 트랜잭션에 묶으면 비즈니스 변경이 롤백될 때 감사 로그도 함께 사라지므로 분리해야 한다.","bad":false},{"txt":"감사 로그를 INSERT 로만 쌓으면 테이블이 커져 조회가 불가능해지는 것이 주된 문제다.","bad":false},{"txt":"감사 로그에 사용자 식별자를 남기면 개인정보 규정 위반이므로 익명화해야 한다.","bad":false},{"txt":"트랜잭션 안에서 INSERT 하면 성능이 떨어지므로 비동기로 보내야 한다.","bad":false}],"ex":"결함 2가지: (1) 변경 가능한 감사 로그 — 권한을 INSERT 로 제한하고 필요하면 해시 체인이나 WORM 저장소를 쓴다. (2) 운명 공유 — 같은 DB 가 손상되면 증거도 사라진다. 디스트랙터: 세 번째는 함정이다 — 롤백된 작업의 감사 로그가 함께 사라지는 것은 오히려 올바른 동작이다. 파티셔닝으로 크기를 관리할 수 있고, 감사 로그에는 행위자 식별이 필수다. 비동기 전송은 유실 위험을 만든다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"백프레셔:\n  수신 API → 내부 큐(무제한) → 처리 워커 10개\n  유입 3,000 rps / 처리 능력 800 rps","items":[{"txt":"유입이 처리 능력의 4배인데 큐에 상한이 없다. 메모리가 계속 늘어 결국 프로세스가 죽는다.","bad":true},{"txt":"유입을 거절하거나 늦추는 장치가 없다. 상한에 도달하면 429 로 명확히 거절해야 한다.","bad":true},{"txt":"큐가 길어질수록 처리 대기 시간이 늘어, 이미 의미 없어진 요청까지 처리한다. 만료 개념이 필요하다.","bad":true},{"txt":"워커를 늘리면 항상 해결되므로 큐 설계는 고려할 필요가 없다.","bad":false},{"txt":"무제한 큐는 요청을 유실하지 않으므로 신뢰성 면에서 최선의 선택이다.","bad":false},{"txt":"429 를 반환하면 클라이언트가 재시도하므로 오히려 부하가 늘어 사용해서는 안 된다.","bad":false}],"ex":"결함 3가지: (1) 무제한 큐. (2) 유입 제어 없음. (3) 요청 만료 없음. 디스트랙터: 워커 증설에는 하류 한계가 있다. 무제한 큐는 유실 대신 전면 붕괴를 부른다. 429 는 Retry-After 와 함께 쓰면 부하를 제어하는 정상적인 수단이다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"장애 격리:\n  하나의 스레드 풀(200) 에서 모든 외부 호출을 처리한다.\n  결제·추천·이메일·검색 API 를 모두 여기서 호출","items":[{"txt":"스레드 풀을 공유해, 추천 API 하나가 느려지면 결제까지 스레드를 못 얻는다. 의존성별로 풀을 나눠야 한다(벌크헤드).","bad":true},{"txt":"중요도가 다른 호출이 같은 자원을 놓고 경쟁한다. 결제는 추천보다 우선해야 한다.","bad":true},{"txt":"호출별 타임아웃 차등이 없어, 오래 걸려도 되는 작업이 짧게 끝나야 할 작업의 자원을 잡는다.","bad":true},{"txt":"스레드 풀을 나누면 전체 스레드 수가 늘어 컨텍스트 스위칭 비용이 커지므로 항상 하나로 유지해야 한다.","bad":false},{"txt":"외부 호출을 비동기로 바꾸면 자원 격리가 자동으로 이루어진다.","bad":false},{"txt":"200개 스레드는 어떤 부하에서도 충분하므로 크기 조정만으로 해결된다.","bad":false}],"ex":"결함 3가지: (1) 벌크헤드 부재. (2) 우선순위 미구분. (3) 타임아웃 차등 없음. 디스트랙터: 풀 분리 비용보다 격리 이득이 크다. 비동기로 바꿔도 커넥션 수 같은 자원은 여전히 공유되므로 격리는 별도로 필요하다. 스레드 수를 늘려도 느린 의존성이 전부를 소진하는 구조는 그대로다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"지표 수집:\n  요청마다 Prometheus 카운터를 증가시킨다.\n  레이블: method, path, status, userId","items":[{"txt":"userId 를 레이블로 쓰면 시계열 수가 사용자 수만큼 폭발한다(카디널리티 폭발). 수집기 메모리가 감당하지 못한다.","bad":true},{"txt":"path 를 원본 그대로 쓰면 /users/1, /users/2 가 각각 다른 시계열이 된다. 경로 템플릿으로 정규화해야 한다.","bad":true},{"txt":"카운터 대신 히스토그램을 써야 요청 수를 셀 수 있다.","bad":false},{"txt":"status 를 레이블로 두면 4xx/5xx 를 구분할 수 없으므로 별도 지표가 필요하다.","bad":false},{"txt":"Prometheus 는 풀 방식이므로 애플리케이션에서 카운터를 증가시킬 수 없다.","bad":false},{"txt":"레이블이 4개면 조회 성능이 떨어지므로 항상 2개 이하로 제한해야 한다.","bad":false}],"ex":"결함 2가지: 둘 다 카디널리티 문제다. 시계열 수는 레이블 값 조합의 곱이므로, 값의 범위가 무한한 것(사용자 ID·요청 ID·경로 파라미터)은 레이블이 아니라 로그·트레이스에 남긴다. 디스트랙터: 요청 수에는 카운터가 맞다. status 레이블은 오히려 구분을 가능하게 한다. Prometheus 는 애플리케이션이 노출한 값을 긁어가는 방식이라 카운터 증가는 정상이다. 레이블 개수 자체보다 각 레이블의 값 범위가 중요하다."}],"th":{"sum":"설계 리뷰는 **정상 경로가 아니라 실패·경쟁·확장 경로**를 본다: 이게 죽으면 무엇이 함께 죽는가, 동시에 오면 어떻게 되는가, 10배가 되면 어디가 먼저 무너지는가.","body":[{"h":"장애는 전파된다","t":"동기 호출 체인에서 하류가 느려지면 상류의 스레드·커넥션이 함께 묶인다. 타임아웃은 깊이가 늘수록 줄어야 하고(예산 차감), 의존성별로 자원을 나누고(벌크헤드), 반복 실패는 회로를 열어 끊어야 한다. liveness 에 외부 의존성을 넣으면 남의 장애가 우리 인스턴스 재시작으로 번진다. 관측 도구도 마찬가지다 — 로그 전송 실패가 요청 실패가 되면 안 된다."},{"h":"동시에 오면 무슨 일이 생기는가","t":"읽고 계산해 쓰는 모든 코드는 경쟁을 의심한다. 캐시 미스가 몰리면 DB 로 그대로 전달되고(스탬피드), 재시도에 백오프·지터가 없으면 부하가 동기화돼 장애를 키운다. 분산 락에는 만료·소유자 확인·작업 시간 초과 대비가 모두 필요하다. 재시도되는 쓰기에는 멱등성 키가 있어야 한다."},{"h":"최종 일관성은 UI 까지 온다","t":"복제 지연 때문에 방금 쓴 데이터가 안 보이고, 이벤트 순서가 뒤바뀌면 존재하지 않는 주문이 취소된다. DB 커밋과 이벤트 발행은 원자적이지 않으므로 Outbox 가 필요하고, 소비는 최소 한 번 배달을 전제로 멱등해야 한다. 캐시 무효화는 파생 캐시까지 함께 다뤄야 한다."},{"h":"10배가 되면 어디가 먼저 무너지는가","t":"무제한 큐·상한 없는 페이지 크기·깊은 OFFSET·전량 재계산 배치는 규모에 비례해 무너진다. 나머지 연산 샤딩은 확장 시 전면 재배치를 부른다. 지표 레이블에 사용자 ID 를 넣으면 시계열이 폭발한다. '지금 되는가' 가 아니라 '10배에서도 되는가' 를 묻는다."}],"code":{"c":"// 결함: 트랜잭션 안 외부 호출 + 롤백 불가 부수효과 + 멱등성 없음\nBEGIN\n  INSERT INTO orders ...\n  UPDATE inventory SET stock = stock - 1 ...\n  HTTP POST /charge          // 커넥션을 쥔 채 네트워크 대기\n  INSERT INTO payments ...\nCOMMIT                       // 여기서 실패하면 돈만 나간다\n\n// 고침: 경계를 나누고, 부수효과는 멱등하게, 실패는 보상한다\n1) BEGIN; 주문 생성(status=PENDING); 재고 예약; COMMIT\n2) 결제 호출 (Idempotency-Key: orderId, 타임아웃, 회로 차단기)\n3) BEGIN; 결과에 따라 CONFIRMED / 재고 반환; COMMIT\n   실패·타임아웃은 조회 API 로 실제 상태를 확인해 정리(보상 트랜잭션)","cap":"외부 부수효과는 롤백되지 않는다 — 경계를 나누고 보상 경로를 둔다"},"key":["트랜잭션 안에 외부 I/O 를 두지 않는다. 외부 부수효과는 롤백되지 않는다","재시도되는 쓰기에는 멱등성 키, 재시도에는 지수 백오프+지터","타임아웃은 호출 깊이만큼 차감하고, 의존성별로 자원을 격리한다","liveness·로그 전송 같은 부수 경로가 서비스를 인질로 잡지 않게 한다","최종 일관성은 화면까지 온다 — 순서 보장, 멱등 소비, read-your-writes","무제한 큐·상한 없는 페이지·깊은 OFFSET·전량 배치는 규모에서 먼저 무너진다"]}}]},{"t":"설계 · 직접 그리는 아키텍처","l":[{"t":"설계 I","q":[{"t":"arch","kind":"erd","k":"데이터 모델링","lv":1,"cat":"design","q":"블로그의 <b>글과 댓글</b>을 설계하세요. 글은 제목·본문·작성시각을 갖고, 댓글은 어느 글에 달렸는지 알아야 합니다. 각 테이블에는 기본키가 있어야 하고, 댓글에서 글로 가는 외래키가 필요합니다.","src":"{\n  \"entities\": [\n    { \"name\": \"post\", \"fields\": [] }\n  ],\n  \"relations\": []\n}","tests":[{"d":"post 와 comment 두 테이블이 있다","js":"D.entities.length===2 && ['post','comment'].every(n=>D.entities.some(e=>e.name===n))"},{"d":"두 테이블 모두 기본키가 정확히 하나다","js":"D.entities.every(e=>e.fields.filter(f=>f.pk).length===1)"},{"d":"post 에 제목·본문·작성시각이 있다","js":"['title','body','created_at'].every(n=>D.entities.find(e=>e.name==='post').fields.some(f=>f.name===n))"},{"d":"comment 가 post 를 가리키는 외래키를 갖는다","js":"D.entities.find(e=>e.name==='comment').fields.some(f=>f.fk && String(f.fk).indexOf('post')===0)"},{"d":"외래키에 인덱스가 걸려 있다 (글별 댓글 조회가 잦다)","js":"D.entities.find(e=>e.name==='comment').fields.some(f=>f.fk && f.index===true)"},{"d":"1:N 관계가 선언돼 있다","js":"D.relations.some(r=>r.type==='1:N' && r.from==='post' && r.to==='comment')"}],"ex":"외래키에 인덱스를 거는 것이 이 문제의 핵심입니다. 대부분의 데이터베이스는 <b>외래키를 만들어도 인덱스를 자동으로 만들지 않습니다</b>. '글 하나의 댓글 목록' 은 가장 잦은 조회인데, 인덱스가 없으면 댓글 테이블 전체를 훑습니다. 그리고 시각은 타임존을 포함하는 타입으로 두어야 서버 위치가 바뀌어도 값이 흔들리지 않습니다."},{"t":"arch","kind":"erd","k":"데이터 모델링","lv":3,"cat":"design","q":"<b>다대다</b>를 설계하세요. 학생은 여러 과목을 듣고 과목에는 여러 학생이 있습니다. 같은 학생이 같은 과목을 <b>두 번 등록할 수 없어야</b> 하고, 등록 시각도 남겨야 합니다.","src":"{\n  \"entities\": [\n    { \"name\": \"student\", \"fields\": [{ \"name\": \"id\", \"type\": \"bigint\", \"pk\": true }] },\n    { \"name\": \"course\",  \"fields\": [{ \"name\": \"id\", \"type\": \"bigint\", \"pk\": true }] }\n  ],\n  \"relations\": []\n}","tests":[{"d":"연결 테이블이 따로 있다 (총 3개 엔티티)","js":"D.entities.length===3"},{"d":"연결 테이블이 양쪽으로 외래키를 갖는다","js":"(function(){var j=D.entities.find(e=>e.fields.filter(f=>f.fk).length===2);return !!j;})()"},{"d":"복합 기본키로 중복 등록을 막는다","js":"(function(){var j=D.entities.find(e=>e.fields.filter(f=>f.fk).length===2);return j.fields.filter(f=>f.pk).length===2;})()"},{"d":"등록 시각을 남긴다","js":"(function(){var j=D.entities.find(e=>e.fields.filter(f=>f.fk).length===2);return j.fields.some(f=>/at$|time|date/i.test(f.name));})()"},{"d":"양쪽에서 연결 테이블로 1:N 관계가 선언돼 있다","js":"D.relations.filter(r=>r.type==='1:N').length>=2"}],"ex":"다대다는 <b>연결 테이블(join table)</b>로 풉니다. 여기서 중요한 건 중복 방지를 어디서 하느냐입니다. 애플리케이션에서 '이미 등록했나' 를 확인하고 넣으면 동시 요청 두 개가 모두 통과할 수 있습니다(check-then-act). 두 외래키를 묶은 <b>복합 기본키</b>를 두면 데이터베이스가 중복을 원천 차단합니다."},{"t":"arch","kind":"erd","k":"데이터 모델링","lv":4,"cat":"design","q":"주문·결제를 설계하세요. 금액은 <b>부동소수로 저장하면 안 되고</b>, 주문 상태는 정해진 값만 허용해야 하며, 상품 가격이 바뀌어도 <b>과거 주문 금액은 변하지 않아야</b> 합니다.","src":"{\n  \"entities\": [\n    { \"name\": \"product\", \"fields\": [\n      { \"name\": \"id\", \"type\": \"bigint\", \"pk\": true },\n      { \"name\": \"price\", \"type\": \"float\" }\n    ]},\n    { \"name\": \"order\", \"fields\": [\n      { \"name\": \"id\", \"type\": \"bigint\", \"pk\": true },\n      { \"name\": \"status\", \"type\": \"varchar(20)\" }\n    ]}\n  ],\n  \"relations\": []\n}","tests":[{"d":"주문 상세(order_item)를 별도 테이블로 둔다","js":"D.entities.length>=3"},{"d":"금액을 부동소수로 저장하지 않는다","js":"D.entities.every(e=>e.fields.every(f=>!/float|double|real/i.test(f.type||'')))"},{"d":"주문 시점의 단가를 상세에 복사해 둔다 (가격 변경에 흔들리지 않게)","js":"D.entities.some(e=>e.fields.some(f=>/unit_price|price_at|snapshot/i.test(f.name)))"},{"d":"주문 상태가 정해진 값만 허용된다 (enum 또는 check)","js":"(function(){var f=D.entities.find(e=>e.name==='order').fields.find(x=>x.name==='status');return /enum|check/i.test(f.type||'')||Array.isArray(f.values);})()"},{"d":"상세의 두 외래키에 인덱스가 있다","js":"(function(){var oi=D.entities.find(e=>e.fields.filter(f=>f.fk).length===2);return oi && oi.fields.filter(f=>f.fk&&f.index).length===2;})()"},{"d":"수량 필드가 있다","js":"D.entities.some(e=>e.fields.some(f=>/qty|quantity|count/i.test(f.name)))"}],"ex":"세 가지가 한꺼번에 걸린 문제입니다. ① 금액은 이진 부동소수로 정확히 표현되지 않으므로 <b>최소 단위 정수</b>로 저장합니다. ② 상태를 자유 문자열로 두면 오타가 그대로 저장되므로 허용값을 데이터베이스가 강제하게 합니다. ③ 상품 가격은 바뀝니다 — 주문 시점의 단가를 상세에 <b>복사해 두지 않으면</b> 과거 영수증 금액이 소급해서 바뀝니다."},{"t":"arch","kind":"erd","k":"데이터 모델링","lv":3,"cat":"design","q":"소프트 삭제와 감사 로그를 설계하세요. 사용자를 지워도 <b>실제로 지우지 않고</b> 표시만 하고, 누가 언제 무엇을 바꿨는지 남겨야 합니다. 활성 사용자 조회가 빨라야 합니다.","src":"{\n  \"entities\": [\n    { \"name\": \"user\", \"fields\": [\n      { \"name\": \"id\", \"type\": \"bigint\", \"pk\": true },\n      { \"name\": \"email\", \"type\": \"varchar(255)\" }\n    ]}\n  ],\n  \"relations\": []\n}","tests":[{"d":"삭제 표시 컬럼이 있다 (soft delete)","js":"D.entities.find(e=>e.name==='user').fields.some(f=>/deleted|removed|is_active/i.test(f.name))"},{"d":"삭제 표시 컬럼에 인덱스가 있다 (활성 사용자 조회)","js":"D.entities.find(e=>e.name==='user').fields.some(f=>/deleted|removed|is_active/i.test(f.name)&&f.index===true)"},{"d":"감사 로그 테이블이 있다","js":"D.entities.some(e=>/audit|history|log/i.test(e.name))"},{"d":"로그에 행위자·행위·시각이 모두 있다","js":"(function(){var a=D.entities.find(e=>/audit|history|log/i.test(e.name)).fields.map(f=>f.name).join(' ');\n       return /actor|user/.test(a) && /action|event|type/.test(a) && /at$|_at|time/.test(a);})()"},{"d":"이메일에 유일 제약이 있다","js":"D.entities.find(e=>e.name==='user').fields.some(f=>f.name==='email'&&(f.unique===true||f.pk===true))"}],"ex":"소프트 삭제는 편하지만 <b>모든 조회에 조건이 하나씩 붙는다</b>는 비용이 따라옵니다. 그 조건이 인덱스를 타지 못하면 사용자가 늘수록 느려집니다. 그리고 소프트 삭제와 유일 제약은 충돌합니다 — 지운 이메일로 다시 가입할 수 없게 되므로, 실무에서는 부분 인덱스나 삭제 시 이메일 치환 같은 정책이 함께 필요합니다."}],"th":{"sum":"설계를 고르는 게 아니라 직접 적습니다. JSON 으로 적은 설계가 다이어그램으로 그려지고, 요구사항이 규칙으로 검사됩니다.","body":[{"h":"설계에는 정답이 아니라 요건이 있다","t":"'어느 쪽이 더 낫나요' 는 맥락 없이는 답이 없습니다. 대신 <b>요구사항을 만족하는가</b>를 봅니다 — 중복 등록을 막았는가, 정적 파일이 앱을 거치지 않는가, 롤백 경로가 있는가."},{"h":"데이터 모델은 나중에 못 바꾼다","t":"금액을 부동소수로 저장하거나, 주문 시점의 단가를 복사해 두지 않거나, 외래키에 인덱스를 빠뜨리면 <b>데이터가 쌓인 뒤에는 고치기 매우 비쌉니다</b>. 설계 단계에서 결정되는 것들입니다."},{"h":"API 는 계약이다","t":"경로는 자원을, 메서드는 동작을 표현합니다. 상태 코드에는 의미가 있고(201 생성 · 204 내용 없음 · 401 인증 · 403 인가), 재시도가 반드시 일어난다는 전제로 멱등성을 설계합니다."},{"h":"구조는 장애를 가정하고 그린다","t":"단일 장애점을 없애고, 타임아웃·서킷 브레이커로 전파를 끊고, 사용자보다 먼저 알 수 있게 지표와 경보를 둡니다. 배포는 <b>되돌릴 수 있어야</b> 끝난 것입니다."}],"code":{"t":"설계를 JSON 으로 적는다","c":"{\n  \"entities\": [\n    { \"name\": \"comment\", \"fields\": [\n      { \"name\": \"post_id\", \"type\": \"bigint\",\n        \"fk\": \"post.id\", \"index\": true }   // ← 외래키에 인덱스\n    ]}\n  ]\n}"},"key":["요구사항 충족 여부로 판정한다","금액·상태·시점 스냅샷은 모델 단계에서 결정된다","경로는 자원 · 메서드는 동작 · 상태 코드는 의미","단일 장애점·타임아웃·롤백을 먼저 그린다"]}},{"t":"설계 II","q":[{"t":"arch","kind":"api","k":"API 설계","lv":1,"cat":"design","q":"할 일 목록 REST API 를 설계하세요. <b>목록 조회 · 단건 조회 · 생성 · 수정 · 삭제</b> 다섯 가지가 필요합니다. 메서드와 상태 코드를 REST 관례에 맞게 정하세요.","src":"{\n  \"endpoints\": [\n    { \"method\": \"GET\", \"path\": \"/todos\", \"status\": 200, \"desc\": \"목록\" }\n  ]\n}","tests":[{"d":"엔드포인트가 5개다","js":"D.endpoints.length===5"},{"d":"생성은 POST 이고 201 을 돌려준다","js":"D.endpoints.some(e=>e.method==='POST'&&e.status===201)"},{"d":"삭제는 DELETE 이고 204 를 돌려준다","js":"D.endpoints.some(e=>e.method==='DELETE'&&e.status===204)"},{"d":"경로에 동사를 쓰지 않는다 (자원 이름만)","js":"D.endpoints.every(e=>!/\\/(get|create|update|delete|add|remove)/i.test(e.path))"},{"d":"단건 조회·수정·삭제는 경로에 식별자를 받는다","js":"['GET','PATCH','DELETE'].every(m=>D.endpoints.some(e=>e.method===m&&/\\{\\w+\\}|:\\w+/.test(e.path)))"},{"d":"없는 자원에 대한 404 를 선언한다","js":"D.endpoints.filter(e=>/\\{\\w+\\}|:\\w+/.test(e.path)).every(e=>(e.errors||[]).indexOf(404)>=0)"}],"ex":"REST 의 핵심은 <b>경로가 자원을 가리키고 동작은 메서드가 표현한다</b>는 것입니다. <code>/todos/create</code> 대신 <code>POST /todos</code> 를 씁니다. 상태 코드도 의미가 있습니다 — 생성은 201, 본문 없는 성공은 204 입니다. 식별자를 받는 경로는 없는 자원일 수 있으므로 404 를 반드시 정의합니다."},{"t":"arch","kind":"api","k":"API 설계","lv":3,"cat":"design","q":"게시글 목록 API 에 <b>페이지네이션·정렬·필터</b>를 설계하세요. 목록이 수십만 건이므로 OFFSET 방식은 쓰지 않습니다. 그리고 <b>속도 제한</b> 응답도 정의하세요.","src":"{\n  \"endpoints\": [\n    { \"method\": \"GET\", \"path\": \"/posts\", \"status\": 200, \"query\": [], \"desc\": \"목록\" }\n  ]\n}","tests":[{"d":"커서 기반 페이지네이션이다 (offset/page 를 쓰지 않는다)","js":"(function(){var q=(D.endpoints[0].query||[]).map(x=>x.name).join(' ');return /cursor|after|since/.test(q) && !/offset|page/.test(q);})()"},{"d":"limit 에 상한이 있다","js":"(D.endpoints[0].query||[]).some(x=>/limit|size|per/.test(x.name) && x.max!=null)"},{"d":"정렬 파라미터가 정해진 값만 받는다","js":"(D.endpoints[0].query||[]).some(x=>/sort|order/.test(x.name) && /enum|\\|/.test(String(x.type||'')))"},{"d":"필터 파라미터가 있다","js":"(D.endpoints[0].query||[]).some(x=>/_id$|filter|status|q$/.test(x.name))"},{"d":"응답에 다음 커서를 돌려준다","js":"/cursor|next/.test(JSON.stringify(D.endpoints[0].response||{}))"},{"d":"속도 제한 응답(429)을 정의한다","js":"(D.endpoints[0].errors||[]).indexOf(429)>=0"}],"ex":"OFFSET 은 건너뛸 행을 <b>실제로 읽고 버리므로</b> 뒤 페이지일수록 느려지고, 그 사이 새 글이 들어오면 항목이 중복되거나 누락됩니다. 커서 방식은 '마지막으로 본 지점' 부터 읽으므로 항상 일정하고 흔들리지 않습니다. limit 에 상한이 없으면 <code>?limit=1000000</code> 한 방으로 서버가 멈출 수 있습니다."},{"t":"arch","kind":"api","k":"API 설계","lv":4,"cat":"design","q":"결제 API 를 설계하세요. 네트워크 오류로 클라이언트가 <b>같은 요청을 두 번 보내도 두 번 결제되면 안 됩니다</b>. 비동기 처리라 결과를 나중에 확인할 수 있어야 하고, 실패 원인도 구분되어야 합니다.","src":"{\n  \"endpoints\": [\n    { \"method\": \"POST\", \"path\": \"/payments\", \"status\": 200, \"desc\": \"결제\" }\n  ]\n}","tests":[{"d":"멱등성 키를 헤더로 받는다","js":"(D.endpoints[0].headers||[]).some(h=>/idempotenc/i.test(h.name))"},{"d":"비동기 접수를 202 로 표현한다","js":"D.endpoints.some(e=>e.method==='POST'&&e.status===202)"},{"d":"상태를 조회하는 엔드포인트가 따로 있다","js":"D.endpoints.some(e=>e.method==='GET'&&/\\{\\w+\\}/.test(e.path))"},{"d":"조회 응답에 진행 상태가 있다","js":"/pending|state|status/.test(JSON.stringify(D.endpoints.find(e=>e.method==='GET').response||{}))"},{"d":"실패 원인을 구분해 돌려준다","js":"/failure|reason|error/.test(JSON.stringify(D.endpoints.find(e=>e.method==='GET').response||{}))"},{"d":"중복 요청 충돌(409)을 정의한다","js":"(D.endpoints[0].errors||[]).indexOf(409)>=0"}],"ex":"결제는 <b>재시도가 반드시 일어난다</b>고 가정하고 설계해야 합니다. 클라이언트가 만든 멱등성 키를 서버가 기억하면, 같은 키의 두 번째 요청은 새 결제가 아니라 <b>첫 결과를 그대로</b> 돌려줍니다. 그리고 결제는 즉시 끝나지 않으므로 202 로 접수만 알리고 상태 조회를 따로 두는 편이 타임아웃에 강합니다."},{"t":"arch","kind":"api","k":"API 설계","lv":3,"cat":"design","q":"인증·인가를 설계하세요. 로그인 · 토큰 갱신 · 로그아웃이 필요하고, <b>액세스 토큰은 짧게</b> 두어야 하며, 권한 부족과 인증 실패는 <b>다른 상태 코드</b>로 구분해야 합니다.","src":"{\n  \"endpoints\": [\n    { \"method\": \"POST\", \"path\": \"/login\", \"status\": 200, \"desc\": \"로그인\" }\n  ]\n}","tests":[{"d":"토큰 발급·갱신·폐기 세 가지가 있다","js":"D.endpoints.length>=3"},{"d":"액세스 토큰의 만료 시간이 응답에 있다","js":"/expires_in|exp/.test(JSON.stringify(D.endpoints[0].response||{}))"},{"d":"액세스 토큰이 짧다 (1시간 이하)","js":"(function(){var r=D.endpoints[0].response||{};var v=r.expires_in;return typeof v==='number'&&v<=3600;})()"},{"d":"리프레시 토큰이 따로 있다","js":"/refresh/.test(JSON.stringify(D.endpoints.map(e=>[e.path,e.response])))"},{"d":"로그아웃은 상태를 바꾸므로 GET 이 아니다","js":"D.endpoints.every(e=>!(/logout|signout/i.test(e.path)&&e.method==='GET'))"},{"d":"인증 실패(401)와 권한 부족(403)을 모두 정의한다","js":"(function(){var all=D.endpoints.flatMap(e=>e.errors||[]);return all.indexOf(401)>=0&&all.indexOf(403)>=0;})()"}],"ex":"401 과 403 은 다릅니다 — <b>401 은 '누구인지 모르겠다'</b>(로그인하면 될 수도 있음), <b>403 은 '알겠는데 권한이 없다'</b>(로그인해도 안 됨)입니다. 클라이언트가 401 에만 재로그인을 시도해야 하는데 이걸 섞으면 무한 로그인 루프가 생깁니다. 액세스 토큰을 짧게 두는 이유는 탈취되어도 피해 시간이 제한되기 때문이고, 그 불편은 리프레시 토큰이 메웁니다."}],"th":{"sum":"설계를 고르는 게 아니라 직접 적습니다. JSON 으로 적은 설계가 다이어그램으로 그려지고, 요구사항이 규칙으로 검사됩니다.","body":[{"h":"설계에는 정답이 아니라 요건이 있다","t":"'어느 쪽이 더 낫나요' 는 맥락 없이는 답이 없습니다. 대신 <b>요구사항을 만족하는가</b>를 봅니다 — 중복 등록을 막았는가, 정적 파일이 앱을 거치지 않는가, 롤백 경로가 있는가."},{"h":"데이터 모델은 나중에 못 바꾼다","t":"금액을 부동소수로 저장하거나, 주문 시점의 단가를 복사해 두지 않거나, 외래키에 인덱스를 빠뜨리면 <b>데이터가 쌓인 뒤에는 고치기 매우 비쌉니다</b>. 설계 단계에서 결정되는 것들입니다."},{"h":"API 는 계약이다","t":"경로는 자원을, 메서드는 동작을 표현합니다. 상태 코드에는 의미가 있고(201 생성 · 204 내용 없음 · 401 인증 · 403 인가), 재시도가 반드시 일어난다는 전제로 멱등성을 설계합니다."},{"h":"구조는 장애를 가정하고 그린다","t":"단일 장애점을 없애고, 타임아웃·서킷 브레이커로 전파를 끊고, 사용자보다 먼저 알 수 있게 지표와 경보를 둡니다. 배포는 <b>되돌릴 수 있어야</b> 끝난 것입니다."}],"code":{"t":"설계를 JSON 으로 적는다","c":"{\n  \"entities\": [\n    { \"name\": \"comment\", \"fields\": [\n      { \"name\": \"post_id\", \"type\": \"bigint\",\n        \"fk\": \"post.id\", \"index\": true }   // ← 외래키에 인덱스\n    ]}\n  ]\n}"},"key":["요구사항 충족 여부로 판정한다","금액·상태·시점 스냅샷은 모델 단계에서 결정된다","경로는 자원 · 메서드는 동작 · 상태 코드는 의미","단일 장애점·타임아웃·롤백을 먼저 그린다"]}},{"t":"설계 III","q":[{"t":"arch","kind":"cloud","k":"인프라 설계","lv":2,"cat":"design","q":"트래픽이 늘어난 웹 서비스의 구조를 설계하세요. <b>단일 장애점이 없어야</b> 하고, 정적 파일은 앱 서버를 거치지 않아야 하며, 데이터베이스 읽기 부하를 나눠야 합니다.","src":"{\n  \"components\": [\n    { \"name\": \"app\", \"icon\": \"🖥\", \"scale\": 1 },\n    { \"name\": \"db\", \"icon\": \"🗄\", \"scale\": 1 }\n  ],\n  \"connections\": [\n    { \"from\": \"app\", \"to\": \"db\" }\n  ]\n}","tests":[{"d":"앱 서버가 2대 이상이다 (단일 장애점 제거)","js":"D.components.some(c=>/app|web|api/.test(c.name) && (c.scale||1)>=2)"},{"d":"앞단에 로드밸런서가 있다","js":"D.components.some(c=>/load|lb|balancer|gateway/i.test(c.name))"},{"d":"정적 파일이 앱을 거치지 않는다 (CDN → 스토리지)","js":"D.connections.some(e=>/cdn/i.test(e.from) && /storage|s3|bucket/i.test(e.to))"},{"d":"읽기 복제본이 있다","js":"D.components.some(c=>/replica|read/i.test(c.name))"},{"d":"쓰기와 읽기가 다른 곳으로 간다","js":"(function(){var w=D.connections.find(e=>/write|쓰기/.test(e.via||''));var r=D.connections.find(e=>/read|읽기/.test(e.via||''));return w&&r&&w.to!==r.to;})()"},{"d":"캐시 계층이 있다","js":"D.components.some(c=>/cache|redis|memcach/i.test(c.name))"}],"ex":"확장은 대개 이 순서로 갑니다 — ① 앱을 여러 대로 늘리고 앞에 로드밸런서를 둔다 ② 정적 파일을 CDN·오브젝트 스토리지로 빼서 앱 부하를 없앤다 ③ 조회를 캐시로 흡수한다 ④ 그래도 모자라면 읽기 복제본으로 나눈다. <b>복제본은 약간 늦게 따라오므로</b>(복제 지연) 방금 쓴 값을 바로 읽어야 하는 경로는 주 데이터베이스로 보내야 합니다."},{"t":"arch","kind":"cloud","k":"인프라 설계","lv":4,"cat":"design","q":"이미지 업로드·처리 파이프라인을 설계하세요. 업로드가 몰려도 <b>요청이 밀리지 않아야</b> 하고, 처리 실패는 재시도되며, <b>계속 실패하는 작업은 따로 모아야</b> 합니다.","src":"{\n  \"components\": [\n    { \"name\": \"api\", \"icon\": \"🖥\" },\n    { \"name\": \"worker\", \"icon\": \"⚙️\" }\n  ],\n  \"connections\": [\n    { \"from\": \"api\", \"to\": \"worker\" }\n  ]\n}","tests":[{"d":"큐로 요청과 처리를 분리한다","js":"D.components.some(c=>/queue|sqs|kafka|rabbit/i.test(c.name))"},{"d":"워커가 여러 대다 (처리량을 늘릴 수 있다)","js":"D.components.some(c=>/worker|consumer/i.test(c.name) && (c.scale||1)>=2)"},{"d":"실패한 작업을 모으는 곳이 있다 (DLQ)","js":"D.components.some(c=>/dead|dlq|failed/i.test(c.name))"},{"d":"DLQ 로 가는 경로가 재시도 초과와 연결돼 있다","js":"D.connections.some(e=>/dead|dlq/i.test(e.to) && /재시도|retry|초과|max/i.test(e.via||''))"},{"d":"원본 파일을 오브젝트 스토리지에 둔다","js":"D.connections.some(e=>/storage|s3|bucket/i.test(e.to))"},{"d":"API 가 처리를 직접 하지 않는다 (워커로 바로 연결하지 않는다)","js":"!D.connections.some(e=>/api|web/i.test(e.from) && /worker/i.test(e.to))"}],"ex":"업로드 처리를 요청 안에서 하면 트래픽이 몰릴 때 <b>요청 스레드가 전부 이미지 변환에 묶입니다</b>. 큐를 사이에 두면 API 는 접수만 하고 즉시 응답하며, 처리량은 워커 수로 조절합니다. 그리고 어떤 작업은 무엇을 해도 실패하므로(깨진 파일 등) 무한 재시도를 막고 DLQ 로 격리해야 큐 전체가 막히지 않습니다."},{"t":"arch","kind":"cloud","k":"인프라 설계","lv":3,"cat":"design","q":"장애 대응 구조를 설계하세요. 한 구성 요소가 느려져도 <b>전체가 무너지지 않아야</b> 하고, 문제를 <b>사용자보다 먼저 알아야</b> 합니다.","src":"{\n  \"components\": [\n    { \"name\": \"gateway\", \"icon\": \"🚪\" },\n    { \"name\": \"service_a\", \"icon\": \"🖥\" },\n    { \"name\": \"service_b\", \"icon\": \"🖥\" }\n  ],\n  \"connections\": [\n    { \"from\": \"gateway\", \"to\": \"service_a\" },\n    { \"from\": \"service_a\", \"to\": \"service_b\" }\n  ]\n}","tests":[{"d":"서비스 간 호출에 타임아웃이 있다","js":"D.connections.some(e=>/timeout|타임아웃/i.test(e.via||''))"},{"d":"서킷 브레이커로 전파를 끊는다","js":"D.connections.some(e=>/circuit|서킷|breaker|차단/i.test(e.via||''))"},{"d":"지표 수집 구성 요소가 있다","js":"D.components.some(c=>/metric|monitor|prometheus/i.test(c.name))"},{"d":"경보 구성 요소가 있다","js":"D.components.some(c=>/alert|경보|page/i.test(c.name))"},{"d":"지표에서 경보로 이어지는 경로가 있다","js":"D.connections.some(e=>/metric|monitor/i.test(e.from) && /alert|경보/i.test(e.to))"},{"d":"각 서비스가 2대 이상이다","js":"D.components.filter(c=>/service|api/i.test(c.name)).every(c=>(c.scale||1)>=2)"}],"ex":"타임아웃이 없으면 <b>느려진 의존성이 호출자의 스레드를 전부 붙잡습니다</b> — 장애가 그대로 전파됩니다. 서킷 브레이커는 실패가 잦아지면 아예 호출을 끊어 회복할 시간을 줍니다. 그리고 지표·경보가 없으면 사용자 문의로 장애를 알게 되는데, 그때는 이미 늦습니다. '무엇을 재면 사용자보다 먼저 알 수 있는가' 가 설계의 일부입니다."},{"t":"arch","kind":"cloud","k":"인프라 설계","lv":4,"cat":"design","q":"무중단 배포 구조를 설계하세요. 배포 중 <b>요청이 실패하지 않아야</b> 하고, 문제가 생기면 <b>빠르게 되돌릴 수 있어야</b> 합니다.","src":"{\n  \"components\": [\n    { \"name\": \"load_balancer\", \"icon\": \"⚖️\" },\n    { \"name\": \"app\", \"icon\": \"🖥\", \"scale\": 2 }\n  ],\n  \"connections\": [\n    { \"from\": \"load_balancer\", \"to\": \"app\" }\n  ]\n}","tests":[{"d":"구버전과 신버전이 동시에 존재한다 (블루·그린 또는 카나리)","js":"D.components.filter(c=>/app|service/i.test(c.name)).length>=2"},{"d":"로드밸런서가 두 버전 모두와 연결돼 있다","js":"D.connections.filter(e=>/load|lb/i.test(e.from) && /app|service/i.test(e.to)).length>=2"},{"d":"헬스체크 통과 후에 전환한다","js":"D.connections.some(e=>/health|헬스|readiness/i.test(e.via||''))"},{"d":"롤백 경로가 명시돼 있다","js":"D.connections.some(e=>/rollback|롤백|되돌/i.test(e.via||''))"},{"d":"두 버전이 같은 DB 를 쓰므로 스키마가 하위 호환이어야 한다","js":"D.connections.filter(e=>/db|database/i.test(e.to)).length>=2 && D.connections.some(e=>/호환|compatible|backward/i.test(e.via||''))"},{"d":"CI 와 이미지 저장소가 파이프라인에 있다","js":"D.components.some(c=>/ci|pipeline|build/i.test(c.name)) && D.components.some(c=>/registry|artifact/i.test(c.name))"}],"ex":"무중단 배포에서 가장 자주 놓치는 것은 <b>데이터베이스 스키마</b>입니다. 구버전과 신버전이 잠시 동시에 돌기 때문에, 컬럼을 지우거나 이름을 바꾸는 변경은 구버전을 즉시 깨뜨립니다. 그래서 '추가만 하고 나중에 정리' 하는 <b>확장-수축(expand-contract)</b> 순서로 나눠 배포합니다. 롤백이 빠르려면 이전 버전이 아직 살아 있어야 합니다 — 그게 블루·그린의 요점입니다."}],"th":{"sum":"설계를 고르는 게 아니라 직접 적습니다. JSON 으로 적은 설계가 다이어그램으로 그려지고, 요구사항이 규칙으로 검사됩니다.","body":[{"h":"설계에는 정답이 아니라 요건이 있다","t":"'어느 쪽이 더 낫나요' 는 맥락 없이는 답이 없습니다. 대신 <b>요구사항을 만족하는가</b>를 봅니다 — 중복 등록을 막았는가, 정적 파일이 앱을 거치지 않는가, 롤백 경로가 있는가."},{"h":"데이터 모델은 나중에 못 바꾼다","t":"금액을 부동소수로 저장하거나, 주문 시점의 단가를 복사해 두지 않거나, 외래키에 인덱스를 빠뜨리면 <b>데이터가 쌓인 뒤에는 고치기 매우 비쌉니다</b>. 설계 단계에서 결정되는 것들입니다."},{"h":"API 는 계약이다","t":"경로는 자원을, 메서드는 동작을 표현합니다. 상태 코드에는 의미가 있고(201 생성 · 204 내용 없음 · 401 인증 · 403 인가), 재시도가 반드시 일어난다는 전제로 멱등성을 설계합니다."},{"h":"구조는 장애를 가정하고 그린다","t":"단일 장애점을 없애고, 타임아웃·서킷 브레이커로 전파를 끊고, 사용자보다 먼저 알 수 있게 지표와 경보를 둡니다. 배포는 <b>되돌릴 수 있어야</b> 끝난 것입니다."}],"code":{"t":"설계를 JSON 으로 적는다","c":"{\n  \"entities\": [\n    { \"name\": \"comment\", \"fields\": [\n      { \"name\": \"post_id\", \"type\": \"bigint\",\n        \"fk\": \"post.id\", \"index\": true }   // ← 외래키에 인덱스\n    ]}\n  ]\n}"},"key":["요구사항 충족 여부로 판정한다","금액·상태·시점 스냅샷은 모델 단계에서 결정된다","경로는 자원 · 메서드는 동작 · 상태 코드는 의미","단일 장애점·타임아웃·롤백을 먼저 그린다"]}}]}]);
